window.__SUM[11]={"LR003639":{"pair":"a -> Mc2r","headline":"Agouti/ASIP inhibits MC2R in one human recombinant study; evidence for the mouse pair is projected from it.","interaction_type":"functional only","direction_and_effect":"Recombinant ASIP inhibits ACTH-stimulated cAMP at hMC2R in OS3 cells; ASIP is a potent inhibitor at hMC2R with nonsurmountable inhibition, and it inhibited radiolabeled melanocortin binding to hMCR1-5 [PMID:9058374].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used human ASIP and human receptors; the dossier pair is mouse and ortholog-inferred [PMID:9058374].","localisation_and_range":"Agouti is flagged secreted [flag]; paracrine per the abstract [PMID:9058374].","caveats":"One paper, abstract only; no mouse experiment for this receptor in our evidence.","key_references":[{"PMID":"9058374","why":"ASIP inhibition at five human melanocortin receptors including MC2R"}],"covers":["LR003639"]},"LR003558":{"pair":"ADAM15 -> ITGA9","headline":"ADAM-15 disintegrin domain binds integrin alpha9beta1 in an RGD-independent manner in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520]; the interaction supports cell-cell interaction [PMID:10944520].","molecular_requirements":"Receptor is alpha9beta1; alpha9 alone not tested [PMID:10944520].","affinity_potency":[],"species_and_systems":"Recombinant domains; species not reported in our evidence.","localisation_and_range":"ADAM15 is flagged not secreted [flag]; cell-cell adhesion context [PMID:10944520].","caveats":"One paper, abstract only; the human pair is ortholog-inferred in the dossier.","key_references":[{"PMID":"10944520","why":"alpha9beta1 binding to ADAM-15 disintegrin domain"}],"covers":["LR000008","LR003558"]},"LR005394":{"pair":"Adam17 -> Il6ra","headline":"Mouse pair projected from the human ADAM17-IL6R evidence; a single abstract-only paper reports an extracellular-domain interaction.","interaction_type":"direct binding","direction_and_effect":"ADAM17 interacts with IL-6R as a protease with its substrate; no receptor activation is reported [PMID:22575642].","molecular_requirements":"Only ADAM17 extracellular domains are needed; its membrane-proximal domain is mandatory for recognition of IL-6R [PMID:22575642].","affinity_potency":[],"species_and_systems":"The mouse pair is ortholog-inferred; the paper's own species is not reported in the abstract we hold [PMID:22575642].","localisation_and_range":"Both proteins are flagged as non-secreted/receptor [flag]; interaction would be at the cell surface (contact).","caveats":"Abstract read only; support is inferred from human-annotated evidence; enzyme-substrate rather than ligand-receptor signalling.","key_references":[{"PMID":"22575642","why":"ADAM17 membrane-proximal domain recognises IL-6R"}],"covers":["LR005394"]},"LR003567":{"pair":"ADAM2 -> ITGA6","headline":"Mouse egg alpha6beta1 is the receptor for sperm fertilin beta (ADAM2) by photoaffinity labelling and bead binding.","interaction_type":"direct binding","direction_and_effect":"A photoaffinity DECD peptide from fertilin beta's disintegrin domain covalently labelled an alpha6 integrin complexed with beta1 on mouse eggs; authors conclude fertilin beta binds alpha6beta1 directly, mediating sperm-egg fusion [PMID:9889149]. Alpha6beta1 interacts with ADAM 2 [PMID:10518536].","molecular_requirements":"alpha6 is complexed with beta1; CD9 is needed for high-avidity binding [PMID:9889149][PMID:10518536].","affinity_potency":[],"species_and_systems":"Mouse eggs and sperm; peptide probe, not full-length protein [PMID:9889149]. The human pair is ortholog-inferred.","localisation_and_range":"ADAM2 flagged non-secreted [flag]; sperm-egg contact.","caveats":"Both papers abstract only; direct binding relies on a peptide probe.","key_references":[{"PMID":"9889149","why":"DECD peptide photoaffinity labels egg alpha6beta1"},{"PMID":"10518536","why":"Fertilin beads bind eggs via alpha6beta1; CD9 involved"}],"covers":["LR000017","LR003567"]},"LR003576":{"pair":"ADCYAP1 -> ADCYAP1R1","headline":"PACAP binds and activates the PAC1 receptor with picomolar to low-nanomolar affinity; well supported by many papers and databases.","interaction_type":"direct binding","direction_and_effect":"PACAP-27 and PACAP-38 are agonists: PAC1 accepts PACAP as a high-affinity ligand but not VIP [PMID:10100920]; PACAP-38 raised cAMP and calcium, and drove catecholamine secretion in human fetal chromaffin cells via PAC1 [PMID:12429744]. A PAC1 antagonist (M65) abolished PACAP-stimulated ANP secretion in rat antrum [PMID:12488235]. GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"A 21-amino-acid N-terminal extracellular deletion variant changes PACAP-27 versus -38 selectivity and phospholipase C potency [PMID:8703026]; PAC1n bound both PACAP forms in the low nanomolar range [PMID:10583729]. Single receptor chain.","affinity_potency":[{"value":"Ki 4.6 pM","assay":"competitive binding, PACAP38","system":"purified PACAP receptor, bovine brain","cite":"PMID:8253796"},{"value":"Ki 30.0 pM","assay":"competitive binding, PACAP27","system":"purified PACAP receptor, bovine brain","cite":"PMID:8253796"},{"value":"Kd 25.8 pM","assay":"125I-PACAP27 binding","system":"purified receptor, bovine brain","cite":"PMID:8253796"},{"value":"Ki 37.3 nM","assay":"competitive binding, VIP","system":"purified PACAP receptor, bovine brain","cite":"PMID:8253796"}],"species_and_systems":"Human recombinant PAC1 in HEK293 and CHO cells [PMID:10583729][PMID:16930633]; rat AR4-2J cells [PMID:10100920]; bovine brain receptor [PMID:8253796]; human fetal chromaffin cells [PMID:12429744]. Mouse experiments are not shown in our evidence.","localisation_and_range":"Ligand flagged secreted [flag]; neuropeptide acting on a membrane receptor (paracrine or neurotransmitter-like) [PMID:12429744].","caveats":"All papers read as abstracts only. Picomolar values come from bovine receptor. Three further papers were abstract_insufficient. A caution: PACAP also acts at VIP receptors [DB:UniProt].","key_references":[{"PMID":"8253796","why":"purified PACAP receptor with pM affinity"},{"PMID":"10583729","why":"PAC1 splice variants, low nM binding"},{"PMID":"16930633","why":"cAMP and calcium potency at human PAC1"}],"covers":["LR000026","LR003576"]},"LR003585":{"pair":"ADM -> CALCRL","headline":"Adrenomedullin binds and activates CALCRL (CLR); six confirmed papers, with RAMPs defining receptor phenotype.","interaction_type":"direct binding","direction_and_effect":"CALCRL expressed in COS-7 cells mediates a cAMP response to adrenomedullin and binds 125I-adrenomedullin [PMID:7592696]. With RAMP2 or RAMP3, CLR is an ADM receptor [PMID:9620797][PMID:10347248]. GtoPdb lists ADM as full agonist [DB:GtoPdb]. Stimulatory.","molecular_requirements":"CALCRL needs a RAMP for surface transport; RAMP2 or RAMP3 yield an ADM receptor, RAMP1 a CGRP receptor [PMID:9620797]. RAMP2 and RAMP3 present CLR as core-glycosylated [PMID:10347248].","affinity_potency":[{"value":"KD 8.2 x 10(-9) M","assay":"125I-adrenomedullin binding","system":"COS-7 cells","cite":"PMID:7592696"},{"value":"EC50 7 x 10(-9) M","assay":"cAMP response","system":"COS-7 cells","cite":"PMID:7592696"},{"value":"pKi 8.3-9.2","assay":"GtoPdb record","system":"HEK-293 per paper","cite":"PMID:11693189"}],"species_and_systems":"Transfected HEK-293, HEK293T and COS-7 cells; human and porcine receptors [PMID:11693189]; the first paper cloned an orphan receptor originally isolated from rat lung [PMID:7592696].","localisation_and_range":"ADM flagged secreted [flag], so paracrine/endocrine.","caveats":"All papers read as abstracts only. The 1995 paper tested CALCRL without a RAMP, whereas later papers show a RAMP is required for ADM receptor phenotype [PMID:9620797].","key_references":[{"PMID":"7592696","why":"cloning, KD and EC50"},{"PMID":"9620797","why":"RAMP2 confers ADM receptor phenotype"},{"PMID":"10347248","why":"RAMP2/RAMP3 CRLR pharmacology"}],"covers":["LR000035","LR003585"]},"LR008481":{"pair":"AFDN -> EPHB6","headline":"Database-only protein interaction between AFDN and EPHB6; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID and IntAct list a two-hybrid interaction between AFDN (MLLT4) and EPHB6 [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; EPHB6 flagged secreted, receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR008481"]},"LR009156":{"pair":"AFDN -> NRXN3","headline":"Database-only protein interaction between AFDN and NRXN3; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a two-hybrid interaction between AFDN (MLLT4) and NRXN3 [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; NRXN3 flagged receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR009156"]},"LR003594":{"pair":"AGRP -> SDC3","headline":"Syndecan-3 is reported to modulate AGRP action in feeding control in mice; a single abstract-only paper, with no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Via their HS chains, syndecans potentiate the action of agouti-related protein and agouti signaling protein [PMID:11461706]. Syndecan-3 null mice showed markedly reduced reflex hyperphagia after food deprivation [PMID:11461706].","molecular_requirements":"HS chains are required [PMID:11461706]. Not reported otherwise.","affinity_potency":[],"species_and_systems":"Mouse in vivo [PMID:11461706]. Mouse pair is not ortholog-inferred; human is.","localisation_and_range":"Syndecan-3 is the predominantly neural syndecan, expressed in hypothalamic regions controlling energy balance and increased several-fold by food deprivation [PMID:11461706].","caveats":"Abstract-only. The syndecan-3 null phenotype shows a role in feeding but does not itself show an AGRP-syndecan-3 interaction; the AGRP potentiation statement is general for syndecans. Modulator rather than classical receptor.","key_references":[{"PMID":"11461706","why":"Syndecan-3 null mice have reduced fasting-induced hyperphagia; syndecans potentiate AGRP"}],"covers":["LR000044","LR003594"]},"LR005439":{"pair":"ANGPTL4 -> NRP2","headline":"ANGPTL4 is reported to bind NRP2 and NRP1 directly on endothelial cells, activating RhoA/ROCK; abstract-level.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 binds directly to NRP1 and NRP2 on endothelial cells, rapidly activating RhoA/ROCK and breaking down EC-EC junctions; curator labels it agonist [PMID:31545295]. The permeability effect is independent of VEGFR2, and soluble NRP1 blocks ANGPTL4-NRP1 binding and retinal leakage in vivo [PMID:31545295].","molecular_requirements":"NRP2 alone is not shown to suffice; NRP1 is the partner dissected with the soluble-receptor blocker, and no co-receptor requirement is stated for NRP2 [PMID:31545295].","affinity_potency":[],"species_and_systems":"Endothelial cells in vitro, diabetic mouse retina, and diabetic macular edema patient samples [PMID:31545295]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; NRP2 transmembrane [flag]; paracrine action on endothelium.","caveats":"Abstract only; no affinity or binding assay detail; the block experiments target NRP1, so NRP2-specific functional evidence is thinner.","key_references":[{"PMID":"31545295","why":"ANGPTL4 binds NRP1/NRP2 to drive RhoA/ROCK junction breakdown"}],"covers":["LR002117","LR005439"]},"LR005448":{"pair":"APLP1 -> CNTN5","headline":"APLP1 binds CNTN5 ectodomain in a systematic binding screen with crystal-structure context; direction as ligand to receptor is arbitrary for this adhesion pair.","interaction_type":"direct binding","direction_and_effect":"APLP1 interacts with CNTN5; the paper reports that APP and APLP1 interact with CNTN3-5 [PMID:34958801]. Signalling direction or agonist/antagonist effect is not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins to transmit signals [PMID:34958801].","molecular_requirements":"Interaction involves the second fibronectin type III repeat of the contactin and the copper-binding domain of the amyloid protein, a conserved interface across five CNTN-amyloid structures [PMID:34958801]. Binding was tested with the APLP1 E1 domain and FN1-FN3 fragments of CNTN3-5 by biolayer interferometry [PMID:34958801]. APLP1 appeared to bind CNTN5 less strongly than CNTN4 [PMID:34958801]; CNTN5 and APLP1 form coreceptor complexes at presynaptic sites in cultured hippocampal neurons, per the authors' discussion of prior work (background) [PMID:34958801].","affinity_potency":[],"species_and_systems":"Human proteins in AlphaScreen extracellular binding assay and biolayer interferometry; zebrafish used for expression and some structures [PMID:34958801]. The mouse pair is inferred from human evidence.","localisation_and_range":"Contactins are GPI-anchored to the membrane [PMID:34958801]. Interaction could occur in cis on the same cell or in trans across cells [PMID:34958801]. Entity flags list APLP1 as secreted [flag], which conflicts with a membrane-anchored role.","caveats":"Paper was read for evidence as abstract per the curator, with full-text excerpts available [PMID:34958801]. The authors note that their BLI affinities are weaker than earlier reported values for APP and APLP1 with CNTN3-5 (17-35 nM), attributed to oligomeric state [PMID:34958801]. No APLP1-specific Kd is in our excerpts. IntAct has a pull-down record [DB:IntAct].","key_references":[{"PMID":"34958801","why":"Systematic binding and structural study of contactin-amyloid pairs."}],"covers":["LR002131","LR005448"]},"LR005466":{"pair":"APOM -> LRP2","headline":"Surface plasmon resonance and megalin-dependent uptake support apoM-megalin binding; abstract level.","interaction_type":"direct binding","direction_and_effect":"Recombinant apoM bound immobilised megalin (Kd approximately 0.3-1 microm) and was endocytosed by cultured rat yolk sac cells in a megalin-dependent manner [PMID:16099815]. Kidney-specific megalin-deficient mice excreted apoM in urine, suggesting megalin-mediated endocytosis prevents loss [PMID:16099815]. Acts as clearance receptor, not signalling.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd approximately 0.3-1 microm","assay":"surface plasmon resonance","system":"recombinant E. coli apoM on immobilised megalin","cite":"PMID:16099815"}],"species_and_systems":"Human apoM, rat yolk sac cells and mouse knockouts [PMID:16099815]. Human pair is ortholog-inferred.","localisation_and_range":"ApoM flagged secreted [flag]; megalin acts in kidney proximal tubule cells [PMID:16099815].","caveats":"Abstract only; one confirmed paper shown of two.","key_references":[{"PMID":"16099815","why":"SPR Kd and megalin-deficient mice"}],"covers":["LR002151","LR005466"]},"LR005475":{"pair":"APP -> LRP10","headline":"LRP10 interacts with the APP ectodomain and retains APP at the trans-Golgi network; one paper, mainly a trafficking effect.","interaction_type":"direct binding","direction_and_effect":"LRP10 interacts directly with the APP ectodomain and colocalizes with it at the TGN [PMID:22734645]. LRP10 overexpression in SH-SY5Y cells increased mature APP in the Golgi, lowered cell-surface APP and reduced Abeta production, while LRP10 knockdown increased Abeta [PMID:22734645]. LRP10 mutants lacking TGN-recycling motifs sent APP to early endosomes and raised beta-cleavage [PMID:22734645].","molecular_requirements":"LRP10 shuttles between the TGN, plasma membrane and endosomes; recycling motifs are needed for the effect [PMID:22734645]. No co-receptor reported.","affinity_potency":[],"species_and_systems":"Human SH-SY5Y neuroblastoma cells; LRP10 expression is lower in post-mortem AD brain [PMID:22734645]. Mouse pair is ortholog-inferred.","localisation_and_range":"Largely intracellular trafficking between TGN, surface and endosomes [PMID:22734645]; not a secreted paracrine signal. Flags only mark LRP10 as a receptor [flag].","caveats":"Single paper, abstract plus excerpts. The abstract calls LRP10 a functional APP receptor, but the readout is APP trafficking and processing, not signalling. IntAct lists a solid-phase assay record [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"22734645","why":"LRP10 binds APP and regulates its trafficking"}],"covers":["LR002160","LR005475"]},"LR007095":{"pair":"APP -> TNFRSF21","headline":"Contested: a later paper reports a co-IP interaction, while the founding paper is retracted.","interaction_type":"conflicting","direction_and_effect":"APP and TNFRSF21 were co-immunoprecipitated in AD model mice; TNFRSF21, APP, NF-kB and MAPK8 were increased and inflammatory cytokines fell when TNFRSF21 was inhibited [PMID:33075465].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"C57BL6 mice, Tg2576 and JNPL3 AD models, and in vitro knockdown [PMID:33075465]. IntAct lists solid-phase assays [DB:IntAct].","localisation_and_range":"Both flagged transmembrane [flag].","caveats":"Abstract only. One judged row for the founding paper is recorded as retracted (outcome count), and the curator note says to treat the pair as contested [PMID:33075465]. The abstract text only reports a Co-IP at protein level, not a binding assay.","key_references":[{"PMID":"33075465","why":"Co-IP and cytokine data in AD mouse models"}],"covers":["LR007095"]},"LR006825":{"pair":"ARF1 -> PLD2","headline":"Database-asserted activation of PLD2 by ARF1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists ARF1 as an activator of PLD2 [DB:GtoPdb]; BioGRID has reconstituted complex records [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No verified papers: judged rows were different_entity, abstract_insufficient or unresolvable. Intracellular regulator-effector relation.","key_references":[],"covers":["LR006825"]},"LR005484":{"pair":"ASGR1 -> LDLR","headline":"ASGR1 is reported to target LDLR for degradation, independently of PCSK9; supported by one cell-and-mouse paper, with direct binding inferred.","interaction_type":"functional only","direction_and_effect":"ASGR1, like PCSK9, targets LDLR; both independently interact with and enhance degradation of the receptor, with no cooperativity seen in livers of wild-type and Pcsk9-/- mice [PMID:34508778]. ASGR1 knockdown raised LDLR (curator summary: about 1.2-fold total, about 4-fold cell-surface in HepG2-naive cells) [PMID:34508778]. Effect is LDLR-lowering (antagonist-like).","molecular_requirements":"The curator's reading of the abstract is that ASGR1 binds LDLR both sugar-dependently and sugar-independently, based on a carbohydrate-binding-deficient mutant; furin cleaves ASGR1 into a secreted form likely losing LDLR-degrading function [PMID:34508778]. ASGR2 is overexpressed together in some experiments [PMID:34508778].","affinity_potency":[],"species_and_systems":"Human HepG2 cells (naive and PCSK9-knockout) and mouse livers; both partners recorded as human [PMID:34508778].","localisation_and_range":"ASGR1 is flagged secreted and receptor, LDLR as receptor [flag]. The paper describes a cleaved secreted ASGR1 form [PMID:34508778]. Cell-surface and cellular interaction, range not reported in our evidence.","caveats":"Single paper; evidence is Western blot, immunofluorescence and knockdown, so no purified-protein binding or affinity is shown in the excerpts. ASGR1 is a receptor itself, so this is a receptor-receptor regulatory interaction, not a classical ligand-receptor pair.","key_references":[{"PMID":"34508778","why":"ASGR1 targets LDLR for degradation independently of PCSK9"}],"covers":["LR002170","LR005484"]},"LR003648":{"pair":"B2M -> HFE","headline":"B2M and HFE bind directly by several methods in human breast cancer cells; the paper's ERK-activation claim is inconsistent with its own excerpts.","interaction_type":"direct binding","direction_and_effect":"B2M directly interacted with HFE by co-IP, mass spectrometry, yeast two-hybrid and His pull-down in human breast cancer cells, and the paper reports that B2M activated ERK and induced apoptosis through HFE [PMID:39128984]. However, in MDA-MB-453 cells B2M overexpression or silencing did not significantly change p-ERK/ERK, while HFE overexpression increased it [PMID:39128984].","molecular_requirements":"The B2M/HFE complex was detected; endogenous interaction was seen in MDA-MB-453, MDA-MB-231 and MCF-7 cells but not BT474, possibly because HFE was undetectable there [PMID:39128984]. The databases list crystal structures of the two chains [DB:PDB 1A6Z, 1DE4].","affinity_potency":[],"species_and_systems":"Human breast cancer cell lines, recombinant B2M from E. coli and HA-HFE from HEK-293T for the pull-down [PMID:39128984]. Database records are human [DB:BioGRID, DB:IntAct]. The mouse pair is projected from human.","localisation_and_range":"The complex was mainly cytoplasmic with some on the cell membrane [PMID:39128984]; HFE is flagged transmembrane and B2M secreted [flag].","caveats":"B2M-HFE is also a heavy/light-chain-type association in structures, so ligand-receptor direction is not established. The functional ERK claim is internally mixed (above). The primary evidence is a single paper; 1 more row is pending.","key_references":[{"PMID":"39128984","why":"Co-IP, Y2H, pull-down of B2M-HFE in breast cancer cells"}],"covers":["LR000099","LR003648"]},"LR009732":{"pair":"B2M -> KLRC1","headline":"B2M-KLRC1 rests on HLA-E complex structures with the CD94/NKG2A receptor, not on direct B2M binding.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for B2M; Reactome describes KLRC1:KLRD1 heterodimer interacting with HLA-E [DB:Reactome R-HSA-199062]; structures [DB:PDB 3CDG, 3CII] and x-ray IntAct entry [DB:IntAct EBI-21280996].","molecular_requirements":"The records describe the KLRC1:KLRD1 heterodimer with HLA-E [DB:Reactome R-HSA-198914]; KLRC1 alone and B2M contact are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; the receptor is flagged transmembrane [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (IntAct, PDB, Reactome). ","key_references":[],"covers":["LR009732"]},"LR009714":{"pair":"B2M -> KLRC2","headline":"B2M-KLRC2 rests on a single Reactome complex record; no paper or structure in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the only record is the complex CD94:NKG2C:HLA-E [DB:Reactome R-HSA-2326867].","molecular_requirements":"Reactome lists the receptor as a CD94:NKG2C complex with HLA-E [DB:Reactome R-HSA-2326867]; B2M contact is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; the receptor is flagged transmembrane [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (Reactome only).  1 additional row was classified different_entity.","key_references":[],"covers":["LR009714"]},"LR001659":{"pair":"BAG6 -> NCR3","headline":"BAG6 (BAT3) is a directly binding cellular ligand of NKp30; full-length protein activates NK cells while a C-terminal fragment inhibits.","interaction_type":"conflicting","direction_and_effect":"BAT3 released from tumour cells bound NKp30 directly and triggered NKp30-mediated cytotoxicity [PMID:18055229]. Exosomal surface BAT3 was recognised by NKp30-Ig, and NK/DC cross-talk was BAT3-dependent [PMID:18852879]. By contrast, the BAG-6(686-936) fragment alone inhibited NKp30 signalling, IFN-gamma release and degranulation of NK cells with transformed target cells [PMID:24133212].","molecular_requirements":"The NKp30 binding site is a 250-amino-acid C-terminal region, BAG-6(686-936), forming a noncovalent 57-59 kDa dimer sufficient for high-affinity interaction [PMID:24133212]. Other subunits or co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD < 100 nM","assay":"binding of the BAG-6(686-936) fragment to NKp30 (assay details not in abstract)","system":"human proteins","cite":"PMID:24133212"}],"species_and_systems":"Human proteins [PMID:24133212, PMID:18852879]; species unspecified in [PMID:18055229]. Systems: tumour cells and NK cells, 293T cell and immature dendritic cell exosomes, NKp30-Ig fusion protein.","localisation_and_range":"Ligand is flagged secreted [flag]; BAT3 was released from tumour cells [PMID:18055229] and presented on exosome surfaces, while being intracellular in origin [PMID:18852879].","caveats":"The fragment result is not the full-length ligand effect. 1 further row is pending. Papers other than 18852879 were read as abstract only; the first paper's species is unspecified.","key_references":[{"PMID":"18055229","why":"BAT3 released from tumour cells binds NKp30 and triggers cytotoxicity"},{"PMID":"18852879","why":"Exosomal BAT3 recognised by NKp30-Ig; NK-DC cross-talk"},{"PMID":"24133212","why":"Binding site on BAG-6 and KD < 100 nM; fragment inhibits NKp30 signalling"}],"covers":["LR001659"]},"LR012378":{"pair":"BAMBI -> FZD5:LRP6","headline":"BAMBI interacts with Frizzled5 and LRP6 in one abstract-only study, which also shows it enhances Wnt signalling; a modulator rather than a classical ligand.","interaction_type":"direct binding","direction_and_effect":"BAMBI interacts with Frizzled5 and the coreceptor LRP6 [PMID:18838381]. Overexpression of BAMBI enhances Wnt-responsive reporters and knockdown attenuates them, so the effect is positive (stimulatory) on Wnt/beta-catenin signalling [PMID:18838381]. It also increases the Frizzled5-Dishevelled2 interaction [PMID:18838381]. Two IntAct co-IP records cite the same paper [DB:IntAct].","molecular_requirements":"Frizzled5, LRP6 and Dishevelled2 are each reported to interact with BAMBI [PMID:18838381]. Whether both receptor subunits are needed for BAMBI's effect is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and cell system are not stated in the abstract; read at abstract level only [PMID:18838381]. IntAct methods: anti tag and anti bait coimmunoprecipitation [DB:IntAct].","localisation_and_range":"Not reported in our evidence; LRP6 has a transmembrane flag [flag].","caveats":"Single paper, abstract only. Evidence is co-IP-type interaction plus reporter readouts; affinity not reported. The paper calls BAMBI a pseudoreceptor, so it acts as a pathway modulator rather than a classical ligand.","key_references":[{"PMID":"18838381","why":"BAMBI interacts with Frizzled5/LRP6/Dvl2 and promotes Wnt/beta-catenin signalling"}],"covers":["LR012378"]},"LR003657":{"pair":"BMP10 -> BMPR1B","headline":"Functional evidence only: ALK6 (BMPR1B) overexpression confers BMP10 signalling in COS7 cells; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"Overexpressing ALK3 or ALK6 in COS7 cells conferred BMP10 signalling, measured with a Smad1/5/8 reporter [PMID:16049014]. GtoPdb lists BMP10 as an agonist at BMPR1B [DB:GtoPdb].","molecular_requirements":"ALK6 was one of two type I receptors sufficient in this overexpression assay; a type II partner requirement is not reported for this pair in our evidence.","affinity_potency":[],"species_and_systems":"COS7 cell line, reporter assay, abstract read only; curators annotate human ligand and receptor. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Signalling readout only. The loss-of-function (shRNA) result in the abstract concerns ALK3, not ALK6.","key_references":[{"PMID":"16049014","why":"ALK6 overexpression confers BMP10 signalling"}],"covers":["LR000108","LR003657"]},"LR003666":{"pair":"BMP2 -> ACVR2A","headline":"Direct binding by SPR and affinity labelling, but BMP2 binds ACVR2A weaker than its type I receptors.","interaction_type":"direct binding","direction_and_effect":"BMP2 bound ACVR2A, ACVR2B and BMPR2 with comparable affinity and activated SMAD1/5/8 in C3H10T1/2 cells [PMID:21702718]. In P19 cells, BMP2 formed heteromeric complexes with ActRII and ActRIIB [PMID:9748228]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type II binding is at least 10-fold weaker than type I (ALK3 1.1 nM, ALK6 1.6 nM) [PMID:21702718]; BMP2 also bound ALK3 and ALK6 tightly, while ALK2 binding was orders of magnitude weaker [PMID:21702718]. Whether a type I partner is required is not reported in our evidence.","affinity_potency":[{"value":"KD 60.0 nM (SD 40.5)","assay":"SPR, rhBMP2 on ACVR2A","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human proteins, SPR [PMID:21702718]; mouse P19 cells, [125I]BMP2 affinity labelling [PMID:9748228]. Both human and mouse pairs are experimental.","localisation_and_range":"BMP2 is annotated as secreted and ACVR2A as transmembrane [flag].","caveats":"Abstract-level reads for both; the 1998 paper focuses on BMP7/ALK2 and BMP2 is a side result. The KD has a large SD. One review-only row not shown.","key_references":[{"PMID":"21702718","why":"SPR affinities of BMP2 for type I and type II receptors"},{"PMID":"9748228","why":"BMP2 forms complexes with ActRII/ActRIIB in P19 cells"}],"covers":["LR000117","LR003666"]},"LR003675":{"pair":"BMP4 -> ACVR1","headline":"BMP4 acts in an ALK2 (ACVR1)-dependent manner in endothelial cells; evidence is one functional paper, with no direct binding shown.","interaction_type":"functional only","direction_and_effect":"BMP4 treatment of untransfected endothelial cells induced ALK2-dependent endothelial-to-mesenchymal transition and a stem-like phenotype; the paper calls BMP4 an ALK2-activating ligand [PMID:21102460]. ALK2 siRNA blocked the effect, and BMP4 induced ALK2 receptor phosphorylation within 15 min in immunoprecipitation assays [PMID:21102460]. Effect is agonist.","molecular_requirements":"ALK2 co-precipitated with ALK5 in BMP4-treated cells, suggesting an ALK2/ALK5 interaction; a type II partner is not reported in our evidence [PMID:21102460].","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVECs, HCMECs); heterotopic ossification experiments in mice were also reported [PMID:21102460].","localisation_and_range":"BMP4 is flagged secreted [flag]; acts on cell-surface receptor ALK2 in treated cells.","caveats":"No binding measurement in our evidence. Dependence on ALK2 is shown by knockdown and inhibitor, which does not rule out indirect action. Another review-only row exists but is not shown. Abstract plus excerpts only for one paper.","key_references":[{"PMID":"21102460","why":"BMP4 drives ALK2-dependent endothelial-to-mesenchymal transition"}],"covers":["LR000126","LR003675"]},"LR005493":{"pair":"BMP4 -> CDCP1","headline":"CDCP1 CUB domains bind BMP4 directly (BIAcore) but CDCP1 did not modulate BMP signalling; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"BIAcore showed CDCP1 CUB domains bind directly to TGF-beta1 and BMP4 [PMID:31302030]. CDCP1 enhanced TGF-beta1 reporter activity and phospho-Smad2 but did not modulate the BMP signalling pathway [PMID:31302030].","molecular_requirements":"CUB domains of CDCP1 mediate binding [PMID:31302030]. A signalling partner for BMP4 is not reported.","affinity_potency":[],"species_and_systems":"BIAcore recombinant proteins and cell reporter assays; curators record human [PMID:31302030].","localisation_and_range":"BMP4 is flagged secreted; CDCP1 is flagged secreted and receptor [flag], so the receptor may be soluble or shed.","caveats":"Binding does not translate to a BMP signalling effect, so the interaction may be non-functional or regulatory. Abstract only; no affinity value in our evidence. The curator's agonist label is not supported by the paper's abstract for BMP4.","key_references":[{"PMID":"31302030","why":"BIAcore binding of CDCP1 CUB domains to BMP4"}],"covers":["LR002179","LR005493"]},"LR011199":{"pair":"BMP5 -> ACVR2B","headline":"BMP5 to ACVR2B rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Three screened papers were abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR011199"]},"LR003684":{"pair":"BMP6 -> ACVR2B","headline":"BMP6 binds ActR-IIB (ACVR2B) per a 1999 study and a cryo-EM structure; some data are 'not shown'.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist. BMP-6 bound ActR-II and ActR-IIB in singly transfected cells [PMID:10504300]. A cryo-EM structure shows ALK2-ActRIIB bound to BMP6 [DB:PDB 9N4K][PMID:40854140]. UniProt says ACVR2B interacts with BMP6 [DB:UniProt][PMID:18070108].","molecular_requirements":"ACVR2B bound BMP6 without a type I receptor in the paper [PMID:10504300]; the structure contains ALK2 as well [DB:PDB 9N4K].","affinity_potency":[],"species_and_systems":"Recombinant human BMP-6 with COS-7 transfectants; endogenous binding in mouse MC3T3-E1 and C2C12 lines [PMID:10504300]. The structure is by electron microscopy [DB:PDB 9N4K]. Both species pairs are projected from this evidence.","localisation_and_range":"BMP6 is flagged secreted and ACVR2B transmembrane [flag].","caveats":"The quoted binding result is marked 'data not shown'. Affinity not reported. One further judged row was abstract_insufficient.","key_references":[{"PMID":"10504300","why":"cross-linking of BMP-6 to ActR-IIB"}],"covers":["LR000135","LR003684"]},"LR003693":{"pair":"BMP7 -> BMPR2","headline":"BMP7 binds BMPR2 directly, but with a very fast dissociation rate; ligand binding is enhanced by type I receptors.","interaction_type":"direct binding","direction_and_effect":"BMPR-II binds BMP-7 on its own, and binding is enhanced by coexpression of type I BMP receptors [PMID:7791754]. In SPR, BMP7 bound BMPR2 but dissociated at a very fast rate [PMID:35643319]. GtoPdb lists agonist action [DB:GtoPdb].","molecular_requirements":"BMP-2 and BMP-7 induced a transcriptional response only in cells coexpressing ActR-I and BMPR-II, not either receptor alone; kinase activity of both receptors was needed [PMID:7791754]. UniProt notes BMPR2 as type II receptor for some BMP7 functions [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, SPR with immobilised BMPR2-Fc [PMID:35643319]; human BMPR-II in mammalian cells [PMID:7791754].","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"No affinity value for BMP7-BMPR2 is given in the dossier excerpts. PMID 7791754 was read as abstract only. In PMID 35643319, BMP7 was one of eight growth factors tested; high-affinity BMPR2 ligands were other factors (BMP15, BMP10, Nodal).","key_references":[{"PMID":"35643319","why":"SPR of BMPR2 with BMP7 and other ligands"},{"PMID":"7791754","why":"BMPR-II binds BMP-7; needs type I partner for signalling"}],"covers":["LR000144","LR003693"]},"LR007149":{"pair":"BMP8A -> ACVR1:ACVR2A","headline":"BMP8A -> ACVR1:ACVR2A: the mouse paper supports ACVR2A but does not name ACVR1; GtoPdb lists both chains.","interaction_type":"functional only","direction_and_effect":"The verified paper shows BMP8A signalling through ACVR2A, paired with ALK3 or ALK5, in mouse spermatogonia [PMID:28465413]. GtoPdb lists BMP8A as agonist at ACVR1 and ACVR2A [DB:GtoPdb].","molecular_requirements":"ACVR1 plus ACVR2A as a pair is not shown; ACVR2A acts with ALK3 or ALK5 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"ACVR1 rests on a GtoPdb record only. Three papers were review-only. Evidence is functional, abstract-level.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR007149"]},"LR001668":{"pair":"BMP8A -> BMPR2","headline":"BMP8A acts through BMPR2 in mouse spermatogonia (functional, abstract-level); GtoPdb and UniProt agree.","interaction_type":"functional only","direction_and_effect":"Agonist (curator annotation). BMPR2 with ALK3 mediated SMAD1/5/8 activation [PMID:28465413]. GtoPdb lists an agonist record [DB:GtoPdb]; UniProt says BMP8A associates with type II receptor BMPR2 [DB:UniProt].","molecular_requirements":"BMPR2 is the type II partner of ALK3, an alternative to ACVR2A [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"Paper evidence is functional only, abstract-level; no binding data.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR001668"]},"LR008265":{"pair":"BMP8B -> ACVR2B:BMPR1B","headline":"BMP8B is asserted by GtoPdb as an agonist of the ACVR2B:BMPR1B receptor complex; no verified paper supports it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-ACVR2B and BMP8B-BMPR1B each as Type=Agonist, Action=Agonist [DB:GtoPdb]. Effect is therefore stimulatory by annotation only.","molecular_requirements":"The receptor is a type II (ACVR2B) plus type I (BMPR1B) complex; both members are flagged as receptors [flag]. Whether both chains are needed together is not reported in our evidence; GtoPdb records the two chains separately [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence; records are for human entities.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; ligand localisation not reported in our evidence.","caveats":"No curator-verified paper; several candidate papers were judged abstract-insufficient, review-only or about a different entity, so none supports the pair. The GtoPdb record is a database assertion, not an experiment.","key_references":[],"covers":["LR008265"]},"LR007158":{"pair":"BMPR1B:BMPR2 -> BMPR1A","headline":"A receptor-receptor entry (BMPR1B:BMPR2 with BMPR1A) supported only by database records, not by a ligand-receptor experiment.","interaction_type":"database-asserted only","direction_and_effect":"Annotated Receptor-Receptor, not Ligand-Receptor; no signalling direction or effect is reported in our evidence. BioGRID lists BMPR2-BMPR1B affinity capture-western [PMID:7791754] [DB:BioGRID], and Reactome has BMPRI dimer complexes [DB:Reactome].","molecular_requirements":"The 'ligand' is a BMPR1B:BMPR2 complex. The BioGRID examples shown involve BMPR1B, BMPR2 and BMPR1B-BMPR1B, not BMPR1A [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Affinity-capture and co-localisation records [PMID:10712517]; species and cell system not reported in our evidence.","localisation_and_range":"Both partners are flagged as receptors and transmembrane [flag]; this is a contact or in-membrane receptor association, not a secreted ligand.","caveats":"No curator-verified paper. Candidate papers were abstract-insufficient or about a different entity. The shown database records do not directly document BMPR1A binding.","key_references":[],"covers":["LR007158"]},"LR002199":{"pair":"C1QA -> LRP1","headline":"C1q is reported to act through calreticulin bound to CD91 (LRP1) to stimulate apoptotic cell uptake; the link to LRP1 is likely indirect.","interaction_type":"functional only","direction_and_effect":"C1q and MBL bind apoptotic cells and stimulate ingestion via phagocyte calreticulin, which is bound to CD91; uptake proceeds by macropinocytosis [PMID:11560994].","molecular_requirements":"Calreticulin is required as an intermediary; it has no transmembrane domain and presumably needs CD91 as partner [PMID:11560994].","affinity_potency":[],"species_and_systems":"Human macrophages (HMDM) and apoptotic cells [PMID:11560994].","localisation_and_range":"C1q annotated secreted [flag].","caveats":"Two further rows were abstract_insufficient. An IntAct ELISA record exists [DB:IntAct]. Direct C1q-CD91 binding is not shown in our excerpts.","key_references":[{"PMID":"11560994","why":"C1q-calreticulin-CD91 uptake of apoptotic cells"}],"covers":["LR002199","LR005513"]},"LR005529":{"pair":"C1QL2 -> NRXN3","headline":"C1QL2 acts through direct interaction with the neurexin-3 splice variant Nrxn3(25b+) at mouse mossy fiber-CA3 synapses; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"C1ql2 regulates synaptic vesicle recruitment and long-term potentiation at mossy fiber-CA3 synapses; a non-binding C1ql2 mutant or Nrxn3 deletion in dentate gyrus granule neurons recapitulates major parts of the Bcl11b and C1ql2 mutant phenotypes [PMID:38358390].","molecular_requirements":"Requires a specific splice variant, Nrxn3(25b+) [PMID:38358390]; other variants are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse, in vivo and in vitro (the abstract says 'in mice'); the mouse pair is not ortholog-inferred, the human pair is [PMID:38358390].","localisation_and_range":"C1ql2 is described as a synaptic organizer; flags: ligand secreted, NRXN3 transmembrane [flag].","caveats":"Abstract and a few excerpts only; the binding assay itself is not described in our evidence, and no affinity is given.","key_references":[{"PMID":"38358390","why":"Bcl11b-C1ql2-Nrxn3(25b+) pathway in mouse mossy fiber synapses"}],"covers":["LR002216","LR005529"]},"LR001677":{"pair":"C4A -> NRP1","headline":"C4d, a C4A-derived fragment, binds NRP1 directly in one full-text paper; single-study support.","interaction_type":"direct binding","direction_and_effect":"NRP1 was identified as a receptor for C4d by an expression-library screen with recombinant human C4d; binding was dose-dependent, saturable and competed by unlabeled C4d or a polyclonal NRP1 antibody [PMID:31572401]. Signalling effect is not reported in our evidence.","molecular_requirements":"Both human C4Ad and C4Bd isotypes bound; the ligand acting is the split product C4d, not intact C4A. Whether NRP1 acts alone or in a complex is not known: the paper says this is unknown in the immune system [PMID:31572401].","affinity_potency":[{"value":"apparent KD 0.71 \u03bcM (\u00b10.09 \u03bcM)","assay":"flow cytometry binding of rh-C4Ad, Langmuir isotherm","system":"BW cells expressing human NRP1","cite":"PMID:31572401"}],"species_and_systems":"Human recombinant/isolated proteins on mouse BW cells expressing human NRP1; mouse NRP1 also bound complement split products, and NRP1 is on human moDCs but absent on monocytes [PMID:31572401].","localisation_and_range":"C4A is flagged secreted; NRP1 is flagged transmembrane and secreted [flag]. C4d bound NRP1 on cell surfaces (paracrine/juxtacrine presentation) [PMID:31572401].","caveats":"The authors state the apparent KD is a minimal estimate of intrinsic affinity [PMID:31572401]. Only one paper; no database records.","key_references":[{"PMID":"31572401","why":"Library screen, flow and ELISA binding, KD for C4d-NRP1"}],"covers":["LR001677"]},"LR005538":{"pair":"CADM2 -> CADM1","headline":"Direct CADM2-CADM1 binding in SPR with Kd 86.8 nM; one primary paper plus Reactome homodimer entries.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc interacted with CADM2 in SPRi [PMID:30131958]. No signalling effect reported.","molecular_requirements":"Whole ectodomain Fc fusions; no extra subunit reported [PMID:30131958].","affinity_potency":[{"value":"Kd 86.8 nM","assay":"SPRi, CADM1-Fc analyte with CADM2-Fc","system":"purified Fc fusions","cite":"PMID:30131958"}],"species_and_systems":"Human-labelled recombinant ectodomains in SPRi [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound, not secreted [flag]; contact-dependent adhesion is the likely mode but this paper's evidence here is binding only.","caveats":"Single paper. Reactome entries listed concern Necl homodimerisation, not this heterodimer [DB:Reactome].","key_references":[{"PMID":"30131958","why":"SPRi showing CADM1-CADM2 binding and Kd"}],"covers":["LR002228","LR005538"]},"LR005547":{"pair":"CADM4 -> CADM4","headline":"CADM4 homophilic binding is reported by SPRi in one family-wide screen; no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM4 with all CADM family proteins [PMID:30131958]. The same molecule acts as ligand and receptor; no effect direction is reported.","molecular_requirements":"SPRi detects only direct interactions between two molecules [PMID:30131958].","affinity_potency":[],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"Flagged transmembrane [flag]; cell-cell adhesion is described for the family [PMID:30131958].","caveats":"Single paper. The curator's evidence sentence concerns CADM1-CADM4, not CADM4 self-binding; the self-binding support is the family-wide SPRi statement in the full text [PMID:30131958]. No Kd for CADM4-CADM4 in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002237","LR005547"]},"LR009309":{"pair":"CALM1 -> MIP","headline":"Calmodulin-MIP is supported by UniProt text only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says calmodulin interacts with MIP in a 1:2 stoichiometry, and that binding the cytoplasmic domains of two MIP subunits promotes water channel closure [DB:UniProt].","molecular_requirements":"One calmodulin binds two MIP cytoplasmic domains [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not stated; database record.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only.","key_references":[],"covers":["LR009309"]},"LR008913":{"pair":"CALM3 -> KCNQ3","headline":"Calmodulin binds the KCNQ2/KCNQ3 C-terminal region; support is structural and from UniProt only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt states that calmodulin interacts with the heterotetrameric KCNQ2 and KCNQ3 channel [DB:UniProt].","molecular_requirements":"The crystal structure is of a chimeric Kv7.2-Kv7.3 proximal C-terminal domain in complex with calmodulin, so a KCNQ2 portion is part of the construct [DB:PDB 5J03]. KCNQ3 alone is not shown to suffice.","affinity_potency":[],"species_and_systems":"X-ray diffraction of a chimeric protein fragment [DB:PDB 5J03]; the UniProt statement cites PMID 12871148 and the species is not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Support rests on one PDB record and one UniProt line, with no curated paper. The structure uses a Kv7.2-Kv7.3 chimera, and the UniProt line concerns the KCNQ2/KCNQ3 heterotetramer rather than KCNQ3 alone. The judged paper concerned a different entity.","key_references":[{"PMID":"27564677","why":"Crystal structure of chimeric Kv7.2-Kv7.3 C-terminal domain with calmodulin (PDB 5J03)"}],"covers":["LR008913"]},"LR008463":{"pair":"CALM3 -> MYLK","headline":"CALM3 activates MYLK according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM3 as an activator of MYLK (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. Judged papers were assigned to a different entity (2 rows). Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008463"]},"LR008472":{"pair":"CALM3 -> PDE1C","headline":"CALM3 activates PDE1C according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM3 as an activator of PDE1C (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. One judged paper was review-only. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008472"]},"LR005556":{"pair":"CBLN2 -> GRID2","headline":"CBLN2 binds GRID2 with similar activity to CBLN1 per one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Cbln1 and Cbln2 have similar binding activities to beta-neurexins and Grid2, and ectopic Cbln2 in Purkinje cells rescued cerebellar deficits in Cbln1-null mice [PMID:22117778].","molecular_requirements":"Cbln2 acts by the same bridge with neurexins as Cbln1; no further subunit requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Transgenic and null mice; binding assay species not reported in our evidence; curators recorded human [PMID:22117778]. Human pair is ortholog-inferred.","localisation_and_range":"CBLN2 is flagged secreted and GRID2 transmembrane [flag].","caveats":"Redundancy with Cbln1 holds in cerebellum but not in the thalamic/striatal circuit [PMID:22117778]. Same paper supports CBLN1-GRID2; no database records. A second confirmed paper was not shown.","key_references":[{"PMID":"22117778","why":"Cbln2 shares Grid2 and neurexin binding with Cbln1"}],"covers":["LR002246","LR005556"]},"LR003729":{"pair":"CCL11 -> CCR2","headline":"Conflicting reports: CCL11 (eotaxin) antagonizes CCR2 in one study and acts as an agonist in another; abstract-only evidence.","interaction_type":"conflicting","direction_and_effect":"Eotaxin did not trigger CCR2 even at 1 microM, displaced 125I-MCP-1 and inhibited MCP-1-induced chemotaxis, so is a CCR2 antagonist [PMID:11264152]. A second study states eotaxin-1 acts as a CCR2 agonist and eotaxin-3 as an antagonist [PMID:15207250]. GtoPdb lists a partial agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 7.1-7.7","assay":"GtoPdb record","system":"database","cite":"PMID:15207250"}],"species_and_systems":"Human monocytes and transfected cells [PMID:11264152]; CHO cell lines expressing CCR2 [PMID:15207250]. Mouse pair is projected.","localisation_and_range":"CCL11 flagged secreted, CCR2 transmembrane [flag].","caveats":"The two papers disagree on agonism versus antagonism; abstracts only. Eotaxin triggered CCR5 at 100 nM [PMID:11264152].","key_references":[{"PMID":"11264152","why":"Eotaxin as CCR2 antagonist and CCR5 agonist"},{"PMID":"15207250","why":"CHO lines: eotaxin-1 agonist of CCR2"}],"covers":["LR000184","LR003729"]},"LR001686":{"pair":"CCL17 -> ACKR2","headline":"CCL17 competes for ACKR2-mediated chemokine uptake; ACKR2 is a scavenger, with UniProt support.","interaction_type":"functional only","direction_and_effect":"Decoy/scavenger role: unlabeled CCL17 in 10-fold excess reduced CCL2 uptake by HEK-ACKR2 cells and trophoblasts [PMID:25297873]. UniProt lists CCL17 among ACKR2 chemokines [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK-ACKR2 cells and primary human trophoblasts; mouse Ackr2 deficiency used elsewhere in the paper [PMID:25297873].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Indirect evidence (competition of a CCL2 uptake assay), no direct binding or affinity; browser-read quote not spot-checked.","key_references":[{"PMID":"25297873","why":"Competition of ACKR2 uptake by CCL17"}],"covers":["LR001686","LR005062"]},"LR003738":{"pair":"CCL19 -> CCR7","headline":"Strongly supported direct binding and agonism of CCL19 at CCR7 with picomolar-range affinity and in vivo function.","interaction_type":"direct binding","direction_and_effect":"CCL19 is an agonist: it induced calcium mobilization and chemotaxis in CCR7 (EBI1) transfected cells and HUT78 cells [PMID:9153236]; ELC and SLC were essentially equivalent via CCR7 [PMID:9507024]; in mice, intracutaneous ELC restored T cell trafficking to lymph nodes in plt/plt mice [PMID:11342595].","molecular_requirements":"CCR7 alone sufficed in transfected cells [PMID:9153236][PMID:9507024]; no additional subunits reported in our evidence.","affinity_potency":[{"value":"Kd ~100 pM","assay":"ligand binding","system":"CCR-7-expressing HEK-293E cells","cite":"PMID:10512740"}],"species_and_systems":"Human ligand and receptor in vitro [PMID:9153236][PMID:10512740]; mouse in vivo for the plt/plt rescue [PMID:11342595]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag]. Perivascular ELC is transcytosed to high endothelial venule surfaces [PMID:11342595].","caveats":"All papers read as abstract only except 11342595 (full text), whose CCR7 pairing is background and whose own contribution is transcytosis. GtoPdb records the interaction as agonist [DB:GtoPdb].","key_references":[{"PMID":"9153236","why":"Identifies CCL19 binding specifically to CCR7, calcium and chemotaxis"},{"PMID":"10512740","why":"High-affinity binding, Kd in the 100 pM range"},{"PMID":"11342595","why":"In vivo T cell homing rescue in mice"}],"covers":["LR000210","LR003738"]},"LR003756":{"pair":"CCL2 -> CCR10","headline":"One abstract-read paper with a 1997 receptor named CCR10; identity with current CCR10 is doubtful.","interaction_type":"direct binding","direction_and_effect":"MCP-1 competed for MCP-3 binding to the cloned receptor with IC50 1.2 nM; the paper presents MCP-1 and MCP-3 as the highest-affinity ligands [PMID:9364936].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 1.2 nM","assay":"competition for MCP-3 binding","system":"cloned receptor","cite":"PMID:9364936"}],"species_and_systems":"Human ligand and receptor [PMID:9364936]; expressed mainly in placenta and fetal liver per the abstract [PMID:9364936]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Single abstract-only paper. The same PMID supports CCL2->ACKR2 in this batch, so the receptor may have been mapped to the wrong gene. No database records.","key_references":[{"PMID":"9364936","why":"Cloned receptor binds MCP-1 and MCP-3"}],"covers":["LR000235","LR003756"]},"LR006753":{"pair":"Ccl21c -> Cxcr3","headline":"Thin mouse evidence that CCL21 acts on CXCR3; two abstract-read papers that do not distinguish Ccl21c.","interaction_type":"functional only","direction_and_effect":"A chemokine screen on mouse CXCR3-transfected cells identified CCL21 (6Ckine) as a new ligand inducing calcium flux [PMID:9653165]. Lower-affinity binding of SLC/6Ckine/Exodus 2 to murine CXCR3 was also seen [PMID:10556837].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse CXCR3-transfected cells [PMID:9653165] and murine CXCR3 in L1.2 cells [PMID:10556837]; the ligand source species was labelled human in one record.","localisation_and_range":"Ligand flagged secreted and receptor flagged a receptor [flag]; no transmembrane flag is given.","caveats":"Abstract-only reads; no affinity for CCL21 quoted. Binding was lower affinity than for IP10, ITAC and Mig [PMID:10556837]. The papers say CCL21 generically, so Ccl21c is not resolved. No database record; one further paper was abstract_insufficient.","key_references":[{"PMID":"9653165","why":"CCL21 identified as mouse CXCR3 ligand"},{"PMID":"10556837","why":"lower-affinity binding to murine CXCR3"}],"covers":["LR006753"]},"LR008283":{"pair":"CCL24 -> ACKR2","headline":"Asserted only by UniProt's list of chemokines recognised by ACKR2; no paper evidence is shown.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ACKR2 acts as a receptor for chemokines including CCL24 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence.","localisation_and_range":"Ligand flagged secreted, ACKR2 flagged transmembrane [flag].","caveats":"No paper was confirmed; the one judged paper was review-only. UniProt text cites PMIDs 18201974 and 23479571, which are not shown as judged papers [DB:UniProt].","key_references":[],"covers":["LR008283"]},"LR003747":{"pair":"CCL24 -> CCR3","headline":"CCL24 is an established CCR3 agonist, but our evidence for it is mostly indirect or background statements.","interaction_type":"functional only","direction_and_effect":"Agonist: CCR3 is described as a primary receptor for eotaxin-2 [PMID:15207250]. Eotaxin and eotaxin-2 chemotactic responses of dendritic cells were inhibited by CCR3-specific antibodies [PMID:12218106]. In CCR3-expressing L1.2 cells, calcium mobilisation potency ranked eotaxin, MCP-4 > eotaxin-3 > eotaxin-2, RANTES [PMID:10488147]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR3 alone was used in these systems; no co-receptor requirement is reported in our evidence.","affinity_potency":[{"value":"pIC50 8.0-9.4","assay":"GtoPdb affinity range, unspecified assay","system":"database record","cite":"PMID:15207250"}],"species_and_systems":"Human ligand and receptor: engineered CHO cells [PMID:15207250], human dendritic cells [PMID:12218106], L1.2 transfectants [PMID:10488147]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"PMID 16339911 names CCL24 only as background and gives no CCL24-specific data. PMID 15207250 and 12218106 treat the pairing as known, not newly shown. Abstracts only, except PMID 10488147 curated from browser reading, with spot-check pending.","key_references":[{"PMID":"12218106","why":"Antibody blockade of CCR3 inhibits dendritic-cell chemotaxis to eotaxin-2"},{"PMID":"10488147","why":"Relative CCR3 calcium potency of eotaxin-2"},{"PMID":"15207250","why":"High-expression CCR3 cell line used with eotaxins"}],"covers":["LR000221","LR003747"]},"LR001695":{"pair":"CCL4L1 -> CCR3","headline":"One paper shows CCL4L1 behaves like CCL4 in chemotaxis assays on CCR3-expressing cells; no binding data for CCR3.","interaction_type":"functional only","direction_and_effect":"Chemotaxis assays with CCR3-expressing cells showed no substantial difference between CCL4L1 and CCL4 [PMID:15240137]. The curator labels this agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant: CCL4L1 produced in E. coli, tested on cells expressing the receptor [PMID:15240137]. The curator labels both species human.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"CCL4L1 differs from CCL4 by a single amino acid, so the evidence is a paralog comparison, not a CCL4L1-specific affinity. Abstract-level read; no database record. CCR3-specific binding is not reported in our evidence.","key_references":[{"PMID":"15240137","why":"CCL4L1 vs CCL4 binding and chemotaxis at CCR1, CCR3 and CCR5"}],"covers":["LR001695"]},"LR003765":{"pair":"CCL5 -> ACKR2","headline":"CCL5 binds human D6/ACKR2 in competition binding; ACKR2 is a non-signalling scavenger receptor.","interaction_type":"direct binding","direction_and_effect":"Human D6 (ACKR2) bound RANTES in ligand displacement on CHO cells [PMID:9405404]. D6 is promiscuous for beta-chemokines and, per the abstract, does not appear to flux calcium on ligand binding [PMID:9405404]. Unlabeled CCL5 reduced CCL2 uptake in HEK-ACKR2 cells and trophoblasts, consistent with scavenging [PMID:25297873].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 in stably transfected CHO cells with 125I-labeled murine MIP-1a tracer [PMID:9405404]; HEK-ACKR2 cells and primary trophoblasts [PMID:25297873]. The mouse pair is inferred from human evidence.","localisation_and_range":"ACKR2 is transmembrane [flag]; chemokine is taken up and not signalled through (curator notes) [PMID:25297873].","caveats":"BioGRID and UniProt also list CCL5 [DB:BioGRID, DB:UniProt]. PMID:25297873 was read via browser; the quote is unverified. PMID:9405404 lacks a CCL5 affinity value in our evidence.","key_references":[{"PMID":"9405404","why":"Human D6 binds RANTES; displacement assay"},{"PMID":"25297873","why":"CCL5 competes for ACKR2-mediated CCL2 uptake"}],"covers":["LR000255","LR003765"]},"LR005565":{"pair":"CCL5 -> CCR10","headline":"Thin, abstract-only support: RANTES competes with MCP-3 for binding to a receptor named CCR10 (IC50 5.4 nM); no signalling shown.","interaction_type":"direct binding","direction_and_effect":"RANTES and MCP-4 competed for 125I-MCP-3 binding to CCR10, with IC50 values of 5.4 nM for RANTES; CCR10 binds MCP-1 and MCP-3 with highest affinity [PMID:9364936]. No agonism or effect is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 5.4 nM","assay":"competition for MCP-3 binding","system":"CCR10, human","cite":"PMID:9364936"}],"species_and_systems":"Human receptor, as stated in the paper [PMID:9364936]; cell system not given in the abstract. The mouse pair is inferred from human evidence.","localisation_and_range":"CCR10 is transmembrane and a receptor [flag]; the paper reports expression mainly in placenta and fetal liver [PMID:9364936].","caveats":"One paper, abstract only; binding is by competition with MCP-3, not RANTES itself as tracer. No database record.","key_references":[{"PMID":"9364936","why":"CCR10 cloning; RANTES competes with MCP-3 at 5.4 nM"}],"covers":["LR002264","LR005565"]},"LR003774":{"pair":"CCL7 -> ACKR2","headline":"Human ACKR2 (D6) binds MCP-3 (CCL7) in competition binding on CHO cells; no affinity value and no calcium signalling in our evidence.","interaction_type":"direct binding","direction_and_effect":"Human D6 binds many CC chemokines; the full text states binding is seen with RANTES, MCP3, MCP4 and HCC1 [PMID:9405404]. D6 did not flux calcium after ligand binding, so signalling is unclear [PMID:9405404]. BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt lists CCL7 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 stably expressed in CHO cells, 125I-MIP-1a tracer [PMID:9405404].","localisation_and_range":"CCL7 flagged secreted; ACKR2 flagged transmembrane receptor [flag].","caveats":"No affinity reported for MCP-3 specifically. Promiscuous binder, so specificity for CCL7 is low. A second confirmed row cites PMID:9364936, which is about CCR10, not ACKR2.","key_references":[{"PMID":"9405404","why":"D6/ACKR2 promiscuous CC chemokine binding including MCP3"}],"covers":["LR000264","LR003774"]},"LR003783":{"pair":"CCL8 -> ACKR4","headline":"One paper reports MCP-2 (curator-mapped to CCL8) binding the receptor called CCR11 (ACKR4) with IC50 0.45 nM; interpretation is contested.","interaction_type":"direct binding","direction_and_effect":"MCP-2 was the second most potent competitor of radiolabelled MCP-4 binding (IC50 0.45 nM) and MCP-2 induced chemotaxis of L1.2 cells expressing the receptor [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 0.45 nM","assay":"competition vs radiolabelled MCP-4","system":"receptor-transfected murine L1.2 cells (human receptor)","cite":"PMID:10734104"}],"species_and_systems":"Human ligand and receptor expressed in murine L1.2 cells [PMID:10734104]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL8 flagged secreted; ACKR4 flagged transmembrane receptor [flag].","caveats":"Abstract only. Curator notes say the accepted ACKR4 ligands differ, so MCP-family claims were not upheld. Equating MCP-2 with CCL8 is the curators' mapping, not stated in the dossier. No database records.","key_references":[{"PMID":"10734104","why":"MCP-2 binds CCR11/ACKR4, IC50 0.45 nM"}],"covers":["LR000273","LR003783"]},"LR003918":{"pair":"CCN1 -> ITGAV","headline":"CCN1 binds integrin alphavbeta3 and alphavbeta5 directly; the alphav chain alone is not the functional unit.","interaction_type":"direct binding","direction_and_effect":"Purified alphavbeta3 bound Cyr61-Sepharose and soluble Cyr61 bound immobilized alphavbeta3, with endothelial adhesion blocked by RGDS and the alphavbeta3 antibody LM609 [PMID:9446626]. Cyr61 bound directly to purified alphavbeta5, which mediated fibroblast migration, while alphavbeta3 was linked to mitogenesis [PMID:11287419].","molecular_requirements":"ITGAV acts as a heterodimer: with beta5 for migration and with beta3 for mitogenesis enhancement [PMID:11287419]; alphavbeta3 adhesion was RGD-peptide sensitive and divalent-cation dependent [PMID:9446626].","affinity_potency":[{"value":"approximately 5 nM half-saturation","assay":"solid-phase binding, soluble Cyr61 to immobilized alphavbeta3","system":"purified integrin","cite":"PMID:9446626"}],"species_and_systems":"Human CCN1 (Cyr61), human umbilical vein endothelial cells and human skin fibroblasts, purified integrins. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Both papers were read as abstracts only. Half-saturation binding is not a formal Kd. One more paper was judged abstract-insufficient and one is pending.","key_references":[{"PMID":"9446626","why":"Direct alphavbeta3 binding with about 5 nM half-saturation"},{"PMID":"11287419","why":"Direct alphavbeta5 binding; distinct beta-chain roles"}],"covers":["LR000421","LR003918"]},"LR005574":{"pair":"CCN2 -> FGFR3","headline":"CCN2 bound FGFR3 in a protein-array screen, with weaker affinity than for FGFR2; thin abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"CCN2 could bind FGFR2 and FGFR3 in a protein-array screen, with higher affinity toward FGFR2 [PMID:23142580]. Effect on FGFR3 signalling is not reported in our evidence; follow-up work in the paper concerned FGFR2.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Protein array; species not specified in the abstract [PMID:23142580]. IntAct holds the protein-array record [DB:IntAct].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Based on a single screening result in an abstract; no confirmatory binding, affinity or functional data for FGFR3 are reported in our evidence [PMID:23142580].","key_references":[{"PMID":"23142580","why":"Protein-array screen showing CCN2 binding to FGFR2 and FGFR3"}],"covers":["LR002273","LR005574"]},"LR003891":{"pair":"CCN2 -> LRP1","headline":"LRP is reported as a heparin-dependent adhesion receptor for CTGF in rat hepatic stellate cells; abstract-level.","interaction_type":"direct binding","direction_and_effect":"LRP is a receptor for CTGF(1-4) or CTGF(3-4) but not CTGF(4). Blocking LRP with RAP, anti-LRP or a thrombospondin type I peptide reduced adhesion of activated HSCs by 50% [PMID:14585398]. Signalling outcome is not reported in our evidence.","molecular_requirements":"Modules 3-4 are needed: the module-4-only isoform did not use LRP [PMID:14585398]. Cell-surface heparan sulfate proteoglycans were binding sites for all isoforms, and heparin or heparinase fully blocked adhesion, so the interaction is heparin-dependent [PMID:14585398].","affinity_potency":[],"species_and_systems":"Rat activated hepatic stellate cells, rat proteins [PMID:14585398]. The human and mouse pairs are ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. Action is adhesion to matrix-presented CTGF.","caveats":"Abstract read only. The protein is called LRP, and the abstract does not say LRP1 specifically. No affinity value is given. Adhesion blockade was only partial (50%).","key_references":[{"PMID":"14585398","why":"LRP as a heparin-dependent CTGF adhesion receptor in rat HSCs"}],"covers":["LR000385","LR003891"]},"LR007950":{"pair":"CD226 -> NECTIN2","headline":"Well supported: Nectin-2 (CD112) binds the activating receptor CD226 (DNAM-1) by reciprocal Fc-chimera staining and cytotoxicity assays.","interaction_type":"direct binding","direction_and_effect":"Nectin-2-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained Nectin-2 CHO-K transfectants; the specific DNAM-1/Nectin-2 interaction between NK and target cells enhanced NK-mediated tumour cell lysis [PMID:15607800]. CD112 expression on mouse BW5147 cells raised susceptibility to IL-2-activated T and NK killing, blocked by anti-CD226 mAb [PMID:15039383].","molecular_requirements":"Soluble CD226 bound CD155 and CD112 with comparable affinity, but homophilic CD112 interaction on the cell surface may adversely affect CD226 binding [PMID:15039383]. CD226 and LFA-1 ligation cooperate in cytotoxicity and cytokine secretion [PMID:15039383].","affinity_potency":[],"species_and_systems":"Human proteins; COS-7, CHO-K and BW5147 transfectants and NK/T cells [PMID:15607800][PMID:15039383].","localisation_and_range":"Both partners flagged transmembrane [flag]; contact-dependent between NK/T cell and target.","caveats":"No numeric affinity in our evidence. PMID:30759143 only states CD226 binding to nectin-2 as background. Another paper was judged abstract_insufficient. Reconstituted-complex, IntAct and Reactome records agree [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"15039383","why":"CD112 and CD155 identified as CD226 ligands"},{"PMID":"15607800","why":"Reciprocal Fc-chimera binding and NK lysis"}],"covers":["LR007950"]},"LR005079":{"pair":"Cd244a -> Cd48","headline":"Mouse pair supported by one foundational direct-binding paper, using mouse 2B4 and CD48 recombinant proteins.","interaction_type":"direct binding","direction_and_effect":"Recombinant mouse 2B4 on beads bound rodent cells and binding was completely blocked by CD48 mAbs; purified soluble mouse CD48 bound mouse 2B4 [PMID:9841922]. Signalling effect not reported in our evidence.","molecular_requirements":"Extracellular region of 2B4 sufficient for binding [PMID:9841922]. CD48 has a second ligand, CD2, with 6- to 9-fold lower affinity than 2B4 [PMID:9841922].","affinity_potency":[{"value":"Kd approximately 16 microM at 37 degreesC","assay":"surface plasmon resonance","system":"purified soluble mouse CD48 with mouse 2B4","cite":"PMID:9841922"}],"species_and_systems":"Mouse proteins and rodent cells (rat cell line binding also shown); human CD48-2B4 Kd was approximately 8 microM in the same paper [PMID:9841922]. Curated experiment species are recorded as human, which fits only the human measurement.","localisation_and_range":"2B4 flagged not secreted [flag]; UniProt describes CD48 as GPI-anchored cell-surface [DB:UniProt]; contact-dependent.","caveats":"Single paper plus UniProt statements. Affinity is weak. The curated affinity (8000 nM) is the human value, not the mouse one.","key_references":[{"PMID":"9841922","why":"Identified 2B4 as a CD48 ligand in rodents and humans"}],"covers":["LR005079"]},"LR005583":{"pair":"Cd24a -> Sele","headline":"Nanomolar SPR binding of CD24 to E-selectin from one paper using human MCF-7 cells; the mouse pair is projected by orthology.","interaction_type":"direct binding","direction_and_effect":"CD24 on MCF-7 cells was responsible for cell rolling on E-selectin; rolling was completely blocked by anti-CD24 [PMID:21207944]. Binding was directly measured by SPR [PMID:21207944].","molecular_requirements":"The binding is Ca2+-dependent, shown with CD24-coated microspheres on E-selectin surfaces; actin filaments are involved in rolling [PMID:21207944].","affinity_potency":[{"value":"KD = 3.4 \u00b1 0.7 nM","assay":"surface plasmon resonance","system":"CD24 and E-selectin (MCF-7-derived CD24)","cite":"PMID:21207944"}],"species_and_systems":"Human MCF-7 breast cancer cells; the mouse pair is inferred from human evidence (ortholog_inferred) [PMID:21207944].","localisation_and_range":"CD24 is flagged membrane-bound, E-selectin not secreted [flag]; cell-contact rolling interaction.","caveats":"One paper, read as abstract only for the curated row, and no direct mouse experiment. The curated system is MCF-7 / SPR; which species' E-selectin was used is not stated in our evidence.","key_references":[{"PMID":"21207944","why":"SPR affinity and rolling assays for CD24-E-selectin"}],"covers":["LR005583"]},"LR003792":{"pair":"CD34 -> SELL","headline":"CD34 as an L-selectin ligand is supported by several abstract-only papers, but the strongest direct data are on a mouse lymph-node glycoform.","interaction_type":"direct binding","direction_and_effect":"Sgp90 from high endothelial venules has a protein core identical to CD34, and an HEV glycoform of CD34 can function as an L-selectin ligand [PMID:7692600]. Neutrophils tethered and rolled on CD34 at comparable site density to E- and P-selectin, rolling 7.5- to 10.5-fold faster on CD34 [PMID:8977216]. Interaction annotated stimulatory [flag].","molecular_requirements":"Sulfated carbohydrate structures (6-sulfo-sLex) on the mucin domain are described as the recognition determinant, but this is background in [PMID:12889478], not tested there.","affinity_potency":[],"species_and_systems":"Murine CD34 antiserum and lymph-node endothelium in [PMID:7692600]; human neutrophils/lymphocytes in flow assays [PMID:8977216]. Mouse interaction listed as not ortholog-inferred.","localisation_and_range":"CD34 flagged transmembrane, not secreted [flag]; mediates leukocyte-endothelium contact and rolling.","caveats":"All papers abstract only. [PMID:12889478] concerns endoglycan and cites CD34 only as background. [PMID:8977216] is a rolling-adhesion measurement, not a binding assay. No affinity reported.","key_references":[{"PMID":"7692600","why":"HEV glycoform of CD34 functions as L-selectin ligand"},{"PMID":"8977216","why":"Neutrophil rolling on CD34 versus E-/P-selectin"}],"covers":["LR000282","LR003792"]},"LR002289":{"pair":"CD40LG -> ITGA5","headline":"Soluble CD40L binds alpha5beta1 integrin, with lower affinity than for alphaIIbbeta3; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"CD154 bound alpha5beta1 with about 4-fold lower affinity than alphaIIbbeta3, and sCD154 bound CD40 and alpha5beta1 simultaneously on U937 cells, activating p38 and ERK1/2 and synergising in MMP-2/MMP-9 release [PMID:22461623]. sCD40L activated soluble alpha5beta1 in cell-free conditions [PMID:33571526].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer, not ITGA5 alone. CD154 mutants that lost CD40 or alphaIIbbeta3 binding still bound alpha5beta1 [PMID:22461623]. UniProt: ITGA5:ITGB3 is a receptor for soluble CD40LG [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human U937 cells [PMID:22461623]; soluble integrins and CHO cells [PMID:33571526]; mouse pair projected.","localisation_and_range":"CD40LG flagged secreted [flag]; soluble form acts at a distance [PMID:33571526].","caveats":"Both papers read as abstracts (one marked full text); no absolute affinity values reported; chain-only attribution.","key_references":[{"PMID":"22461623","why":"CD154 binds alpha5beta1, simultaneous with CD40"},{"PMID":"33571526","why":"sCD40L activates alpha5beta1"}],"covers":["LR002289","LR005588"]},"LR005592":{"pair":"CD47 -> THBS1","headline":"CD47 and thrombospondin-1 signal in human red cells, but the pair lists them in reversed roles; evidence is functional.","interaction_type":"functional only","direction_and_effect":"Per the abstract, TSP-1 signals through its cognate receptor CD47; recombinant human TSP-1 raised red blood cell Ca2+ and an amiloride-sensitive inward current, promoted microparticle shedding and cell death, and an anti-CD47 antibody (1F7) recapitulated the death-inducing effects [PMID:32948210]. UniProt calls THBS1 a ligand for CD47 and CD47 a THBS1 receptor [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond a CD47 receptor role for TSP-1 [PMID:32948210].","affinity_potency":[],"species_and_systems":"Human red blood cells and recombinant human TSP-1; CD47 ligation with a mouse IgG1 antibody [PMID:32948210]. Mouse pair is ortholog-inferred.","localisation_and_range":"THBS1 carries a secreted flag and CD47 transmembrane and receptor flags [flag], matching a secreted TSP-1 acting on membrane CD47 [DB:UniProt].","caveats":"Paper is abstract-only (with excerpts) and shows function, not a binding assay. Direction in the pair is the reverse of the biology described [PMID:32948210].","key_references":[{"PMID":"32948210","why":"TSP-1/CD47 signalling in human red blood cells"}],"covers":["LR002293","LR005592"]},"LR005097":{"pair":"CD86 -> CD28","headline":"CD86 binds and activates CD28, supported by binding comparisons, functional studies and databases; the evidence is mixed in species.","interaction_type":"direct binding","direction_and_effect":"CD86 is a stimulatory CD28 ligand: human CD86 kept binding and costimulation within about 2- to 3-fold of CD80 [PMID:7534620]. In memory CD4 T cells, CD86 was the dominant ligand for Treg proliferation, survival and phenotype [PMID:33363541]. In mouse T cells CD86 alone costimulated IL-4 and IL-10 [PMID:9184909]. CD80/CD86-CD28 interactions were implicated in CD8+CD122+ regulatory T-cell action [PMID:18205792].","molecular_requirements":"CD86 and CD80 use different binding determinants and kinetics for CD28 and CTLA-4 [PMID:7534620]. CD80-CD28 interactions were compromised by CTLA-4 on Treg cells, CD86-CD28 was not similarly affected [PMID:33363541].","affinity_potency":[],"species_and_systems":"Human cells and proteins [PMID:7534620] [PMID:33363541]; murine T cells for PMID:9184909; species not listed for PMID:18205792. Both human and mouse pairs are in the dossier. Databases show surface plasmon resonance and Reactome binding reactions [DB:IntAct] [DB:Reactome].","localisation_and_range":"CD86 is membrane-bound on antigen-presenting cells, with a transmembrane flag [flag].","caveats":"Papers were read as abstracts, with excerpts for PMID:33363541. No numeric affinity for CD86-CD28 in our evidence. PMID:21530327 mainly concerns B7-H2. Several readouts use blocking antibodies or CHO/P815 transfectants [PMID:33363541] [PMID:9184909].","key_references":[{"PMID":"7534620","why":"Quantitative comparison of CD86 and CD80 receptor binding"},{"PMID":"33363541","why":"CD86 is the dominant CD28 ligand for Treg homeostasis"},{"PMID":"9184909","why":"CD86 costimulation drives Th2 responses"}],"covers":["LR001732","LR005097"]},"LR002298":{"pair":"CD8A -> HLA-A","headline":"CD8 alpha binds the HLA class I alpha-3 domain as a coreceptor; one 1993 paper read as abstract plus UniProt.","interaction_type":"functional only","direction_and_effect":"CD8 interacts with MHC class I through an acidic loop in the alpha-3 domain; mutations reduced binding of mutant-HLA cells to CD8-alpha-transfected CHO cells, with residue 227 having the greatest effect [PMID:8320133]. Efficient CD8-MHC I interaction was needed for continued expansion of allogeneic CTLs [PMID:8320133].","molecular_requirements":"UniProt: one HLA-A molecule interacts (mainly via the alpha-3 domain) with one CD8A homodimer [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human HLA-A*0201 transfectants, donor PBLs and CD8-alpha CHO cells [PMID:8320133].","localisation_and_range":"Membrane-bound, contact-dependent coreceptor interaction; the CD8A 'secreted' flag in the entity annotation is not supported by the text [flag].","caveats":"Abstract only; no affinity reported; CD8A is a coreceptor for MHC rather than a conventional signalling ligand.","key_references":[{"PMID":"8320133","why":"CD8-HLA alpha-3 domain interaction needed for CTL differentiation"}],"covers":["LR002298"]},"LR005619":{"pair":"CDH8 -> CDH8","headline":"Cadherin-8 homophilic binding is weaker than its binding to cadherin-11 in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"Cadherin-8 binds itself: homophilic cadherin-8 binding followed heterophilic cadherin-11 binding on the cadherin-8 surface [PMID:29742438].","molecular_requirements":"Cadherin-8 and -11 form one specificity group preferring each other [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"Homophilic and heterophilic cadherin-8 SPR"}],"covers":["LR002321","LR005619"]},"LR006843":{"pair":"CEACAM1 -> SELE","headline":"Database-only evidence; the single IntAct solid phase record is the only support.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper. IntAct records a solid phase assay between the two proteins [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the IntAct record.","localisation_and_range":"SELE is annotated non-secreted, transmembrane [flag].","caveats":"Three papers were judged to be about a different entity and one was abstract-insufficient, so none confirm this pair. Interaction class is Adhesion-Adhesion rather than Ligand-Receptor.","key_references":[],"covers":["LR006843"]},"LR005628":{"pair":"CIRBP -> TLR4","headline":"Extracellular CIRP binds TLR4 and the TLR4-MD2 complex by SPR and acts as a pro-inflammatory agonist; one paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant CIRP stimulates TNF-alpha and HMGB1 release from macrophages and causes tissue injury in vivo; CIRP-deficient mice had reduced hemorrhage-induced TNF-alpha/HMGB1 release and lethality [PMID:24097189]. Annotated agonist by curators [PMID:24097189].","molecular_requirements":"CIRP binds the TLR4-MD2 complex as well as TLR4 and MD2 individually [PMID:24097189].","affinity_potency":[],"species_and_systems":"SPR with human proteins; macrophages and animal models of hemorrhage and sepsis [PMID:24097189].","localisation_and_range":"CIRP flagged secreted [flag]; released into the circulation [PMID:24097189].","caveats":"Single paper, read as abstract; no affinity value reported in our evidence. Functional effects were not shown to be TLR4-dependent in our evidence.","key_references":[{"PMID":"24097189","why":"SPR binding of CIRP to TLR4, MD2 and TLR4-MD2; in vivo effects"}],"covers":["LR002345","LR005628"]},"LR001749":{"pair":"CLEC2B -> KLRF1","headline":"AICL (CLEC2B) binds NKp80 (KLRF1) in two human abstract-level papers, with database support; the pair is absent from rodents.","interaction_type":"functional only","direction_and_effect":"NKp80 binds AICL, promoting NK-cell cytolysis of malignant myeloid cells and cytokine release from NK cells and monocytes [PMID:17057721]. Monokine-converted NK cells upregulate surface AICL and downregulate NKp80, becoming targets of NKp80-mediated killing by other NK cells [PMID:23929856].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK cells, monocytes and myeloid cells [PMID:17057721][PMID:23929856]. Reactome and IntAct list the pair [DB:Reactome][DB:IntAct]; UniProt lists the interaction [DB:UniProt].","localisation_and_range":"Both partners are membrane-bound (flags), so contact-dependent [flag]. Paper says the pair is absent from rodents [PMID:17057721].","caveats":"Both papers abstract only; neither gives an affinity. The 2013 evidence sentence refers to earlier studies [PMID:23929856].","key_references":[{"PMID":"17057721","why":"Shows NKp80 binds AICL and function"},{"PMID":"23929856","why":"AICL surface regulation and NKp80 killing"}],"covers":["LR001749"]},"LR005637":{"pair":"CLU -> LRP2","headline":"Clusterin binds LRP2/megalin (gp330) directly with Kd 14.2 nM and is endocytosed; two abstract-only papers plus database records.","interaction_type":"direct binding","direction_and_effect":"gp330 (LRP2) bound apoJ/clusterin with high affinity, and only gp330-expressing cells endocytosed and degraded 125I-apoJ, so LRP2 acts as an uptake receptor [PMID:7768901]. A second paper reports a separate LRP-2 binding class on clusterin [PMID:11772027].","molecular_requirements":"LRP (LRP1) showed no binding to apoJ in either assay type, so the binding is gp330-specific; competed by apoE, lipoprotein lipase and RAP [PMID:7768901]. Clusterin has three independent binding-site classes, one for LRP-2; recombinant Pichia clusterin with truncated alpha C-terminus and beta N-terminus still used it [PMID:11772027].","affinity_potency":[{"value":"Kd 14.2 nM","assay":"solid-phase binding assay","system":"purified gp330 and apoJ (human milk-derived apoJ)","cite":"PMID:7768901"}],"species_and_systems":"Human clusterin and receptor per the dossier [PMID:7768901][PMID:11772027]; cultured cell lines and F9 cells for uptake.","localisation_and_range":"Clusterin is flagged secreted [flag]; receptor-mediated endocytosis by epithelial cells [PMID:7768901].","caveats":"Both papers abstract-only. Databases: BioGRID (reconstituted complex) and UniProt list the interaction [DB:BioGRID 298080][DB:UniProt P10909]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"7768901","why":"gp330 binds apoJ, Kd 14.2 nM, and mediates endocytosis; LRP1 does not bind"},{"PMID":"11772027","why":"Clusterin has a discrete LRP-2 binding site"}],"covers":["LR002357","LR005637"]},"LR005646":{"pair":"CNTN2 -> CNTN2","headline":"Homophilic CNTN2 self-association shown by bead aggregation in one paper.","interaction_type":"direct binding","direction_and_effect":"TAG-1-Fc displays homophilic interactions by forming self-aggregates of moderate size (14 beads) [PMID:12139915]. Isolated Ig domains gave few small aggregates [PMID:12139915].","molecular_requirements":"Fibronectin repeats mediate homophilic aggregation by the abstract's statement [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human TAG-1 Fc chimeras on beads [PMID:12139915]. Mouse pair inferred.","localisation_and_range":"Adhesion in trans between cells (paper context); CNTN2 carries a secreted flag [flag].","caveats":"Single paper; self-binding, so ligand/receptor direction is not meaningful. No affinity reported.","key_references":[{"PMID":"12139915","why":"TAG-1 bead homophilic aggregation"}],"covers":["LR002366","LR005646"]},"LR010974":{"pair":"CNTN2 -> L1CAM","headline":"Conflicting: Fc-chimera binding reported between TAG-1 and L1, but another paper found no trans interaction.","interaction_type":"conflicting","direction_and_effect":"Fc-chimeric binding reported TAG-1 interacts with L1 [PMID:12139915], but L1-CAM and TAG-1 were unable to interact when expressed on different cells (trans) in S2 cells [PMID:9837910]. A cis complex was described in that paper's title [PMID:9837910].","molecular_requirements":"L1-deficient mouse DRG neurons still extended neurites on TAG-1, so L1 is not required for TAG-1 outgrowth activity [PMID:12139915]. In bead assays TAG-1-Fc did not form mixed aggregates with L1-Fc beads [PMID:12139915].","affinity_potency":[],"species_and_systems":"Fc chimeras, human [PMID:12139915]; Drosophila S2 cells [PMID:9837910].","localisation_and_range":"Cis (same membrane) rather than trans per the negative paper [PMID:9837910]; CNTN2 flagged secreted, L1CAM secreted and transmembrane [flag].","caveats":"Both are abstract-level for the negative result; the binding result is in conflict with the same paper's bead data.","key_references":[{"PMID":"9837910","why":"Negative trans-interaction result; cis complex"},{"PMID":"12139915","why":"Fc-chimera binding report"}],"covers":["LR010974"]},"LR003819":{"pair":"CNTN4 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN4; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN4 is annotated secreted and PTPRG non-secreted [flag].","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN4 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR000313","LR003819"]},"LR006852":{"pair":"COL11A1 -> ITGA2:ITGB1","headline":"Evidence is an abstract-level TNBC study showing COL11A1 binding to ITGB1 only; the named integrin heterodimer is not tested.","interaction_type":"functional only","direction_and_effect":"COL11A1 promoted TNBC metastasis by binding ITGB1, initiating a FAK/YAP cascade; siRNA and rotating magnetic fields suppressed tumour growth and lung metastasis, reversed by an ITGB1 agonist [PMID:41391796].","molecular_requirements":"The paper names the integrin b1 chain only; the alpha subunit (ITGA2) is not reported in our evidence, so the heterodimer assignment is not supported [PMID:41391796].","affinity_potency":[],"species_and_systems":"TNBC cells and an in vivo tumour model; the abstract does not give host species [PMID:41391796].","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; no alpha-subunit-specific data. Other judged papers were review-only, so no primary support for this heterodimer in our evidence [PMID:41391796].","key_references":[{"PMID":"41391796","why":"COL11A1 binding ITGB1 in TNBC"}],"covers":["LR006852"]},"LR005655":{"pair":"COL11A2 -> DDR2","headline":"Support is indirect: a paper on collagen type XI with no chain identification, plus IntAct records for the pair.","interaction_type":"functional only","direction_and_effect":"DDR2 mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. IntAct records cite surface plasmon resonance and NMR from PMID 17703188, which is not among the judged papers [DB:IntAct P13942-Q16832].","localisation_and_range":"COL11A2 is annotated secreted and not transmembrane [flag].","caveats":"The curated paper refers to collagen type XI generally, not COL11A2; the IntAct records are the only pair-specific support and their paper is not in our judged set [PMID:36233024][DB:IntAct P13942-Q16832].","key_references":[{"PMID":"36233024","why":"Collagen XI binding to DDR2 in CAFs (chain not specified)"}],"covers":["LR002376","LR005655"]},"LR002379":{"pair":"COL13A1 -> ITGA11","headline":"Integrin a11b1 binds collagen XIII by SPR and pull-down and mediates cell adhesion; mouse bone data support function.","interaction_type":"direct binding","direction_and_effect":"Integrin a11b1 is a receptor for collagen XIII: C2C12 cells expressing a11b1 as their only collagen receptor adhered to it, and SPR and pull-down assays confirmed the interaction [PMID:33306155]. a11b1 mediates adhesion to the motifs GPKGER and GF(S)QGEK [PMID:33306155]. Effect labelled agonist.","molecular_requirements":"Binding is by the heterodimer; the a11-I domain recognises the motifs, with docking to a homology model [PMID:33306155].","affinity_potency":[],"species_and_systems":"C2C12 cells expressing human a11b1, recombinant assays and mice (Itga11-/- crossed with Col13a1-overexpressing mice) [PMID:33306155].","localisation_and_range":"COL13A1 is annotated non-secreted and transmembrane [flag]; the paper calls it a transmembrane collagen [PMID:33306155].","caveats":"Abstract-level read plus excerpts; no affinity values in our evidence. The in vivo bone phenotype was milder in double mutants than in Col13a1 overexpression alone [PMID:33306155].","key_references":[{"PMID":"33306155","why":"a11b1 as a collagen XIII receptor with SPR, pull-down and in vivo data"}],"covers":["LR002379","LR005658"]},"LR003828":{"pair":"COL1A1 -> CD44","headline":"Purified lymphocyte CD44 binds native type I collagen fibrils in one 1992 paper whose focus is fibronectin.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified CD44 bound native type I collagen fibrils, laminin and fibronectin, but not gelatin [PMID:1730778]. Effect on signalling: not reported in our evidence.","molecular_requirements":"Fibronectin binding was via the chondroitin sulfate-containing form of CD44 [PMID:1730778]; whether this applies to collagen: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Affinity-purified lymphocyte CD44 antigen in a protein binding assay [PMID:1730778]. Species is not stated in the dossier beyond lymphocytes.","localisation_and_range":"Receptor is a lymphocyte surface glycoprotein; collagen is matrix.","caveats":"Collagen binding is a side observation in a paper mainly about fibronectin; no affinity; abstract plus limited excerpts only. Not resolved to the COL1A1 chain.","key_references":[{"PMID":"1730778","why":"Purified CD44 binds native type I collagen fibrils"}],"covers":["LR000322","LR003828"]},"LR008670":{"pair":"COL1A1 -> ITGA5","headline":"No curated paper supports this pair; the only record is a BioGRID entry for COL1A1-ITGB1.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond the annotated stimulatory effect.","molecular_requirements":"Not reported in our evidence; ITGA5 is annotated with the name integrin alpha5beta1 [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No papers were confirmed (4 abstract_insufficient). The only database record is BioGRID COL1A1-ITGB1 co-purification from PMID 2156854, which concerns ITGB1, not ITGA5 [DB:BioGRID].","key_references":[],"covers":["LR008670"]},"LR005664":{"pair":"COL1A1 -> OSCAR","headline":"OSCAR is reported as a collagen receptor costimulating osteoclastogenesis; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"OSCAR is a collagen receptor that costimulates osteoclastogenesis in DAP12-deficient humans and mice; recorded as agonist [PMID:21841309].","molecular_requirements":"OSCAR signals through ITAM-containing adaptors (FcR gamma, DAP12 named in the abstract) [PMID:21841309]; the specific requirement for this pair is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse osteoclast differentiation cells [PMID:21841309].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract only. A collagen assay cannot separate COL1A1 from COL1A2. The evidence sentence does not itself state binding. No database support.","key_references":[{"PMID":"21841309","why":"OSCAR identified as collagen receptor"}],"covers":["LR002385","LR005664"]},"LR001758":{"pair":"COL1A2 -> GP6","headline":"Recombinant GPVI binds collagen; evidence is for collagen generally, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant GPVI bound collagen and convulxin, and soluble GPVI blocked collagen-induced platelet aggregation [PMID:10961879]. Annotated effect is stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human and mouse GPVI [PMID:10961879].","localisation_and_range":"GP6 is a platelet receptor; collagen is matrix [flag].","caveats":"Abstract-only. Evidence is for collagen generically, not resolved to COL1A2; type I collagen is a heterotrimer. No database support.","key_references":[{"PMID":"10961879","why":"GPVI binds collagen; soluble GPVI blocks aggregation"}],"covers":["LR001758","LR005116"]},"LR003837":{"pair":"COL1A2 -> ITGA1","headline":"Alpha1 I-domain bound type I collagen by SPR in one full-text paper; evidence is for the intact heterotrimer.","interaction_type":"direct binding","direction_and_effect":"alpha1 I-domain bound fibrillar collagen types I-III with similar affinities [PMID:16043429]. Annotated effect is stimulatory.","molecular_requirements":"Recombinant alpha1 I-domain alone was sufficient in vitro; the beta1 partner is not tested here [PMID:16043429].","affinity_potency":[{"value":"Kd 0.3 uM (range 0.15-1.75 uM)","assay":"SPR (BIAcore), two affinity classes, reported for the study","system":"recombinant human I-domains, purified fibrillar collagen","cite":"PMID:16043429"}],"species_and_systems":"Human recombinant I-domains and purified collagen [PMID:16043429].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"The Kd is a range for the study's interactions and may not be specific to alpha1 or to type I collagen. Collagen I was tested as the (COL1A1)2COL1A2 heterotrimer, not COL1A2 alone. One other row abstract_insufficient. No database support.","key_references":[{"PMID":"16043429","why":"SPR binding of alpha1 I-domain to collagen"}],"covers":["LR000331","LR003837"]},"LR002388":{"pair":"COL1A2 -> OSCAR","headline":"OSCAR binds motifs in fibrillar collagens and costimulates osteoclastogenesis; one 2011 abstract-read paper, collagen chain not resolved.","interaction_type":"direct binding","direction_and_effect":"OSCAR binds specific motifs within fibrillar collagens exposed on bone surfaces, and this binding signalled to increase osteoclast numbers in culture; OSCAR costimulates an FcR-gamma-associated pathway [PMID:21841309]. Curator label: agonist.","molecular_requirements":"OSCAR signals as an FcR gamma-associated ITAM receptor, so the adaptor is needed [PMID:21841309]. The collagen motif, not a specific chain, is the binder.","affinity_potency":[],"species_and_systems":"Samples from mice and from patients deficient in ITAM signalling pathways [PMID:21841309]; curator notes both human and mouse were assayed, although the dossier marks mouse rows as ortholog-inferred.","localisation_and_range":"Ligand COL1A2 is flagged secreted, not transmembrane [flag]; the receptor acts on the cell surface, so signalling is by contact with the secreted matrix protein (inferred from the flags, not stated by the paper).","caveats":"Abstract read only. Fibrillar collagens are tested as a class, so COL1A1 and COL1A2 (chains of one heterotrimer) cannot be separated. No database records. A second confirmed paper is counted but not shown.","key_references":[{"PMID":"21841309","why":"OSCAR binds fibrillar collagen motifs and costimulates osteoclastogenesis"}],"covers":["LR002388","LR005667"]},"LR003846":{"pair":"COL3A1 -> DDR1","headline":"No paper in our evidence tests collagen III against DDR1; the pair rests on a solid-phase IntAct record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. IntAct lists Q08345 - P02461 as a solid phase assay, citing PMID:22483115 [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"COL3A1 flagged secreted, DDR1 receptor [flag].","caveats":"PMID:9659900 was judged pair_absent: collagen III never tested in that paper (full text). Two pair_absent, two review-only, three different_entity and two abstract-insufficient verdicts; no confirmation.","key_references":[],"covers":["LR000340","LR003846"]},"LR005673":{"pair":"COL3A1 -> OSCAR","headline":"Collagen binding to OSCAR reported in human and mouse; support is one abstract-only paper, not chain-specific.","interaction_type":"direct binding","direction_and_effect":"OSCAR is described as a receptor that binds specific motifs within fibrillar collagens and costimulates osteoclastogenesis; the curator labels the effect agonist [PMID:21841309].","molecular_requirements":"OSCAR is described as FcRgamma-associated (ITAM adaptor) [PMID:21841309]. Whether COL3A1 specifically is the binding chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse samples were both used (DAP12-deficient humans and mice), so the mouse pair is not only a projection [PMID:21841309].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only. The paper speaks of fibrillar collagens as a class; the curator notes a collagen-binding assay cannot separate individual chains [PMID:21841309].","key_references":[{"PMID":"21841309","why":"OSCAR binds fibrillar collagen motifs and costimulates osteoclastogenesis"}],"covers":["LR002394","LR005673"]},"LR002397":{"pair":"COL4A1 -> DDR2","headline":"Direct but weak collagen IV binding and phosphorylation of DDR2 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR2 and induced receptor phosphorylation, but binding and phosphorylation were consistently weaker than with fibril-forming collagens [PMID:9659900].","molecular_requirements":"DDR2 is a collagen receptor tyrosine kinase; no co-receptor requirement is reported in our evidence. The tested material was commercial type IV collagen [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot binding and phosphorylation assays; mouse pair is projected from human [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002397","LR005676"]},"LR003864":{"pair":"COL5A1 -> ITGB1","headline":"Collagen V-integrin beta1 supported only through alpha2beta1 in fibroblast disease genetics; abstract only.","interaction_type":"functional only","direction_and_effect":"EDS fibroblasts with COL5A1 mutations show reduced alpha2beta1, its functional receptor [PMID:14970208]; database effect label is stimulatory.","molecular_requirements":"ITGB1 stands for the alpha2beta1 heterodimer [PMID:14970208].","affinity_potency":[],"species_and_systems":"Human dermal fibroblasts [PMID:14970208].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"No binding assay; abstract only; one other paper abstract_insufficient.","key_references":[{"PMID":"14970208","why":"Fibroblasts with COL5A1 mutations lose alpha2beta1"}],"covers":["LR000358","LR003864"]},"LR005709":{"pair":"COLQ -> LRP4","headline":"ColQ binds LRP4 directly by multiple binding assays, including SPR, and competes with agrin; well supported.","interaction_type":"direct binding","direction_and_effect":"ColQ binds directly to LRP4 but not MuSK, and interacts indirectly with MuSK through LRP4 (coimmunoprecipitation, pull-down, plate-binding, SPR) [PMID:37356721]. ColQ constitutively reduces MuSK phosphorylation in agrin-stimulated myotubes while increasing MuSK surface accumulation [PMID:37356721].","molecular_requirements":"The LRP4 N-terminal region, which contains the agrin-binding sites, is crucial for ColQ binding; ColQ-LRP4 interaction was reduced in the presence of agrin, suggesting competition [PMID:37356721]. LRP6 coprecipitated only very little with ColQ, so binding is specific to LRP4 among those tested [PMID:37356721].","affinity_potency":[],"species_and_systems":"HEK 293T cells and myotubes; excerpts also note COS cells gave identical results [PMID:37356721]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; ColQ is a nonfibrillar collagen anchoring acetylcholinesterase at the neuromuscular junction [PMID:37356721].","caveats":"No affinity value is reported in our evidence. Two opposing effects on agrin-induced signaling mean the net direction depends on context.","key_references":[{"PMID":"37356721","why":"Direct ColQ-LRP4 binding, agrin competition, MuSK modulation"}],"covers":["LR002430","LR005709"]},"LR003873":{"pair":"CORT -> SSTR1","headline":"Cortistatin binds SSTR1 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 10.02","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst1 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 9.1-9.6","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR1 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID]. Other papers were pending or review-only.","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000367","LR003873"]},"LR005718":{"pair":"CRLF1 -> IL6ST","headline":"CRLF1 to IL6ST (gp130) is a downstream member of the CLC/CLF-CNTFR complex; direct CRLF1-gp130 binding is not shown.","interaction_type":"functional only","direction_and_effect":"CLC/CLF activated JAK1, JAK2 and TYK2, causing tyrosine phosphorylation of gp130 and LIFR in human neuroblastoma cells [PMID:11294841]. gp130 is a signalling chain of the CNTF receptor complex [PMID:10966616]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Signalling needs the composite CLC/CLF ligand, the membrane-bound form of CNTFR alpha, and gp130 with LIFR [PMID:11294841, PMID:10966616].","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells [PMID:11294841]; mouse system [PMID:10966616]. Mouse pair is inferred.","localisation_and_range":"CRLF1 is flagged secreted [flag].","caveats":"Both papers read as abstracts only. The phosphorylation is a downstream effect of the complex engaging CNTFR, not evidence of direct CRLF1-gp130 binding. Treat as a complex member.","key_references":[{"PMID":"11294841","why":"CLC/CLF activates JAKs and gp130/LIFR phosphorylation"},{"PMID":"10966616","why":"Defines the CLC/CLF ligand and receptor chains"}],"covers":["LR002439","LR005718"]},"LR003882":{"pair":"CSF2 -> CSF2RA","headline":"GM-CSF binds its alpha receptor chain with low affinity; well supported, with high affinity needing the beta chain.","interaction_type":"direct binding","direction_and_effect":"The alpha chain binds GM-CSF with low affinity [PMID:10572088]. Human GM-CSF in cells expressing the alpha and beta chains induced differentiation, with the alpha cytoplasmic domain needed [PMID:9211889]. Curators label the effect stimulatory; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Alpha alone confers low-affinity binding only; the beta chain (betac) gives high affinity when associated with alpha [PMID:8910448]. Cotransfection of KH97 (betac) with the low-affinity receptor made a high-affinity receptor [PMID:1702217].","affinity_potency":[{"value":"Kd approximately 37 pM","assay":"125I-GM-CSF binding, single class of high-affinity receptors on mature myelomonocytic cells","system":"human neutrophils, macrophages and eosinophils","cite":"PMID:2828352"}],"species_and_systems":"Human proteins and cells in most papers; murine NIH-3T3 and FDC-P1-derived WT-19 cells were used as hosts [PMID:8910448] [PMID:9211889]. A mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and non-transmembrane [flag]; receptor is a membrane receptor [flag]; paracrine range is not otherwise reported.","caveats":"All shown papers were read as abstracts only. The Kd is for native high-affinity receptors on cells, so it reflects the receptor complex and not alpha alone [PMID:2828352]. The 54-residue alpha cytoplasmic domain matters for signalling through the beta chain [PMID:8910448].","key_references":[{"PMID":"1702217","why":"Cloning of betac and reconstitution of high affinity"},{"PMID":"10572088","why":"Kinetics: alpha low affinity, beta raises k(on)"},{"PMID":"2828352","why":"Receptor numbers and Kd on human cells"}],"covers":["LR000376","LR003882"]},"LR005727":{"pair":"CTLA4 -> CD80","headline":"CTLA4 binds CD80 with strong structural and biochemical database support; a paper shows soluble CD80 binding CTLA-4-Ig.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble s1CD80 binds recombinant CD152(CTLA-4)-Ig and CD28-Ig by direct binding and inhibits mixed lymphocyte reaction and T-cell proliferation, acting inhibitory [PMID:17953528]. UniProt describes CTLA4 as a decoy receptor with stronger affinity for CD80 and CD86 than CD28 [DB:UniProt].","molecular_requirements":"CD80 also binds CD28; s1CD80 lacks the transmembrane domain [PMID:17953528]. A co-crystal structure exists [DB:PDB 1I8L] and Reactome lists CTLA-4 binding B7-1/B7-2 [DB:Reactome R-HSA-388809].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and human T cells, serum from healthy individuals [PMID:17953528]; mouse pair ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted, receptor and transmembrane [flag]; soluble CD80 occurs in serum, 0-1 mg/l in 24% of individuals [PMID:17953528]; otherwise membrane-bound juxtacrine.","caveats":"The paper is read as abstract only and tests the soluble s1CD80 isoform rather than the membrane form; no affinity reported in our evidence. Binding is to CTLA-4-Ig. Interaction also in BioGRID, IntAct [DB:BioGRID, DB:IntAct].","key_references":[{"PMID":"17953528","why":"Soluble CD80 binds CTLA-4-Ig and CD28-Ig"}],"covers":["LR002451","LR005727"]},"LR006834":{"pair":"CTNNB1 -> TCF4","headline":"Intracellular protein-protein interaction with many database records; no verified paper; not a classic extracellular ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a binding record with no type [DB:GtoPdb]. BioGRID has 61 records including Reconstituted Complex and affinity capture-Western [DB:BioGRID]; IntAct has 14 records [DB:IntAct]. UniProt notes TCF7L2/TCF4 in a complex with CTNNB1 and FERMT2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; the pair is human.","localisation_and_range":"Neither partner is flagged secreted; TCF4 is flagged receptor [flag].","caveats":"No confirmed paper; one paper was review_only. Support rests on databases only. The pair is an intracellular transcriptional complex rather than a secreted ligand acting on a membrane receptor.","key_references":[],"covers":["LR006834"]},"LR009354":{"pair":"CUBN -> LRP2","headline":"Cubilin and megalin (LRP2) associate in rat intestine; receptor-receptor pair, one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Mucosal membrane cubilin associated with megalin, reduced from approximately 12% in control to approximately 4% in thyroidectomized rats [PMID:11595644].","molecular_requirements":"Cubilin is a multidomain receptor without direct effect reported on megalin; co-receptor role not reported in our evidence beyond the curator's note [PMID:11595644].","affinity_potency":[],"species_and_systems":"Rat intestine and kidney membranes; the paper is in rats though the pair is human [PMID:11595644].","localisation_and_range":"Both flagged receptors [flag]; apical brush-border membranes [PMID:11595644].","caveats":"Abstract only; association is a percentage in tissue membranes, not a direct binding assay. Interaction class is Receptor-Receptor. One paper was review_only and one unresolvable.","key_references":[{"PMID":"11595644","why":"Cubilin-megalin association in rat intestine"}],"covers":["LR009354"]},"LR001767":{"pair":"CXADR -> JAML","headline":"Direct human binding of neutrophil JAML to epithelial CAR is reported in one study, with domain mapping; also asserted by Reactome.","interaction_type":"direct binding","direction_and_effect":"A JAML fusion protein specifically bound epithelial CAR at tight junctions in T84 monolayers and normal human colonic mucosa [PMID:15800062]. The authors say PMN-expressed JAML regulates transepithelial migration through binding to epithelial CAR [PMID:15800062]. Reactome holds a CXADR:JAML complex [DB:Reactome].","molecular_requirements":"Binding is mediated by the membrane distal Ig loop of CAR and the membrane proximal Ig loop of JAML [PMID:15800062]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells and tissue: T84 epithelial monolayers, human colonic mucosa, neutrophils [PMID:15800062]. IntAct has a protein-array record [DB:IntAct].","localisation_and_range":"CXADR is epithelial at tight junctions and JAML is on neutrophils, so interaction is cell-cell (juxtacrine) [PMID:15800062]. JAML is flagged transmembrane [flag].","caveats":"One primary paper, read as abstract only. PMN bound immobilised CAR but not JAML in a divalent cation-independent manner (from the curator's assay detail). No affinity reported in our evidence.","key_references":[{"PMID":"15800062","why":"JAML fusion binds epithelial CAR; domain mapping"}],"covers":["LR001767"]},"LR005736":{"pair":"CXCL12 -> ACKR1","headline":"Dimeric CXCL12 binds the ACKR1 N terminus with low nanomolar affinity; single abstract-read paper, human system.","interaction_type":"direct binding","direction_and_effect":"Dimeric CXCL12 bound the extracellular N terminus of ACKR1 with low nanomolar affinity by NMR and ITC, whereas monomeric CXCL12 bound orders of magnitude more weakly [PMID:34404752]. In transfected MDCK cells and primary human Duffy-positive erythrocytes, dimeric but not monomeric CXCL12 bound and internalised with ACKR1 [PMID:34404752]. ACKR1 is atypical, so this is retention or internalisation, not signalling.","molecular_requirements":"CXCL12 oligomeric state matters: dimer binds, monomer binds weakly; ACKR1 N terminus is the binding region [PMID:34404752].","affinity_potency":[{"value":"low nanomolar","assay":"NMR and ITC, dimeric CXCL12 to ACKR1 N terminus","system":"recombinant proteins","cite":"PMID:34404752"}],"species_and_systems":"Human proteins, MDCK transfectants and human erythrocytes [PMID:34404752]. Mouse pair is projected from human by ortholog inference, not tested.","localisation_and_range":"CXCL12 flagged secreted, ACKR1 transmembrane [flag]; chemokine presentation or retention on cells.","caveats":"One paper read as abstract and excerpts; the paper notes previous reports gave contradicting claims on CXCL12-ACKR1 [PMID:34404752]. No database support in our evidence.","key_references":[{"PMID":"34404752","why":"NMR/ITC and cell evidence for dimeric CXCL12 binding ACKR1"}],"covers":["LR002462","LR005736"]},"LR000399":{"pair":"CXCL12 -> CD4","headline":"One abstract-only 1999 paper reports SDF-1alpha binding to CD4 on cells and blotted soluble CD4; binding is glycan-dependent and unreplicated.","interaction_type":"direct binding","direction_and_effect":"SDF-1alpha bound CD4 on intact cells and on soluble CD4 electroblotted onto Immobilon; soluble CD4 inhibited the binding, but a truncated sCD4 lacking D3 and D4 did not, so the site differs from the gp120 site [PMID:10600606]. Signalling effect is not reported in our evidence.","molecular_requirements":"Heparin, mannan and heparitinase treatment reduced binding, so glycans and glycosaminoglycans are 'directly or indirectly' involved [PMID:10600606]. CXCR4 was co-expressed in some cells.","affinity_potency":[],"species_and_systems":"Human SDF-1alpha and human cell lines (U937, CEM, HOS-CD4+CXCR4+/-); the mouse pair is projected from human evidence [PMID:10600606].","localisation_and_range":"CXCL12 is flagged secreted [flag]; binding to cell-surface CD4 would be paracrine/contact-proximal, but this is not stated in the paper.","caveats":"Abstract only. Glycan dependence means direct protein-protein binding is not established. CXCR4 is the canonical receptor; the curator flagged CD4 for inferability. No affinity reported.","key_references":[{"PMID":"10600606","why":"Only paper: SDF-1alpha binding to CD4"}],"covers":["LR000399","LR003904"]},"LR003909":{"pair":"CXCL13 -> CXCR5","headline":"Well-supported canonical pair: CXCL13 activates CXCR5 in several papers, with binding, chemotaxis and calcium data and curated database records.","interaction_type":"direct binding","direction_and_effect":"CXCL13 (BCA-1) induced chemotaxis and Ca2+ mobilisation in BLR1/CXCR5-transfected cells and attracted human blood B lymphocytes; no activity was seen with 10 CXC and 19 CC chemokines, lymphotactin, neurotactin/fractalkine and other peptide ligands [PMID:9463416]. An independent paper showed BLC stimulates calcium influx and chemotaxis in BLR-1-transfected cells [PMID:9486651]. GtoPdb lists CXCL13 as a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR5 alone is sufficient in transfected cells [PMID:9463416][PMID:9486651]. EBI2 co-expression forms CXCR5/EBI2 heterodimers that reduce CXCL13 affinity and G-protein efficacy [PMID:22913878].","affinity_potency":[{"value":"KD 5.05\u00d710(-8) M","assay":"CXCL13 binding to CXCR5 alone","system":"HEK293T cells","cite":"PMID:22913878"},{"value":"KD 1.49\u00d710(-7) M","assay":"CXCL13 binding to CXCR5/EBI2 co-expressing cells","system":"HEK293T cells","cite":"PMID:22913878"}],"species_and_systems":"Murine pre-B 300-19 cells transfected with BLR1 and human blood B cells [PMID:9463416]; human HEK293T cells and primary activated murine B cells [PMID:22913878]; species not specified in [PMID:9486651]. Mouse pair is also listed as a direct (not projected) interaction.","localisation_and_range":"CXCL13 is flagged secreted [flag]; soluble chemokine acting on a cell-surface GPCR, guiding B cells to follicles [PMID:9486651].","caveats":"All three papers were read as abstracts only. Receptor heterodimerisation with EBI2 lowers apparent affinity, relevant where EBI2 is co-expressed [PMID:22913878]. Reactome records binding and complex [DB:Reactome].","key_references":[{"PMID":"9463416","why":"Identifies CXCL13 as selective BLR1/CXCR5 agonist with negative tests on 29 chemokines"},{"PMID":"9486651","why":"Independent report of BLC activating BLR-1 by calcium influx and chemotaxis"},{"PMID":"22913878","why":"KD values and CXCR5/EBI2 heterodimer effect on CXCL13 binding"}],"covers":["LR000404","LR003909"]},"LR002469":{"pair":"CXCL17 -> NRP1","headline":"One 2024 BRET study reports CXCL17 binding neuropilin-1 in cells in a GAG-dependent way; no affinity or second source.","interaction_type":"direct binding","direction_and_effect":"BRET-based assays showed CXCL17 interacts with neuropilin-1, a VEGFR2 coreceptor [PMID:38502733]. CXCL17 displaced labelled VEGF165a from Nluc/NRP1 (but not from Nluc/VEGFR2), and CXCL17-HiBiT gave a BRET increase with SNAP/NRP1 [PMID:38502733]. No downstream signalling effect on NRP1 is reported in our evidence.","molecular_requirements":"Binding depends on glycosaminoglycans: surfen or protamine sulfate abolished the CXCL17-HiBiT signal [PMID:38502733].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells; protein species not stated in our excerpts [PMID:38502733]. Mouse pair is projected from human.","localisation_and_range":"CXCL17 flagged secreted and NRP1 transmembrane [flag]; cell-surface interaction.","caveats":"Single paper, no affinity value. Cell-based BRET with GAG dependence, so direct protein-protein binding is not proven. No database record.","key_references":[{"PMID":"38502733","why":"NanoBRET evidence for CXCL17 binding to NRP1"}],"covers":["LR002469","LR005743"]},"LR007176":{"pair":"CXCL2 -> DPP4","headline":"Database-asserted only: one IntAct enzymatic-study record; no curator-verified papers.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; the only record is an IntAct entry described as an enzymatic study [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the IntAct record (PMID 18275857) [DB:IntAct].","localisation_and_range":"Ligand flagged secreted, DPP4 flagged transmembrane [flag].","caveats":"No paper was judged as confirmed. An enzymatic study may reflect DPP4 proteolysis of the chemokine rather than receptor binding; the dossier does not say.","key_references":[],"covers":["LR007176"]},"LR005745":{"pair":"CXCL5 -> ACKR1","headline":"Direct binding of CXCL5 to the atypical receptor ACKR1/DARC in competition assays; scavenger-type binding, not signalling.","interaction_type":"direct binding","direction_and_effect":"DARC selectively bound pro-inflammatory chemokines including CXCL5 but not lymphoid chemokines; bound CCL2 failed to raise calcium, suggesting DARC down-regulates chemokine activity (scavenger/decoy-type) [PMID:13679391].","molecular_requirements":"ACKR1 alone was used; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"Ki 28.8 nM","assay":"125I-CXCL8 competition displacement","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor; competition binding with 20 chemokines [PMID:13679391]; human erythrocytes [PMID:15358176]. Knockout mice showed no lymph node changes [PMID:13679391].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"The Ki value is attributed to this pair by the curator from the paper's Table 1, which is not in the excerpts shown. ACKR1 does not signal, so it should not be scored as a signalling receptor. Ortholog mouse pair is projected, not tested.","key_references":[{"PMID":"13679391","why":"CXCL5 binds DARC in competitive binding"},{"PMID":"15358176","why":"Ki for CXCL5 at Duffy antigen"}],"covers":["LR000415","LR005745"]},"LR002478":{"pair":"DCHS1 -> FAT4","headline":"Human Fat4 and Ds1 (DCHS1) form complexes at cell boundaries in reconstituted cells; structures are also listed in PDB.","interaction_type":"direct binding","direction_and_effect":"Fat4-Ds1 complexes accumulate on cell boundaries in a threshold-like manner; co-expression is sufficient for complex formation [PMID:28826487]. Signalling direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the two proteins.","affinity_potency":[],"species_and_systems":"Synthetic reconstitution of human Fat4 and Ds1 in mammalian cells with live imaging [PMID:28826487]. Mouse pair is ortholog-projected.","localisation_and_range":"Both partners are flagged not secreted [flag]; the cell-boundary accumulation suggests contact-dependent (juxtacrine) action [PMID:28826487].","caveats":"Abstract only. PDB 8EGW and 8EGX contain a chain of Q96JQ0 and a chain of Q6V0I7 [DB:PDB 8EGW] [DB:PDB 8EGX].","key_references":[{"PMID":"28826487","why":"Fat4-Ds1 complex accumulation in reconstituted cells"}],"covers":["LR002478","LR005752"]},"LR001776":{"pair":"DEFB106A -> CCR2","headline":"NMR model of human beta-defensin 6 with a CCR2 N-terminal peptide supports binding; abstract-only and no functional readout.","interaction_type":"direct binding","direction_and_effect":"NMR of hBD6 with peptides from the CCR2 extracellular domain (Nt-CCR2, with or without sulfation on Tyr26 and Tyr28) gives a complex model with a contiguous binding surface on hBD6 (alpha-helix and beta2-beta3 loop) [PMID:23938203]. UniProt records the interaction as well [DB:UniProt]. Agonism or antagonism is not reported in our evidence.","molecular_requirements":"Only the receptor N-terminal peptide was used, not full-length CCR2, so whether other CCR2 regions or subunits are needed is not reported [PMID:23938203].","affinity_potency":[],"species_and_systems":"Human hBD6 and a synthetic CCR2 peptide, in vitro NMR [PMID:23938203].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only. hBD6 is encoded by the near-identical duplicated loci DEFB106A and DEFB106B and the paper does not distinguish them, so the evidence applies to both. The peptide complex is not proof of binding to intact cell-surface CCR2. UniProt support cites the same paper [DB:UniProt]. No affinity reported.","key_references":[{"PMID":"23938203","why":"NMR hBD6/Nt-CCR2 complex"}],"covers":["LR001776"]},"LR003927":{"pair":"DHH -> BOC","headline":"Structural evidence (PDB 3N1G) that DHH binds BOC; positive modulator role, abstract-level.","interaction_type":"direct binding","direction_and_effect":"x-ray structures of Sonic, Indian and Desert Hh alone and in complex with the active domains of CDO and BOC show all mammalian Hh proteins bind CDO and BOC in the same manner [PMID:20519495]. Database records agree: PDB 3N1G (DhhN bound to BOCFn3) [DB:PDB 3N1G], IntAct x-ray crystallography [DB:IntAct], UniProt subunit annotation [DB:UniProt]. The abstract notes that CDO and BOC positively regulate Hh signalling, but this is background and not measured for DHH here [PMID:20519495].","molecular_requirements":"The N-terminal signalling domain of DHH (DhhN) binds the BOC fibronectin domain in the structure [DB:PDB 3N1G]. Whether Patched is also needed is not reported for this pair.","affinity_potency":[],"species_and_systems":"Mammalian proteins in a crystal; the species of the recombinant proteins is not stated in the abstract [PMID:20519495]. The mouse row is projected by orthology (ortholog_inferred) [flag].","localisation_and_range":"DHH is flagged both secreted and transmembrane [flag]; membrane tethering is therefore suggested only by an annotation flag, and contact-dependent versus diffusible action is not reported in our evidence.","caveats":"Abstract only. Affinity for DHH is not given in the abstract; micromolar affinities are cited for Ihog and for CDO with Sonic Hh as background [PMID:20519495]. Crystal binding does not show signalling effect for DHH.","key_references":[{"PMID":"20519495","why":"Crystal structures of Hh proteins with CDO and BOC"}],"covers":["LR000435","LR003927"]},"LR005754":{"pair":"DHH -> GAS1","headline":"Functional evidence only: Gas1 acts as a Hedgehog co-receptor potentiating Dhh signalling in endothelial cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Gas1 promotes Dhh binding to Smo and potentiates Dhh effects; Gas1 deficiency phenocopies Dhh deficiency, including VCAM-1 and ICAM-1 overexpression [PMID:33028094]. Direct Dhh-Gas1 binding is not reported in our evidence.","molecular_requirements":"Described as a hedgehog co-receptor alongside Cdon, which acts as a decoy that prevents Dhh binding to Ptch1 [PMID:33028094]. Subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used endothelial cells with siRNA and EC-specific conditional knockout mice (mouse in vivo); the human pair is listed, with the mouse pair projected by ortholog inference.","localisation_and_range":"DHH is flagged both secreted and transmembrane, GAS1 as a receptor and not secreted [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as an abstract only. The finding is a knockdown/knockout phenotype and a binding-to-Smo statement, not a measured Dhh-Gas1 interaction.","key_references":[{"PMID":"33028094","why":"Gas1 potentiates Dhh signalling in endothelial cells; Cdon acts as decoy"}],"covers":["LR002486","LR005754"]},"LR002487":{"pair":"DKK1 -> CKAP4","headline":"Direct binding supported: CKAP4 identified as a DKK1 receptor with binding, internalization and signalling data; one paper.","interaction_type":"direct binding","direction_and_effect":"DKK1 binds CKAP4 and LRP6 with similar affinity, using different cysteine-rich domains; DKK1 induced clathrin-dependent CKAP4 internalization, and DKK1/CKAP4 activated AKT via a CKAP4-PI3K complex, driving proliferation [PMID:27322059]. An anti-CKAP4 antibody blocked binding [PMID:27322059].","molecular_requirements":"CKAP4 alone mediates the AKT signalling; LRP6 binds a different DKK1 domain [PMID:27322059]. BioGRID records affinity capture-western and reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Cancer cell lines, human tumour samples and a xenograft in immunodeficient mice [PMID:27322059]; mouse pair is ortholog-inferred.","localisation_and_range":"DKK1 is flagged secreted, CKAP4 as a receptor [flag].","caveats":"One paper, abstract only; a numeric affinity is not given. Second confirmed row is the same paper.","key_references":[{"PMID":"27322059","why":"CKAP4 identified as DKK1 receptor"}],"covers":["LR002487","LR005755"]},"LR003936":{"pair":"DKK2 -> KREMEN2","headline":"Functional evidence that Kremen2 switches Dkk2 from LRP6 activator to Wnt inhibitor; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Dkk2 activates LRP6 signalling in transfected human 293 fibroblasts, but co-transfection of krm2 blocks this and enhances inhibition of Wnt/Frizzled signaling; Krm2 can switch Dkk2 from activator to inhibitor [PMID:12527209].","molecular_requirements":"Interaction with Krm2 is mediated by the second cysteine-rich domain of Dkks; the abstract notes Kremen1 and 2 bind Dkk1 and Dkk2 with high affinity (from earlier work) [PMID:12527209]. LRP6 is part of the readout.","affinity_potency":[],"species_and_systems":"Human 293 fibroblasts and Xenopus embryos (Dkk2 and Krm2 cooperate to anteriorize embryos) [PMID:12527209]; the human pair is ortholog-inferred.","localisation_and_range":"DKK2 flagged secreted; KREMEN2 flagged receptor [flag].","caveats":"Abstract only; binding affinity is not measured here. Second confirmed row is the same paper.","key_references":[{"PMID":"12527209","why":"Krm2 turns Dkk2 into a Wnt/LRP6 inhibitor"}],"covers":["LR000444","LR003936"]},"LR003945":{"pair":"DLL4 -> NOTCH3","headline":"Two abstract-only papers support DLL4 activating NOTCH3 in cells, one with proximity-ligation interaction data.","interaction_type":"functional only","direction_and_effect":"Endogenous Notch2/3-DLL4 interactions were detected by in situ proximity ligation in human bladder cancer cell lines, and recombinant DLL4 activated canonical Notch signalling [PMID:39951484]. Dll4 interaction was sufficient to maintain Notch3 activity in quiescent C2C12 reserve cells [PMID:29230914].","molecular_requirements":"Not reported in our evidence beyond Notch3 being the receptor tested; Reactome lists a DLL4:NOTCH3 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human bladder cancer cell lines [PMID:39951484]; mouse C2C12 myoblast reserve cells and primary satellite cells [PMID:29230914]. The dossier's species fields are blank for both.","localisation_and_range":"Both partners annotated transmembrane, DLL4 not secreted [flag]; Dll4 on nascent myotubes acting on adjacent stem cells fits contact signalling [PMID:29230914].","caveats":"Abstracts only. In the bladder paper Notch2 and Notch3 are not separated, and the proximity assay is not a purified-protein binding test. Six papers were abstract-insufficient.","key_references":[{"PMID":"39951484","why":"DLL4-Notch2/3 proximity ligation in bladder cancer cells"},{"PMID":"29230914","why":"Dll4 activates Notch3 in muscle stem cells"}],"covers":["LR000453","LR003945"]},"LR005763":{"pair":"DRAXIN -> LRP6","headline":"Weak support: one abstract-only paper on Neucrin (the name used for Draxin) reports binding to LRP6 and Wnt antagonism.","interaction_type":"direct binding","direction_and_effect":"Neucrin bound LDL receptor-related protein 6 and inhibited stabilisation of cytosolic beta-catenin, so it acts as an antagonist of canonical Wnt signalling [PMID:19857465].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated in the dossier; the paper describes mouse and human Neucrin [PMID:19857465].","localisation_and_range":"DRAXIN annotated secreted, LRP6 transmembrane [flag]; Neucrin is described as a secreted antagonist [PMID:19857465].","caveats":"Abstract only; the binding assay type is not given. The abstract uses the name Neucrin, so whether it is the entity curated as DRAXIN is a name-mapping assumption not checkable in our evidence.","key_references":[{"PMID":"19857465","why":"Neucrin binds LRP6 and inhibits Wnt"}],"covers":["LR002495","LR005763"]},"LR001785":{"pair":"DSC1 -> DSG3","headline":"Heterophilic DSC1-DSG3 binding inferred from a family-wide study; no database records.","interaction_type":"direct binding","direction_and_effect":"All Dsgs form adhesive dimers with all Dscs with characteristic affinities, which includes DSC1:DSG3 [PMID:27298358].","molecular_requirements":"Strand-swap binding; opposite-charge attraction promotes Dsg:Dsc pairing [PMID:27298358]. Dsg3 crystal structure was reported [PMID:27298358].","affinity_potency":[],"species_and_systems":"Human ectodomains; mouse record ortholog-inferred [PMID:27298358].","localisation_and_range":"Annotated transmembrane [flag]; trans-cellular adhesion [PMID:27298358].","caveats":"Abstract read only; the pair is covered by a family-level statement. No pair-specific affinity and no database records.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc binding"}],"covers":["LR001785","LR005141"]},"LR002496":{"pair":"DSC2 -> DSC2","headline":"Homophilic DSC2 trans binding shown by cross-linking in keratinocytes.","interaction_type":"direct binding","direction_and_effect":"Extracellular cross-linking in HaCaT keratinocytes gave evidence for homophilic, isoform-specific Dsc2 binding that represents trans interaction [PMID:21098030]. Mutating Trp-2 and Ala-80 abolished Dsc2 binding [PMID:21098030].","molecular_requirements":"No evidence for heterophilic or cis interaction, though neither was fully excluded; adducts sit in the detergent-insoluble fraction [PMID:21098030].","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes [PMID:21098030].","localisation_and_range":"Transmembrane, in desmosomes; cell-cell trans interaction [PMID:21098030][flag].","caveats":"Abstract read only. Self-pair, so ligand and receptor are the same protein. The paper reports no cross-isoform binding between Dsc2 and Dsg2/Dsg3, which differs from the heterophilic picture in other papers for related pairs.","key_references":[{"PMID":"21098030","why":"Cross-linking shows homophilic Dsc2 trans binding"}],"covers":["LR002496","LR005764"]},"LR001794":{"pair":"DSC3 -> DSG4","headline":"DSC3 -> DSG4: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001794","LR005150"]},"LR005772":{"pair":"DSG3 -> DSC2","headline":"Heterophilic DSG3:DSC2 adhesive binding supported by one abstract-only structural/biophysical paper.","interaction_type":"direct binding","direction_and_effect":"Per the paper, all desmogleins form adhesive dimers with all desmocollins, including DSG3:DSC2; this is an adhesive pair, not a classical agonist signal [PMID:27298358].","molecular_requirements":"Binding is via a strand-swap mechanism between ectodomains; opposite-charge attraction promotes heterophilic Dsg:Dsc binding while same-charge repulsion blocks Dsg:Dsg and Dsc:Dsc pairing [PMID:27298358]. Crystal structures were of Dsg2/Dsg3 and Dsc1/Dsc2 ectodomains.","affinity_potency":[],"species_and_systems":"Human proteins; solution biophysics and coated-bead aggregation. Mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Both partners are flagged as non-secreted receptors, so this is membrane-bound, contact-dependent (juxtacrine) adhesion [flag].","caveats":"Read as abstract only. The paper covers a 25-pair Dsg:Dsc matrix; a DSG3:DSC2-specific affinity is not reported in our evidence.","key_references":[{"PMID":"27298358","why":"Systematic Dsg:Dsc heterophilic binding with crystal structures"}],"covers":["LR002504","LR005772"]},"LR003954":{"pair":"EDN2 -> EDNRB","headline":"ET-2 binds the non-selective ETB receptor by inference from one cloning paper; little else.","interaction_type":"direct binding","direction_and_effect":"The cloning paper defines ETB as binding ET-1, ET-2 and ET-3 with comparable affinity [PMID:2175397]; the effect is recorded as agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor cloned and expressed in cells [PMID:2175397]. Both species pairs are ortholog-inferred. Reactome lists EDNRA/EDNRB binding EDNs [DB:Reactome R-HSA-388560].","localisation_and_range":"ET-2 is annotated secreted and EDNRB transmembrane [flag].","caveats":"Single paper, read as abstract only; the ET-2 statement is a class statement about all three isopeptides rather than an ET-2 measurement shown in the dossier.","key_references":[{"PMID":"2175397","why":"ETB cloned as binding all three endothelins"}],"covers":["LR000463","LR003954"]},"LR003963":{"pair":"EFNA1 -> EPHA6","headline":"Database-asserted only: UniProt lists EphA receptors including EPHA6 as EFNA1 binders; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt PMID:18794797]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag]; no paper text on localisation.","caveats":"No curated paper evidence; support is a single UniProt annotation.","key_references":[],"covers":["LR000472","LR003963"]},"LR003972":{"pair":"EFNA2 -> EPHA7","headline":"Ephrin-A2 binds EphA7 in rat striatal lysates; one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A2, ephrin-A3 and ephrin-A5 bind EphA7 but not EphA4 in striatal tissue binding assays [PMID:10366629].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat striatal lysates [PMID:10366629]; BioGRID affinity capture-western [DB:BioGRID]. Human pair ortholog-inferred.","localisation_and_range":"EFNA2 annotated transmembrane, EPHA7 secreted and transmembrane [flag].","caveats":"One paper, read as abstract only; no affinity values.","key_references":[{"PMID":"10366629","why":"ephrin-A2 binds EphA7 in rat striatum"}],"covers":["LR000481","LR003972"]},"LR005781":{"pair":"EFNA3 -> EPHA10","headline":"Supported only by a UniProt statement that EPHA10 binds EFNA3; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 'Binds to EFNA3, EFNA4 and EFNA5' [DB:UniProt]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental species or system reported in our evidence; the dossier covers human and a mouse pair projected from human (ortholog-inferred).","localisation_and_range":"EFNA3 is flagged membrane-bound (transmembrane) [flag]; EPHA10 is flagged secreted [flag]. These are annotation flags only.","caveats":"No paper-level evidence; both judged papers were review-only. Rests on a single database annotation.","key_references":[],"covers":["LR002513","LR005781"]},"LR000489":{"pair":"EFNA3 -> EPHA7","headline":"Ephrin-A3 binds EphA7 in rat striatal lysates and by ELISA; direct binding evidence.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A2, ephrin-A3 and ephrin-A5 bind EphA7 but not EphA4 in rat striatal tissue [PMID:10366629]. Ephrin-A3 AP binds best to EphA3, EphA5 and EphA7 [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat postnatal striatum lysates and in situ hybridisation [PMID:10366629]; ELISA, species unspecified [PMID:22568954]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA3 is flagged membrane-bound; EPHA7 is flagged both secreted and transmembrane [flag].","caveats":"10366629 was read as an abstract only; 22568954 was a browser read with an unverifiable quote. BioGRID lists an affinity capture-Western record [DB:BioGRID].","key_references":[{"PMID":"10366629","why":"Ephrin-A3 binds EphA7 in rat striatum"},{"PMID":"22568954","why":"ELISA binding ranking"}],"covers":["LR000489","LR003980"]},"LR000498":{"pair":"EFNA4 -> EPHA8","headline":"Ephrin-A4 Fc binds EphA8 in cells and by ELISA; direct binding evidence.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 chimeric ligands efficiently bound EphA8 in NIH3T3 fibroblasts, with EphA8 tyrosine phosphorylation on stimulation [PMID:10515610]. Ephrin-A4 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Fc-fusion ligands on EphA8-expressing NIH3T3 cells (human recorded for both partners) [PMID:10515610]; ELISA, species unspecified [PMID:22568954]. The human pair is ortholog-inferred.","localisation_and_range":"EFNA4 flagged secreted and transmembrane; EPHA8 flagged membrane-bound [flag].","caveats":"10515610 was an abstract-only read; 22568954 a browser read with an unverifiable quote.","key_references":[{"PMID":"10515610","why":"Ephrin-A4-Fc binds and activates EphA8"},{"PMID":"22568954","why":"ELISA of ephrin-A4 Fc across EphA receptors"}],"covers":["LR000498","LR003989"]},"LR005790":{"pair":"EFNA5 -> EPHA10","headline":"Only a UniProt note that EPHA10 binds EFNA5; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 'Binds to EFNA3, EFNA4 and EFNA5' [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; EPHA10 flagged secreted [flag].","caveats":"Both judged papers were review-only; a single database annotation supports it.","key_references":[],"covers":["LR002522","LR005790"]},"LR008724":{"pair":"EFNB2 -> PECAM1","headline":"Co-IP and colocalisation of ephrinB2 with CD31 at endothelial junctions; association, not ligand-receptor binding.","interaction_type":"functional only","direction_and_effect":"EphB4-Fc-mediated activation strongly enhanced translocation of ephrinB2 to junctions, where it colocalizes and coimmunoprecipitates with CD31 [PMID:16357318]. The association is context-dependent.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured human endothelial cells (curator annotation) [PMID:16357318].","localisation_and_range":"Both annotated transmembrane [flag]; association is at interendothelial junctions [PMID:16357318].","caveats":"Abstract only; no direct binding or affinity shown. Typed Receptor-Receptor; no ligand-receptor direction is demonstrated.","key_references":[{"PMID":"16357318","why":"EphrinB2 colocalizes and co-IPs with CD31 in endothelial cells"}],"covers":["LR008724"]},"LR008238":{"pair":"EGF -> ERBB2:ERBB4","headline":"EGF is reported to bind the ErbB2/ErbB4 heterodimer in one soluble binding study; no affinity value in our evidence.","interaction_type":"direct binding","direction_and_effect":"The ErbB2/4 heterodimer bound all eleven ErbB ligand EGF domains tested, including EGF, with moderate to very high affinity [PMID:10214951]. ErbB2 enhanced ligand binding to ErbB3 or ErbB4 [PMID:10214951].","molecular_requirements":"Heterodimer format tested; ErbB4 alone for EGF is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Soluble receptor-ligand binding format using EGF domains of the ligands [PMID:10214951]. PDB 8HGO and Reactome complexes concern EGFR/ERBB2 and not this pair [DB:PDB 8HGO].","localisation_and_range":"Not reported in our evidence.","caveats":"One paper, abstract only; the EGF-specific affinity is not given in the abstract.","key_references":[{"PMID":"10214951","why":"Binding of eleven ErbB ligands to six receptor combinations"}],"covers":["LR008238"]},"LR005808":{"pair":"EPHA2 -> EFNA1","headline":"EPHA2-EFNA1 is well supported by structure and binding databases, but no curated paper was verified in this dossier.","interaction_type":"direct binding","direction_and_effect":"UniProt states EFNA1 activates EPHA2, regulating migration, adhesion, proliferation and angiogenesis [DB:UniProt]. Structures of the EphA2-ephrin-A1 complex exist [DB:PDB 3CZU]. BioGRID lists affinity capture-MS and -Western [DB:BioGRID]; IntAct lists x-ray crystallography and coimmunoprecipitation [DB:IntAct].","molecular_requirements":"Subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; PDB 3CZU is titled as a human ephrin A2-ephrin A1 complex [DB:PDB 3CZU].","localisation_and_range":"EPHA2 is flagged non-secreted; EFNA1 secreted [flag], likely reflecting a soluble form but not confirmed here. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Evidence is database records only; four review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002540","LR005808"]},"LR005817":{"pair":"EPHA3 -> EFNA5","headline":"EphA3 binds ephrin-A5 with a crystal structure and ELISA binding data from three sources; strongly supported but affinity values not in dossier.","interaction_type":"direct binding","direction_and_effect":"The crystal structure of the EphA3 ligand-binding domain with its preferred ligand ephrin-A5 shows a pronounced tilt of ephrin-A5 that enlarges the interface beyond the canonical pocket [PMID:25993310]. Ephrin-A5 Fc binds EphA receptors with high apparent affinity in ELISA [PMID:22568954]. UniProt says activation by EFNA5 regulates adhesion, cytoskeleton and migration [DB:UniProt].","molecular_requirements":"The ligand-binding domain of EphA3 is sufficient for the structure [PMID:25993310]. Buried surface area: 1,298 \u00c52 for ephrin-A5 on EphA3 versus 847 \u00c52 on EphA2 [PMID:25993310].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the structural paper [PMID:25993310]; the ELISA paper does not specify species [PMID:22568954]. PDB 4L0P is a structure of the pair [DB:PDB 4L0P].","localisation_and_range":"EPHA3 is flagged secreted, which is unlikely for a transmembrane Eph receptor; EFNA5 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Abstract read for the structure paper; the ELISA paper was browser-read and its quote is unverified (spot-check pending). No numeric affinity in our evidence.","key_references":[{"PMID":"25993310","why":"EphA3/ephrin-A5 complex structure"},{"PMID":"22568954","why":"ELISA: ephrin-A5 Fc binds EphA receptors"}],"covers":["LR002549","LR005817"]},"LR005826":{"pair":"EPHA5 -> EFNA2","headline":"EPHA5-EFNA2 rests on a single UniProt statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA2 binds EPHA3, EPHA4 and EPHA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; both pairs are ortholog-inferred.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; one database sentence only, no affinity data.","key_references":[],"covers":["LR002558","LR005826"]},"LR005835":{"pair":"EPHA7 -> EFNA1","headline":"UniProt lists EPHA7 among receptors bound by EFNA1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA1 entry) states it binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt]. Effect and direction are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners carry secreted and transmembrane flags [flag]; the actual range is unclear from our evidence.","caveats":"No curator-verified paper; support is database records only. Only a UniProt subunit sentence; no assay or affinity in our evidence.","key_references":[],"covers":["LR002567","LR005835"]},"LR002568":{"pair":"EPHA7 -> EFNA2","headline":"Two abstract-level papers support EPHA7/ephrin-A2 binding or signalling, but one does not name the pair explicitly.","interaction_type":"functional only","direction_and_effect":"In human rhabdomyosarcoma cells, EphA7 binds and signals to ephrin-A2, and Fc chimeras of EphA7 and ephrin-A5 inhibit proliferation [PMID:40426233]. The abstract does not say which partner is the signalling receptor beyond this. An earlier mouse study reports high-affinity binding of the ligands Elf-1 and B61 to MDK1 and receptor autophosphorylation in Rat1 cells, but its abstract does not name EphA7 or ephrin-A2 [PMID:9010230].","molecular_requirements":"Subunit or co-receptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human rhabdomyosarcoma cell lines in vitro [PMID:40426233]; mouse receptor MDK1 fusion proteins and Rat1 cells [PMID:9010230]. Both papers were read as abstracts only.","localisation_and_range":"EPHA7 carries secreted and transmembrane flags; EFNA2 carries a transmembrane flag [flag]. Both papers describe cell-based assays; range is not reported beyond that.","caveats":"Abstract-only reading. The 1.7 x 10(-10) M and 2.2 x 10(-10) M values in [PMID:9010230] are for Elf-1 and B61 binding MDK1, and the abstract does not link them to EFNA2 in our evidence, so they are not assigned to this pair. BioGRID lists an affinity capture-Western record [DB:BioGRID 280891]. Three other papers were judged abstract-insufficient.","key_references":[{"PMID":"40426233","why":"Human hRMS cells: EphA7 binds and signals to ephrin-A2, abstract only."},{"PMID":"9010230","why":"Scatchard binding of Elf-1 and B61 to MDK1; link to this pair not explicit in the abstract."}],"covers":["LR002568","LR005836"]},"LR005844":{"pair":"EPHA8 -> EFNA5","headline":"Database-only pair: IntAct co-immunoprecipitations and a UniProt interaction statement; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA5 entry) states it interacts with EPHA8 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct records are anti-tag coimmunoprecipitations [DB:IntAct EBI-21873799], [DB:IntAct EBI-54775381]; these do not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002576","LR005844"]},"LR005853":{"pair":"EPHB2 -> EFNA5","headline":"UniProt asserts an EPHB2-EFNA5 interaction, one entry only by similarity; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt EPHB2 entry states it interacts with EFNA5 (by similarity), and the EFNA5 entry states it binds EPHB2 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. The EPHB2 entry is marked by similarity, so it is not independent direct evidence. This is a cross-class (EphB receptor with ephrin-A) assertion; affinity not reported in our evidence.","key_references":[],"covers":["LR002585","LR005853"]},"LR002586":{"pair":"EPHB2 -> EFNB1","headline":"Eph B2-ephrin-B1 pair supported by IntAct and UniProt records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that upon activation by EFNB1, EPHB2 abolishes ARHGEF15-mediated negative regulation of excitatory synapse formation, and that EFNB1 can also bind EPHB2 and EPHB3 [DB:UniProt]. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct records an anti-tag coimmunoprecipitation [DB:IntAct EBI-54525293] and a solid phase assay [DB:IntAct P29323-P98172]. Affinity not reported in our evidence.","key_references":[],"covers":["LR002586","LR005854"]},"LR005871":{"pair":"EPHB6 -> EPHB2","headline":"Receptor-receptor heterodimerisation of EPHB6 with EPHB2 in breast cancer cells, abstract only; not a classical ligand-receptor binding.","interaction_type":"functional only","direction_and_effect":"The paper reports that EPHB6, a kinase-deficient receptor, interacts with EPHB2 in mammalian cells (within-class B-type heterodimer), and proposes that EPHB6 suppresses tumour invasiveness by sequestering kinase-sufficient oncogenic EPH receptors [PMID:21737611]. The curator labels this antagonist. EPHB6 does not interact with EPHA10 [PMID:21737611].","molecular_requirements":"Not reported beyond the two partners; EPHB6 is described as kinase-deficient [PMID:21737611].","affinity_potency":[],"species_and_systems":"Human breast carcinoma cell lines, mammalian cell co-expression; abstract only [PMID:21737611].","localisation_and_range":"EPHB6 carries secreted and transmembrane flags; EPHB2 is transmembrane-flagged [flag]. Heterodimerisation is within the membrane (cis or on the same cell); range is not reported.","caveats":"Abstract-only reading. This is a receptor-receptor association, so a ligand-to-receptor direction is not shown. The BioGRID record is Affinity Capture-Western [DB:BioGRID 3496525]. Direct physical binding is not distinguished from complex formation in our evidence.","key_references":[{"PMID":"21737611","why":"EPHB6 heterodimerises with EPHB2 in breast carcinoma cell lines."}],"covers":["LR002603","LR005871"]},"LR008247":{"pair":"EPO -> CSF2RB:EPOR","headline":"Database records support EPO binding EPOR; nothing in our evidence addresses the CSF2RB partner of the complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists EPO acting as an agonist at EPOR [DB:GtoPdb]. UniProt states EPO binds EPOR, leading to EPOR dimerization and JAK2 activation, activating effectors including STAT1 and STAT3 [DB:UniProt].","molecular_requirements":"All records here name EPO and EPOR only (UniProt P01588 and P19235) [DB:UniProt]; no record concerns CSF2RB, so its requirement is not supported by our evidence.","affinity_potency":[],"species_and_systems":"Species and systems of the records are not reported in our evidence.","localisation_and_range":"Not reported in our evidence; no annotation flags are listed.","caveats":"No verified paper for this complex pair; one paper was abstract-insufficient. Structural records exist for EPO with EPOR chains [DB:PDB 1CN4], [DB:PDB 1EER]; BioGRID lists two-hybrid, reconstituted complex and affinity capture-Western records [DB:BioGRID 314575]; IntAct includes surface plasmon resonance and X-ray crystallography [DB:IntAct P19235-P01588]. GtoPdb gives an affinity unit (pIC50) but no value in our evidence.","key_references":[],"covers":["LR008247"]},"LR008607":{"pair":"ERBB2 -> EFNB1","headline":"ERBB2 and EFNB1 co-immunoprecipitate in breast cancer cells; one paper plus IntAct, no ligand-receptor direction shown.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation and colocalisation show EphrinB1 interacts with ErbB2 [PMID:22279592]. The oncogenic V660E ErbB2 mutation enhances the interaction, and Src mediates EphrinB1 phosphorylation and MAP kinase signalling [PMID:22279592]. Which partner signals to which is not established.","molecular_requirements":"Part of a complex with Src and PTPN13 [PMID:22279592]. Other requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human breast cancer cells [PMID:22279592]. IntAct records the same co-immunoprecipitation [DB:IntAct].","localisation_and_range":"Both partners are flagged transmembrane receptors [flag]; contact-dependent range is inferred from that flag only.","caveats":"Single paper, with evidence read at abstract level for the pair. Co-IP does not prove direct binding. The pair is receptor-receptor, not a classical ligand-receptor pair [flag].","key_references":[{"PMID":"22279592","why":"Co-IP and colocalisation of EphrinB1 with ErbB2 in breast cancer cells"}],"covers":["LR008607"]},"LR005880":{"pair":"FAT1 -> GPC3","headline":"FAT1 C-terminal EGF-like domains bind GPC3 in liver cancer cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"GPC3 binding was mapped to the last four EGF-like domains of FAT1 (residues 4013-4181) by ELISA and flow cytometry [PMID:33420124]. Endogenous FAT1 was pulled down from HepG2 lysate by a GPC3 antibody [PMID:33420124]. Effect direction not reported in our evidence.","molecular_requirements":"The RTP domain (residues 3662-3788) and Laminin G-2nd EGF-like region (residues 3829-4050) showed non-specific GPC3 binding [PMID:33420124].","affinity_potency":[],"species_and_systems":"Human proteins in HCC cells including HepG2; the mouse pair is ortholog-inferred. An IntAct co-IP record exists [DB:IntAct].","localisation_and_range":"Both are flagged not secreted; GPC3 is flagged receptor [flag]. FAT1 is described as a cell-surface transmembrane protein and GPC3 as a cell-surface proteoglycan [PMID:33420124], so any signaling would be contact-dependent.","caveats":"Single paper, read as abstract only (excerpts available). The ligand/receptor direction is an annotation; both are membrane proteins. No affinity reported.","key_references":[{"PMID":"33420124","why":"Identifies and maps the FAT1-GPC3 interaction."}],"covers":["LR002613","LR005880"]},"LR007194":{"pair":"FCER2 -> FGFR2","headline":"No paper evidence; two IntAct records (SPR, solid phase) are the only support.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond IntAct entries [DB:IntAct P06734-P21802] [DB:IntAct P21802-P06734].","localisation_and_range":"CD23 is flagged secreted, receptor and transmembrane; FGFR2 receptor and transmembrane [flag]. Classed Receptor-Receptor.","caveats":"Both records cite one study (PMID 35922511), no curator-verified paper; one judged paper was abstract-insufficient. Treat as unvalidated, possibly a screening hit between two receptors.","key_references":[],"covers":["LR007194"]},"LR000597":{"pair":"FGF1 -> FGFR4","headline":"Well-supported direct FGF1-FGFR4 binding by cross-linking, SPR and cell binding; FGF1 activates the receptor.","interaction_type":"direct binding","direction_and_effect":"FGFR4 in liver parenchymal cells binds only FGF-1 in a heparan sulfate binding assay [PMID:10336501]. Purified human FGFR4 extracellular domain formed complexes with FGF-1 and FGF-2 in solution, with and without heparin [PMID:10736564]. FGF1 binds FGFR4 directly without KLB and is curated as agonist [PMID:22442730]. FGF1 activates all seven FGFR-expressing BaF3 lines [PMID:8663044].","molecular_requirements":"Heparan sulfate is a co-factor for binding specificity [PMID:10336501], but FGFR4 extracellular domain binding is heparin-independent [PMID:10736564]. KLB is not required [PMID:22442730].","affinity_potency":[],"species_and_systems":"Recombinant human FGFR4 ectodomain (cross-linking, biosensor) [PMID:10736564]; 125I-FGF1 binding to receptor-expressing 293 cells [PMID:22442730]; BaF3 species unspecified [PMID:8663044]. Human and mouse records exist, neither ortholog-inferred.","localisation_and_range":"FGF1 secreted; FGFR4 transmembrane receptor, also flagged secreted [flag].","caveats":"Most papers are abstract level, BaF3 papers browser-read with quotes pending spot-check [PMID:16597617][PMID:8663044]. No affinity values in our evidence. One review-only paper. Database: BioGRID reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"10736564","why":"FGFR4 ectodomain complexes with FGF-1 by cross-linking and biosensor"},{"PMID":"22442730","why":"FGF1 binds FGFR4 directly, KLB-independent"},{"PMID":"10336501","why":"FGFR4 binds only FGF-1 in liver cells"}],"covers":["LR000597","LR004081"]},"LR005169":{"pair":"FGF10 -> FGFRL1","headline":"FGF10 binds FGFRL1 with high affinity, which acts as a kinase-lacking decoy that antagonises FGF signalling.","interaction_type":"direct binding","direction_and_effect":"The FGFRL1 ectodomain, shed or membrane-bound, binds FGF2, FGF3, FGF4, FGF8, FGF10 and FGF22 with high affinity (dot blot, cell-based binding, surface plasmon resonance) [PMID:19920134]. FGFRL1 lacks the split tyrosine kinase domain and antagonises FGF signalling in Xenopus embryos, so it acts as a decoy [PMID:19920134].","molecular_requirements":"Both the soluble shed ectodomain and the membrane form bind; no co-receptor requirement is reported in our evidence [PMID:19920134].","affinity_potency":[],"species_and_systems":"C2C12 myoblasts and HEK293 cells for shedding and binding; Xenopus embryos for the functional assay [PMID:19920134]. Mouse pair is projected.","localisation_and_range":"FGFRL1 can be shed as a soluble ectodomain, so it may act at range as well as at the cell surface [PMID:19920134].","caveats":"Affinity values for FGF10 specifically are not given in the dossier. Abstract-only reading. Decoy action does not drive a kinase signal, so CCC scoring should treat it as inhibitory.","key_references":[{"PMID":"19920134","why":"FGFRL1 binds FGF10 and acts as a decoy"}],"covers":["LR001814","LR005169"]},"LR000579":{"pair":"FGF16 -> FGFR4","headline":"FGF16 activates FGFR4-expressing BaF3 cells with high activity; functional evidence from one panel study.","interaction_type":"functional only","direction_and_effect":"FGF9, FGF16 and FGF20 activated FGFR4 and FGFRc isoforms with high activity [PMID:16597617]. Agonist.","molecular_requirements":"not reported in our evidence beyond the BaF3 FGFR4 line [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF16 flagged secreted; FGFR4 flagged secreted and transmembrane, hence possibly membrane and soluble forms [flag].","caveats":"Single functional paper, read as full text in a browser (quote unverified); activity is mitogenesis in BaF3 cells, not binding. Two other judged rows were review-only.","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFR4"}],"covers":["LR000579","LR004063"]},"LR000588":{"pair":"FGF19 -> FGFR1","headline":"FGF19 engages FGFR1 only with KLB present (direct binding, human); a separate BaF3 assay shows FGFR1c activity.","interaction_type":"direct binding","direction_and_effect":"FGF19 bound FGFR1-KLB as well as FGFR4-KLB and acts as an agonist, with comparable affinity for the two receptors [PMID:22442730]. In BaF3 mitogenic assays FGF19 was active toward FGFR1c but not FGFR1b [PMID:16597617].","molecular_requirements":"KLB is required: FGF19 did not bind FGFR1 alone, while 10% binding to FGFR4 alone was seen [PMID:22442730]. FGFR1c, not the b splice form, responds [PMID:16597617].","affinity_potency":[],"species_and_systems":"Binding work used human ligand and receptor in cells co-expressing FGFR1 and KLB, with 125I-FGF19 cross-linking [PMID:22442730]. The BaF3 study does not state species [PMID:16597617]. Databases: IntAct solid-phase assay and UniProt in-vitro interaction note [DB:IntAct][DB:UniProt].","localisation_and_range":"FGF19 is annotated secreted and FGFR1 as transmembrane [flag], so endocrine/paracrine signalling to cells expressing FGFR1-KLB is implied by the flags only.","caveats":"Not a standalone FGFR1 pair: it needs KLB, so FGFR1 expression alone is a poor predictor. FGF19 mainly acts through the liver FGFR4-KLB and less in adipose FGFR1-KLB [PMID:22442730]. The BaF3 paper was read as abstract only; affinity not reported in our evidence.","key_references":[{"PMID":"22442730","why":"FGF19 binds FGFR1-KLB comparably to FGFR4-KLB; KLB required"},{"PMID":"16597617","why":"BaF3 activity toward FGFR1c but not FGFR1b"}],"covers":["LR000588"]},"LR004098":{"pair":"FGF2 -> NRP1","headline":"FGF2 binds immobilised NRP1 by optical biosensor, largely through ionic, heparin-sensitive interaction, and NRP1 potentiates FGF2 action.","interaction_type":"direct binding","direction_and_effect":"FGF2 interacts with Npn-1 immobilised on a biosensor and in a solution assay. Npn-1 potentiated FGF-2 growth stimulation of HUVECs [PMID:15695515]. A BioGRID FRET record is also listed [DB:BioGRID].","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"270,000-1,600,000 M-1s-1","assay":"association rate constants for FGF-2, FGF-4 and HGF/SF binding to Npn-1 (optical biosensor)","system":"recombinant, in vitro","cite":"PMID:15695515"}],"species_and_systems":"Human proteins; HUVEC growth assay [PMID:15695515]. Mouse and human pairs are ortholog-inferred.","localisation_and_range":"NRP1 is flagged both secreted and transmembrane, and FGF2 secreted [flag].","caveats":"Binding is largely electrostatic and Npn-1 binds many heparin-binding proteins, so specificity is limited; rate range covers FGF-2, FGF-4 and HGF/SF together, not FGF2 alone [PMID:15695515]. The BioGRID record cites a different paper than the one in our evidence [DB:BioGRID].","key_references":[{"PMID":"15695515","why":"Biosensor binding of FGF-2 to Npn-1 and potentiation of FGF-2 activity"}],"covers":["LR000614","LR004098"]},"LR004089":{"pair":"FGF23 -> FGFR3","headline":"FGF23 binds FGFR3c with high affinity in opossum kidney cells and activates c isoforms in other assays.","interaction_type":"direct binding","direction_and_effect":"FGF-23 binds FGF receptor 3c with high affinity in opossum kidney cells [PMID:12032146]; FGF23 binds and activates c isoforms of FGFR1-3 and FGFR4 [PMID:16081635, PMID:16597617]. Stimulatory.","molecular_requirements":"c isoform needed, not b [PMID:16081635]; heparin-like molecules were required for FGF-23 activity [PMID:12032146].","affinity_potency":[],"species_and_systems":"Opossum kidney cells [PMID:12032146]; human reagents for SPR [PMID:16081635]; BaF3 screen species unspecified [PMID:16597617]. Human pair is not ortholog-inferred; mouse also direct.","localisation_and_range":"FGF23 secreted [flag].","caveats":"No numeric affinity in the dossier. Abstract-only reading for two papers. One review-only row not shown.","key_references":[{"PMID":"12032146","why":"FGF-23 binds FGFR3c in opossum kidney cells"},{"PMID":"16081635","why":"SPR and mitogenesis on c isoforms"},{"PMID":"16597617","why":"BaF3 screen"}],"covers":["LR000605","LR004089"]},"LR005178":{"pair":"FGF8 -> FGFRL1","headline":"FGF8 binds FGFRL1 with high affinity; FGFRL1 acts as a decoy that antagonises FGF signalling.","interaction_type":"direct binding","direction_and_effect":"Soluble and membrane-bound FGFRL1 bind FGF8 (among FGF2, FGF3, FGF4, FGF10, FGF22), and FGFRL1 expressed in Xenopus embryos antagonised FGFR signalling, supporting a decoy role [PMID:19920134].","molecular_requirements":"FGFRL1 has an FGFR-like extracellular domain but lacks the split tyrosine kinase domain needed for signal transduction [PMID:19920134]. Heparin dependence is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand dot blot, cell-based binding and surface plasmon resonance; shed ectodomain from C2C12 myoblasts and HEK293 cells; Xenopus embryo antagonism [PMID:19920134]. Mouse pair is projected from human.","localisation_and_range":"FGFRL1 ectodomain is shed from the membrane by an unidentified protease, giving soluble and membrane-bound forms [PMID:19920134].","caveats":"Abstract-only reading. \"High affinity\" has no number in our evidence, and the abstract does not resolve binding per ligand.","key_references":[{"PMID":"19920134","why":"FGFRL1 shedding, FGF8 binding and antagonism"}],"covers":["LR001823","LR005178"]},"LR005907":{"pair":"FGL2 -> FCGR2B","headline":"FGL2 binds Fcgr2b-transfected cells by flow cytometry in mouse; one paper.","interaction_type":"direct binding","direction_and_effect":"Fgl2 binding to Fcgr2b-transfected cells was confirmed by flow cytometry and abrogated by anti-FcgRIIB [PMID:38902261]. Fgl2 is immunosuppressive; T cell Fgl2 deletion improved tumour control [PMID:38902261].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins and cells; B16 tumour and LCMV models [PMID:38902261]. Human pair listed but not inferred.","localisation_and_range":"FGL2 is flagged secreted [flag]; it is produced by CD8+ T cells [PMID:38902261].","caveats":"Single paper; binding shown on transfected cells only, no affinity. Human relevance not shown in our evidence. No database records.","key_references":[{"PMID":"38902261","why":"Fgl2 binds Fcgr2b-transfected cells; T cell exhaustion"}],"covers":["LR002641","LR005907"]},"LR002649":{"pair":"FLRT2 -> ADGRL3","headline":"Well supported direct binding of FLRT2 to LPHN3 (ADGRL3), with a measured Kd and crystallographic and cell-based studies.","interaction_type":"direct binding","direction_and_effect":"FLRT proteins were identified as endogenous latrophilin ligands; ecto-LPHN3-Fc bound strongly to FLRT1 and FLRT2 on cells [PMID:22405201]. FLRT2-LPHN3 drives adhesion of HeLa cells in stripe assays, while cortical neurons expressing endogenous FLRTs are repelled by LPHN3 [PMID:25728924]. Unc5D in cis switches FLRT2-dependent adhesion to Lphn3 [PMID:27091502].","molecular_requirements":"FLRT2 and LPHN3 ectodomains suffice for binding (SPR); the LPHN3 Olf domain carries the FLRT-binding site [PMID:25728924]. FLRT2 can bind Lphn3 and Unc5D simultaneously in a ternary complex, 1:1:2 FLRT2:Unc5D:Lphn3 [PMID:27091502].","affinity_potency":[{"value":"Kd 18\u201340 nM","assay":"Surface plasmon resonance, FLRT2 with LPHN3 Lec-Olf","system":"Purified recombinant proteins","cite":"PMID:25728924"}],"species_and_systems":"Binding studies used purified proteins and cells; the curated rows list human, while paper text refers to mouse Lphn3/FLRT2 and rat Unc5D [PMID:27091502, PMID:25728924]. Mouse pair is listed as not ortholog-inferred.","localisation_and_range":"Both partners carry transmembrane flags [flag]; the interaction occurs in trans between adjacent cells [PMID:22405201].","caveats":"Outcome counts also include abstract_insufficient, review_only and pending rows not shown. Effect depends on context (adhesion vs repulsion; Unc5D in cis) [PMID:25728924, PMID:27091502].","key_references":[{"PMID":"25728924","why":"SPR Kd for FLRT2-LPHN3 and structural basis."},{"PMID":"22405201","why":"FLRTs identified as latrophilin ligands; FLRT2 binds LPHN3."},{"PMID":"27091502","why":"FLRT2:Unc5D:Lphn3 ternary complex."}],"covers":["LR002649","LR005915"]},"LR005916":{"pair":"FLRT2 -> FLRT2","headline":"FLRT2 homophilic interaction is suggested by one abstract-level paper on FLRT proteins generally.","interaction_type":"functional only","direction_and_effect":"FLRT proteins can physically interact and FLRT-transfected cells sort out from non-transfected cells, a calcium-dependent homotypic adhesion effect [PMID:16440004]. This is a self-interaction, so ligand and receptor are the same protein.","molecular_requirements":"Cell sorting requires the LRR domains and is independent of the cytoplasmic domain [PMID:16440004].","affinity_potency":[],"species_and_systems":"Cultured transfected cells, Xenopus embryos and tissue aggregates; species of the proteins is unspecified in the curated row [PMID:16440004].","localisation_and_range":"Membrane-mediated homotypic adhesion (contact); FLRT2 is also flagged secreted [flag].","caveats":"Read on abstract only. The abstract speaks of FLRT proteins generally, not FLRT2 specifically. Both human and mouse versions are ortholog-inferred.","key_references":[{"PMID":"16440004","why":"FLRT cells sort homotypically; physical FLRT-FLRT interaction."}],"covers":["LR002650","LR005916"]},"LR002658":{"pair":"FLRT3 -> FLRT3","headline":"FLRT3 interacts homophilically, shown by cell aggregation and structure-guided mutants; the pair is FLRT3 with itself.","interaction_type":"direct binding","direction_and_effect":"FLRT3-FLRT3 homophilic interactions regulate their tangential distribution, and FLRT-transfected cells sort from non-transfected cells, suggesting altered adhesion [PMID:25374360][PMID:16440004]. FLRT proteins can physically interact [PMID:16440004]. Signalling direction is not applicable to a homophilic adhesion; effect not reported beyond adhesion.","molecular_requirements":"Homophilic binding uses a surface distinct from the Unc5-binding surface; separate mutants block FLRT-FLRT (FLRTFF) and FLRT-Unc5 (UF) binding [PMID:25374360]. Complexes of FLRT3, ADGRL3 and UNC5B/UNC5D are noted [DB:UniProt].","affinity_potency":[],"species_and_systems":"Cloned mouse Flrt3 in cell-aggregation, mutagenesis and neuron repulsion assays [PMID:25374360]; the 2006 paper used FLRT-transfected cultured cells with species unspecified (abstract only) [PMID:16440004].","localisation_and_range":"FLRT3 annotated secreted and transmembrane [flag]; adhesion is by cell-surface contact [PMID:25374360].","caveats":"The human pair is ortholog-inferred from mouse. The 2006 evidence is functional (cell sorting) and read as abstract only [PMID:16440004]. No affinity reported. IntAct lists a molecular sieving record [DB:IntAct].","key_references":[{"PMID":"25374360","why":"FLRT3 homophilic adhesion and structural basis"},{"PMID":"16440004","why":"FLRTs interact and drive cell sorting"}],"covers":["LR002658","LR005924"]},"LR005925":{"pair":"FLRT3 -> UNC5B","headline":"FLRT3 is the established UNC5B partner; supported by a binding screen, database complexes and repulsion work.","interaction_type":"direct binding","direction_and_effect":"Unc5B binds FLRT3, and shed FLRT2/3 ectodomains act as repulsive guidance cues for Unc5-positive neurons [PMID:21673655]. In a 126 x 126 screen, FLRT3 and Unc5B bound near saturation [PMID:26633812]; BioGRID lists reconstituted-complex records [DB:BioGRID].","molecular_requirements":"Interaction is via the extracellular domains; UNC5B has higher affinity for FLRT3 than FLRT2 [DB:UniProt]. FLRT3, ADGRL3 and UNC5B are found together in complexes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse retina, CHO.K1 and purified ectodomains [PMID:26633812]; 2011 paper supports it as background, abstract only [PMID:21673655]. Dossier covers human (ortholog-inferred) and mouse.","localisation_and_range":"FLRT3 annotated secreted and transmembrane, UNC5B transmembrane [flag]; ectodomains are shed [PMID:21673655].","caveats":"The 2011 row treats FLRT3-Unc5B as prior work, not its own test [PMID:21673655]. Unc5B stripes elicited no significant neuronal response in one assay (n=3/380, 1% repulsive) [PMID:26633812]. No affinity value in our evidence.","key_references":[{"PMID":"26633812","why":"Screen: all FLRT x Unc5 pairs bind"},{"PMID":"21673655","why":"Context: FLRT2/3 shed ectodomains repel Unc5 neurons"}],"covers":["LR002659","LR005925"]},"LR008580":{"pair":"FN1 -> ITGA4:ITGB1","headline":"Fibronectin EIIIA segment supports cell adhesion via alpha4beta1; broader evidence is mainly generic ITGB1 records.","interaction_type":"functional only","direction_and_effect":"Integrin alpha9beta1 or alpha4beta1 mediated cell adhesion to the EIIIA segment, blocked by anti-EIIIA and anti-integrin antibodies [PMID:11839764]. Adhesion-type.","molecular_requirements":"Specific to the alternatively spliced EIIIA segment [PMID:11839764]; alpha4 and beta1 both needed as the dimer. Other fibronectin forms are not tested in this paper.","affinity_potency":[],"species_and_systems":"Human, per curator fields, using MOLT-3 cells [PMID:11839764].","localisation_and_range":"FN1 flagged secreted; matrix-to-cell contact is inferred from flags [flag].","caveats":"One abstract-read paper; BioGRID ITGB1 and IntAct records are generic [DB:BioGRID] [DB:IntAct], and PDB/Reactome rows concern alpha5beta1 [DB:Reactome]. A review-only paper was not used.","key_references":[{"PMID":"11839764","why":"EIIIA segment of fibronectin is a ligand for alpha4beta1"}],"covers":["LR008580"]},"LR008535":{"pair":"FN1 -> ITGA5:ITGB1","headline":"Fibronectin binds the alpha5beta1 complex; direct binding evidence plus structural and database support.","interaction_type":"direct binding","direction_and_effect":"FN1 is a stimulatory ligand of the complex [flag]. High-affinity binding needs RGD and the synergy site [PMID:9211865]; in P29 cells stress-fibre formation on fibronectin needed alpha5beta1 together with syndecan 2 [PMID:10772816].","molecular_requirements":"Both chains are named in the complex (ITGA5, ITGB1) [flag]. Synergy site is recognised mainly by alpha5 N-terminal repeats, RGD mainly by beta1 [PMID:9211865]. Syndecan-2 heparan sulfate chains binding the fibronectin substrate cooperate with the integrin [PMID:10772816].","affinity_potency":[],"species_and_systems":"Human integrin/antibody mapping [PMID:9211865]; Lewis lung carcinoma-derived P29 cells with syndecan 2 antisense [PMID:10772816]. Species of the P29 cells is not stated beyond the cell line name.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Both papers are abstract-only. PMID:10772816 shows a co-receptor requirement and is a functional readout, not direct binding. Databases: BioGRID FN1-ITGB1 reconstituted complex and affinity capture records [DB:BioGRID], IntAct SPR [DB:IntAct], PDB 7NWL [DB:PDB 7NWL], Reactome [DB:Reactome], UniProt [DB:UniProt].","key_references":[{"PMID":"9211865","why":"Two-site (RGD plus synergy) binding mapped on the integrin"},{"PMID":"10772816","why":"Syndecan-2 co-receptor dependence"}],"covers":["LR008535"]},"LR008490":{"pair":"FN1 -> ITGA8:ITGB1","headline":"Fibronectin binds the alpha8beta1 complex; two concordant 1995 abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Alpha8beta1 is a fibronectin receptor: 293 cells use it for adhesion and it binds fibronectin-Sepharose, eluted by GRGDSP [PMID:7559467]; K562 transfectants attach and spread, and RGD peptides localise binding to the RGD site [PMID:7626807]. Annotated stimulatory [flag].","molecular_requirements":"Complex of ITGA8 and ITGB1 [flag]; alpha8 associates with beta1 [PMID:7559467].","affinity_potency":[],"species_and_systems":"Human 293 cells [PMID:7559467]; K562 cells, with chick embryo fibroblasts for localisation [PMID:7626807].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Both papers abstract-only. Unlike endogenous alpha5beta1 in K562 cells, alpha8beta1 promotes extensive spreading, not only attachment [PMID:7626807]. Database records shown are for FN1-ITGB1 / alpha5beta1, not alpha8 specifically [DB:BioGRID].","key_references":[{"PMID":"7559467","why":"Alpha8beta1 binds fibronectin matrix; RGD-eluted"},{"PMID":"7626807","why":"Adhesion, spreading, neurite outgrowth on fibronectin"}],"covers":["LR008490"]},"LR000669":{"pair":"FN1 -> MAG","headline":"Fibronectin was pulled down with MAG-Fc from rat/mouse neural cells; a single abstract-level binding study.","interaction_type":"direct binding","direction_and_effect":"A 210-kDa protein precipitated with MAG-Fc from NG108-15 cells was identified as fibronectin by peptide microsequencing, and confirmed in N2A cells, rat brain and spinal cord [PMID:11423128]. Effect direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat/mouse cell lines and rat tissue; human pair is ortholog-inferred [PMID:11423128].","localisation_and_range":"MAG is flagged secreted and receptor [flag]; the paper describes MAG as mediating glia-neuron cell-cell interactions [PMID:11423128].","caveats":"Affinity precipitation cannot exclude an indirect association; no affinity constant; abstract only. Different fibronectin isoforms were found in young and adult rat brain [PMID:11423128].","key_references":[{"PMID":"11423128","why":"Fibronectin identified as MAG binding partner"}],"covers":["LR000669","LR004153"]},"LR002667":{"pair":"FSTL1 -> FZD4","headline":"FSTL1 binds FZD4 directly in human-protein pull-downs and enhances Wnt3a-FZD4 association; one paper, full text read.","interaction_type":"direct binding","direction_and_effect":"FSTL1 interacted with FZD4 through its EC domain and increased Wnt3a association with FZD4, promoting Wnt/beta-catenin signalling (agonist/enhancer) [PMID:35525270].","molecular_requirements":"The EC domain of FSTL1 is the FZD4-binding part; the VWC and FS domains did not bind FZD4. FSTL1 did not interact with the coreceptor LRP6 alone, but LRP6 pulled down FSTL1 in the presence of FZD4, so FSTL1, FZD4 and LRP6 formed a complex [PMID:35525270].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in HEK293T cells and a pull-down with recombinant FSTL1 and FZD4-Fc supported a direct interaction; the experiments used human proteins. The mouse pair is projected from human evidence; kidney fibrosis experiments were in mouse obstructed kidneys [PMID:35525270].","localisation_and_range":"FSTL1 is flagged as secreted [flag]; FZD4 is flagged as a receptor [flag].","caveats":"Only one paper; no affinity reported in our evidence. FSTL1 also bound Wnt3a, so the effect may depend on the Wnt ligand present. FSTL1 also co-precipitated with FZD5, so the binding is not specific to FZD4 [PMID:35525270].","key_references":[{"PMID":"35525270","why":"Co-IP and recombinant pull-down showing direct FSTL1-FZD4 binding via the EC domain"}],"covers":["LR002667","LR005933"]},"LR005934":{"pair":"Ftl1 -> Scara5","headline":"Mouse pair projected from human evidence: ferritin light chain binds the SCARA5 SRCR domain; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The SRCR domain of SCARA5 recognises ferritin in a Ca2+-dependent manner, and L- and H-ferritin are both recognised [PMID:32907880]. Signalling effect is not reported in our evidence.","molecular_requirements":"The SRCR domain is the recognising region [PMID:32907880].","affinity_potency":[],"species_and_systems":"The pair is an ortholog-inferred mouse pair; the paper used biochemical assays with purified proteins, and the abstract does not say which species' proteins were used for this pair [PMID:32907880].","localisation_and_range":"Ftl1 is flagged as secreted and Scara5 as a receptor [flag].","caveats":"Abstract only; no affinity reported; the mouse assignment is inferred from human evidence.","key_references":[{"PMID":"32907880","why":"Biochemical assays showing ferritin recognition by the SCARA5 SRCR domain"}],"covers":["LR005934"]},"LR000678":{"pair":"GAL -> GALR3","headline":"Galanin binds GALR3 with lower affinity than GALR1/2 in human and rat receptor assays; supported by two abstracts.","interaction_type":"direct binding","direction_and_effect":"Galanin acts as an agonist at GALR3; GtoPdb lists a full agonist action [DB:GtoPdb]. Human GALR3 signals predominantly by inhibiting adenylate cyclase [PMID:9832121], and functional confirmation by GIRK-channel activation is reported [PMID:9722565].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"rat KD = 0.98 nM and human KD = 2.23 nM","assay":"125I-galanin saturation binding","system":"stably expressed rat and human GALR3","cite":"PMID:9722565"},{"value":"IC50 of 75 nM","assay":"competition binding by human galanin","system":"human GALR3","cite":"PMID:9832121"}],"species_and_systems":"Experiments used rat and human GALR3 expressed in cells. The mouse pair is projected from human evidence.","localisation_and_range":"GAL is flagged as secreted and GALR3 as a transmembrane receptor [flag]. Reactome also records a galanin-receptor binding reaction [DB:Reactome].","caveats":"The two papers report different affinities (KD 2.23 nM versus IC50 75 nM for human galanin) from different assay formats and are not directly comparable. Both were read as abstracts only. One further paper is pending.","key_references":[{"PMID":"9722565","why":"Cloning of GALR3 with rat and human galanin binding affinities"},{"PMID":"9832121","why":"Human GALR3 pharmacology: IC50 75 nM for human galanin"}],"covers":["LR000678","LR004162"]},"LR008850":{"pair":"GAL -> GPR151","headline":"Only one abstract reports weak activation of GPR151 (GalRL) by galanin; weak, single-source support.","interaction_type":"functional only","direction_and_effect":"Galanin gave a weak activation of GalRL, suggesting the endogenous ligand shares structural features with galanin [PMID:15111018].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell-based functional assay; species and system are not reported in our evidence (abstract only) [PMID:15111018].","localisation_and_range":"Galanin is flagged as secreted [flag].","caveats":"The activation is described as weak, and galanin is probably not the endogenous ligand. No affinity or potency reported, no database record, abstract only.","key_references":[{"PMID":"15111018","why":"Weak galanin activation of GalRL (GPR151)"}],"covers":["LR008850"]},"LR002676":{"pair":"GDF10 -> ACVR2A","headline":"Functional evidence only: GDF10 (BMP-3b) activity is facilitated by ActRIIA together with ALK-4 in mouse C2C12 cells.","interaction_type":"functional only","direction_and_effect":"BMP-3b directly activated Smad2/3 phosphorylation and PAI-1 expression but not Smad1/5/8, and opposed BMP-2 signalling [PMID:22155034]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Activity was facilitated by the combination of ALK-4 and ActRIIA; ActRIIA is paired with a type I chain, and ALK-2/-3/-6 were excluded [PMID:22155034].","affinity_potency":[],"species_and_systems":"Mouse myoblastic C2C12 cells per the abstract [PMID:22155034]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"One abstract-only paper (abstract truncated); inhibition by receptor extracellular-domain constructs, no direct binding or affinity.","key_references":[{"PMID":"22155034","why":"BMP-3b uses ALK-4/ActRIIA to activate Smad2/3"}],"covers":["LR002676","LR005941"]},"LR005943":{"pair":"GDF10 -> TGFBR1","headline":"Functional evidence: GDF10 selectively activates TbetaRI/II-dependent Smad3 phosphorylation in mouse mammary tumour cells.","interaction_type":"functional only","direction_and_effect":"GDF10 selectively activated TGF-beta receptor (TbetaRI/II)-dependent Smad3 phosphorylation; overexpression attenuated tumour formation and silencing reversed it [PMID:21518866]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Signalling needs the TbetaRI-TbetaRII heterodimer; Sca-1 disrupts that heterodimerization [PMID:21518866].","affinity_potency":[],"species_and_systems":"Murine mammary tumour cells and mice per the abstract [PMID:21518866]; the mouse pair is not ortholog-inferred, the human pair is.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"Single abstract-only paper; no direct binding to TGFBR1 chain alone and no affinity.","key_references":[{"PMID":"21518866","why":"GDF10 activates TbetaRI/II-Smad3; Sca-1 disrupts the heterodimer"}],"covers":["LR002678","LR005943"]},"LR000687":{"pair":"GDF11 -> ACVR1B","headline":"Database-asserted only: UniProt says GDF11 interacts with ACVR1B in an ACVR2B-dependent manner (by similarity).","interaction_type":"database-asserted only","direction_and_effect":"UniProt: GDF11 interacts with ACVR1B, TGFBR1 and ACVR1C in an ACVR2B-dependent manner (By similarity) [DB:UniProt].","molecular_requirements":"ACVR2B is required for the type I interaction per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"No judged papers; the annotation is by similarity, and two screened rows were different-entity.","key_references":[],"covers":["LR000687","LR004171"]},"LR004179":{"pair":"GDF2 -> ENG","headline":"BMP9 (GDF2) binds the endoglin ectodomain directly; crystal structure, SPR and BLI data support a co-receptor/decoy role.","interaction_type":"direct binding","direction_and_effect":"Structural work shows BMP9 binding to the ENG orphan domain, described as compatible with type I but not type II receptor recognition [PMID:28564608]. Membrane ENG is a co-receptor and BMP9 is labelled agonist at the receptor level [PMID:17311849]. Soluble ENG ECD-Fc acts as an antagonist/decoy that reduced VEGF-induced vessel formation and tumour burden [PMID:21737454].","molecular_requirements":"BMP9 contacts a hydrophobic groove of ENG orphan domain 1 (OR1); OR2 alone does not bind, and point mutants (Q270A/I271A, S278P, F282V) abolished binding [PMID:28564608]. Two ENG copies embrace homodimeric BMP9 (2:2 heterotetramer) [PMID:28564608][DB:UniProt]. ENG and type II receptors bind overlapping sites on BMP9 [PMID:21737454].","affinity_potency":[{"value":"KD 9.81 \u00d7 10\u22129 M (ENG ectodomain); 2.95 \u00d7 10\u22127 M (OR); 1.79 \u00d7 10\u22127 M (MOR)","assay":"biolayer interferometry (BLI)","system":"recombinant human ENG constructs with BMP9","cite":"PMID:28564608"}],"species_and_systems":"Crystal structures use human ENG and BMP9 [PMID:28564608]. ECD-Fc work used mouse and human endoglin in SPR, cell assays, chick CAM and mouse tumour models [PMID:21737454]. COS cells, bovine aortic and glioblastoma cells in [PMID:17311849]. The mouse pair is projected from human evidence.","localisation_and_range":"BMP9 is flagged secreted [flag]; ENG is described as a transmembrane co-receptor, with a shed soluble form [PMID:21737454]. Acts in endothelial cells [PMID:17311849].","caveats":"Two of three papers were read as abstracts only. Two cited reports show high-affinity binding without a Kd in our excerpts [PMID:17311849][PMID:21737454]. Soluble ENG is antagonistic whereas membrane ENG supports signalling.","key_references":[{"PMID":"28564608","why":"Crystal structure and BLI kinetics of ENG-BMP9"},{"PMID":"21737454","why":"Direct high-affinity binding of ENG ECD-Fc to BMP9, orphan domain mapping"},{"PMID":"17311849","why":"BMP9 binds ALK1 and endoglin in transfected cells"}],"covers":["LR000695","LR004179"]},"LR008274":{"pair":"GDF3 -> ACVR1C:ACVR2A","headline":"Complex pair with no curator-verified paper; rests on GtoPdb and UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF3 as agonist of both subunits (ACVR1C and ACVR2A) as separate records [DB:GtoPdb]. UniProt says GDF3 signals via a receptor complex based on ACVR1C and CRIPTO [DB:UniProt].","molecular_requirements":"UniProt names CRIPTO as part of the receptor complex; it is not in this entry [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the database evidence is not reported in our evidence.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor complex is flagged transmembrane [flag].","caveats":"No papers; only review-level sources were judged. Pairing with this type II receptor is not shown directly.","key_references":[],"covers":["LR008274"]},"LR002685":{"pair":"GDF3 -> ACVR2A","headline":"GDF3 signalling involves ActRIIA (with ALK4 and Cripto) in reporter assays; binding is not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 signalling can be mediated by ALK4, type II receptors ActRIIA and ActRIIB, and Cripto, activating Smad-dependent reporters [PMID:17936261]. Agonist [PMID:17936261][DB:GtoPdb].","molecular_requirements":"The paper tests the full set (ALK4, ActRIIA, ActRIIB, Cripto), so the role of this receptor alone is not separated; native GDF3 needs a heterologous prodomain, Furin or Nodal to signal [PMID:17936261].","affinity_potency":[],"species_and_systems":"Heterologous cell reporter assays; curators label human [PMID:17936261]. The human pair is ortholog-inferred and the mouse pair listed as direct.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor is flagged transmembrane [flag].","caveats":"Abstract only. No direct binding data; the paper treats the type II receptors as a group.","key_references":[{"PMID":"17936261","why":"GDF3 signals via ALK4, ActRIIA/B and Cripto"}],"covers":["LR002685","LR005950"]},"LR000696":{"pair":"GDF5 -> ACVR2A","headline":"GDF-5 binds ActR-II (ACVR2A) in COS-1 transfectants; one abstract-level paper plus a BioGRID record.","interaction_type":"direct binding","direction_and_effect":"GDF-5 bound ActR-II when type II receptor cDNAs were transfected into COS-1 cells [PMID:8702914]. Listed as stimulatory in the interaction record.","molecular_requirements":"Not reported in our evidence beyond type II binding; GDF-5 did not bind TGF-beta type II receptor [PMID:8702914].","affinity_potency":[],"species_and_systems":"COS-1 transfectants, curators label human [PMID:8702914]. The mouse pair is projected from human.","localisation_and_range":"The ligand is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only; second confirmed row not shown. BioGRID is the Affinity Capture-Western record of the same paper [DB:BioGRID].","key_references":[{"PMID":"8702914","why":"GDF-5 binds ActR-II in transfected COS-1 cells"}],"covers":["LR000696","LR004180"]},"LR007239":{"pair":"GDF6 -> BMPR1B:BMPR2","headline":"GDF6 (CDMP-2) binds BMPR1B and BMPR2 in human-labelled binding assays and signals through BMPR1B; abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Stimulatory. CDMP-2 (curator-mapped to GDF6) showed affinity for BMPR-IB and BMPR-II, weakly for BMPR-IA, and signal was transduced by BMPR-IB in the presence of BMPR-II [PMID:9525338]. ALK6 (BMPR1B) overexpression conferred GDF6 signalling, and BMPRII shRNA suppressed it [PMID:16049014]. BioGRID lists reconstituted complexes for GDF6-BMPR1B and GDF6-BMPR2 [DB:BioGRID].","molecular_requirements":"Both chains are implicated: BMPR-IB (type I) plus BMPR-II (type II) for transcriptional activation [PMID:9525338]. Whether either chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator fields record human ligand and receptor; cell systems named are ATDC5, ROB-C26, MC3T3-E1 [PMID:9525338] and COS7 transfectants and MC3T3 cells [PMID:16049014]. Both papers read as abstracts only.","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Abstract-only evidence. No affinity values in the dossier. BMPR-IA binding was weaker, so BMPR1A is not excluded.","key_references":[{"PMID":"9525338","why":"Binding of CDMP-2 to BMPR-IB and BMPR-II plus reporter activation."},{"PMID":"16049014","why":"ALK6 and BMPRII required for GDF6 signalling."}],"covers":["LR007239"]},"LR004188":{"pair":"GDF6 -> BMPR2","headline":"GDF6 binds BMPR2 directly (KD 28.1 nM for rhBMP13) and BMPRII knockdown suppresses its signalling; binding is weaker than for type I receptors.","interaction_type":"direct binding","direction_and_effect":"Agonist-type binding: rhBMP13 (GDF6) bound BMPR2, as well as ALK3, ALK6, ACVR2A and ACVR2B [PMID:21702718]. BMPRII shRNA suppressed GDF6 signalling in MC3T3 cells [PMID:16049014]. CDMP-2 (GDF6) had affinity for BMPR-II [PMID:9525338]. BioGRID lists a reconstituted GDF6-BMPR2 complex [DB:BioGRID].","molecular_requirements":"BMPR2 acts with a type I receptor: ALK3 or ALK6 conferred GDF6 signalling [PMID:16049014]; BMPR-IB with BMPR-II transduced the CDMP-2 signal [PMID:9525338].","affinity_potency":[{"value":"KD 28.1 nM","assay":"surface plasmon resonance, KD (kin), rhBMP13 (GDF6) vs BMPR2 ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human ligands and receptors in binding assays [PMID:21702718]; MC3T3 cells with shRNA [PMID:16049014]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"BMPR2 and ACVR2A binding was more than 10-fold weaker than type I receptor binding [PMID:21702718]. rhBMP13 did not detectably activate SMAD1/5/8 in C3H10T1/2 cells [PMID:21702718] although Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. Two papers are abstract-only.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP13 (GDF6) to BMPR2 and other receptors."},{"PMID":"16049014","why":"BMPRII shRNA suppresses GDF6 signalling."},{"PMID":"9525338","why":"CDMP-2 receptor binding."}],"covers":["LR000704","LR004188"]},"LR009237":{"pair":"GDF9 -> ACVR2A","headline":"GDF9 -> ACVR2A: functional blockade only; ActR-IIA ectodomain partially blocked GDF-9 action.","interaction_type":"functional only","direction_and_effect":"The ActR-IIA ectodomain was partially effective in blocking GDF-9 action on granulosa cells, acting as a functional antagonist; BMPRII was most effective [PMID:12135884]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond BMPRII being the strongest blocker.","affinity_potency":[],"species_and_systems":"Cultured granulosa cells with receptor ectodomain-Fc chimeras; species not reported in our evidence; abstract-only [PMID:12135884].","localisation_and_range":"GDF-9 is described as an oocyte-secreted glycoprotein acting on granulosa cells [PMID:12135884]; ligand secreted flag also set [flag].","caveats":"Ectodomain blockade does not show direct binding to ACVR2A; only BMPRII was shown to coprecipitate GDF-9. Abstract-only; no affinity.","key_references":[{"PMID":"12135884","why":"Receptor ectodomain-Fc blockade of GDF-9 action."}],"covers":["LR009237"]},"LR004197":{"pair":"Gh -> Ghr","headline":"Weak: one mouse-row paper measured human GH on bovine/rat receptors in mouse cells; no mouse GH evidence.","interaction_type":"direct binding","direction_and_effect":"Wild-type and mutant bovine GHR bound human GH with similar affinity; the mutant lowered bovine GH affinity 200-fold [PMID:7862673]. Both hGH and bGH stimulated tyrosine phosphorylation of a 95-kDa protein via wild-type GHR [PMID:7862673].","molecular_requirements":"Arg43 in hGHR interacts with Asp171 of hGH; this explains species specificity [PMID:7862673].","affinity_potency":[],"species_and_systems":"Human GH, bovine GHR or rat GH-binding protein expressed in mouse L cells [PMID:7862673]; the pair row is a mouse ortholog projection.","localisation_and_range":"GH is flagged secreted [flag]; GHBP is secreted receptor ectodomain [PMID:7862673].","caveats":"The experiments do not test mouse GH or mouse GHR. Two other papers were abstract_insufficient. No databases listed.","key_references":[{"PMID":"7862673","why":"hGH binding to GHRs; Arg43 species specificity"}],"covers":["LR004197"]},"LR002694":{"pair":"GHRH -> GHSR","headline":"GHRH acts as an agonist at the ghrelin receptor GHS-R1a in one abstract-only study; not its canonical receptor.","interaction_type":"direct binding","direction_and_effect":"hGHRH(1-29)NH2 induced dose-dependent calcium mobilization in GHS-R1a-transfected HEK293 cells but not wild-type cells; radioligand binding and cross-linking indicated mediation by GHS-R1a. It activated inositol phosphate signalling, potentiated the ghrelin maximal response and increased 125I-ghrelin binding capacity [PMID:19088192].","molecular_requirements":"GHS-R1a isoform was used; GHRH-receptor antagonists JV-1-42 and JMR-132 also antagonized GHS-R1a [PMID:19088192].","affinity_potency":[],"species_and_systems":"Human GHRH on HEK293 and CHO cells expressing GHS-R1a [PMID:19088192]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted, receptor transmembrane [flag].","caveats":"Single paper, abstract only; no affinity reported; no database records. Independent confirmation not in our evidence.","key_references":[{"PMID":"19088192","why":"GHRH agonist activity at GHS-R1a"}],"covers":["LR002694","LR005959"]},"LR009219":{"pair":"GHRL -> MLNR","headline":"No curator-verified paper evidence; only a BioGRID reconstituted-complex record supports ghrelin-motilin receptor.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists a reconstituted complex between MLNR and GHRL [DB:BioGRID][PMID:12606621].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"Three papers were judged abstract_insufficient and none confirmed. Support rests on one database record.","key_references":[],"covers":["LR009219"]},"LR005961":{"pair":"GP1BA -> ITGB2","headline":"Evidence is for the alphaM beta2 heterodimer, with the binding site on alphaM; ITGB2 alone is not shown to bind GP Ibalpha.","interaction_type":"direct binding","direction_and_effect":"GP Ibalpha binding to Mac-1 (alphaM beta2) is mapped to the P201-K217 sequence of the alphaM I domain: swapping it for alphaL sequence abolished adhesion, and grafting it onto alphaL made alphaL beta2 bind GP Ibalpha [PMID:14530377]. Synthetic P201-K217 peptide bound GP Ibalpha directly and blocked alphaM beta2 adhesion [PMID:14530377]. Effect is adhesion.","molecular_requirements":"The paper maps binding to the alphaM I domain, not beta2; the ITGB2 row inherits complex-level evidence (curator note). Chain-only binding by ITGB2 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; alphaM beta2-expressing 293 cells [PMID:14530377]. Mouse pair is ortholog-inferred.","localisation_and_range":"GP Ibalpha is the platelet counter receptor and Mac-1 is on leukocytes, so contact-dependent platelet-leukocyte adhesion [PMID:14530377]; both are annotated non-secreted [flag].","caveats":"ITGB2 is only the partner chain of Mac-1; a CCC tool scoring ITGB2 alone would rest on complex-level evidence. No affinity reported in our evidence.","key_references":[{"PMID":"14530377","why":"Maps the binding site to alphaM; complex-level evidence"}],"covers":["LR002696","LR005961"]},"LR005187":{"pair":"GPHB5 -> TSHR","headline":"GPHB5, as part of the GPHA2:GPHB5 heterodimer, binds and activates TSHR; evidence is for the heterodimer, not the lone chain.","interaction_type":"direct binding","direction_and_effect":"The GPHA2/GPHB5 heterodimer (CGH, thyrostimulin) activates TSHR; 125I-CGH binding to TSHR cells was saturable, specific and of high affinity [PMID:16210345]. Agonist. In vivo CGH given to mice produced a hyperthyroid phenotype [PMID:16210345].","molecular_requirements":"The tested ligand is the GPHA2/GPHB5 heterodimer; GPHB5 alone was not shown to bind TSHR in our evidence. Unlabeled TSH did not compete for CGH binding, and the data are consistent with two binding sites, one shared with TSH and one binding CGH alone [PMID:16210345].","affinity_potency":[],"species_and_systems":"TSHR-transfected baby hamster kidney cells and mice; curators list human ligand and receptor [PMID:16210345].","localisation_and_range":"GPHB5 is flagged as secreted [flag].","caveats":"Chain-only caveat: support for GPHB5 is via the heterodimer. Abstract read only, and no affinity value reported in our evidence. Reactome records list TSHR binding TSH/thyrostimulin [DB:Reactome].","key_references":[{"PMID":"16210345","why":"Saturable high-affinity CGH binding to TSHR and competition data"}],"covers":["LR001832","LR005187"]},"LR005970":{"pair":"GPNMB -> GPR39","headline":"GPR39 is reported as a receptor for circulating GPNMB in cardiac repair; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"GPNMB was identified as a ligand for GPR39: GPR39 absence negated the beneficial effects of GPNMB after myocardial infarction [PMID:39455836]. Agonist-like effect: GPNMB enhanced myocyte contraction and reduced fibroblast activation in single-cell data [PMID:39455836].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Failing human and mouse hearts after MI; mouse loss-of-function models and viral delivery of GPNMB [PMID:39455836]. Human pair is ortholog-inferred.","localisation_and_range":"GPNMB is flagged as secreted [flag]; the abstract refers to circulating GPNMB and a type I transmembrane protein [PMID:39455836].","caveats":"Abstract only. The binding claim in the title is not backed by a described binding assay in our evidence; the evidence is genetic (GPR39 absence).","key_references":[{"PMID":"39455836","why":"GPR39 identified as receptor for circulating GPNMB in cardiac repair"}],"covers":["LR002705","LR005970"]},"LR006807":{"pair":"GUCA2B -> GUCY2C","headline":"Uroguanylin-GC-C is supported by database records and only a computational paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists an agonist [DB:GtoPdb]; UniProt says GUCY2C is also activated by guanylin and uroguanylin [DB:UniProt]. The one confirmed paper is a scRNA-seq ranking study that highlights GUCA2A/GUCA2B-GUCY2C in intestinal epithelial-endocrine crosstalk [PMID:41875947].","molecular_requirements":"Reactome lists a GUCY2C trimer with GUCA2A,B [DB:Reactome].","affinity_potency":[],"species_and_systems":"The paper's evidence is computational (LIANA-based consensus scoring of scRNA-seq), not an experiment [PMID:41875947].","localisation_and_range":"GUCA2B is flagged secreted [flag].","caveats":"No experimental paper in the dossier; computational evidence only predicts expression-based interactions. Abstract-only reading.","key_references":[{"PMID":"41875947","why":"Computational ranking of GUCA2A/GUCA2B-GUCY2C"}],"covers":["LR006807"]},"LR006762":{"pair":"H60a -> Klrk1","headline":"H60a is a mouse NKG2D ligand identified by NKG2D-Ig binding and NK-cell target susceptibility.","interaction_type":"direct binding","direction_and_effect":"H60 family proteins are GPI-anchored cell-surface ligands for mouse activating NKG2D; ectopic RAE-1 and H60 expression confers NK-cell target susceptibility [PMID:10894171].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor; mNKG2D-Ig fusion protein used to identify ligands [PMID:10894171].","localisation_and_range":"GPI-anchored cell-surface protein, so contact-dependent (juxtacrine) signalling [PMID:10894171]; entity flagged not secreted [flag].","caveats":"No affinity reported. The family is treated together in the paper; the excerpts do not separate H60a, H60b and H60c individually.","key_references":[{"PMID":"10894171","why":"RAE-1/H60 family as NKG2D ligands"}],"covers":["LR006762"]},"LR009228":{"pair":"HBEGF -> CD82","headline":"HB-EGF associates with CD82 at the cell surface by co-immunoprecipitation; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation showed CD82, along with CD63 and CD81, associates with proHB-EGF on the cell surface [PMID:10749879]. These TM4 proteins did not up-regulate diphtheria toxin binding of proHB-EGF, unlike CD9 [PMID:10749879].","molecular_requirements":"Association involves the membrane-anchored proHB-EGF; BioGRID lists affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Cell-surface co-IP; cell type and species not reported in our evidence beyond this [PMID:10749879].","localisation_and_range":"proHB-EGF is membrane-anchored (flag: secreted and transmembrane) and acts on neighbouring cells [PMID:10749879][flag].","caveats":"Abstract only. Co-IP shows association, not direct binding or a signalling effect. CD82 is a tetraspanin and not annotated as a receptor [flag].","key_references":[{"PMID":"10749879","why":"Co-IP of CD82 with proHB-EGF"}],"covers":["LR009228"]},"LR000759":{"pair":"HLA-C -> LILRB2","headline":"Direct, low-affinity binding of HLA-C to inhibitory LILRB2 shown by SPR and an allele survey.","interaction_type":"direct binding","direction_and_effect":"LILRB2 (ILT4) binds classical HLA class I including HLA-C (Cw*0401, Cw*0702) [PMID:12853576]; it carries ITIMs that inhibit cellular responses [PMID:12853576].","molecular_requirements":"Unlike LILRB1, LILRB2 bound both folded and free heavy chain forms [PMID:21270408]. The D1D2 domains alone bound by SPR [PMID:12853576].","affinity_potency":[{"value":"Kd approx 14 to approx 45 uM","assay":"surface plasmon resonance, ILT4 D1D2 over HLA-A*1101, -B*3501, -Cw*0401, -Cw*0702","system":"recombinant human proteins (range across the four alleles, not HLA-C alone)","cite":"PMID:12853576"}],"species_and_systems":"Human proteins and cells [PMID:12853576][PMID:21270408].","localisation_and_range":"HLA-C is flagged transmembrane [flag]; contact-dependent. UniProt records that LILRB2 recognises a broad spectrum of HLA-A, -B, -C, -G and -F alleles [DB:UniProt].","caveats":"The SPR paper was a browser read with an unverified quote. The Kd range pools several HLA alleles. Abstract-only survey paper.","key_references":[{"PMID":"12853576","why":"SPR affinities of ILT4 for classical HLA class I"},{"PMID":"21270408","why":"Binds both folded and free heavy chain HLA forms"}],"covers":["LR000759"]},"LR008346":{"pair":"HLA-DRA -> LAG3","headline":"A LAG-3 : HLA-DR1 complex structure exists, but no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"PDB 9BF9 is titled 'Human LAG-3-HLA-DR1 complex' (X-ray diffraction) [DB:PDB 9BF9]; Reactome records 'LAG3 (CD233) binds MHC II' [DB:Reactome R-HSA-8856157]. Effect: not reported in our evidence.","molecular_requirements":"The structure includes a DRA chain (P01903) [DB:PDB 9BF9]; whether the DRB chain is also required: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human complex by PDB title; further details not reported in our evidence.","localisation_and_range":"HLA-DRA is flagged not secreted [flag].","caveats":"Two papers judged review-only; none verified. No affinity in our evidence.","key_references":[],"covers":["LR008346"]},"LR001839":{"pair":"HLA-F -> KIR3DL1","headline":"HLA-F open conformers bind KIR3DL1 with lower affinity than KIR3DS1; direct binding, one full-text paper.","interaction_type":"direct binding","direction_and_effect":"HLA-F OCs bound KIR3DL1-Fc and triggered KIR3DL1zeta Jurkat reporter cells, to a much lesser extent than KIR3DS1 [PMID:27455421]. KIR3DL1 is described as inhibitory; the net effect in NK cells is not reported in our evidence.","molecular_requirements":"Binding is to HLA-F open conformers, not beta2m/peptide-bound HLA-F; Fc-fusion bead binding and surface plasmon resonance with HLA-F open conformers (OCs: heavy chain without beta2-microglobulin or peptide) [PMID:27455421].","affinity_potency":[{"value":"KD = (157 \u00b1 2) nM","assay":"surface plasmon resonance","system":"HLA-F OCs with KIR3DL1-Fc","cite":"PMID:27455421"}],"species_and_systems":"Human recombinant proteins and Jurkat reporter cells [PMID:27455421].","localisation_and_range":"Not reported in our evidence; HLA-F flagged transmembrane [flag].","caveats":"The headline of the paper is KIR3DS1; KIR3DL1 binding is secondary and weaker. Curators note only the Fc-bead assay for this row; the stimulatory modulatory label on the interaction conflicts with KIR3DL1 being inhibitory.","key_references":[{"PMID":"27455421","why":"HLA-F OCs bind KIR3DS1, KIR3DL1, KIR3DL2"}],"covers":["LR001839"]},"LR000768":{"pair":"HMGB1 -> SDC1","headline":"Amphoterin (HMGB1) binds syndecan in a 1992 solid-phase assay via heparan sulfate chains; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Syndecan bound amphoterin in a saturable way; binding was inhibited by heparan sulfate and heparin and partly by anti-amphoterin antibodies [PMID:1369684]. Amphoterin is proposed as a putative pericellular ligand. Signalling effect is not reported in our evidence.","molecular_requirements":"Heparan sulfate chains of syndecan are involved, since chondroitin sulfate was less effective at inhibiting [PMID:1369684].","affinity_potency":[],"species_and_systems":"Solid-phase assay; mouse mammary epithelial cells bound amphoterin directly [PMID:1369684]. Both species pairs are ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; both proteins localised to lateral surfaces of adhered epithelial cells, which suggests pericellular, contact-range action [PMID:1369684].","caveats":"Single old abstract-only paper. Binding rests on a glycosaminoglycan chain, so core-protein specificity is unclear.","key_references":[{"PMID":"1369684","why":"Syndecan binds amphoterin via heparan sulfate"}],"covers":["LR000768","LR004227"]},"LR002739":{"pair":"HMGB1 -> TLR2","headline":"HMGB1 acts as an agonist of TLR2 in a glioma model; functional evidence only, from one abstract-level paper plus database notes.","interaction_type":"functional only","direction_and_effect":"HMGB1 released from dying tumour cells acts as an endogenous TLR2 ligand on GBM-infiltrating dendritic cells; the anti-tumour response is TLR2-dependent, and glycyrrhizin or anti-HMGB1 blocks TLR2 activation by tumour supernatants and abolishes efficacy in vivo [PMID:19143470]. UniProt notes apoptotic HMGB1:nucleosome complexes can signal through TLR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence; UniProt describes TLR2 signalling via CD14 and TLR4:LY96/TLR2 complexes for endotoxin transfer [DB:UniProt]. IntAct lists a co-immunoprecipitation [DB:IntAct].","affinity_potency":[],"species_and_systems":"Mouse glioma models and bone-marrow-derived dendritic cells; the curator lists HMGB1 as human and TLR2 as mouse [PMID:19143470]. The mouse pair is listed without ortholog inference; the human pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged as secreted [flag]; the paper shows release from dying tumour cells acting on nearby dendritic cells [PMID:19143470].","caveats":"Paper read as abstract and excerpts only. No direct binding measurement is reported; the evidence is inhibition and TLR2-dependence. The paper's text notes HMGB1 can also activate TLR4 [PMID:19143470].","key_references":[{"PMID":"19143470","why":"Mouse glioma model: HMGB1 as TLR2 ligand, blocked by glycyrrhizin and antibody"}],"covers":["LR002739","LR005987"]},"LR002748":{"pair":"HSP90AA1 -> LRP1","headline":"Extracellular HSP90alpha is reported to engage LRP1/CD91; direct binding and functional evidence from two papers.","interaction_type":"direct binding","direction_and_effect":"Fluorescent hsp90 binds RAW264.7 and related cells via CD91, shown by alpha2-macroglobulin competition and anti-CD91 blockade [PMID:11290339]. Extracellular Hsp90alpha with clusterin promotes EMT, AKT/ERK/NFkB activation and migration in breast cancer cells, mediated by LRP1 [PMID:31273033].","molecular_requirements":"Clusterin joins the eHsp90alpha-LRP1 complex and enhances Hsp90alpha binding affinity to LRP1 [PMID:31273033].","affinity_potency":[],"species_and_systems":"Mouse macrophage-type cell lines [PMID:11290339]; human breast cancer cells [PMID:31273033]. BioGRID lists co-localisation and reconstituted-complex records [DB:BioGRID].","localisation_and_range":"HSP90AA1 carries no secreted flag [flag], but the paper studies extracellular Hsp90alpha [PMID:31273033].","caveats":"The 2001 paper shows direct CD91 binding only for gp96 (earlier work); hsp90 binding there is on cells. The 2019 paper was read as abstract only; no Kd reported. One further row was abstract_insufficient.","key_references":[{"PMID":"11290339","why":"hsp90 binds cells via CD91, competed by alpha2-macroglobulin and anti-CD91"},{"PMID":"31273033","why":"Extracellular Hsp90alpha acts through LRP1; clusterin enhances binding"}],"covers":["LR002748","LR005996"]},"LR000777":{"pair":"HSPG2 -> ITGA2","headline":"Endorepellin, the perlecan C-terminal fragment, signals through alpha2beta1 integrin in endothelial cells; evidence is for the fragment, not full-length perlecan.","interaction_type":"functional only","direction_and_effect":"The interaction between endorepellin and alpha2beta1 integrin raised cAMP, activated PKA and FAK, transiently activated p38 and HSP27, and led to disassembly of actin stress fibers and focal adhesions, blocking endothelial migration and angiogenesis [PMID:15240572]. Reactome records endorepellin binding alpha2beta1 integrin [DB:Reactome R-HSA-4088220].","molecular_requirements":"Acting form is the soluble C-terminal fragment (endorepellin; LG3 module said to hold most activity), paired with alpha2beta1, so ITGB1 is also needed [PMID:15240572] [DB:Reactome R-HSA-4088236].","affinity_potency":[],"species_and_systems":"Endothelial cells including HUVECs, in vitro, per the paper [PMID:15240572]. Species of the receptor assay beyond that is not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"Perlecan is flagged secreted [flag]; endorepellin is described as a soluble proteolytic fragment released from basement membrane [PMID:15240572].","caveats":"Evidence is for a fragment, not full-length HSPG2. Two other papers judged abstract_insufficient and are not shown. The alpha2 chain alone is not shown to be sufficient.","key_references":[{"PMID":"15240572","why":"Endorepellin-alpha2beta1 integrin signalling in endothelial cells"}],"covers":["LR000777","LR004235"]},"LR006816":{"pair":"HTN1 -> KDR","headline":"Histatin-1 directly binds VEGFR2 (KDR) and activates it to drive endothelial migration, per one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"VEGFR2 was necessary for histatin-1-induced endothelial cell migration (inhibitor and siRNA experiments), and histatin-1 co-immunoprecipitated and co-localised with VEGFR2; curators label it an agonist [PMID:35551916]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"Residues Phe26, Tyr30 and Tyr34 in the histatin-1 C-terminal domain were identified as relevant for VEGFR2 binding and activation [PMID:35551916].","affinity_potency":[],"species_and_systems":"Human histatin-1 with VEGFR2 in endothelial cells and pure-protein pulldowns [PMID:35551916].","localisation_and_range":"Histatin-1 is described as a salivary peptide acting on endothelial cells; KDR is flagged transmembrane [flag] [PMID:35551916].","caveats":"Abstract only. Pulldowns with pure proteins and optical tweezers indicate a transient but direct interaction; numeric kinetic parameters are not in our evidence. Histatin-1 also has TMEM97 assigned as receptor.","key_references":[{"PMID":"35551916","why":"Histatin-1 directly binds and activates VEGFR2 in endothelial cells"}],"covers":["LR006816"]},"LR002757":{"pair":"IBSP -> ITGB3","headline":"Integrin beta3 (alphaVbeta3) mediates BSP-RGD-induced migration of breast cancer cells; one abstract plus database records.","interaction_type":"functional only","direction_and_effect":"Blocking antibodies showed BSP-RGD-induced migration used the alpha(v)beta3 vitronectin receptor [PMID:9699501]. UniProt says ITGAV:ITGB3 is a receptor for IBSP promoting adhesion and migration [DB:UniProt].","molecular_requirements":"Receptor is the alphaV/beta3 heterodimer; ITGB3 alone is not shown.","affinity_potency":[],"species_and_systems":"Human MDA-MB-231 breast cancer cells [PMID:9699501]. Mouse pair is ortholog-inferred.","localisation_and_range":"IBSP is flagged secreted [flag].","caveats":"Abstract only; antibody blocking is indirect. One further row was review_only and one abstract_insufficient.","key_references":[{"PMID":"9699501","why":"alpha(v)beta3 used for BSP-RGD-induced migration"}],"covers":["LR002757","LR006004"]},"LR000786":{"pair":"ICAM1 -> ITGAX","headline":"Single abstract-level report of direct ICAM-1 binding to CD11c/CD18 by surface plasmon resonance; one paper only.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 acts as agonist/adhesion ligand for CD11c/CD18 (alphaXbeta2); surface plasmon resonance showed direct interaction, and soluble ICAM-1-Fc and a mimicking peptide competed for CD11c/CD18 binding [PMID:16252253].","molecular_requirements":"The evidence is for the alphaXbeta2 heterodimer, not ITGAX alone; ICAM-1 domain D4 was required, and the peptide did not bind alphaMbeta2 [PMID:16252253]. ITGB2 is therefore needed alongside ITGAX.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; mouse pair is projected from human evidence (ortholog inferred). Recombinant/in vitro binding [PMID:16252253].","localisation_and_range":"ICAM1 carries a secreted annotation flag [flag], but the evidence here is cell-surface adhesion, i.e. membrane-bound, contact-dependent signalling; the flag-based secreted label should be read with care.","caveats":"Single paper, read as abstract only [PMID:16252253]. One further judged row was abstract_insufficient. No database records.","key_references":[{"PMID":"16252253","why":"SPR and competition showing ICAM-1 binds CD11c/CD18 via domain D4"}],"covers":["LR000786","LR004244"]},"LR000795":{"pair":"ICAM4 -> ITGA2B","headline":"Direct binding of ICAM-4-Fc to activated alphaIIbbeta3 (platelet integrin) in one transfectant study; the human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Activated alphaIIbbeta3 binds recombinant ICAM-4-Fc specifically and dose dependently; curated as stimulatory [PMID:15355350]. UniProt describes ICAM4 as a ligand of ITGA2B:ITGB3 in erythrocyte-activated platelet adhesion [DB:UniProt].","molecular_requirements":"The receptor is the alphaIIb/beta3 heterodimer, and only the activated form bound. The alphaIIbbeta3 contact site is the ABED face of domain D1 with an extension in the C'-E loop of D2 [PMID:15355350].","affinity_potency":[],"species_and_systems":"Human ICAM-4-Fc and integrin cell transfectants [PMID:15355350]. Both listed interactions (human, mouse) are ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion. UniProt describes heterotypic erythrocyte-platelet adhesion [DB:UniProt].","caveats":"One paper, abstract only. Affinity not reported in our evidence. No mouse experiments.","key_references":[{"PMID":"15355350","why":"Integrin specificity for ICAM-4; alphaIIbbeta3 binding residues"}],"covers":["LR000795","LR004249"]},"LR008193":{"pair":"ICAM5 -> ITGAL:ITGB2","headline":"LFA-1 complex binding to ICAM-5 is supported by a human domain-mapping study, a crystal structure record and UniProt.","interaction_type":"direct binding","direction_and_effect":"ICAM-5 domain 1 supports CD11a/CD18 interaction and antibodies block human T-cell binding to rat hippocampal neurons [PMID:10741396]. UniProt states ITGAL:ITGB2 is a receptor of ICAM5 ensuring neuron-leukocyte adhesion [DB:UniProt].","molecular_requirements":"The complex is the receptor; the structure record PDB 3BN3 shows ICAM5 with the ITGAL chain (P20701) only [DB:PDB 3BN3]. Domain 1 of ICAM-5 is required [PMID:10741396].","affinity_potency":[{"value":"50 nM","assay":"lowest soluble ICAM-5 domain 1 concentration that inhibited T-cell binding to immobilized ICAM-5","system":"human T cells, immobilized ICAM-5","cite":"PMID:10741396"}],"species_and_systems":"Human proteins and T cells with rat hippocampal neurons [PMID:10741396].","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; neuron-leukocyte adhesion described in UniProt [DB:UniProt].","caveats":"One paper, abstract only. The 50 nM figure is an inhibition concentration, not an affinity. Beta2-subunit contribution is not separated.","key_references":[{"PMID":"10741396","why":"ICAM-5 domain 1 and CD11a/CD18 interaction"}],"covers":["LR008193"]},"LR005196":{"pair":"Icosl -> Ctla4","headline":"Mouse Icosl-Ctla4 binding was tested and not found; the only paper reports the interaction as human-specific.","interaction_type":"database-asserted only","direction_and_effect":"No mouse binding was seen: murine CTLA-4Ig did not stain murine B7-H2 transfected 293T cells [PMID:21530327]. The same paper reports B7-H2 (ICOSLG) as a ligand of CTLA-4 in human, with binding blocked by an anti-CTLA-4 mAb [PMID:21530327].","molecular_requirements":"Not reported for mouse. Replacing the murine B7-H2 IgV region with the human counterpart allowed binding to murine CTLA-4, which localises the species difference to that domain [PMID:21530327].","affinity_potency":[],"species_and_systems":"Experiments used 293T transfectants and Ig fusion proteins; human B7-H2 binds human CTLA-4 and also murine CTLA-4 [PMID:21530327]. This mouse pair is ortholog-inferred from human evidence.","localisation_and_range":"Annotation flags list Icosl as non-secreted and a receptor, and Ctla4 as secreted [flag]. Range not reported in our evidence.","caveats":"This mouse pair is an explicit negative in the verified paper [PMID:21530327]. The only database record is a UniProt note on the human protein: interacts with CTLA4 (in vitro) [DB:UniProt]. Treat the mouse edge as unsupported.","key_references":[{"PMID":"21530327","why":"Shows the B7-H2/CTLA-4 interaction in human and its absence in mouse"}],"covers":["LR005196"]},"LR001848":{"pair":"ICOSLG -> CTLA4","headline":"Direct binding of human B7-H2 to CTLA-4 (receptor array, flow cytometry, SPR); human-specific.","interaction_type":"direct binding","direction_and_effect":"CTLA-4Ig bound B7-H2+ 293T cells and binding was largely abolished by anti-CTLA-4 mAb [PMID:21530327]. The curator labelled the effect antagonist, but the paper's text shown here does not state the functional effect on CTLA-4 signalling [PMID:21530327].","molecular_requirements":"B7-H2 binding sites for CD28 and CTLA-4 largely overlap; B7-2 but not B7-1 partially blocks CTLA-4Ig binding to B7-H2 cells [PMID:21530327]. CTLA-4Ig (Abatacept) bound B7-H2+ cells [PMID:21530327].","affinity_potency":[],"species_and_systems":"Human proteins in 293T transfectants, with SPR confirmation [PMID:21530327]. Not conserved in mouse.","localisation_and_range":"Both partners flagged transmembrane [flag]; CTLA4 is also flagged secreted [flag].","caveats":"Single paper. B7-H2Ig binds weaker than B7-1/B7-2 [PMID:21530327]. UniProt notes CTLA4 interacts with ICOSLG [DB:UniProt].","key_references":[{"PMID":"21530327","why":"Shows B7-H2 binds CTLA-4 in human"}],"covers":["LR001848"]},"LR007275":{"pair":"IFNA4 -> IFNAR1:IFNAR2","headline":"IFNA4 to the IFNAR1:IFNAR2 heterodimer rests on class-wide binding data for each chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM and IFNAR2 at 0.4-5 nM [PMID:21856167]. GtoPdb lists IFNA4 as an agonist at both chains [DB:GtoPdb].","molecular_requirements":"Both chains are listed; each binds separately, IFNAR2 much more tightly [PMID:21856167]. Binding to the assembled heterodimer is not reported in our evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"},{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single verified paper, abstract only, class-wide values with no value for IFNA4; one further row was review only.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR007275"]},"LR004269":{"pair":"IFNB1 -> IFNAR1","headline":"IFNB1 binds IFNAR1 directly, including an IFNAR2-independent mode, with nanomolar affinity; well supported.","interaction_type":"direct binding","direction_and_effect":"IFN-beta is an agonist at IFNAR1 [DB:GtoPdb]. IFN-beta can ligate IFNAR1 independently of IFNAR2, and the IFNAR1-IFN-\u03b2 complex signalled a distinct gene set independent of Jak-STAT [PMID:23872679]. All IFNs tested showed competitive 1:1 binding to ifnar1-EC and ifnar2-EC [PMID:17174979].","molecular_requirements":"IFNAR1 alone is sufficient for ligation per the structural study, though in the canonical receptor it pairs with IFNAR2 [PMID:23872679]. Deleting Pro335 of IFNAR1 reduced affinity for hIFN-\u03b2 [PMID:29311663].","affinity_potency":[{"value":"15.8 \u00b1 3.4 nM","assay":"affinity of hIFN-\u03b2 for wild-type IFNAR1 (n = 3)","system":"human proteins","cite":"PMID:29311663"},{"value":"28.1 \u00b1 3.1 nM","assay":"affinity for IFNAR1 with Pro335 deletion","system":"human proteins","cite":"PMID:29311663"}],"species_and_systems":"Human proteins in binding studies [PMID:17174979][PMID:29311663]; mouse Ifnar1-/- mice were protected from LPS-induced sepsis, Ifnar2-/- mice were not [PMID:23872679]. Both human and mouse pairs are listed, neither ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"One paper (PMID:1834641) is recorded as pair_absent: its abstract concerns IFN-omega competing with labelled IFN-alpha for the receptor, and IFN-beta also blocked binding, so it does not show absence. Two of three binding papers are abstract-level. Affinity values come from the full-text paper only.","key_references":[{"PMID":"23872679","why":"IFN-\u03b2 ligates IFNAR1 independently of IFNAR2; structure"},{"PMID":"29311663","why":"IFN-\u03b2 affinity for wild-type and Pro335-deleted IFNAR1"},{"PMID":"17174979","why":"real-time binding of type I IFNs to ifnar1-EC and ifnar2-EC"}],"covers":["LR000829","LR004269"]},"LR002766":{"pair":"IGF1 -> ITGAV","headline":"Integrin alphavbeta3 directly binds IGF1 in one verified study; ITGAV is the alpha chain.","interaction_type":"direct binding","direction_and_effect":"Integrin alphavbeta3 specifically and directly bound IGF-1 in cell adhesion, ELISA-type binding and surface plasmon resonance assays. IGF-1 mediated co-precipitation of alphavbeta3 and IGF1R, giving a ternary complex [PMID:19578119].","molecular_requirements":"The R36E/R37E IGF-1 mutant (C-domain) had reduced integrin binding and still bound IGF1R, but failed to drive IGF1R phosphorylation, AKT and ERK1/2 activation or proliferation [PMID:19578119]. The heterodimer was tested, not ITGAV alone.","affinity_potency":[],"species_and_systems":"Binding assays were run with alphavbeta3; proliferation was tested in Chinese hamster ovary cells [PMID:19578119]. The mouse pair is ortholog-inferred.","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"Abstract-only read. Evidence is for the alphavbeta3 heterodimer; no affinity value is reported in our evidence.","key_references":[{"PMID":"19578119","why":"Direct alphavbeta3-IGF-1 binding and ternary complex"}],"covers":["LR002766","LR006012"]},"LR007266":{"pair":"IGF1 -> ITGAV:ITGB3","headline":"Binding is annotated in UniProt (from a direct-binding study), but the only paper judged here is a verified negative.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ITGAV:ITGB3 binds IGF1, that this binding is essential for IGF1 signaling, and that the integrin is in a ternary complex with IGF1 and IGF1R [DB:UniProt] [PMID:19578119].","molecular_requirements":"Both chains are listed in the complex [flag]. Ternary complex with IGF1R is reported by UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond UniProt.","localisation_and_range":"IGF1 is flagged secreted; the integrin complex is flagged transmembrane [flag].","caveats":"The judged paper (a skin carcinoma study) showed IGF1R signaling raising ITGAV expression, with no IGF1-integrin binding claim [PMID:39075581]. Another paper was abstract-insufficient. No verified paper in this dossier shows the binding.","key_references":[],"covers":["LR007266"]},"LR010938":{"pair":"IGFBP3 -> IGF2","headline":"Database-supported IGFBP3-IGF2 binding, classed as ligand-ligand; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory, class Ligand-Ligand. Reactome lists formation of the IGF:IGFBP3:ALS complex [DB:Reactome].","molecular_requirements":"IGFBP3 forms a ternary complex of about 140 to 150 kDa with IGF1 or IGF2 and an 85 kDa glycoprotein (ALS) [DB:UniProt]; UniProt also says IGFBP3 binds IGF2 more than IGF1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human only; BioGRID lists reconstituted complexes; IntAct lists bio-layer interferometry [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag].","caveats":"No curator-verified paper (six candidates judged as a different entity). Database records only; no affinity.","key_references":[],"covers":["LR010938"]},"LR002775":{"pair":"IGFBP5 -> CAV1","headline":"Abstract and full text show IGFBP-5 co-precipitates with caveolin-1 in human lung fibroblasts; a trafficking interaction rather than classical signalling.","interaction_type":"direct binding","direction_and_effect":"IGFBP-5 localized to lipid rafts and bound Cav-1; Cav-1 was needed for IGFBP-5 internalization and nuclear trafficking, and Cav-1 scaffolding peptide increased IGFBP-5 uptake [PMID:20345844]. UniProt agrees the interaction allows trafficking to the nucleus [DB:UniProt].","molecular_requirements":"Not reported beyond Cav-1 itself.","affinity_potency":[],"species_and_systems":"Human lung fibroblasts (co-precipitation with anti-Cav-1 antibody) and Cav-1-null mouse fibroblasts for the loss-of-function side [PMID:20345844].","localisation_and_range":"IGFBP5 is annotated as secreted [flag]. Cav-1 sits in lipid rafts and the paper reports nuclear Cav-1 [PMID:20345844]; the curator frames Cav-1 as an internalization receptor.","caveats":"Evidence is co-immunoprecipitation from cell lysates, which does not show direct binding. Cav-1 is an intracellular scaffold, so this is unlikely to be a classical extracellular ligand-receptor pair for cell-cell communication scoring. No affinity.","key_references":[{"PMID":"20345844","why":"IGFBP-5 binds Cav-1; Cav-1 needed for uptake and nuclear trafficking"}],"covers":["LR002775","LR006021"]},"LR010947":{"pair":"IGFBP5 -> IGF1","headline":"Database-supported IGFBP5-IGF1 binding with an X-ray complex structure; no curated paper, classed as ligand-ligand.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory, class Ligand-Ligand; Reactome lists an IGF:IGFBP5:ALS complex [DB:Reactome]. UniProt says the interaction enhances the growth-stimulatory effects of IGF1 on fibroblasts, which sits opposite the inhibitory label [DB:UniProt].","molecular_requirements":"A complex of IGFBP-5 with IGF-I is deposited [DB:PDB 1H59]; ALS joins in the Reactome complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human only; assays include reconstituted complex and isothermal titration calorimetry [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag].","caveats":"No curator-verified paper (five candidates judged as a different entity). Database records only; no affinity value reported. Inhibitory versus enhancing effect is conflicting between annotation and UniProt.","key_references":[],"covers":["LR010947"]},"LR001857":{"pair":"IGSF11 -> VSIR","headline":"VSIG-3 (IGSF11) binds VISTA (VSIR) in a binding screen and inhibits human T cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"VSIG-3 binds VISTA in a functional ELISA binding screen and not other known B7 family members; no significant VSIG-8-VISTA interaction was seen [PMID:30220083]. VSIG-3 inhibits human T-cell proliferation and reduces IFN-gamma, IL-2, IL-17, CCL5, CCL3 and CXCL11 production; anti-VISTA neutralising antibodies attenuate both the binding and the T-cell inhibition [PMID:30220083]. VISTA acts as a co-inhibitory receptor in this report.","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human T cells and recombinant proteins; ELISA screen [PMID:30220083]. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"IGSF11 is flagged non-secreted and VSIR a transmembrane receptor [flag], suggesting membrane-bound contact signalling; the paper does not state this.","caveats":"Abstract only; affinity not reported. A single paper supports this pair. Mouse pair is ortholog-inferred, not tested.","key_references":[{"PMID":"30220083","why":"VSIG-3 binds VISTA and inhibits human T-cell function"}],"covers":["LR001857","LR005203"]},"LR004278":{"pair":"IHH -> BOC","headline":"Crystal structures and binding show all mammalian Hedgehog proteins, including IHH, bind BOC; abstract only.","interaction_type":"direct binding","direction_and_effect":"X-ray structures of Hh proteins alone and in complex with active domains of CDO and BOC show that all mammalian Hh proteins bind CDO and BOC in the same manner [PMID:20519495]. Hh-BOC binding is a co-receptor-type interaction; the paper reports it as positively linked to Hh signalling only in the background of Ihog family relatives [PMID:20519495]. IntAct and UniProt cite the same paper [DB:IntAct] [DB:UniProt].","molecular_requirements":"BOC binds Hh via its active domain; PTCH and SMO are separate membrane components [PMID:20519495].","affinity_potency":[],"species_and_systems":"Recombinant proteins; Sonic, Indian and Desert Hh studied, so IHH is covered by the paper's general statement [PMID:20519495]. PDB 3N1M and 3N1P hold Q14623 (IHH) with Q9BWV1 (BOC) [DB:PDB 3N1M]. Mouse pair is ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Abstract only; the abstract is truncated in the dossier and affinity for IHH-BOC is not reported. The paper says the Hh-CDO interaction is weakened at low pH.","key_references":[{"PMID":"20519495","why":"Structures of Hh proteins with CDO and BOC"}],"covers":["LR000848","LR004278"]},"LR000849":{"pair":"IHH -> CDON","headline":"Crystal structures and binding show all mammalian Hh proteins, including IHH, bind CDO (CDON); abstract only.","interaction_type":"direct binding","direction_and_effect":"X-ray structures of Hh proteins with the active domains of CDO and BOC show that all mammalian Hh proteins bind them in the same manner; Hh-CDO interaction is weakened at low pH [PMID:20519495]. CDO binds Sonic Hh with micromolar affinity and positively regulates Hh signalling, according to the abstract's background [PMID:20519495].","molecular_requirements":"Binding is through the CDO active domain [PMID:20519495]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant proteins; the PDB entry 3N1F holds Q14623 (IHH) with Q4KMG0 (CDON) [DB:PDB 3N1F]. Mouse pair is ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Abstract only; IHH-specific affinity is not given. The micromolar figure refers to Sonic Hh and background, not IHH.","key_references":[{"PMID":"20519495","why":"Structures of Hh proteins with CDO and BOC"}],"covers":["LR000849","LR004279"]},"LR007257":{"pair":"IHH -> GAS1:PTCH1","headline":"Mouse joint genetics links IHH and GAS1 in interzone apoptosis; the GAS1:PTCH1 complex is not tested.","interaction_type":"functional only","direction_and_effect":"In the Ihh E95K mouse model, IHH and partners CDON and GAS1 regulate interzone apoptosis; the model has GAS1 and CDON acting as dependence receptors, with raised IHH suppressing apoptosis [PMID:38472182]. GAS1 potentiated WT IHH signalling in a Gli1-luciferase assay, and this effect was reduced for the IHH mutants (from 26.5% to 83.9%) [PMID:38472182].","molecular_requirements":"The paper tests GAS1 and IHH; PTCH1 as part of a GAS1:PTCH1 complex is not tested [PMID:38472182]. PTCH1 is listed as a hedgehog receptor by UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse model, chick electroporation and cell luciferase assays [PMID:38472182]. The curator recorded human species.","localisation_and_range":"GAS1 is flagged non-secreted and PTCH1 a receptor [flag].","caveats":"No binding assay in the dossier for GAS1; the evidence sentence is from the abstract. The effect labelled antagonist by the curator conflicts with GAS1 potentiating IHH signalling in the luciferase assay.","key_references":[{"PMID":"38472182","why":"IHH and GAS1 in joint-interzone apoptosis and signalling"}],"covers":["LR007257"]},"LR004287":{"pair":"IL12A -> IL12RB1","headline":"IL12A (p35) to IL12RB1 rests on IL-12 receptor literature that mainly concerns the heterodimeric cytokine; direct evidence for this chain pair is thin.","interaction_type":"database-asserted only","direction_and_effect":"IL-12 is an agonist; GtoPdb lists IL12A-IL12RB1 as agonist [DB:GtoPdb]. IL-12Rbeta2-deficient mice lost all detectable IL-12-induced functions [PMID:11086056].","molecular_requirements":"The curator note says IL-12 is the IL12A:IL12B heterodimer and the receptor needs IL12RB1 and IL12RB2 [PMID:11086056]. In mouse, IL-12Rbeta1 is the subunit primarily responsible for binding IL-12 [PMID:11086056]. IL12RB1 chain appears with a P42701 chain in structures 8XRP and 8YI7 [DB:PDB 8XRP].","affinity_potency":[],"species_and_systems":"The only paper used IL12RB2-knockout mouse splenocytes (T and NK cells); dossier tags it human. Ortholog-inferred for human, direct for mouse. IntAct records a FACS-based association [DB:IntAct].","localisation_and_range":"IL12A is flagged secreted [flag].","caveats":"The sole paper is abstract-only and tests IL12RB2, not IL12RB1 binding to p35. Reactome records are for 'Interleukin-12' as a whole [DB:Reactome]. No affinity is reported.","key_references":[{"PMID":"11086056","why":"IL12RB2 knockout; notes IL12RB1 primarily binds IL-12 in mouse"}],"covers":["LR000857","LR004287"]},"LR000858":{"pair":"IL12A -> IL12RB2","headline":"IL12A-IL12RB2 is supported by direct binding data and a cryo-EM structure, though the ligand is really the IL12A:IL12B heterodimer.","interaction_type":"direct binding","direction_and_effect":"IL-12 induced heterodimerization of IL-12Rbeta1 and IL-12Rbeta2 [PMID:22306691]. IL12RB2-deficient mice had no detectable IL-12-induced function [PMID:11086056]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"IL12RB2 binds IL-12 on its own and with IL12RB1 forms high- and low-affinity sites [PMID:8943050]. Cryo-EM structures 8XRP and 8YI7 show an IL-12, IL12RB1 and IL12RB2 complex [DB:PDB 8XRP]. The same paper reports that IL-35 (p35-containing) also acts through IL-12Rbeta2 [PMID:22306691].","affinity_potency":[{"value":"Kd of about 5 nM","assay":"125I-huIL-12 radioligand binding to IL-12R beta2 alone","system":"cloned human subunit in COS-7 cells","cite":"PMID:8943050"},{"value":"Kds of about 55 pM and 8 nM","assay":"high- and low-affinity sites with IL-12R beta1 coexpressed","system":"COS-7 cells","cite":"PMID:8943050"}],"species_and_systems":"Human receptor cloned and tested in COS-7 [PMID:8943050]; HEK293T co-IP/FRET [PMID:22306691]; knockout mice [PMID:11086056].","localisation_and_range":"IL12A is flagged secreted [flag].","caveats":"IL12A alone is not the ligand: the dossier notes IL-12 is the p35/p40 heterodimer. Two of three shown papers were abstract-only, and the knockout paper does not test binding. One paper was judged a different entity.","key_references":[{"PMID":"8943050","why":"cloned IL-12Rbeta2 binds IL-12, with Kd values"},{"PMID":"22306691","why":"IL-12 induces IL-12Rbeta1/beta2 heterodimerization"},{"PMID":"11086056","why":"IL12RB2 required for IL-12 function in mice"}],"covers":["LR000858","LR004288"]},"LR002784":{"pair":"IL12A -> IL6ST","headline":"IL12A-IL6ST rests on one abstract: IL-35, not IL-12, signals through gp130; weak for this pair.","interaction_type":"functional only","direction_and_effect":"IL-35 (containing p35/IL12A) signalled through an IL-12Rbeta2/gp130 heterodimer or homodimers of each chain [PMID:22306691]. Gp130 homodimers sufficed for partial suppression of conventional T cells, not for iTr35 conversion [PMID:22306691].","molecular_requirements":"The full IL-35 receptor (IL-12Rbeta2 plus gp130) is needed for iTr35 conversion; one chain suffices for partial effects [PMID:22306691]. UniProt says p35 signals through IL12RB2/IL6ST heterodimers or homodimers [DB:UniProt].","affinity_potency":[],"species_and_systems":"Abstract-only; dossier tags both species as human, but the experiments' species are not stated in the abstract. Human pair ortholog-inferred, mouse pair not.","localisation_and_range":"IL12A is flagged secreted and IL6ST transmembrane [flag].","caveats":"The partner of p35 in IL-35 is not named in this dossier's abstract. Physical IL12A-IL6ST binding is not shown; evidence is functional. IL-12 itself is not shown to use gp130.","key_references":[{"PMID":"22306691","why":"IL-35 signals via IL-12Rbeta2/gp130 or homodimers"}],"covers":["LR002784","LR006027"]},"LR007293":{"pair":"IL12A:IL12B -> IL12RB1:IL12RB2","headline":"The correct IL-12 complex pair, but supported only by database records, no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL12A and IL12B as agonists at IL12RB1 and IL12RB2 [DB:GtoPdb]. Reactome records IL-12 binding the IL-12 receptor [DB:Reactome].","molecular_requirements":"Both receptor chains are listed. Cryo-EM structure 8XRP shows IL-12 with receptor subunits beta-1 and beta-2 [DB:PDB 8XRP]; X-ray 6WDQ is an IL23/IL23R/IL12Rb1 complex [DB:PDB 6WDQ]. IntAct records physical association by FACS for IL12B-IL12RB1 and IL12B-IL12RB2 chains [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human records only; the experimental systems are not detailed in our evidence.","localisation_and_range":"Ligand flagged secreted, not transmembrane [flag].","caveats":"No confirmed papers; two rows are review-only. Support is database-only. No affinity is reported.","key_references":[],"covers":["LR007293"]},"LR004296":{"pair":"IL15 -> IL2RB","headline":"IL15 uses IL2RB (with IL2RG) for binding and signalling; shown by transfection in 1994.","interaction_type":"direct binding","direction_and_effect":"IL-15 requires the IL-2R beta and gamma chains for binding and signaling in transfected cells [PMID:8026467]. GtoPdb lists agonist [DB:GtoPdb]. The soluble IL15RA acts as an IL-15 antagonist [PMID:15265897].","molecular_requirements":"Both beta and gamma chains are needed; the IL-2R alpha subunit is not involved in IL-15 binding [PMID:8026467]. High-affinity receptors share IL-2R beta and gamma with a private alpha chain [PMID:15265897].","affinity_potency":[],"species_and_systems":"Cells transfected with IL-2R subunits [PMID:8026467]; human cell lines [PMID:15265897].","localisation_and_range":"IL15 flagged secreted [flag].","caveats":"Both abstracts only. An IL-15-specific additional component was implied but not identified in the 1994 paper [PMID:8026467]. Affinity not reported in our evidence.","key_references":[{"PMID":"8026467","why":"IL-15 binding and signalling need IL-2R beta and gamma"},{"PMID":"15265897","why":"Shared beta/gamma with private alpha chains"}],"covers":["LR000866","LR004296"]},"LR000867":{"pair":"IL15 -> IL2RG","headline":"IL15 uses the shared IL2RG with IL2RB; chain-level evidence from two abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-15 interacts with the IL-2R beta/gamma c subunits; IL-15 forms a less stable bridge between IL-2Rbeta and gamma c than IL-2 does [PMID:8568232]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-2R beta and gamma c co-precipitate 1:1 with IL-2; with IL-15 only IL-2R beta was found [PMID:8568232]. High-affinity receptors share beta and gamma chains with a private alpha [PMID:15265897].","affinity_potency":[],"species_and_systems":"YT cells and OKT3 blasts (human) for cross-linking; the curated species is mouse in the record [PMID:8568232]. Soluble receptor work in human cell lines [PMID:15265897].","localisation_and_range":"IL15 flagged secreted [flag].","caveats":"Abstract only. The 1996 paper's co-precipitation shows IL2RG poorly associated with IL15, so direct IL15-IL2RG binding is not clearly shown [PMID:8568232]. One paper judged different_entity.","key_references":[{"PMID":"8568232","why":"Compares IL-15 and IL-2 interaction with beta/gamma c"},{"PMID":"15265897","why":"Receptor architecture"}],"covers":["LR000867","LR004297"]},"LR000876":{"pair":"IL19 -> IL20RA","headline":"IL-19 signals through IL20RA as part of the IL20RA/IL20RB heterodimer; binding and signalling shown in human transfected cells.","interaction_type":"functional only","direction_and_effect":"IL-19 acts as an agonist: it binds the IL-20R complex (IL-20Ralpha/IL-20Rbeta, type I) and this gives STAT3 phosphorylation and STAT-promoter activation [PMID:11564763]. IL-19 signals only through the type I complex, not IL-22R/IL-20Rbeta [PMID:11564763]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL20RB is also required: IL-19 signals through the IL-20RA/IL-20RB heterodimer [PMID:12351624, PMID:11564763]. Evidence is for the complex, not IL20RA alone.","affinity_potency":[],"species_and_systems":"Human ligand and receptors in transfected cell lines [PMID:11564763, PMID:12351624]; Reactome lists IL19:IL20RA:JAK1:IL20RB [DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers were read as abstracts. The single-chain row inherits complex-level evidence. In one cell line growth inhibition by IL-19 needed cytokine levels two orders of magnitude above those for STAT activation [PMID:12351624]. IntAct lists a surface plasmon resonance record for Q6UXL0-Q9UHD0 [DB:IntAct]. Binding to IL20RA alone is not shown separately.","key_references":[{"PMID":"11564763","why":"IL-19 binds the type I IL-20R complex and activates STAT3"},{"PMID":"12351624","why":"IL-19 signals through IL-20RA/IL-20RB"}],"covers":["LR000876","LR004306"]},"LR002793":{"pair":"IL1F10 -> IL1RAPL1","headline":"IL-38 binds IL1RAPL1 (full-length and truncated), with processing-dependent opposite effects on IL-6; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Both full-length and truncated IL-38 bound IL1RAPL1; the precursor increased macrophage IL-6, whereas truncated IL-38 reduced IL-6 by attenuating JNK/AP1 signalling downstream of IL1RAPL1 [PMID:26892022]. Curators label it antagonist, which applies to the truncated form only.","molecular_requirements":"The N-terminally processed (truncated) form is the anti-inflammatory one [PMID:26892022]. Reactome lists complexes for both forms [DB:Reactome]. Co-receptor needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human apoptotic cells and primary human macrophages [PMID:26892022]; the mouse pair is inferred.","localisation_and_range":"IL1F10 is flagged secreted and IL1RAPL1 transmembrane [flag]; the paper describes release from apoptotic cells [PMID:26892022].","caveats":"Abstract only. The effect depends on which IL-38 form is present, so a single agonist/antagonist label is misleading. Another paper judged for this pair is still pending.","key_references":[{"PMID":"26892022","why":"IL-38 forms bind IL1RAPL1 with opposite IL-6 effects"}],"covers":["LR002793","LR006036"]},"LR000885":{"pair":"IL1RN -> IL1R1","headline":"IL1RA (IL1RN) binds IL1R1 as an antagonist, shown by a 2.7 A crystal structure; abstract-level.","interaction_type":"direct binding","direction_and_effect":"The crystal structure of soluble type-I IL1R complexed with IL1RA shows contacts from all three Ig domains; the 'receptor trigger site' important for IL-1beta function is not in direct contact in the IL1RA complex [PMID:9062194]. GtoPdb lists it as antagonist [DB:GtoPdb].","molecular_requirements":"Soluble extracellular IL1R1 alone was crystallised; a role for the accessory chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crystal structure of the soluble extracellular receptor complexed with IL1RA; species not stated in the abstract (curated as human). Mouse pair is inferred.","localisation_and_range":"IL1RN is flagged secreted [flag].","caveats":"Abstract only; no affinity values in our evidence. Two further papers are pending.","key_references":[{"PMID":"9062194","why":"Crystal structure of IL1R1 with IL1RA"}],"covers":["LR000885","LR004315"]},"LR011739":{"pair":"IL22 -> IL22:IL22RA1","headline":"No papers; this entry has IL-22 itself inside the receptor complex, resting only on database records.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. GtoPdb lists IL22-IL22RA1 as an agonist [DB:GtoPdb]; Reactome has IL22:IL22RA1:JAK1 [DB:Reactome R-HSA-448411].","molecular_requirements":"Receptor members listed are IL22 and IL22RA1; subunit requirements are not reported in our evidence beyond database complexes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; structures exist [DB:PDB 3DGC][DB:PDB 3DLQ].","localisation_and_range":"IL-22 flagged secreted [flag].","caveats":"Zero papers judged; three rows pending. The receptor entity contains the ligand itself, so this is a ligand-bound complex, not a receptor.","key_references":[],"covers":["LR011739"]},"LR000894":{"pair":"IL22 -> IL22RA2","headline":"IL22RA2 (IL-22BP) is a soluble decoy receptor that binds IL-22 and neutralises it; well supported.","interaction_type":"direct binding","direction_and_effect":"IL-22RA2 binds IL-22 specifically and neutralises IL-22-induced BaF3 proliferation [PMID:11481447]; the recombinant protein binds IL-22 and inhibits it on hepatocytes and intestinal epithelial cells [PMID:11390453]. Antagonist, not a signalling receptor.","molecular_requirements":"A single chain is sufficient; IL-22RA2 lacks transmembrane and cytoplasmic domains [PMID:11390453]. Structure of the pair exists [DB:PDB 3G9V].","affinity_potency":[],"species_and_systems":"Human proteins; BaF3 cells expressing IL-22 receptor subunits, hepatocytes and intestinal epithelial cells [PMID:11481447][PMID:11390453].","localisation_and_range":"Naturally expressed soluble receptor [PMID:11481447]; acts in the extracellular space.","caveats":"Both papers read as abstracts only. A signalling-oriented CCC tool would misread direction here.","key_references":[{"PMID":"11481447","why":"IL-22RA2 is a naturally occurring soluble IL-22 antagonist"},{"PMID":"11390453","why":"cloning of IL-22 binding protein"}],"covers":["LR000894","LR004324"]},"LR010776":{"pair":"IL4 -> IL13RA2:IL4R","headline":"Only the IL4R chain is supported (picomolar IL4 binding); IL13RA2 is not shown to take part.","interaction_type":"direct binding","direction_and_effect":"IL4 binds the IL4R alpha-chain ectodomain with high affinity [PMID:11786020]; GtoPdb records IL4-IL4R as agonist [DB:GtoPdb].","molecular_requirements":"Evidence covers IL4R only; the IL13RA2 half of the complex is not mentioned in the paper [PMID:11786020]. UniProt says IL13RA2 binds IL13 but not IL4 [DB:UniProt]. IL4R pairs with IL2RG or IL13RA1 in the known signalling complexes [DB:UniProt].","affinity_potency":[{"value":"KD 150 pM","assay":"mutational binding analysis of IL4-BP (IL4R extracellular domain)","system":"human recombinant receptor ectodomain","cite":"PMID:11786020"}],"species_and_systems":"Human ligand and receptor, recombinant ectodomain [PMID:11786020]; structures of IL4 with IL4R [DB:PDB 3BPL].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Chain-only evidence: the complex with IL13RA2 is not supported. Paper read as abstract only.","key_references":[{"PMID":"11786020","why":"IL4 to IL4R-alpha binding, KD 150 pM, two binding clusters"}],"covers":["LR010776"]},"LR007329":{"pair":"IL5 -> CSF2RB:IL5RA","headline":"IL5 acts through the IL5RA plus common beta complex; IL5RA binding is well documented, the beta chain more indirectly.","interaction_type":"direct binding","direction_and_effect":"IL5 binds IL5RA, and a second receptor protein identical to the GM-CSF receptor beta chain was cloned as part of the IL5 receptor [PMID:1833065]. Agonistic ligation induces betac cytoplasmic degradation [PMID:11748263]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Both chains: IL5RA gives specific binding and betac is shared with GM-CSF [PMID:1833065]. The soluble alpha chain forms a 1:1 complex with hIL5 [PMID:7721873]. A soluble IL5RA form with antagonistic properties is reported [PMID:1833065].","affinity_potency":[{"value":"Kd 3.1 nM","assay":"titration microcalorimetry, hIL5 to soluble IL5R alpha","system":"Drosophila-expressed human proteins","cite":"PMID:7721873"},{"value":"Kd 250-590 pM","assay":"IL-5 binding","system":"COS7 cells transfected with human IL-5 receptor alpha","cite":"PMID:1732409"}],"species_and_systems":"Human proteins throughout: recombinant soluble domains [PMID:7721873], human eosinophil cDNA expressed in COS7 [PMID:1732409], chimeras [PMID:10880230].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Most papers address IL5RA only; the beta chain is mainly supported by [PMID:1833065] and [PMID:11748263]. All abstract-only.","key_references":[{"PMID":"1833065","why":"Cloning of IL5RA and beta chain as IL5 receptor components"},{"PMID":"7721873","why":"1:1 IL5-IL5RA complex, calorimetry"},{"PMID":"11748263","why":"Betac degradation after ligation"}],"covers":["LR007329"]},"LR006780":{"pair":"INHA -> ACVR1B","headline":"INHA to ACVR1B: GtoPdb assertion only; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA-ACVR1B as agonist [DB:GtoPdb]; modulatory effect stimulatory by annotation only.","molecular_requirements":"A type I receptor alone; a type II receptor is not evidenced here in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Secreted ligand [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Two papers were abstract_insufficient. Type I activin receptors usually need a type II partner, but that is not stated in this dossier.","key_references":[],"covers":["LR006780"]},"LR007923":{"pair":"INHA -> ACVR1C:ACVR2A","headline":"INHA on ACVR1C plus ACVR2A: database-asserted only; the type II receptor is the likely contact, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA with the type II receptor as agonist [DB:GtoPdb]; BioGRID has ACVR2A-INHA affinity capture-western [DB:BioGRID 275207] and Reactome has an inhibin-A:TGFBR3:ACVR2A complex [DB:Reactome]. Effect is stimulatory by annotation only.","molecular_requirements":"Type II chain ACVR2A carries the database evidence; the type I chain is not specifically evidenced in our evidence. Reactome places betaglycan (TGFBR3) in the inhibin-A:ACVR2A complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species of database experiments not reported in our evidence.","localisation_and_range":"Secreted ligand [flag]; receptor complex transmembrane [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. GtoPdb calls INHA an agonist, whereas related papers on other INHA pairs describe inhibin as competing with activin and BMPs.","key_references":[],"covers":["LR007923"]},"LR007932":{"pair":"INHA:INHBB -> ACVR1:ACVR2B","headline":"Inhibin A:activin B to ACVR1:ACVR2B rests on database records for single chains only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records INHBB-ACVR2B (Affinity Capture-Western) [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome].","molecular_requirements":"Receptor is a type I (ACVR1) plus type II (ACVR2B) pair; whether this heterodimeric ligand binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. ","key_references":[],"covers":["LR007932"]},"LR001866":{"pair":"INHBA -> ACVR1C","headline":"Papers show activin AB and B, not activin A, signal through ACVR1C (ALK7); this pair is weakly supported.","interaction_type":"conflicting","direction_and_effect":"Activin AB and activin B are ligands for ALK7; the combination of ActRIIA and ALK7 is preferred by activin AB and activin B but not by activin A [PMID:15196700]. GtoPdb lists agonist for INHBA-ACVR1C [DB:GtoPdb].","molecular_requirements":"ALK7 works with ActRIIA in reconstitution [PMID:15196700]. UniProt names ACVR1C as a type I partner for INHBA [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse receptor reconstitution and MIN6 beta cell line; human pair is the source and the mouse pair is ortholog-projected [PMID:15196700].","localisation_and_range":"Ligand secreted flag [flag].","caveats":"The paper's abstract says ALK7 is not preferred by activin A, which argues against this pair; read as abstract only. Both confirmed rows come from the same paper.","key_references":[{"PMID":"15196700","why":"Activin AB and B use ALK7; activin A uses ALK4."}],"covers":["LR001866","LR005211"]},"LR004359":{"pair":"INHBA -> TGFBR3","headline":"Inhibin A binds betaglycan (TGFBR3) with high affinity; activin A binding is not shown here.","interaction_type":"direct binding","direction_and_effect":"Betaglycan binds inhibin with high affinity and acts as an inhibin co-receptor with ActRII, enabling inhibin antagonism of activin [PMID:10746731]. Reactome lists inhibin-A binding to TGFBR3 [DB:Reactome].","molecular_requirements":"Betaglycan enhances binding in cells co-expressing ActRII and betaglycan [PMID:10746731].","affinity_potency":[],"species_and_systems":"Recombinant and endogenous complexes in cell lines; species not stated in our evidence [PMID:10746731].","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"Evidence concerns inhibin, not activin A; the INHBA ligand symbol may stand for inhibin A (INHA:INHBA) rather than the activin A homodimer. Abstract only; no affinity value.","key_references":[{"PMID":"10746731","why":"Betaglycan is an inhibin co-receptor with ActRII."}],"covers":["LR000936","LR004359"]},"LR008256":{"pair":"INHBB -> ACVR1B:ACVR2B","headline":"Activin B to ACVR1B:ACVR2B; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHBB with each receptor chain as agonist [DB:GtoPdb]. Reactome describes activin A, AB and B binding ACVR2A,B:ACVR1B [DB:Reactome]. BioGRID records INHBB with ACVR2B [PMID:9202237]; UniProt says type 2 receptors bind activin B [PMID:8622651].","molecular_requirements":"Chain-level records only; whether both subunits are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"Only abstract-insufficient rows exist, so no curator-verified paper supports this pair; records are per chain, not for the assembled complex.","key_references":[],"covers":["LR008256"]},"LR000939":{"pair":"INHBB -> ACVR1C","headline":"Activin B signals through ACVR1C (ALK7) in a reconstitution system; one abstract-level paper; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Activin B and activin AB were identified as ALK7 ligands, acting as agonists; ActRIIA with ALK7 is preferred by activin B and activin AB but not activin A [PMID:15196700]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"ActRIIA plus ALK7 combination carries the insulin-secretion response [PMID:15196700]; ALK7 alone as sufficient is not reported.","affinity_potency":[],"species_and_systems":"Experiments used mouse ligand and receptor in receptor reconstitution; the human pair is projected from this [PMID:15196700].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only [PMID:15196700]; no affinity reported. The paper's own notes say the dimer (activin B) is the correct entity.","key_references":[{"PMID":"15196700","why":"Shows activin AB and B are ALK7 ligands"}],"covers":["LR000939","LR004362"]},"LR000948":{"pair":"INSL5 -> RXFP4","headline":"INSL5 is the cognate nanomolar agonist of RXFP4, supported by binding, signalling and structure-function papers.","interaction_type":"direct binding","direction_and_effect":"Human INSL5 displaces 125I-relaxin-3 from the receptor, binds in saturation assays and activates GTPgammaS and cAMP responses [PMID:15525639]. In NCI-H716 cells endogenously expressing RXFP4, INSL5 induced ERK1/2 phosphorylation and inhibited cAMP production [PMID:29535183]. Relaxin-3 also acts on RXFP4 with similar signalling [PMID:27888281]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RXFP4 residues Glu100, Asp104 and Glu182 and INSL5 B13Arg and B23Arg are important for activation [PMID:25043977]. RXFP4 transmembrane domains 2, 3 and 5 are critical for activation by INSL5 [PMID:18582868].","affinity_potency":[{"value":"Ki 1.5 nM","assay":"125I-relaxin-3 displacement","system":"GPCR142 (RXFP4)","cite":"PMID:15525639"},{"value":"Kd 2.5 nM","assay":"125I-INSL5 saturation binding","system":"GPCR142 (RXFP4)","cite":"PMID:15525639"},{"value":"EC50 1.3 nM and 1.2 nM","assay":"GTPgammaS and cAMP assays","system":"GPCR142 (RXFP4)","cite":"PMID:15525639"},{"value":"4.57 nM","assay":"potency of native hINSL5","system":"human RXFP4","cite":"PMID:26824523"}],"species_and_systems":"Mostly recombinant human receptor in cell lines; human enteroendocrine L-cell line NCI-H716 for native expression [PMID:29535183]. Mouse pair is ortholog-inferred; mouse data are mRNA expression only [PMID:29535183].","localisation_and_range":"Ligand is flagged secreted [flag]. INSL5 is expressed in colonic enteroendocrine L-cells [PMID:29535183].","caveats":"All shown papers are abstract only. Ten confirmed rows exist, eight shown; seven rows are pending. Relaxin-3 is also an agonist, so ligand selectivity is not exclusive.","key_references":[{"PMID":"15525639","why":"Binding and activation of RXFP4 (GPCR142) by INSL5"},{"PMID":"29535183","why":"INSL5 signalling in a human L-cell line"},{"PMID":"25043977","why":"Electrostatic INSL5-RXFP4 residue mapping"}],"covers":["LR000948","LR004371"]},"LR002829":{"pair":"ITGB2 -> ICAM1","headline":"Mac-1 binds ICAM-1 in cell and purified-protein assays; ITGB2 row inherits Mac-1 heterodimer evidence.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 is a counter-receptor for Mac-1 and contributes to neutrophil-endothelial adhesion [PMID:1980124].","molecular_requirements":"The evidence is for Mac-1 (alphaMbeta2); binding differed from LFA-1 in temperature sensitivity, avidity and antibody profile [PMID:1980124].","affinity_potency":[],"species_and_systems":"Human cells and purified proteins, transfected murine L and monkey COS cells [PMID:1980124]. Mouse pair orthology-projected.","localisation_and_range":"Membrane-bound adhesion molecules [PMID:1980124].","caveats":"Abstract read; no affinity values; chain-only attribution.","key_references":[{"PMID":"1980124","why":"ICAM-1 as a Mac-1 counter-receptor"}],"covers":["LR002829","LR006066"]},"LR008571":{"pair":"ITGB3BP -> ITGB3","headline":"ITGB3BP to ITGB3 is an intracellular interaction in databases; probably not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction is not reported in our evidence.","molecular_requirements":"UniProt: isoform 3, but not other isoforms, interacts with the ITGB3 cytoplasmic tail [DB:UniProt]. BioGRID lists two-hybrid and reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Yeast two-hybrid and reconstituted complex [DB:BioGRID].","localisation_and_range":"Intracellular binding to the cytoplasmic tail [DB:UniProt].","caveats":"Curated judgements were unresolvable or different_entity; no confirmed paper.","key_references":[],"covers":["LR008571"]},"LR004377":{"pair":"JAG1 -> NOTCH3","headline":"Jagged1 binds Notch3 and drives its signalling; supported by binding, mutation and functional papers.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch3 extracellular protein bound JAG1 directly in solid-phase assays [PMID:11006133]. Jagged1-induced RBP/JK reporter activity of Notch3 was reduced by two CADASIL mutants; C428S lost Jagged1 binding while C542Y kept binding but had impaired surface presentation [PMID:14714274]. Murine Notch3 signalled in response to Jagged 1 [PMID:12482954]. TSP2 augmented the Notch3-Jagged1 interaction [PMID:19147503]. Annotation: stimulatory.","molecular_requirements":"Ca2+ dependent binding [PMID:11006133]. The ligand-binding domain lies in EGF repeats 10-11 of Notch3 [PMID:14714274].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:11006133][PMID:14714274][PMID:19147503]; murine Notch3 stable cell lines [PMID:12482954].","localisation_and_range":"JAG1 is flagged as transmembrane [flag]. TSP2 is an extracellular facilitator [PMID:19147503].","caveats":"All papers abstract-only. The TSP2 paper treats the pair as background and its finding concerns facilitation. The murine CADASIL paper does not measure binding [PMID:12482954]. Database records exist [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct binding"},{"PMID":"14714274","why":"Binding-domain mutants and Jagged1-induced signalling"},{"PMID":"19147503","why":"TSP2 potentiates the pair"}],"covers":["LR000954","LR004377"]},"LR000957":{"pair":"JAG2 -> NOTCH2","headline":"Jagged2 binds and activates Notch2 in mouse BaF3 cells; limited human evidence.","interaction_type":"direct binding","direction_and_effect":"Jagged2 bound endogenous Notch2 on BaF3 cells, with binding characteristics differing from Delta1 and Jagged1, and induced cleavage, nuclear translocation and reporter activation (agonist) [PMID:10958687]. In human cell assays, MFNG inhibited NOTCH2 activation by JAG1 and JAG2 [PMID:32820046].","molecular_requirements":"Fringe enzymes modulate NOTCH2 activation [PMID:32820046].","affinity_potency":[],"species_and_systems":"Mouse cell system [PMID:10958687]; human cell-based assay [PMID:32820046]. Human pair is ortholog-inferred.","localisation_and_range":"JAG2 flagged as not secreted [flag].","caveats":"Both papers abstract-only. The Fringe paper shows an inhibitory modulation, not a direct measure of JAG2 alone. BioGRID and Reactome records add support [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"10958687","why":"Binding and signalling in BaF3 cells"},{"PMID":"32820046","why":"Fringe modulation in human cells"}],"covers":["LR000957","LR004380"]},"LR006069":{"pair":"JAM2 -> ITGA4","headline":"JAM2 engages integrin alpha4beta1 in T cells in adhesion assays, conditional on JAM3; chain-level record.","interaction_type":"functional only","direction_and_effect":"Neutralizing integrin antibodies defined a JAM2-alpha4beta1 interaction in T cells, attenuated by the alpha4-specific inhibitor TBC 772 [PMID:12070135]. Reactome records the binding [DB:Reactome].","molecular_requirements":"alpha4 pairs with beta1; engagement was enabled only after prior JAM2-JAM3 adhesion and was undetectable where JAM3 was absent [PMID:12070135]. The first Ig-like fold of JAM2 binds both [PMID:12070135].","affinity_potency":[],"species_and_systems":"Human T-cell line adhesion assays [PMID:12070135].","localisation_and_range":"JAM2 flagged as not secreted [flag]; membrane adhesion.","caveats":"Evidence is for the alpha4beta1 heterodimer, not alpha4 alone. Abstract-only; antibody and inhibitor based, no direct binding.","key_references":[{"PMID":"12070135","why":"JAM2-alpha4beta1 in T cells"}],"covers":["LR002832","LR006069"]},"LR002838":{"pair":"KISS1 -> NPFFR1","headline":"Kisspeptin-10 binds and activates NPFFR1 in one 2011 study; the pair is ortholog-projected from that evidence.","interaction_type":"direct binding","direction_and_effect":"Kisspeptin-10 showed potent binding and activation of NPFFR1, whereas short GPR54-selective peptide agonists bound with much lower affinity [PMID:24900254]. Reported NPFFR ligands showed negligible affinity for GPR54, i.e. cross-reactivity runs one way [PMID:24900254].","molecular_requirements":"Kisspeptin-10 form specifically; short synthetic agonists were weak at NPFFRs [PMID:24900254].","affinity_potency":[],"species_and_systems":"Human and mouse entries are both ortholog-inferred; the paper's experiment species are labelled human by the curators; abstract-only read [PMID:24900254].","localisation_and_range":"KISS1 is flagged secreted [flag]; the paper suggests secondary kisspeptin targets may lie in the median eminence [PMID:24900254].","caveats":"Single paper, abstract only, with no numbers in the dossier. The canonical kisspeptin receptor is GPR54, so this is a cross-reactivity finding [PMID:24900254]. Not present in any database.","key_references":[{"PMID":"24900254","why":"Kisspeptin-10 binds and activates NPFFR1 and NPFFR2"}],"covers":["LR002838","LR006074"]},"LR006078":{"pair":"KLRG1 -> CDH4","headline":"KLRG1 binds R-cadherin (CDH4) in one paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"KLRG1 is an inhibitory receptor and binds R-cadherin; the functional inhibition was shown for E-cadherin [PMID:16461340].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The KLRG1 tetramer stained cells transduced with E-, N- or R-cadherins, but not P-, M- or VE-cadherins; mouse KLRG1 tetramer was used [PMID:16461340]. Human pair is ortholog-inferred [flag].","localisation_and_range":"Membrane proteins; localisation flags are available for KLRG1 [flag].","caveats":"One paper only, and no database record. No affinity and no R-cadherin-specific functional result.","key_references":[{"PMID":"16461340","why":"KLRG1 binds E-, N- and R-cadherins"}],"covers":["LR002843","LR006078"]},"LR004386":{"pair":"KNG1 -> GP1BA","headline":"Kininogen is reported to bind the platelet GP Ib-IX-V complex and restrict thrombin binding; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Kininogen did not inhibit thrombin-induced aggregation of Bernard-Soulier platelets, which lack GP Ib-IX-V, consistent with kininogen interacting with that complex and limiting thrombin access; this is an inhibition of thrombin binding, not a classic receptor activation [PMID:9269768].","molecular_requirements":"The binding site is in kininogen domain 3 (K270-G292); a heptapeptide L271-A277 is the minimal effective sequence [PMID:9269768]. The receptor is the whole GP Ib-IX-V complex, and GP1BA alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Platelets, with recombinant K270-G292 polypeptide and a synthetic peptide [PMID:9269768]; species not reported in our evidence.","localisation_and_range":"KNG1 is secreted [flag]; platelet-surface receptor.","caveats":"Abstract only (partly truncated). The abstract says kininogen interacts 'either directly or indirectly' with the complex, so direct binding to GP1BA is not shown. Receptor complex subunits GP1BB, GP9 and GP5 are not examined.","key_references":[{"PMID":"9269768","why":"Kininogen and the platelet GP Ib-IX-V complex"}],"covers":["LR000964","LR004386"]},"LR004395":{"pair":"L1CAM -> ITGA5","headline":"Direct L1-alpha5beta1 binding shown in ELISA with purified integrins (FN3) and RGD-dependent Ig6 adhesion; supported across three papers.","interaction_type":"direct binding","direction_and_effect":"Purified alphaVbeta3 and alpha5beta1 bound L1 FN3 directly in ELISA [PMID:10871287]. VLA-5 (alpha5beta1) bound murine L1 in cell aggregation and binding assays [PMID:8557754]. L1-Ig6 supported alpha5beta1-mediated adhesion; effect labelled agonist [PMID:9396761].","molecular_requirements":"Two sites: RGD-independent FN3 binding requiring FN3 multimers [PMID:10871287], and RGD-dependent Ig6 binding, beta1 integrins needing Mn2+ and inhibited by Ca2+ [PMID:9396761]. alpha5 pairs with beta1 here.","affinity_potency":[],"species_and_systems":"Purified human/unspecified proteins in ELISA [PMID:10871287]; mouse L1 on mouse and human cells and platelets [PMID:8557754]; human L1-Ig6 [PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; thymocyte and platelet binding assays [PMID:8557754].","caveats":"Hierarchy alphavbeta3 or active alphaIIbbeta3 > alphavbeta1 > alpha5beta1 suggests weakest of the three [PMID:9396761]. 8557754 and 9396761 were abstract only; no affinity values.","key_references":[{"PMID":"10871287","why":"ELISA direct binding of purified alpha5beta1 to L1 FN3"},{"PMID":"8557754","why":"VLA-5 binds murine L1"},{"PMID":"9396761","why":"L1-Ig6 RGD-dependent integrin binding"}],"covers":["LR000973","LR004395"]},"LR002847":{"pair":"L1CAM -> ITGB1","headline":"VLA-5 (alpha5beta1) binds murine L1 and L1-Ig6 supports beta1 integrin adhesion; ITGB1 is the shared beta chain.","interaction_type":"direct binding","direction_and_effect":"VLA-5 bound murine L1 in cell aggregation, platelet and bead binding assays, blocked by anti-L1 and anti-VLA-5 mAbs and an L1 RGD peptide [PMID:8557754]. L1-Ig6 is a heterophilic ligand for alpha5beta1 and alphavbeta1 [PMID:9396761].","molecular_requirements":"Beta1 integrins bind in Mn2+ only, inhibited by Ca2+; RGD-dependent [PMID:9396761]. ITGB1 pairs with alpha5 or alphav; chain-level evidence.","affinity_potency":[],"species_and_systems":"Mouse cells, platelets and thymocytes plus human Nalm-6 [PMID:8557754]; human L1-Ig6 [PMID:9396761].","localisation_and_range":"Cell-contact adhesion [PMID:8557754].","caveats":"Both papers abstract only; no affinity; beta1 binding weaker than beta3 per hierarchy.","key_references":[{"PMID":"8557754","why":"VLA-5 binds murine L1"},{"PMID":"9396761","why":"L1-Ig6 beta1 integrin binding"}],"covers":["LR002847","LR006082"]},"LR000975":{"pair":"LACRT -> SDC1","headline":"Lacritin binds the deglycanated syndecan-1 core protein; one full-text paper with pull-downs and knockdown.","interaction_type":"direct binding","direction_and_effect":"Lacritin binds SDC1 and SDC1 knockdown abolished lacritin-dependent COX2 expression, so SDC1 ligation appears to be a required upstream step in lacritin mitogenic signalling [PMID:16982797].","molecular_requirements":"Binding needs prior removal of heparan sulfate chains by heparanase; the core protein is targeted, not HS chains. SDC2 and SDC4 did not bind. Lacritin's C-terminal domain (around residues 100-109 of mature lacritin) and SDC1's N terminus specify binding [PMID:16982797].","affinity_potency":[],"species_and_systems":"Lacritin affinity purification from human salivary gland cells (mass spectrometry identified SDC1) and precipitation from HEK293T cells expressing human SDC1 [PMID:16982797].","localisation_and_range":"Lacritin is flagged secreted and SDC1 as transmembrane [flag]; SDC1 binding is a cell-surface interaction that heparanase activity restricts to particular sites [PMID:16982797].","caveats":"No affinity reported in our evidence. BioGRID also lists records, including one from PMID 23504321 not curated here [DB:BioGRID].","key_references":[{"PMID":"16982797","why":"Full-text pull-downs, truncations, competition and SDC1 knockdown"}],"covers":["LR000975"]},"LR006087":{"pair":"LAMA2 -> ADGRG6","headline":"Laminin-211 binds the GPR126 N-terminal fragment by co-IP, including in vivo and lost in Lama2-null nerve; full text.","interaction_type":"direct binding","direction_and_effect":"Laminin-211 binds GPR126-NTF and can either suppress or promote Stachel-mediated activation of GPR126-CTF [PMID:25695270].","molecular_requirements":"The N-terminal fragment (NTF) binds laminin-211; the NTF is necessary and sufficient for radial sorting while the CTF raises cAMP [PMID:25695270]. LAMA2 is inferred as laminin-211's defining chain.","affinity_potency":[],"species_and_systems":"GPR126-NTF-hFc co-immunoprecipitated with mouse-derived laminin-211, confirmed in P4 mouse sciatic nerve lysate and lost in Lama2-null mice; zebrafish genetics also used [PMID:25695270]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and non-transmembrane; receptor transmembrane [flag]; matrix ligand acting on the receptor's extracellular fragment.","caveats":"The ligand is the laminin-211 trimer. Two review-only rows are not shown. No affinity reported.","key_references":[{"PMID":"25695270","why":"Co-IP of GPR126-NTF with laminin-211, absent in Lama2-null nerve"}],"covers":["LR002853","LR006087"]},"LR001875":{"pair":"LAMA2 -> DAG1","headline":"Crystal structure shows laminin alpha2 LG4-LG5 bound to the glycan on alpha-dystroglycan; abstract-only, plus database records.","interaction_type":"direct binding","direction_and_effect":"The structure of laminin-alpha2 LG4-LG5 bound to a LARGE-synthesized oligosaccharide reveals the matrix-binding interaction [PMID:27526028]. UniProt calls DAG1 a receptor for laminin-2 (LAMA2) in Schwann cells (by similarity) [DB:UniProt Q14118]. Labelled Stimulatory [flag].","molecular_requirements":"Binding needs the LARGE-synthesized matrix-binding heteropolysaccharide on alpha-DG [PMID:27526028]; the LG4-LG5 domains of laminin-alpha2 are the contact [PMID:27526028].","affinity_potency":[],"species_and_systems":"Crystal structure with an oligosaccharide, not full-length DAG1 [PMID:27526028]. BioGRID lists a reconstituted complex [DB:BioGRID 306204]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor flagged transmembrane and secreted [flag]; matrix ligand.","caveats":"Abstract only; the structure uses a glycan fragment. UniProt support is by similarity.","key_references":[{"PMID":"27526028","why":"Crystal structure of laminin LG4-LG5 with the DAG1 glycan"}],"covers":["LR001875","LR005217"]},"LR000984":{"pair":"LAMA2 -> ITGA2","headline":"Recombinant laminin alpha2 short-arm domains carry an alpha2beta1 integrin recognition site; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Using integrin-specific antibodies, recognition sites for alpha1beta1 and alpha2beta1 integrins were found in the short arms of the laminin alpha2 chain [PMID:9361014]. Labelled Stimulatory [flag].","molecular_requirements":"The alpha2beta1 heterodimer is the receptor; the curator maps the site to domain VI [PMID:9361014].","affinity_potency":[],"species_and_systems":"Recombinant laminin alpha2 domains VI-IVb; species not stated [PMID:9361014]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Abstract only; fragments tested, not full-length LAMA2. One review-only row not shown. No affinity reported.","key_references":[{"PMID":"9361014","why":"Alpha2 short-arm domains carry alpha2beta1 recognition site"}],"covers":["LR000984","LR004404"]},"LR002856":{"pair":"LAMA3 -> ITGB1","headline":"Laminin-332 (with LAMA3) binds recombinant integrin alpha3beta1 directly, and keratinocyte adhesion depends on alpha3beta1; assembled-trimer evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-332 bound recombinant alpha3beta1 in solid-phase binding [PMID:16413178]. Keratinocyte adhesion to immunopurified epiligrin was inhibited by an anti-alpha3beta1 antibody, and epiligrin induced alpha3beta1 localisation in focal adhesions, consistent with an adhesion (stimulatory) ligand [PMID:2032285]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Receptor tested is the alpha3beta1 heterodimer, so ITGB1 alone is not shown to suffice. Ligand is the laminin-332/epiligrin trimer, not LAMA3 alone [PMID:16413178][PMID:2032285].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding, laminin-332 vs recombinant alpha3beta1","system":"human recombinant","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins and human foreskin keratinocytes [PMID:16413178][PMID:2032285].","localisation_and_range":"LAMA3 flagged secreted, not transmembrane [flag]; epiligrin is described as a basement-membrane glycoprotein [PMID:2032285].","caveats":"The 2032285 result was read from the abstract only and is antibody-blocking adhesion, not binding. A Reactome record describes alpha2beta1 binding laminin-332, not this receptor [DB:Reactome]. Three papers were abstract-insufficient.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-332"},{"PMID":"2032285","why":"Adhesion to epiligrin blocked by anti-alpha3beta1"}],"covers":["LR002856","LR006090"]},"LR011379":{"pair":"LAMA4 -> ITGA3:ITGB1","headline":"Only co-localisation of LAMA4 with ITGB1 in mouse brain; alpha3 subunit not examined.","interaction_type":"functional only","direction_and_effect":"Authors state they experimentally confirmed LAMA4-ITGB1 in E14.5 mouse brain by immunofluorescence overlap [PMID:31677479].","molecular_requirements":"Only ITGB1 was tested; ITGA3 is not mentioned [PMID:31677479].","affinity_potency":[],"species_and_systems":"Mouse E14.5 brain sections [PMID:31677479].","localisation_and_range":"LAMA4 flagged secreted [flag]; in matrix around endothelial cells [PMID:31677479].","caveats":"Co-localisation is not binding. Five papers were abstract-insufficient. A direct alpha3beta1 binding result for the G domain appears on the LAMA4-ITGA3 card, not in this dossier.","key_references":[{"PMID":"31677479","why":"LAMA4-ITGB1 overlap in brain"}],"covers":["LR011379"]},"LR000993":{"pair":"LAMA4 -> ITGB1","headline":"Recombinant laminin alpha4 G domain binds alpha3beta1 with high affinity, and platelet adhesion to laminin-8 depends on beta1 integrins.","interaction_type":"direct binding","direction_and_effect":"alpha3beta1 bound with high affinity to recombinant G(919-1207) of laminin alpha4 [PMID:12454288]. Platelet adhesion to purified laminin-8 (alpha4beta1gamma1) was largely inhibited by anti-beta1 and anti-alpha6 antibodies [PMID:10585296]. Stimulatory per interaction record [flag].","molecular_requirements":"Receptors are alpha-beta1 heterodimers (alpha3beta1, and alpha6beta1 implicated), not ITGB1 alone [PMID:12454288][PMID:10585296].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to G(919-1207) (adhesion, not Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Human platelets and endothelial cells; recombinant G-domain [PMID:10585296][PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted; ITGB1 not secreted [flag]; laminin-8 is secreted by activated platelets [PMID:10585296].","caveats":"Both papers were read from abstracts only; the antibody result is indirect. One paper was review-only.","key_references":[{"PMID":"12454288","why":"alpha3beta1 binds alpha4 G domain"},{"PMID":"10585296","why":"Platelet adhesion to laminin-8 blocked by anti-beta1"}],"covers":["LR000993","LR004412"]},"LR006096":{"pair":"LAMA5 -> DAG1","headline":"Laminin-10 (alpha5) binds alpha-dystroglycan via LG4 in deletion studies; a curator-verified negative on the same paper conflicts.","interaction_type":"conflicting","direction_and_effect":"Deleting the LG4-5 modules of recombinant laminin-10 abolished binding to alpha-dystroglycan, and LG4 alone bound it [PMID:14701821]. Laminin-10/11 preferentially bound brain alpha-dystroglycan over skeletal muscle alpha-dystroglycan [PMID:16709410].","molecular_requirements":"Ligand tested as laminin-10/11 trimers; LG4 module is the dystroglycan site [PMID:14701821].","affinity_potency":[],"species_and_systems":"Recombinant human laminin-10 [PMID:14701821]; mammalian tissue alpha-dystroglycan [PMID:16709410]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LAMA5 flagged secreted; DAG1 transmembrane [flag].","caveats":"A pair_absent row exists for PMID 14701821, but the same paper is also confirmed; the negative was auto-matched. Both are abstract-only reads. BioGRID and IntAct also list records [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"14701821","why":"LG4 of laminin-10 binds alpha-dystroglycan"},{"PMID":"16709410","why":"Laminin-10/11 prefers brain alpha-dystroglycan"}],"covers":["LR002862","LR006096"]},"LR010668":{"pair":"LAMB1 -> ITGA6:ITGB4","headline":"Complex row for laminin beta1 and integrin alpha6beta4; only a PDB record, no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P07942 and a chain of P23229 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA6:ITGB4 heterodimer per the entity record; the PDB chains listed do not include ITGB4 [DB:PDB 7CEC].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB1 is flagged secreted [flag]; the receptor complex is not flagged as a receptor [flag]. Range otherwise not reported in our evidence.","caveats":"No paper was confirmed for this row (one review_only, five abstract_insufficient). Alpha6beta4 laminin binding appears on the separate LAMB1 -> ITGB4 row but is not counted here.","key_references":[],"covers":["LR010668"]},"LR002865":{"pair":"LAMB1 -> ITGB8","headline":"Integrin beta8-containing heterodimers mediate chick neuron interaction with laminin-1; a single abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"An antibody to the beta8 extracellular domain blocked chick sensory neuron interactions with laminin-1, collagen IV and fibronectin, identifying the first ligands for beta8 integrins [PMID:7542940].","molecular_requirements":"Beta8-containing heterodimers are the binding entity; the alpha partner is not given in our evidence. Laminin-1 is a heterotrimer, so LAMB1 is not isolated [PMID:7542940].","affinity_potency":[],"species_and_systems":"Chick sensory neurons; human and mouse pairs are by homology (ortholog-inferred) [PMID:7542940].","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGB8 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"One abstract-only antibody-blocking study; no direct binding or affinity. The dossier's curator note states the integrin subunit rows should be folded into complex entities before scoring [PMID:7542940].","key_references":[{"PMID":"7542940","why":"Anti-beta8 antibody blocks neuron interaction with laminin-1"}],"covers":["LR002865","LR006099"]},"LR010749":{"pair":"LAMC2 -> ITGA3:ITGB1","headline":"Supported only by a Reactome record of alpha2beta1 binding laminin-332; no curated paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"The only record is Reactome R-HSA-349626 for integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"The record names alpha2beta1, not alpha3beta1, so it does not directly support this complex [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"No verified papers; database record concerns a different integrin heterodimer.","key_references":[],"covers":["LR010749"]},"LR011388":{"pair":"LAMC2 -> ITGA6:ITGB1","headline":"Only an abstract-level LAMC2-ITGB1 proximity signal supports this complex; ITGA6 is not addressed.","interaction_type":"functional only","direction_and_effect":"A Duolink proximity assay showed increased LAMC2-ITGB1 interaction signals in alcohol-exposed colorectal cancer rats and patients [PMID:36188720].","molecular_requirements":"Only ITGB1 was assayed; the alpha6 chain is not addressed in this paper [PMID:36188720].","affinity_potency":[],"species_and_systems":"Rat colorectal cancer model and clinical samples [PMID:36188720].","localisation_and_range":"Not reported in our evidence.","caveats":"Curated from the abstract; tissue proximity signal, not binding. Four other papers were abstract-insufficient. No database record.","key_references":[{"PMID":"36188720","why":"LAMC2-ITGB1 proximity in CRC tissue"}],"covers":["LR011388"]},"LR002874":{"pair":"LCN2 -> SLC22A17","headline":"NGAL binds the SLC22A17 N-terminal domain weakly (about 10 uM) as a fuzzy complex; Reactome lists the full complex.","interaction_type":"direct binding","direction_and_effect":"The disordered N-terminal domain of LCN2-R interacts with NGAL preferentially in its apo state to form a fuzzy complex; the affinity is relatively weak (about 10 uM) so the N terminus alone cannot account for NGAL internalization [PMID:26635366]. Reactome lists SLC22A17:LCN2 complexes with 2,5DHBA and Fe3+ [DB:Reactome R-HSA-5246491].","molecular_requirements":"Other receptor domains are implied beyond the N-terminal domain; the N-terminus may fine-tune or help discriminate apo- from holo-NGAL [PMID:26635366].","affinity_potency":[{"value":"Kd \u224810 \u03bcm","assay":"biophysical measurement (NMR with other methods) of human LCN2-R-NTD with apoNGAL","system":"human proteins","cite":"PMID:26635366"}],"species_and_systems":"Human LCN2-R N-terminal domain and NGAL in vitro; CHO-K1 and murine tubule cells used for topology [PMID:26635366]. Mouse pair is ortholog-projected.","localisation_and_range":"Only the N terminus is extracellular on cell surface staining [PMID:26635366]; LCN2 flagged secreted, SLC22A17 transmembrane [flag].","caveats":"The measured affinity is for the isolated domain only; the dossier lists the 10 uM value as an abstract statement, assay type given loosely. Receptor topology is uncertain between two proposed models [PMID:26635366].","key_references":[{"PMID":"26635366","why":"NMR and biophysical characterisation of NGAL with the SLC22A17 N-terminal domain"}],"covers":["LR002874","LR006108"]},"LR011919":{"pair":"LEFTY1 -> NODAL","headline":"Reactome lists a LEFTY1,2:NODAL complex; this is a ligand-ligand inhibitory pair with no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records a LEFTY1,2:NODAL complex in the extracellular region [DB:Reactome R-HSA-1181340]. Recorded effect: inhibitory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners flagged secreted [flag].","caveats":"Interaction class is Ligand-Ligand, not ligand-receptor; no verified paper (four abstract-insufficient, one different-entity).","key_references":[],"covers":["LR011919"]},"LR002883":{"pair":"LGALS3 -> ITGB1","headline":"Galectin-3 acts through ITGB1 to drive IL-10 in hepatic NK cells; functional evidence from HBV-transgenic mice, no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Galectin-3 from HBsAg+ hepatocytes induced IL-10 in hepatic conventional NK cells via ITGB1 signalling; anti-CD29 blocked the galectin-3/ITGB1 interaction on NK cells [PMID:38793619].","molecular_requirements":"Beta1 subunit (CD29) only; partner integrin alpha chains not reported in our evidence [PMID:38793619].","affinity_potency":[],"species_and_systems":"HBs-Tg and control B6 mice with cultured NK cells; human TCGA expression only correlative. BioGRID lists Affinity Capture-MS and co-localisation [DB:BioGRID][PMID:38793619].","localisation_and_range":"Galectin-3 secreted from hepatocytes acts on NK cells; ITGB1 flagged as non-secreted receptor [flag][PMID:38793619].","caveats":"No binding assay in this paper; blocking antibody against CD29 is the main test. Human and mouse pairs are ortholog-inferred or not, as annotated; the paper is mouse work.","key_references":[{"PMID":"38793619","why":"Gal-3/ITGB1 signalling drives IL-10 in hepatic cNK cells"}],"covers":["LR002883","LR006117"]},"LR002892":{"pair":"LGALS3BP -> SIGLEC11","headline":"Supported only by a BioGRID Reconstituted Complex record; our curators judged no paper to support this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID cites PMID 25320078 [DB:BioGRID]; species of the experiment is not reported in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag].","caveats":"The only support is a BioGRID record (Reconstituted Complex) [DB:BioGRID]. The curated judgment of the cited paper was 'different_entity', meaning it did not support this specific pair, so the record may be spurious (the paper's abstract names Siglec-9, -5 and -10).","key_references":[],"covers":["LR002892"]},"LR001884":{"pair":"LGI1 -> ADAM22","headline":"LGI1 binds ADAM22 (cell-ELISA, brain IP-MS), with structural and interaction-database support.","interaction_type":"direct binding","direction_and_effect":"LGI1 was identified as an ADAM22-binding protein by immunoprecipitation/mass spectrometry from mouse brain, and quantitative cell-ELISA showed specific binding of LGI1 with ADAM22 [PMID:18974846]. UniProt notes a complex with ADAM22, DLG4/PSD95 and CACNG2/Stargazin [DB:UniProt]. PDB has complexes of the two chains, e.g. [DB:PDB 5Y2Z].","molecular_requirements":"ADAM22 sits in a complex with DLG4/PSD95 and CACNG2/Stargazin [DB:UniProt]; ADAM23 and ADAM11 also bind LGI1 [PMID:18974846].","affinity_potency":[],"species_and_systems":"Mouse proteins in brain and cells (curator labels human) [PMID:18974846]; structural and IntAct evidence are listed as electron microscopy and molecular sieving [DB:IntAct].","localisation_and_range":"LGI1 secreted and binds outside the cell; ADAM22 is a type I transmembrane protein [PMID:18974846].","caveats":"Abstract only for the paper; no affinity. Effect direction not reported in our evidence.","key_references":[{"PMID":"18974846","why":"LGI1 identified as ADAM22 binder; cell-ELISA"}],"covers":["LR001884","LR005226"]},"LR001893":{"pair":"LGI4 -> ADAM23","headline":"LGI4 binds ADAM23 moderately in cell-ELISA, alongside ADAM22 and ADAM11; two confirming papers.","interaction_type":"direct binding","direction_and_effect":"LGI4 significantly binds ADAM23 as well as ADAM22 and ADAM11 [PMID:18974846]. Effect on ADAM23 signalling is not reported in our evidence; the importance of ADAM23 in peripheral nerve myelination is stated as undetermined [PMID:18974846].","molecular_requirements":"No co-receptor requirement reported for ADAM23. Reactome lists an LGI4:ADAM22,11,23 complex at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cell-ELISA with mouse LGI4 and ADAMs [PMID:18974846]; dossier lists human. The human pair is ortholog-inferred.","localisation_and_range":"LGI4 is flagged secreted; ADAM23 carries both is_secreted and is_receptor flags [flag].","caveats":"Moderate interaction, weaker than ADAM22 [PMID:18974846]. The second paper is an unverified browser-read sentence [PMID:20220021]. No affinity value is reported.","key_references":[{"PMID":"18974846","why":"Cell-ELISA showing LGI4 binds ADAM23"},{"PMID":"20220021","why":"Reports Lgi4 binding to Adam23 (browser-read)"}],"covers":["LR001893","LR005235"]},"LR007347":{"pair":"LPAR1 -> ADGRE5","headline":"LPAR1 and ADGRE5 (CD97) co-immunoprecipitate and heterodimerise; one full-text paper, receptor-receptor rather than classical ligand-receptor.","interaction_type":"direct binding","direction_and_effect":"Tagged LPAR1 and CD97-3EGF co-immunoprecipitated each other in transfected CHO cells [PMID:21978933]. Co-expression of CD97 with LPAR1 enhanced LPA-initiated RHO-dependent invasion relative to LPAR1 alone [PMID:21978933]. No ligand/receptor direction is established; this is a GPCR heterodimer.","molecular_requirements":"CD97-3EGF construct was used; interaction also seen by proximity ligation in LNCaP cells and with endogenous CD97 in DU145 cells [PMID:21978933].","affinity_potency":[],"species_and_systems":"Human proteins; transfected CHO and LNCaP cells, DU145 and PC3 prostate cancer cells [PMID:21978933].","localisation_and_range":"Both are annotated as transmembrane [flag]; ADGRE5 is also flagged secreted [flag]. The paper shows interaction in the same cell membrane [PMID:21978933].","caveats":"Single paper. Tagged, overexpressed constructs were needed because antibodies for endogenous LPAR1 were insufficiently sensitive [PMID:21978933]. Affinity not reported in our evidence.","key_references":[{"PMID":"21978933","why":"Reciprocal co-IP and proximity ligation of LPAR1-CD97 with functional synergy in invasion"}],"covers":["LR007347"]},"LR002919":{"pair":"LRFN5 -> PTPRS","headline":"LRFN5 (SALM5) binds LAR-RPTPs including PTPRS via Ig domains; one paper, with 8.96 nM Kd measured for LAR.","interaction_type":"direct binding","direction_and_effect":"SALM5 interacts with the Ig domains of LAR-RPTPs (LAR, PTP-delta, PTP-sigma) [PMID:27225731]. PTP-delta and PTP-sigma interacted with SALM5 in cell aggregation assays [PMID:27225731]. Assay detail reports a stimulatory effect on presynaptic differentiation in contacting axons, with the interaction strongly inhibited by splice insert B [PMID:27225731].","molecular_requirements":"The three LAR Ig domains were sufficient for SALM5 binding; the FNIII region did not bind. The interaction was calcium-insensitive [PMID:27225731]. Other SALMs did not interact with LAR in cell aggregation assays [PMID:27225731].","affinity_potency":[{"value":"Kd 8.96 \u00b1 0.92 nM","assay":"Scatchard analysis of LAR-Ecto-Fc binding","system":"SALM5-expressing HEK293T cells; measured for LAR, not PTPRS","cite":"PMID:27225731"}],"species_and_systems":"HEK293T cell aggregation and soluble-binding assays, cocultured hippocampal neurons [PMID:27225731].","localisation_and_range":"Both partners flagged not secreted; transmembrane, so trans-synaptic contact adhesion [flag][PMID:27225731].","caveats":"Affinity was measured for LAR only; PTPRS was shown by cell aggregation only [PMID:27225731]. Record is labelled abstract-only although full-text excerpts exist.","key_references":[{"PMID":"27225731","why":"SALM5 binds LAR-RPTP Ig domains; Kd for LAR 8.96 nM"}],"covers":["LR002919","LR006144"]},"LR004449":{"pair":"LRPAP1 -> LDLR","headline":"RAP (LRPAP1) binds LDL receptors with a KD of 250 nM and inhibits LDL receptor-mediated lipoprotein uptake; structure and database records support it.","interaction_type":"direct binding","direction_and_effect":"RAP inhibited LDL receptor-mediated binding and catabolism of LDL and VLDL in human foreskin fibroblasts [PMID:7822276]. It acts as an inhibitor of ligand binding, not a signalling agonist [PMID:7822276].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 250 nM","assay":"solid-phase binding to partially purified LDL receptors","system":"human fibroblast-derived receptor","cite":"PMID:7822276"},{"value":"KI 60 nM","assay":"inhibition of 125I-LDL binding at 4 degrees C","system":"human foreskin fibroblasts","cite":"PMID:7822276"}],"species_and_systems":"Normal human foreskin fibroblasts and partially purified LDL receptors [PMID:7822276]. Databases hold a PDB structure with a chain of each protein [DB:PDB 2FCW], BioGRID [DB:BioGRID] and IntAct NMR and pull-down records [DB:IntAct], and UniProt lists the interaction [DB:UniProt]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted [flag]; the cell-based inhibition used exogenous RAP [PMID:7822276].","caveats":"The authors report affinity for LDLR 14 to 350 times weaker than for LRP, gp330 or VLDL receptors [PMID:7822276]. Paper read as abstract only.","key_references":[{"PMID":"7822276","why":"RAP binds LDL receptors (KD 250 nM) and inhibits lipoprotein binding"}],"covers":["LR001035","LR004449"]},"LR008364":{"pair":"LRPAP1 -> LRP8","headline":"RAP (LRPAP1) binds apoER2 (LRP8) with a KD of 5 nM and blocks Reelin binding; supported by two papers and BioGRID records.","interaction_type":"direct binding","direction_and_effect":"RAP blocked Reelin binding to VLDLR and ApoER2 and reduced Reelin-induced Dab1 tyrosine phosphorylation in primary embryonic neurons [PMID:10571241]. RAP is an apoER2 ligand that does not induce signalling [PMID:12899622].","molecular_requirements":"RAP binds the same apoER2 regions as Reelin, acidic residues in complement-type repeats 1 and 3, with 1:1 stoichiometry [PMID:12899622].","affinity_potency":[{"value":"KD 5 nM","assay":"surface plasmon resonance","system":"apoER2","cite":"PMID:12899622"}],"species_and_systems":"In vitro binding and SPR; species listed human [PMID:12899622]. Reelin experiments used cultured primary embryonic neurons [PMID:10571241]. BioGRID lists reconstituted complexes [DB:BioGRID].","localisation_and_range":"LRPAP1 is flagged secreted [flag]; LRP8 is flagged transmembrane [flag].","caveats":"RAP is used here as a competitive control and non-signalling ligand, not a physiological signal. The curators' note on 12899622 says the paper's point is differential binding of Reelin and RAP. Abstract-level reading for 12899622.","key_references":[{"PMID":"12899622","why":"RAP binds apoER2 with KD 5 nM at the Reelin-binding regions"},{"PMID":"10571241","why":"RAP blocks Reelin binding to apoER2/VLDLR"}],"covers":["LR008364"]},"LR002928":{"pair":"LRRTM1 -> NRXN2","headline":"LRRTM1 is reported to share the S4-lacking neurexin binding code that covers neurexins 1, 2 and 3; support is one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The neurexin binding code of LRRTM2, which binds neurexins 1, 2 and 3 alpha and beta variants lacking an insert at splice site 4, is conserved in LRRTM1 and functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Neurexin variants must lack the splice site 4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"One paper, read as abstract only; species not specified. Both human and mouse pairs are projected from other evidence (ortholog inferred) [PMID:20519524]. No database records.","localisation_and_range":"Both partners are flagged transmembrane [flag]; localisation is not discussed in our evidence for this pair.","caveats":"The paper's text does not specifically name NRXN2 for LRRTM1; the pair is inferred from the general statement that the code is conserved, and the curator note itself says it covers NRXN1-3. Single paper, abstract read, no affinity reported.","key_references":[{"PMID":"20519524","why":"conserved neurexin binding code in LRRTM1"}],"covers":["LR002928","LR006153"]},"LR006159":{"pair":"LRRTM4 -> GPC1","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner, with GPC1 covered by a class-level result; one paper, mouse glypicans in HEK293T.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC1 says secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. The curator notes the abstract names glypican generically, but the excerpts cover this paralog. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002934","LR006159"]},"LR002937":{"pair":"LRRTM4 -> GPC5","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner, with GPC5 covered by a class-level result; one paper, mouse glypicans in HEK293T.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC5 says secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. The curator notes the abstract names glypican generically, but the excerpts cover this paralog. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002937","LR006162"]},"LR004458":{"pair":"LTB -> TNFRSF1A","headline":"Weak support: TNFR1 recognises a minor LT alpha2/beta1 complex; LT-beta's own contribution is not isolated.","interaction_type":"functional only","direction_and_effect":"The minor, early surface form with LT-alpha2/beta1 stoichiometry is recognised by the p55-TNF receptor [PMID:7995952]. Curator labels agonist.","molecular_requirements":"Recognition is by the complex; the LT-beta chain's contribution is not separated from LT-alpha2, per curator notes [PMID:7995952]. The predominant LT-alpha1/beta2 form is recognised by LTBR instead [PMID:7995952].","affinity_potency":[],"species_and_systems":"PMA-activated II-23 human T cell hybridoma; CHO cells co-transfected with LT-alpha and LT-beta gave similar surface forms [PMID:7995952].","localisation_and_range":"Surface (membrane-bound) LT complexes, not secreted [PMID:7995952].","caveats":"Abstract read only; BioGRID lists a reconstituted complex from the same paper [DB:BioGRID]. Whether LTB itself binds TNFR1 is not shown.","key_references":[{"PMID":"7995952","why":"Minor LT-alpha2/beta1 form recognised by p55 receptor"}],"covers":["LR001045","LR004458"]},"LR006168":{"pair":"LUM -> MMP14","headline":"Lumican directly inhibits MMP-14 activity with moderate affinity (KD about 275 nM); one paper.","interaction_type":"direct binding","direction_and_effect":"The glycosylated form of lumican significantly decreased MMP-14 activity in B16F1 melanoma cells, acting as a competitive inhibitor that completely blocked activity [PMID:25304424]. Curator labels antagonist.","molecular_requirements":"Lumican binds the catalytic domain of MMP-14; decorin did not have this effect [PMID:25304424]. The glycosylated form of lumican is the active form.","affinity_potency":[{"value":"KD ~275 nM","assay":"binding to MMP-14 catalytic domain (SPR per IntAct)","system":"B16F1 melanoma study","cite":"PMID:25304424"}],"species_and_systems":"Human proteins per curator labels; cell system B16F1 melanoma; IntAct lists surface plasmon resonance for this paper [DB:IntAct] [PMID:25304424]. Mouse pair is ortholog-inferred.","localisation_and_range":"Lumican flagged secreted; MMP14 is a membrane protease, not secreted [flag]. Matrix-proximal inhibition [PMID:25304424].","caveats":"Abstract-only. Binding to catalytic domain is a substrate-site interaction, so MMP-14 acts as an enzyme target rather than a signalling receptor. BioGRID lists biochemical activity [DB:BioGRID].","key_references":[{"PMID":"25304424","why":"Lumican competitively inhibits MMP-14, KD about 275 nM"}],"covers":["LR002943","LR006168"]},"LR002946":{"pair":"MAG -> RTN4RL2","headline":"MAG binds NgR2 (RTN4RL2) directly with higher affinity than NgR1 in one abstract-only paper; UniProt records the opposite.","interaction_type":"conflicting","direction_and_effect":"NgR2 is a receptor for MAG and mediates MAG inhibitory responses; forced NgR2 expression imparts MAG inhibition to neonatal sensory neurons and soluble NgR2 antagonises MAG [PMID:15673660].","molecular_requirements":"The NgR2 leucine-rich repeat cluster and 'unique' domain are needed for high-affinity MAG binding; binding is sialic acid dependent [PMID:15673660].","affinity_potency":[],"species_and_systems":"Human labelled for both partners; the paper was read as an abstract only and the assay system is not stated in our evidence [PMID:15673660]. Mouse pair is ortholog-inferred.","localisation_and_range":"MAG is flagged secreted; RTN4RL2 is flagged both secreted and receptor [flag]. Range not otherwise reported.","caveats":"Single paper, abstract only, no affinity value in our evidence. UniProt states RTN4RL2 does not interact with MAG, OMG and RTN4 [PMID:12839991][DB:UniProt], conflicting with the paper.","key_references":[{"PMID":"15673660","why":"NgR2 as a selective, sialic acid-dependent MAG receptor"}],"covers":["LR002946","LR006171"]},"LR004467":{"pair":"MBL2 -> CD93","headline":"Supported only by UniProt annotation; no curated paper evidence for this pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes CD93 as a receptor for defense collagens including C1q, SFTPA1 and mannose-binding lectin (MBL2), enhancing uptake of apoptotic cells and immune complexes [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human annotation; mouse pair is ortholog-inferred. No experimental system in our evidence.","localisation_and_range":"MBL2 is flagged secreted; CD93 flagged transmembrane receptor [flag].","caveats":"No paper confirmed the pair; two judged rows were classed as different entity. Support is a UniProt function statement only [PMID:7977768][DB:UniProt].","key_references":[],"covers":["LR001054","LR004467"]},"LR004476":{"pair":"MDK -> SDC4","headline":"Midkine binds syndecan-4 (ryudocan) with a reported Kd of 0.30 nM through heparan sulfate chains; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Purified human ryudocan bound midkine in a solid-phase assay [PMID:8621465]. Midkine bound both HS and CS chains of syndecan-4, more strongly to its CS chains than those of syndecan-1 [PMID:15226297].","molecular_requirements":"In the human ryudocan study binding was via HS chains: heparitinase destroyed it, heparin and HS inhibited, chondroitin sulfate did not [PMID:8621465]. In murine syndecan-4 both HS and CS chains contributed [PMID:15226297]; the two papers differ on CS involvement.","affinity_potency":[{"value":"Kd 0.30 nM","assay":"solid-phase binding (apparent dissociation constant)","system":"purified human ryudocan from EAhy926 cells","cite":"PMID:8621465"}],"species_and_systems":"Human ryudocan from EAhy926 endothelium-like cells [PMID:8621465]; murine mammary epithelial cell syndecan-4 by BIAcore [PMID:15226297]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence; syndecan-4 is a transmembrane proteoglycan per paper titles/abstracts [PMID:15226297].","caveats":"Both papers read as abstract only. Discrepancy between HS-only and HS+CS binding. Binding is to glycosaminoglycan chains, not necessarily the core protein.","key_references":[{"PMID":"8621465","why":"Kd 0.30 nM for midkine binding to human ryudocan"},{"PMID":"15226297","why":"HS and CS chain binding of midkine to syndecan-4"}],"covers":["LR001063","LR004476"]},"LR006177":{"pair":"MFGE8 -> ITGB1","headline":"Human beta1 evidence comes only via alpha8beta1 adhesion to MFGE8; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"alpha8-transfected human SW480 cells adhered to Mfge8, blocked by an alpha8 antibody; ligation of alpha8beta1 by Mfge8 reduced antral smooth muscle contraction through PTEN-dependent RhoA inhibition [PMID:27092791].","molecular_requirements":"beta1 is implicated only as the partner of alpha8 (alpha8beta1); beta1 alone was not tested separately in our evidence [PMID:27092791].","affinity_potency":[],"species_and_systems":"Human SW480 cells; mouse in vivo [PMID:27092791]. Human pair is ortholog-inferred.","localisation_and_range":"Mfge8 is flagged secreted [flag].","caveats":"Two further papers were judged abstract_insufficient and are not shown. The evidence is really for ITGA8; ITGB1 support is subunit-level, which matters for complex scoring.","key_references":[{"PMID":"27092791","why":"alpha8beta1 engagement by Mfge8"}],"covers":["LR002952","LR006177"]},"LR002955":{"pair":"MIA -> ITGA5","headline":"MIA binds integrin alpha5 (as alpha5beta1) in melanoma cells by far-Western and co-IP and reduces integrin activity; abstract only.","interaction_type":"direct binding","direction_and_effect":"MIA interacts with integrin alpha4beta1 and alpha5beta1, down-regulating integrin activity and MAPK signalling, an antagonist-type effect [PMID:16517605].","molecular_requirements":"The paper identifies alpha4beta1 and alpha5beta1 heterodimers, so both subunits belong to the complex [PMID:16517605]. MIA also binds fibronectin [PMID:16517605].","affinity_potency":[],"species_and_systems":"Human malignant melanoma cells [PMID:16517605]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIA is flagged secreted [flag].","caveats":"Abstract only; no affinity. Evidence is for the integrin heterodimers, not a single chain; the abstract does not say which assay showed which integrin.","key_references":[{"PMID":"16517605","why":"MIA binds alpha4beta1/alpha5beta1 integrins and reduces MAPK signalling"}],"covers":["LR002955","LR006180"]},"LR004485":{"pair":"MMP13 -> LRP1","headline":"MMP-13 is an LRP1 endocytic ligand per ligand blot and SPR; support from one 1999 rat paper and a 2020 survey.","interaction_type":"direct binding","direction_and_effect":"LRP-1 mediates collagenase-3 internalization [PMID:10514495]. SPR shows MMP-13 (E204A) binds LRP-1, and TIMP-3 increases affinity 7.6-fold, TIMP-1 and TIMP-2 by 2.4- and 4.6-fold [PMID:32694578].","molecular_requirements":"Rat work proposes a two-step mechanism using a specific 170-kDa collagenase-3 receptor plus LRP1 [PMID:10514495]. TIMP-bound complexes bind LRP-1 better [PMID:32694578].","affinity_potency":[{"value":"KD 25.6 nM","assay":"SPR, catalytically inactive MMP-13 (E204A)","system":"purified LRP-1","cite":"PMID:32694578"}],"species_and_systems":"Rat osteoblastic UMR 106-01 cells [PMID:10514495]; human proteins in SPR [PMID:32694578].","localisation_and_range":"MMP-13 flagged secreted [flag]; cleared by endocytosis [PMID:10514495].","caveats":"Abstract-only reading. The SPR used an inactive mutant, not wild-type enzyme. The 2020 paper's MMP-1 and MMP-13 rows share one abstract [PMID:32694578]. Ligand-blot evidence is indirect for LRP1 identity.","key_references":[{"PMID":"10514495","why":"Ligand blot; LRP1 required for collagenase-3 internalization"},{"PMID":"32694578","why":"SPR affinity with TIMP bridging"}],"covers":["LR001073","LR004485"]},"LR002964":{"pair":"MMP9 -> RECK","headline":"MMP9 interacts with canonical RECK via its Kazal motifs; RECK is an MMP inhibitor, so this is an inhibitory interaction, not signalling.","interaction_type":"direct binding","direction_and_effect":"Canonical RECK interacts with MMP9 in an inactivating interaction; a short RECK isoform competes with MMP9 for binding to the Kazal motifs, liberating MMP9 [PMID:29874120]. Increasing short RECK reduced co-immunoprecipitation of MMP9 with long RECK by as much as 88%, with no effect on MMP2 binding [PMID:29874120].","molecular_requirements":"Binding involves the Kazal motif region of canonical (long) RECK [PMID:29874120]. UniProt also lists that RECK interacts with MMP9 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in RECK-/- 293T cells with overexpressed proteins, plus fibroblast migration assays [PMID:29874120].","localisation_and_range":"RECK is not annotated secreted in the dossier; localisation is not reported in our evidence.","caveats":"The paper's main subject is the short-isoform competition; the MMP9-long RECK binding is background and was shown by co-IP in overexpression. Curated as an antagonist effect: RECK inhibits MMP9. Only the abstract plus excerpts were read.","key_references":[{"PMID":"29874120","why":"Competitive co-IP showing MMP9 binds the Kazal region of long RECK"}],"covers":["LR002964","LR006189"]},"LR008373":{"pair":"MSN -> PDPN","headline":"Database-only; moesin interacts with the PDPN cytoplasmic domain, so not a classical extracellular ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"PDPN interacts via its cytoplasmic domain with MSN and EZR; through this it promotes EMT and RHOA activation [DB:UniProt].","molecular_requirements":"Cytoplasmic domain of PDPN is involved [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence beyond human annotation.","localisation_and_range":"Not reported in our evidence; the interaction is described at the cytoplasmic domain.","caveats":"No papers verified (different_entity). Support is UniProt text only.","key_references":[],"covers":["LR008373"]},"LR007248":{"pair":"MSTN -> ACVR2A:TGFBR1","headline":"Indirect support only; the papers point to ACVR2B/ALK5 and activin type II receptors, not this exact complex.","interaction_type":"functional only","direction_and_effect":"GDF11 and MSTN signalling was verified through an ActR2b/ALK5 heterodimer [PMID:27340210]. Genetic evidence indicates ligands signal through both ACVR2 and ACVR2B to regulate muscle growth in vivo [PMID:16330774].","molecular_requirements":"ALK5 (TGFBR1) as type I partner, but with ACVR2B in the binding paper [PMID:27340210]; ACVR2A is not named individually.","affinity_potency":[],"species_and_systems":"Receptor dimerisation assay [PMID:27340210]; mouse skeletal muscle [PMID:16330774].","localisation_and_range":"Myostatin is secreted [flag].","caveats":"Both abstracts only; neither resolves the ACVR2A:TGFBR1 combination. A third paper was review only.","key_references":[{"PMID":"27340210","why":"ActR2b/ALK5 predominant for MSTN signalling"},{"PMID":"16330774","why":"Both activin type II receptors in muscle"}],"covers":["LR007248"]},"LR006195":{"pair":"MSTN -> TGFBR1","headline":"TGFBR1 (ALK5) inferred as myostatin type I receptor from one functional abstract.","interaction_type":"functional only","direction_and_effect":"GDF8 reduced PTX3 with SMAD2/3 phosphorylation; this was abolished by the ALK4/5/7 inhibitor SB431542 and ALK5 knockdown [PMID:25641196].","molecular_requirements":"Acts with type II receptors ACVR2A/ACVR2B per companion rows [PMID:25641196].","affinity_potency":[],"species_and_systems":"Human granulosa cell lines and primary granulosa-lutein cells [PMID:25641196]; mouse pair ortholog-inferred.","localisation_and_range":"Myostatin is secreted [flag].","caveats":"Abstract only; no direct binding of myostatin to TGFBR1 shown; inhibitor is not selective for ALK5.","key_references":[{"PMID":"25641196","why":"SB431542 and ALK5 knockdown in human granulosa cells"}],"covers":["LR002970","LR006195"]},"LR002973":{"pair":"MYL12B -> CD69","headline":"Myl9/12 reported as functional CD69 ligands in mouse asthma models; abstract-only and not isoform-specific.","interaction_type":"functional only","direction_and_effect":"Myl9 and Myl12 are described as new functional ligands for CD69; blocking CD69-Myl9/12 interaction ameliorated allergic airway inflammation [PMID:28783682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ovalbumin- and house dust mite-induced asthma models, plus human nasal polyp tissue staining [PMID:28783682].","localisation_and_range":"Ligand is flagged secreted [flag]; platelet-derived Myl9/12 localised to blood vessel luminal surfaces and net-like intravascular structures [PMID:28783682].","caveats":"Abstract only; the abstract does not give binding affinity or a binding assay. Evidence is functional (antibody blockade, in vivo) [PMID:28783682]. Myl9/12 are reported jointly; the abstract does not separate Myl12a from Myl12b. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"28783682","why":"Myl9/12 identified as functional CD69 ligands; blockade reduces airway inflammation"}],"covers":["LR002973","LR006198"]},"LR004494":{"pair":"MYOC -> FZD10","headline":"Myocilin-AP fusion bound FZD10 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. UniProt also records MYOC interacting with FZD10 [DB:UniProt].","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001083","LR004494"]},"LR002982":{"pair":"NCAN -> NRCAM","headline":"Single abstract-only paper reports neurocan association with NrCAM by cell binding and ELISA; no affinity or other support.","interaction_type":"direct binding","direction_and_effect":"Neurocan blocked Sema3F-induced spine elimination and COS-7 cell retraction, which was mediated through NrCAM, Neuropilin-2 and PlexinA3 [PMID:30356641]. Neurocan acts as an inhibitor of NrCAM/Sema3F signalling.","molecular_requirements":"NrCAM is a subunit of the Sema3F receptor complex with Neuropilin-2 and PlexinA3. Neurocan glycosaminoglycan chains were required for inhibition; the C-terminal sushi domain was dispensable [PMID:30356641].","affinity_potency":[],"species_and_systems":"Mouse neocortex, cortical neuron cultures and COS-7 cells; binding by cell binding assay and ELISA [PMID:30356641]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Both entities carry a secreted flag [flag]; neurocan was found at the cell surface of cortical pyramidal neurons and adjacent to dendritic spines [PMID:30356641].","caveats":"Based on one paper read as abstract only; no quantitative binding data. Both species rows are inferred by orthology, not directly tested.","key_references":[{"PMID":"30356641","why":"Cell binding and ELISA association of neurocan with NrCAM"}],"covers":["LR002982","LR006207"]},"LR005259":{"pair":"NECTIN2 -> CD226","headline":"Direct, bidirectional binding with functional NK activation shown in human cells; three curator-verified papers, all read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"Nectin-2 is an activating ligand for CD226 (DNAM-1): Nectin-2-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained Nectin-2-expressing CHO-K cells, and masking either partner reduced NK lysis of tumour cells [PMID:15607800]. Ectopic CD112 (Nectin-2) made mouse BW5147 cells more susceptible to IL-2-activated T and NK cytotoxicity, blocked by anti-CD226 mAb [PMID:15039383]. Ubiquitin-pathway inhibition raised surface Nectin2 and enhanced NK killing [PMID:30888046].","molecular_requirements":"CD226 acts together with LFA-1 in triggering cytotoxicity and cytokine secretion [PMID:15039383]. Homophilic interaction of cell-surface CD112 may reduce CD226 binding to cell-surface CD112 [PMID:15039383]. No subunit requirement beyond this is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in all three papers (recombinant Fc chimeras, transfectants, NK/T cells, tumour cell lines). The mouse pair is projected from human evidence [PMID:15607800] [PMID:15039383].","localisation_and_range":"Both partners carry membrane/transmembrane flags [flag]; the papers describe interaction between NK cell and target cell surfaces, i.e. contact-dependent [PMID:15607800].","caveats":"All papers read as abstracts only. Soluble CD226 binds CD155 and CD112 with comparable affinity but no value is given in our evidence [PMID:15039383]. Nectin-2 is mainly cytoplasmic in tumour lines, which limits surface availability [PMID:30888046]. Database support (BioGRID, IntAct, Reactome, UniProt) agrees [DB:UniProt] [DB:Reactome].","key_references":[{"PMID":"15607800","why":"Reciprocal Fc-chimera binding plus NK lysis"},{"PMID":"15039383","why":"Nectin-2 as CD226 ligand, functional cytotoxicity"},{"PMID":"30888046","why":"Surface Nectin2 regulated by ubiquitination, NK killing"}],"covers":["LR001920","LR005259"]},"LR002991":{"pair":"NID2 -> LGR4","headline":"Nidogen-2 reported to bind LGR4 directly (Kd 26.77 nM) and protect against vascular calcification; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Nidogen-2 directly binds LGR4 with KD 26.77 nM; LGR4 deficiency abolishes the protective effect of nidogen-2 against VSMC calcification, and the abstract describes biased activation of LGR4-Galphaq-PKCalpha-AMPKalpha1 signalling [PMID:36354004]. The curator's effect label reads 'antagonist' while its note calls nidogen-2 a biased agonist; the functional readout is anti-calcification.","molecular_requirements":"LGR4 is required for the effect (its deficiency abolishes protection) [PMID:36354004]; co-receptors or subunits are not reported in our evidence.","affinity_potency":[{"value":"Kd 26.77 nM","assay":"binding after coimmunoprecipitation/interactome; the abstract lists SPR among its methods but does not tie it to this value","system":"purified nidogen-2 and VSMC membrane protein","cite":"PMID:36354004"}],"species_and_systems":"Curator lists human; the abstract also uses mouse models (three calcification models, Nidogen-2-/- mice) and VSMCs. Mouse pair is ortholog-projected [PMID:36354004].","localisation_and_range":"Nidogen-2 is a basement-membrane protein flagged secreted [flag]; the paper calls it a vascular extracellular matrix component, so action is local/paracrine in the matrix [PMID:36354004].","caveats":"Abstract only (truncated); the assay behind the Kd is not clearly stated. Effect label is inconsistent between curator fields.","key_references":[{"PMID":"36354004","why":"Direct binding Kd 26.77 nM and genetic LGR4 dependence"}],"covers":["LR002991","LR006215"]},"LR004539":{"pair":"NPPA -> NPR3","headline":"ANP binds the clearance receptor NPR3 with high affinity; supported by structures, cloning and databases.","interaction_type":"direct binding","direction_and_effect":"Recombinant human ANP C-receptor has high affinity for ANP [PMID:2169733]. UniProt says NPR3 removes the hormone from circulation [DB:UniProt], so it acts as a clearance receptor rather than a signalling one.","molecular_requirements":"NPR-C acts as a dimer binding one hormone molecule (1:2 hormone:receptor) in the structure with CNP [PMID:11533490]; PDB has an ANP-NPR3 structure [DB:PDB 1YK0].","affinity_potency":[{"value":"Kd 6 nM","assay":"binding after transfection of human cDNA","system":"mammalian cells expressing human ANP C-receptor","cite":"PMID:2169733"}],"species_and_systems":"Human receptor in transfected cells [PMID:2169733]; human crystal structures [PMID:11533490]. Mouse pair is projected.","localisation_and_range":"ANP is annotated secreted [flag].","caveats":"Both papers read as abstracts only. PMID:11533490 reports a CNP complex, not ANP, in its abstract; stoichiometry for ANP is from the curator evidence sentence. BioGRID co-crystal record exists [DB:BioGRID].","key_references":[{"PMID":"2169733","why":"Human NPR3 binds ANP with high affinity"},{"PMID":"11533490","why":"Structural basis of natriuretic peptide binding to NPR-C"}],"covers":["LR001129","LR004539"]},"LR004548":{"pair":"NPW -> NPBWR1","headline":"NPW binds and activates NPBWR1 (GPR7) at nanomolar doses; four confirmed binding/activation records, abstract level.","interaction_type":"direct binding","direction_and_effect":"NPW is an agonist of NPBWR1. Synthetic NPW23 and NPW30 activated and bound GPR7 and GPR8 at similar effective doses [PMID:12130646]; binding with low nanomolar affinity to GPR7 and GPR8 in CHO-K1 cells [PMID:12401809]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; both NPW23 and NPW30 mature forms act [PMID:12130646]. No co-receptor reported.","affinity_potency":[{"value":"pIC50 10.0","assay":"affinity recorded by curators (receptor row not specified in the dossier)","system":"CHO, human receptors, porcine-purified ligand","cite":"PMID:12130646"}],"species_and_systems":"Human receptors in CHO cells; ligand purified from porcine hypothalamus in the first paper, with rat in vivo feeding effects [PMID:12130646]; human peptides in [PMID:12401809]. Mouse pair is projected from human.","localisation_and_range":"NPW is flagged secreted, not transmembrane; NPBWR1 transmembrane [flag]. Neuropeptide acting at a central receptor, paracrine/neuroendocrine, is an inference from flags only.","caveats":"All papers were read as abstracts. NPW is not selective between GPR7 and GPR8 [PMID:12130646]. The pIC50 is a curator-recorded value and is not stated in the abstract.","key_references":[{"PMID":"12130646","why":"Purification of NPW and activation of GPR7/GPR8"},{"PMID":"12401809","why":"Low nanomolar binding of L8/L8C to GPR7 and GPR8"}],"covers":["LR001138","LR004548"]},"LR004557":{"pair":"NRG1 -> ERBB4","headline":"NRG1 binds and activates ERBB4 directly; supported by several abstract-level binding studies and database records.","interaction_type":"direct binding","direction_and_effect":"Agonist: heregulin activates ErbB4; all mutants tested induced ERBB4 phosphorylation and MAPK activation [PMID:9565587]. Region 177-226 of heregulin beta is sufficient for binding and receptor phosphorylation [PMID:7721889]. NRG-1 binding to ErbB-4 was displaceable by NRG-4 [PMID:10348342].","molecular_requirements":"Wild-type phage-displayed HRGbeta EGF domain bound ErbB4-IgG; binding was affected by mutation of residues throughout the EGF domain, and ErbB4 appeared less stringent than ErbB3 [PMID:9565587]. Single-molecule imaging examined ErbB3/B4 on MCF-7 cells [PMID:22891299]. ERBB4 can bind alone; ERBB2 is not required in the evidence shown.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; phage display, receptor-IgG fusions, synthetic peptides, MCF-7 cells. The mouse pair is projected from human evidence.","localisation_and_range":"NRG1 is flagged secreted and transmembrane [flag]; not tested in the papers.","caveats":"All shown papers were abstract-only reads, and 6 further papers were judged abstract_insufficient. The single-molecule paper analyses ErbB3/B4 together, so its ERBB4-specific contribution is not separated [PMID:22891299]. PMID 10995872 is background framing. No affinity for ERBB4 is quoted in our evidence; GtoPdb lists pKd and pIC50 records without values [DB:GtoPdb].","key_references":[{"PMID":"9565587","why":"HRGbeta EGF domain binds ErbB4-IgG and activates ERBB4"},{"PMID":"7721889","why":"Heregulin beta 177-226 sufficient for binding"},{"PMID":"22891299","why":"Single-molecule HRG kinetics on ErbB3/B4 in live cells"}],"covers":["LR001148","LR004557"]},"LR007365":{"pair":"NRTN -> GFRA2:RET","headline":"NRTN signals through the GFRA2:RET complex, which prefers NTN over GDNF.","interaction_type":"functional only","direction_and_effect":"Fibroblasts expressing TrnR2 and Ret are approximately 30-fold more sensitive to NTN than to GDNF, so the complex acts preferentially as an NTN receptor [PMID:9182803].","molecular_requirements":"Both GFRA2 (GPI-linked) and RET are required for the complex; BioGRID records RET-NRTN capture [DB:BioGRID]; PDB entries contain NRTN and GFRA2 chains [DB:PDB 5MR4].","affinity_potency":[{"value":"approximately 30-fold more sensitive to NTN than to GDNF","assay":"Ret phosphorylation dose-response","system":"fibroblasts expressing TrnR2 and Ret","cite":"PMID:9182803"}],"species_and_systems":"Human receptors, transfected fibroblasts; TrnR2 and Ret co-expressed in rat SCG neurons [PMID:9182803].","localisation_and_range":"NRTN annotated secreted [flag].","caveats":"Single paper, read as abstract only for this row; no binding affinity.","key_references":[{"PMID":"9182803","why":"TrnR2-Ret is a preferential NTN receptor"}],"covers":["LR007365"]},"LR006249":{"pair":"NRXN2 -> CLSTN3","headline":"Beta-neurexin binding to Clstn3 reported in general; NRXN2 is not named in our evidence.","interaction_type":"direct binding","direction_and_effect":"Beta-Nrxns directly interact via their LNS domain with Clstn3; SS4-positive beta-Nrxn variants reversed the impaired Clstn3 synaptogenic activity in Nrxn-deficient neurons [PMID:32434929].","molecular_requirements":"Needs SS4-insert-positive variants; Clstn3 cadherin domains are involved [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species unspecified in curation; mouse pair is the non-inferred one.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"Abstract only. The abstract names beta-Nrxns as a group, not NRXN2.","key_references":[{"PMID":"32434929","why":"beta-Nrxn LNS domain binds Clstn3"}],"covers":["LR003025","LR006249"]},"LR008544":{"pair":"NRXN2 -> NLGN3","headline":"Neuroligin-neurexin binding is shown in rat, but the abstract does not pin down NRXN2 specifically.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins, as native brain proteins and recombinant proteins [PMID:8576240].","molecular_requirements":"Tight binding is observed only for beta-neurexins lacking an insert in splice site 4 [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat binding assays; abstract only [PMID:8576240].","localisation_and_range":"Both partners flagged transmembrane, non-secreted [flag].","caveats":"Abstract reads only as 'a subset of neurexins' and beta-neurexins in general, so the NRXN2 paralogue is not established; BioGRID support for this pair is not listed here.","key_references":[{"PMID":"8576240","why":"Neuroligins 1-3 bind beta-neurexins in a splice-site 4 dependent way"}],"covers":["LR008544"]},"LR004566":{"pair":"NTF3 -> NTRK1","headline":"NT-3 is a lower-affinity heterologous ligand of TrkA with agonist and partly antagonistic character; abstract-only support.","interaction_type":"direct binding","direction_and_effect":"NT-3 binds TrkA as a lower affinity heterologous ligand [PMID:17439940]. Docking on both site 1 (D5) and site 2 (D4) gives full agonism, additive with NGF; site 1 alone is partially agonistic but noncompetitively antagonizes NGF binding [PMID:17439940].","molecular_requirements":"Two TrkA extracellular sites: D5 hot spot (site 1) and D4 (site 2) [PMID:17439940].","affinity_potency":[],"species_and_systems":"Binding studies with truncated and chimeric human TrkA extracellular subdomains plus survival assays [PMID:17439940]. Mouse pair is ortholog-inferred.","localisation_and_range":"NTF3 flagged secreted, NTRK1 transmembrane [flag].","caveats":"Abstract only; no numeric affinity reported. One review-only row is not shown. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"17439940","why":"TrkA D5 and D4 docking sites for NT-3"}],"covers":["LR001157","LR004566"]},"LR006258":{"pair":"NTN1 -> DSCAM","headline":"Two papers support netrin-1 as a DSCAM ligand, acting independently of DCC; one reports binding, read as abstract only.","interaction_type":"direct binding","direction_and_effect":"Netrin-1 binds DSCAM and acts as an agonist: DSCAM mediates turning responses to netrin-1 and Xenopus neurons expressing DSCAM are attracted by netrin-1 independently of DCC [PMID:18585357]. Without DCC, DSCAM mediates netrin signalling, activating Fyn and Pak1 phosphorylation [PMID:19196994].","molecular_requirements":"DSCAM alone can mediate netrin signalling in transfected cells [PMID:19196994]. DSCAM and DCC can each mediate a turning response, and also collaborate in commissural axon guidance [PMID:18585357]. UniProt says the extracellular domain interacts with NTN1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Spinal commissural axons, Xenopus spinal neurons, transfected cells; siRNA knockdown in ovo [PMID:18585357][PMID:19196994]. Species labelled human for both partners in the curation, but the abstracts do not state it.","localisation_and_range":"Netrin-1 flagged secreted, DSCAM transmembrane (also flagged secreted) [flag].","caveats":"Both papers read as abstracts only. Binding is stated in the abstracts, with no affinity reported. The second paper is mostly functional (knockdown, signalling) [PMID:19196994].","key_references":[{"PMID":"18585357","why":"DSCAM binds netrin-1 and mediates turning independent of DCC"},{"PMID":"19196994","why":"DSCAM knockdown blocks netrin-induced outgrowth; DCC-independent signalling"}],"covers":["LR003034","LR006258"]},"LR001929":{"pair":"NTN1 -> MCAM","headline":"Strong binding evidence from full text: netrin-1 binds CD146 (MCAM) with Kd about 1.33 nM and promotes angiogenesis through it.","interaction_type":"direct binding","direction_and_effect":"Netrin-1 is a ligand for CD146 and acts as an agonist: CD146 knockdown abolished netrin-1-induced HUVEC proliferation, migration and tube formation at 50 or 200 ng/ml, and conditional knockout or antibody blockade reduced netrin-1-induced angiogenesis [PMID:25656845].","molecular_requirements":"Domain V of netrin-1 and the 4th Ig domain of CD146 are required for binding. Netrin-1 induced CD146 dimerization, and activated VEGFR2, ERK1/2 and p38 signalling without binding VEGFR2 itself [PMID:25656845]. When UNC5B was knocked down, netrin-1 promoted endothelial activation mainly via CD146 [PMID:25656845].","affinity_potency":[{"value":"Kd ~1.33 nM","assay":"surface plasmon resonance","system":"netrin-1 with CD146","cite":"PMID:25656845"},{"value":"Kd 5.10 nM","assay":"surface plasmon resonance (netrin-UNC5B comparison)","system":"netrin-1 with UNC5B","cite":"PMID:25656845"}],"species_and_systems":"Pull-down with purified proteins, SPR, HEK293 cell binding, HUVECs, mouse conditional knockout and zebrafish embryos [PMID:25656845]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted; MCAM is flagged as not transmembrane in this annotation [flag] while the paper calls CD146 a transmembrane protein [PMID:25656845].","caveats":"Single paper. Netrin-1 at 2 000 ng/ml was inhibitory and this effect was not CD146-dependent [PMID:25656845]. The transmembrane flag for MCAM conflicts with the paper text.","key_references":[{"PMID":"25656845","why":"Identifies CD146 as a netrin-1 receptor, with SPR affinity and in vivo data"}],"covers":["LR001929","LR005268"]},"LR005268":{"pair":"NTN1 -> MCAM","headline":"Strong binding evidence from full text: netrin-1 binds CD146 (MCAM) with Kd about 1.33 nM and promotes angiogenesis through it.","interaction_type":"direct binding","direction_and_effect":"Netrin-1 is a ligand for CD146 and acts as an agonist: CD146 knockdown abolished netrin-1-induced HUVEC proliferation, migration and tube formation at 50 or 200 ng/ml, and conditional knockout or antibody blockade reduced netrin-1-induced angiogenesis [PMID:25656845].","molecular_requirements":"Domain V of netrin-1 and the 4th Ig domain of CD146 are required for binding. Netrin-1 induced CD146 dimerization, and activated VEGFR2, ERK1/2 and p38 signalling without binding VEGFR2 itself [PMID:25656845]. When UNC5B was knocked down, netrin-1 promoted endothelial activation mainly via CD146 [PMID:25656845].","affinity_potency":[{"value":"Kd ~1.33 nM","assay":"surface plasmon resonance","system":"netrin-1 with CD146","cite":"PMID:25656845"},{"value":"Kd 5.10 nM","assay":"surface plasmon resonance (netrin-UNC5B comparison)","system":"netrin-1 with UNC5B","cite":"PMID:25656845"}],"species_and_systems":"Pull-down with purified proteins, SPR, HEK293 cell binding, HUVECs, mouse conditional knockout and zebrafish embryos [PMID:25656845]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted; MCAM is flagged as not transmembrane in this annotation [flag] while the paper calls CD146 a transmembrane protein [PMID:25656845].","caveats":"Single paper. Netrin-1 at 2 000 ng/ml was inhibitory and this effect was not CD146-dependent [PMID:25656845]. The transmembrane flag for MCAM conflicts with the paper text.","key_references":[{"PMID":"25656845","why":"Identifies CD146 as a netrin-1 receptor, with SPR affinity and in vivo data"}],"covers":["LR001929","LR005268"]},"LR004575":{"pair":"NTN1 -> UNC5B","headline":"Netrin-1 to UNC5B has binding and functional support, but only from abstracts; strongest are a 1997 binding study and a 2026 co-IP.","interaction_type":"direct binding","direction_and_effect":"UNC5 homologues were shown to be netrin-binding proteins [PMID:9126742]. Co-immunoprecipitation validated a Netrin-1-UNC5B interaction in NCI-H1299 lung cancer cells, linked to UNC5B-PI3K signalling and epithelial-mesenchymal transition [PMID:42284640].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cloned UNC-5 homologues [PMID:9126742]; NCI-H1299 NSCLC cells and xenograft [PMID:42284640]. Also IntAct co-immunoprecipitation and avexis records and Reactome [DB:IntAct][DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5B is transmembrane [flag].","caveats":"Both papers read as abstracts only. The 1997 abstract does not name UNC5B specifically. The 2026 paper is an eupatilin pharmacology study where the interaction is a supporting experiment, and its abstract is truncated [PMID:42284640].","key_references":[{"PMID":"9126742","why":"UNC-5 homologues as netrin-binding proteins"},{"PMID":"42284640","why":"Co-IP of Netrin-1 with UNC5B in NSCLC cells"}],"covers":["LR001166","LR004575"]},"LR004584":{"pair":"NTS -> NTSR2","headline":"Neurotensin binds NTSR2 but evidence conflicts on effect: one paper reports no signalling and functional antagonism, while databases say agonist.","interaction_type":"conflicting","direction_and_effect":"In human NT2 receptor expressed in CHO cells, neurotensin binding did not elicit a second-messenger response and antagonised the agonist activity of SR48692 and SR142948A [PMID:9851594]. GtoPdb nevertheless lists an agonist record [DB:GtoPdb], and the interaction carries a 'Stimulatory' annotation. Mouse NTRL (NTSR2) internalised iodinated neurotensin, followed by recycling, without detectable adenylate cyclase, guanylate cyclase or phospholipase C modulation [PMID:9480852]. Neurotensin binding triggers internalisation of NTR2 [PMID:11801734].","molecular_requirements":"Single receptor chain, no co-receptor reported. Mouse NTR2 recycling depends on tyrosine 237 in the third intracellular loop, where human NTR2 has a cysteine and does not recycle [PMID:11801734].","affinity_potency":[{"value":"IC50 0.49 nm","assay":"competition binding, neurotensin","system":"NTR2 (species not stated in our excerpt)","cite":"PMID:16087676"}],"species_and_systems":"Human receptor in CHO cells [PMID:9851594]; mouse receptor in HEK293 [PMID:9480852]; mouse/human/rat receptors in trafficking study [PMID:11801734]. The mouse pair is ortholog-inferred.","localisation_and_range":"Neuropeptide flagged secreted [flag]; receptor is a membrane GPCR.","caveats":"Effect direction is unresolved: antagonism or inactivity in [PMID:9851594] and [PMID:9480852] versus agonist labels in GtoPdb and the curated rows. PMID:16087676 binding quote was browser-read and its spot-check is pending, and the same paper's abstract says SK-N-SH cells lack NTR2. PMID:9480852's evidence sentence is just the title. Species differences in recycling matter.","key_references":[{"PMID":"9851594","why":"Human NT2 receptor binds neurotensin without signalling and neurotensin antagonises SR compounds"},{"PMID":"9480852","why":"Mouse NTSR2 binding, internalisation and recycling"},{"PMID":"11801734","why":"Species difference in NTR2 recycling"}],"covers":["LR001175","LR004584"]},"LR006267":{"pair":"NXNL1 -> BSG","headline":"RdCVF (NXNL1) binds Basigin-1 in photoreceptors to protect cones; a single abstract-only paper plus UniProt supports it.","interaction_type":"direct binding","direction_and_effect":"RdCVF acts through binding to Basigin-1 (BSG1) on photoreceptors, leading to increased glucose entry into cones and survival via aerobic glycolysis [PMID:25957687]. UniProt describes BSG as a retinal cell surface receptor for NXNL1 [DB:UniProt].","molecular_requirements":"The BSG1 isoform is specified; BSG1 then binds the glucose transporter GLUT1 [PMID:25957687]. A missense RdCVF mutation abolishes BSG1 binding, glucose uptake and protection [PMID:25957687].","affinity_potency":[],"species_and_systems":"Abstract does not name species or binding affinity; a model of retinitis pigmentosa was used [PMID:25957687]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"RdCVF is a secreted thioredoxin-like protein [flag][PMID:25957687]; BSG is a transmembrane receptor [flag]. Paracrine from rods to cones [PMID:25957687].","caveats":"Single paper, abstract only; no affinity reported in our evidence. Both species pairs are inferred by orthology.","key_references":[{"PMID":"25957687","why":"RdCVF binds BSG1 to stimulate cone glucose uptake"}],"covers":["LR003043","LR006267"]},"LR007383":{"pair":"PGF -> FLT1:KDR","headline":"No verified paper for the FLT1:KDR heterodimer; database records concern PGF-FLT1 only.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the heterodimer; records describe PGF with FLT1 [DB:IntAct] [DB:PDB 1RV6].","molecular_requirements":"Whether FLT1:KDR heterodimer is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"PDB 1RV6 is PlGF with VEGFR1 domain 2, not the heterodimer [DB:PDB 1RV6].","localisation_and_range":"Not reported in our evidence.","caveats":"Judged rows were abstract_insufficient and different_entity; the database records appear to support the single-chain PGF-FLT1 pair rather than the complex [DB:BioGRID].","key_references":[],"covers":["LR007383"]},"LR003099":{"pair":"PGLYRP1 -> TNFRSF1A","headline":"PGLYRP1/Tag7 peptide 17.1A binds and blocks TNFR1; one abstract plus excerpts paper, from one group.","interaction_type":"direct binding","direction_and_effect":"Peptide 17.1A, from the PGLYRP1 C-terminus, bound TNFR1 and blocked its cytotoxic signals; the paper says the Tag7 protein inhibits TNFalpha cytotoxicity via TNFR1 [PMID:34163464]. UniProt instead describes PGLYRP1 with HSPA1A activating TNFR1 [DB:UniProt].","molecular_requirements":"Peptide 17.1A (RSNYVLKG) is the minimal TNFR1-binding region, shown by affinity chromatography on sTNFRI [PMID:34163464].","affinity_potency":[],"species_and_systems":"Human cell assays; peptide tested in a mouse CFA arthritis model [PMID:34163464]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Binding was shown for the peptide, not full-length PGLYRP1; the inhibitory link for full-length protein cites earlier work. Direction conflicts with UniProt's activating description [DB:UniProt].","key_references":[{"PMID":"34163464","why":"Peptide 17.1A binds TNFR1 and blocks cytotoxicity"}],"covers":["LR003099","LR006321"]},"LR001938":{"pair":"PLA2G2A -> ITGA4","headline":"sPLA2-IIA binds and activates integrin alpha4beta1; alpha4 is listed as one subunit of the heterodimer.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound alpha4beta1, competed with VCAM-1 for binding, and bound a site close to those for VCAM-1 and CS-1 in the alpha4 subunit [PMID:18635536]. It activated alpha4beta1 in a site 2-mediated manner, agonist effect [PMID:25398877]. Signalling was independent of catalytic activity [PMID:18635536]. UniProt records the site 2 binding [DB:UniProt P13612].","molecular_requirements":"The heterodimer alpha4beta1 binds; a site 2 peptide from integrin beta1 blocked sPLA2-IIA effects [PMID:25398877], so the beta1 chain contributes. A separate complex entry exists.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"Abstract-level reading for both papers; one paper's full-text read is marked unverified. Binding Kd given in [PMID:18635536] was for alphavbeta3, not alpha4beta1. Not reported in our evidence for alpha4 alone.","key_references":[{"PMID":"18635536","why":"sPLA2-IIA binds alphavbeta3 and alpha4beta1, competes with VCAM-1"},{"PMID":"25398877","why":"Site 2 activation of alpha4beta1, alphavbeta3, alpha5beta1"}],"covers":["LR001938","LR005275"]},"LR005277":{"pair":"PLA2G2A -> ITGAV","headline":"sPLA2-IIA binds integrin alphavbeta3 with Kd 2 x 10(-7) M and activates it via site 2; two abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound integrin alphavbeta3 at high affinity [PMID:18635536]. It directly activated purified soluble and cell-surface alphavbeta3 independent of catalysis or M-type receptor [PMID:25398877]. Arg-74 and Arg-100 are critical for binding; the integrin-binding-defective R74E/R100E mutant did not induce proliferation or ERK1/2 activation in monocytic cells [PMID:18635536]. Agonist.","molecular_requirements":"alphavbeta3 heterodimer; a site 2 peptide from integrin beta1 bound sPLA2-IIA and suppressed activation [PMID:25398877].","affinity_potency":[{"value":"KD 2 x 10(-7) M","assay":"binding to integrin alphavbeta3","system":"human sPLA2-IIA and integrin; abstract-only","cite":"PMID:18635536"}],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"Abstract only. Site 2 binding in [PMID:25398877] is a docking prediction supported by peptide competition, not a direct structure. Stored per subunit although the heterodimer binds.","key_references":[{"PMID":"18635536","why":"Kd for alphavbeta3, mutagenesis, signalling dependence"},{"PMID":"25398877","why":"Site 2 activation of alphavbeta3"}],"covers":["LR001940","LR005277"]},"LR004629":{"pair":"PLAU -> VLDLR","headline":"uPA complexed with PAI-1 binds the VLDL receptor with high affinity and is internalised; free uPA alone is not shown.","interaction_type":"direct binding","direction_and_effect":"In vitro, the uPA.PAI-1 complex bound purified VLDL receptor with high affinity, and VLDLR-expressing fibroblasts internalised and degraded 125I-labelled uPA.PAI-1; non-infected cells did not [PMID:7592875]. The record is labelled agonist, i.e. endocytic clearance, not signalling.","molecular_requirements":"The ligand tested is uPA bound to PAI-1, not uPA alone [PMID:7592875].","affinity_potency":[],"species_and_systems":"Human cell and protein sources; internalisation tested in VLDLR/LRP-double-deficient murine fibroblasts infected with an adenoviral VLDLR vector [PMID:7592875]. Abstract only.","localisation_and_range":"Ligand flagged secreted; receptor transmembrane [flag]. Complex is cleared by endocytosis [PMID:7592875].","caveats":"One paper, abstract only; one further row is pending and not shown. No affinity value reported. The curated evidence sentence concerns lipoprotein lipase rather than uPA.","key_references":[{"PMID":"7592875","why":"VLDLR binds and internalises uPA.PAI-1"}],"covers":["LR001226","LR004629"]},"LR006339":{"pair":"PLG -> ENO1","headline":"Cell-surface enolase-1 binding plasminogen is reported in monocytes; one database record also supports it.","interaction_type":"direct binding","direction_and_effect":"ENO-1 binds plasminogen at the cell surface, enhancing plasmin production; LPS raised ENO-1 surface expression on human monocytes and U937 cells, and antibodies against its plasminogen-binding site abrogated the effects [PMID:19182206].","molecular_requirements":"Plasminogen-binding site of ENO-1 is required for the effects [PMID:19182206].","affinity_potency":[],"species_and_systems":"Human blood monocytes and U937 cells; in vivo recruitment also tested, species not given here [PMID:19182206]. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted; ENO-1 is a cytosolic enzyme translocated to the surface [PMID:19182206].","caveats":"Abstract only. Binding was stated, not quantified. ENO-1 is also a glycolytic enzyme, so receptor role is context-dependent.","key_references":[{"PMID":"19182206","why":"ENO-1 plasminogen-binding site drives monocyte migration"}],"covers":["LR003118","LR006339"]},"LR004638":{"pair":"PNOC -> OPRL1","headline":"Nociceptin (PNOC product) binds and activates OPRL1 with high affinity in human, rat and mouse systems; very well supported.","interaction_type":"direct binding","direction_and_effect":"Nociceptin/orphanin FQ is an agonist at OPRL1: it was purified as a ligand of the orphan receptor LC132, bound it saturably with high affinity, and nanomolar peptide inhibited forskolin-stimulated adenylyl cyclase, without activating opioid receptors [PMID:7481766]. Nociceptin inhibits cAMP in CHO cells expressing the receptor [PMID:10369464].","molecular_requirements":"Single receptor chain sufficient in recombinant cells. Mutagenesis of transmembrane residues (Asp130, Tyr131, Phe224 and others) reduces nociceptin affinity and reactivity [PMID:10692489]. Gln286Ala keeps binding but abolishes cAMP inhibition [PMID:10692489]. Gln280His leaves nociceptin affinity unchanged [PMID:8849681].","affinity_potency":[{"value":"Kd 0.22 nM","assay":"nociceptin binding, wild-type receptor","system":"recombinant CHO cells, human ORL1","cite":"PMID:10692489"},{"value":"50-100 pM","assay":"[3H]14-Tyr-nociceptin binding","system":"brain or CHO-ORL1 cell membranes","cite":"PMID:9413015"}],"species_and_systems":"Mouse and porcine brain-derived peptide on transfected cells [PMID:7481766]; rat brain membranes and human receptor in CHO cells [PMID:10369464]; human receptor in CHO cells [PMID:10692489][PMID:8849681]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; diffusible peptide acting on a cell-surface receptor.","caveats":"In intact cells most binding is to a low-affinity state of about 8 nM [PMID:9413015]. Several papers study analogues or mutants, with nociceptin as reference [PMID:11097863][PMID:12967935]. Most papers read as abstracts. Two papers are pending and two review-only.","key_references":[{"PMID":"7481766","why":"discovery of orphanin FQ as ligand of the orphan receptor"},{"PMID":"10692489","why":"nociceptin Kd for wild-type and mutant receptors"},{"PMID":"9413015","why":"binding versus functional potency"}],"covers":["LR001236","LR004638"]},"LR004647":{"pair":"POMC -> OPRK1","headline":"Supported only by GtoPdb records of partial agonism; no verified paper in the dossier.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records POMC at OPRK1 as an agonist with partial agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 6.3-7.9","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:7624359"}],"species_and_systems":"No curator-verified paper; species of the underlying experiments not reported in our evidence. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"POMC flagged secreted, OPRK1 transmembrane [flag].","caveats":"Rests on database records only. Curators judged 10 papers abstract_insufficient and 2 review_only, so none confirmed.","key_references":[],"covers":["LR001245","LR004647"]},"LR006348":{"pair":"POSTN -> STAB1","headline":"Periostin was independently confirmed as a circulating ligand of Stab1/Stab2 in one mouse atherosclerosis study, read as an abstract.","interaction_type":"direct binding","direction_and_effect":"Periostin, reelin and TGFBi were independently confirmed as novel circulating ligands of Stab1/2 [PMID:36325910]. Stab1/2 mediate clearance of circulating plasma molecules; ApoE-Stab1-KO and ApoE-Stab2-KO mice show reduced atherogenesis [PMID:36325910]. Receptor clearance, not signalling agonism, is the described effect.","molecular_requirements":"Not reported in our evidence; the curator's notes mention GST-pulldown and endocytosis assays [PMID:36325910].","affinity_potency":[],"species_and_systems":"Mouse knockout and plasma proteomics plus in vitro assays; read as abstract only [PMID:36325910]. Human pair is the dossier species; the mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Periostin is flagged secreted [flag]; the paper describes circulating ligands cleared by liver sinusoidal endothelium [PMID:36325910].","caveats":"Single abstract-level paper, with no affinity or species-of-binding detail. The paper confirms five ligand-receptor combinations at once, and the abstract does not give per-pair detail. Stab1 and Stab2 are paralogs with shared ligands; one study covers both.","key_references":[{"PMID":"36325910","why":"Stab1/2 identified as clearance receptors for periostin, reelin and TGFBi"}],"covers":["LR003127","LR006348"]},"LR004656":{"pair":"PRND -> RPSA","headline":"Direct physical interaction in yeast two-hybrid and co-immunoprecipitation; one abstract-only paper, no signalling effect shown.","interaction_type":"direct binding","direction_and_effect":"Doppel bound the full-length 37-kDa laminin receptor precursor in yeast two-hybrid, validated by immunoprecipitation and immunoblotting in transfected cells and in vivo tissue [PMID:15246873]. Effect on signalling is not reported in our evidence.","molecular_requirements":"LRP residues 100-220 retained Dpl binding, but deleting the N-terminal domain of full-length LRP abolished it [PMID:15246873].","affinity_potency":[],"species_and_systems":"Human per curator; yeast two-hybrid, transfected cell lines and tissue [PMID:15246873].","localisation_and_range":"PRND is flagged non-secreted [flag]; range is not reported in our evidence.","caveats":"Abstract-only, a single paper. RPSA is a precursor binding partner of prion protein too, bound through different domains [PMID:15246873]. No affinity reported. Whether RPSA acts as a signalling receptor for Dpl is not shown.","key_references":[{"PMID":"15246873","why":"Dpl binds 37-kDa laminin receptor precursor by Y2H and IP"}],"covers":["LR001255","LR004656"]},"LR006357":{"pair":"PRRT1 -> GRIA1","headline":"Structural evidence that PRRT1 (SynDIG4) sits beside GluA1 in native AMPA receptors; an auxiliary-subunit relation, not a classic ligand.","interaction_type":"direct binding","direction_and_effect":"Cryo-EM of native AMPA receptors resolved SynDIG4 density whose helix H2 contacts the pre-M1 and M4 helices of GluA1; it did not visibly alter the ligand-binding domain-transmembrane domain, CNIH or M4 conformation [PMID:42284406].","molecular_requirements":"SynDIG4 occupies a peripheral site in a complex that also contains TARPs and CNIHs; GluA1 is one subunit [PMID:42284406]. Whether GluA1 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Native AMPA receptors purified for cryo-EM, species not stated in our evidence [PMID:42284406]; human pair is ortholog-inferred, mouse pair is not.","localisation_and_range":"Both partners are membrane proteins; PRRT1 is not flagged secreted [flag], so contact within the membrane complex.","caveats":"Single 2026 paper read from full text. Functional consequences are not established by the authors, and the paper notes SynDIG4 may be partly lost in purification [PMID:42284406]. This is an auxiliary-subunit interaction rather than a signalling ligand; two other rows were about a different entity.","key_references":[{"PMID":"42284406","why":"Native AMPA receptor cryo-EM showing SynDIG4 contacting GluA1."}],"covers":["LR003136","LR006357"]},"LR004665":{"pair":"PSAP -> LRP1","headline":"LRP1 takes up the saposin precursor for lysosomal delivery; endocytic receptor evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"LRP1 mediates cellular uptake of the saposin precursor and its lysosomal delivery, alongside the mannose-6-phosphate receptor route from the secretory pathway [PMID:9707421]. The curator labelled the assay direct_binding, but the quoted sentence describes uptake.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human fibroblast uptake assays [PMID:9707421]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"PSAP flagged secreted [flag]; LRP1 takes up secreted precursor from outside the cell [PMID:9707421].","caveats":"One abstract-only paper; an endocytic or sorting receptor, not a signalling receptor. No affinity reported. The dossier lists a second confirmed row but shows only one paper.","key_references":[{"PMID":"9707421","why":"LRP1-mediated uptake and lysosomal delivery of saposin precursor."}],"covers":["LR001265","LR004665"]},"LR004674":{"pair":"PTH -> PTH2R","headline":"PTH activates PTH2R, which PTHrP does not; supported by two abstract-level papers and databases.","interaction_type":"functional only","direction_and_effect":"PTH is an agonist at the PTH2 receptor and PTHrP does not activate it [PMID:7797535][PMID:9482662].","molecular_requirements":"The amino terminus and third extracellular domain of the receptor determine selectivity [PMID:9482662].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator; chimeric receptor studies [PMID:9482662].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Both papers abstract only; no affinity values in our evidence. Two further rows pending.","key_references":[{"PMID":"7797535","why":"Identification of PTH2 receptor activated by PTH not PTHrP."},{"PMID":"9482662","why":"Chimeras define structural basis of PTH2R selectivity."}],"covers":["LR001274","LR004674"]},"LR006366":{"pair":"PTN -> ITGAM","headline":"PTN directly binds the alphaM I domain of Mac-1 (ITGAM/ITGB2) in vitro and drives Mac-1-dependent adhesion and migration.","interaction_type":"direct binding","direction_and_effect":"PTN engages Mac-1 as a receptor for macrophage adhesion and migration: Mac-1 expression on HEK293 cells induced PTN-directed adhesion and migration, with Mac-1-dependent spreading and Erk1/2 phosphorylation [PMID:28939773].","molecular_requirements":"Biolayer interferometry and NMR show direct interaction between the alphaMI domain and PTN; Mac-1 cooperates with cell-surface proteoglycans because both anti-Mac-1 mAb and heparin were required to block adhesion [PMID:28939773]. Recombinant fragments reveal two Mac-1-binding sites, one per PTN domain [PMID:28939773]. ITGB2 (partner chain) is a separate pair in the project.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; HEK293 cells plus recombinant proteins [PMID:28939773]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. Integrin binding is cell-surface and proteoglycan-assisted.","caveats":"Abstract only; no affinity reported. ITGAM chain alone is the contact site (alphaMI domain), but the functional receptor is the alphaMbeta2 heterodimer. PDB and IntAct records exist [DB:PDB 8VOH] [DB:IntAct].","key_references":[{"PMID":"28939773","why":"PTN as Mac-1 ligand: adhesion, alphaMI binding by BLI/NMR"}],"covers":["LR003145","LR006366"]},"LR006375":{"pair":"PTN -> SDC2","headline":"Co-IP and rescue data in human spermatogonial stem cells support PTN acting on SDC2; binding evidence is indirect.","interaction_type":"functional only","direction_and_effect":"In human testis, PTN from Leydig cells signals to SDC2 on spermatogonial stem cells; SDC2 knockdown impaired proliferation and PLZF and GFRA1 expression, and exogenous PTN rescued proliferation and GFRA1 in knockdown lines [PMID:39285301]. Curator annotation: agonist.","molecular_requirements":"Downstream GFRA1 and HIF-1 signalling reported; subunit or co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human testicular tissue and human SSC lines [PMID:39285301].","localisation_and_range":"PTN is flagged secreted [flag]; Leydig-to-SSC paracrine signalling [PMID:39285301]. SDC2 is flagged transmembrane, not secreted [flag].","caveats":"Abstract-level curation plus excerpts. The interaction was shown by immunofluorescence, STRING prediction and co-immunoprecipitation, not purified binding; co-localisation occurred only in approximately 50% of cells [PMID:39285301]. The paper lists SDC2 among five reported PTN receptors but the PTN-SDC2 binding there relies on those assays [PMID:39285301]. Rescue by PTN does not separate SDC2-dependent from SDC2-independent effects.","key_references":[{"PMID":"39285301","why":"PTN-SDC2 in human spermatogonial stem cells"}],"covers":["LR003154","LR006375"]},"LR001947":{"pair":"PTPRC -> CD22","headline":"Real but very low-affinity, glycan-mediated binding of CD22 to CD45 sialic acid; not a protein-specific signalling pair.","interaction_type":"direct binding","direction_and_effect":"CD22 binds alpha2-6-linked sialic acid on N-glycans of CD45; soluble CD22-Ig engagement of CD45 modulated early T-cell antigen receptor signals [PMID:7537381]. Sialylating CD22 abrogated its interactions with ligands [PMID:7537381].","molecular_requirements":"Binding requires alpha2-6-linked sialic acid; CD22 bound sialylated CD4 and a synthetic sialoglycoconjugate with similar affinity, so CD45 preference reflects multiple glycan copies [PMID:12115612].","affinity_potency":[{"value":"Kd 130 microM","assay":"surface plasmon resonance, 25 degrees C","system":"CD22 binding native CD45","cite":"PMID:12115612"}],"species_and_systems":"Human experiments [PMID:12115612, PMID:7537381] per curator fields; mouse pair is a separate record.","localisation_and_range":"CD45 and CD22 are both flagged transmembrane [flag]; membrane-bound, contact-dependent.","caveats":"Fast kinetics (koff >=18 s-1) indicate transient contact [PMID:12115612]. Databases list CD22-PTPRC co-IP/capture records [DB:BioGRID, DB:IntAct]. Both papers read as abstracts.","key_references":[{"PMID":"12115612","why":"SPR Kd of CD22 for CD45"},{"PMID":"7537381","why":"soluble CD22 modulates T-cell signalling via CD45"}],"covers":["LR001947","LR005283"]},"LR006384":{"pair":"PTPRF -> LRRC4B","headline":"LAR (PTPRF) binds NGL-3 (LRRC4B) through defined domains; well supported, human data from an abstract plus Reactome.","interaction_type":"direct binding","direction_and_effect":"The NGL-3 leucine-rich repeat domain interacts with the first two FNIII domains of LAR to induce bidirectional synapse formation [PMID:20139422]; curated direction agonist. In a mouse cell-aggregation assay NGL-3 cells showed strong adhesion to LAR cells, used as a positive control [PMID:23345436].","molecular_requirements":"LAR binds via its first two FNIII domains; NGL-3 uses its LRR domain, and Gln-96 in the first LRR is critical for LAR binding and presynaptic differentiation [PMID:20139422]. Reactome lists a complex of LRRC4B with PTPRF, PTPRS and PTPRD [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curated as human proteins for the binding paper (abstract only) [PMID:20139422]; mouse L cells in the second paper [PMID:23345436]. Both pairs listed are ortholog-inferred.","localisation_and_range":"Both flagged transmembrane [flag]; paper describes trans-synaptic adhesion, i.e. contact-dependent [PMID:20139422].","caveats":"Binding paper read only as abstract; the curated row is the reciprocal of an NGL-3 -> LAR row. Second paper's aggregation quote is flagged unverifiable pending spot-check. No affinity in our evidence.","key_references":[{"PMID":"20139422","why":"NGL-3 LRR domain binds LAR FNIII 1-2"},{"PMID":"23345436","why":"NGL-3 cells adhere to LAR cells (positive control)"}],"covers":["LR003163","LR006384"]},"LR005286":{"pair":"PTPRM -> PTPRM","headline":"PTPRM binds itself (homophilic) in recombinant, bead and cell-surface assays; one primary paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"PTPmu mediates aggregation via a homophilic mechanism: PTPmu-coated beads bound endogenous PTPmu on MvLu cells and a GST fusion of the PTPmu extracellular segment, suggesting the ligand is another PTPmu molecule on an adjacent cell [PMID:8394372].","molecular_requirements":"Expression with or without the PTPase domains induced aggregation, but a chimera with the EGF receptor extracellular segment, or the soluble intracellular segment, did not, so the extracellular segment is required [PMID:8394372].","affinity_potency":[],"species_and_systems":"Human PTPmu expressed in Sf9 insect cells by baculovirus; MvLu cells for native PTPmu [PMID:8394372]. The mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound, contact-dependent trans-homophilic binding [PMID:8394372].","caveats":"Self-pair (one protein is both ligand and receptor). Paper read as abstract in the judged row; no affinity reported. IntAct co-IP and dimerization assay records exist [DB:IntAct].","key_references":[{"PMID":"8394372","why":"Homophilic PTPmu binding mediates cell aggregation"}],"covers":["LR001950","LR005286"]},"LR006393":{"pair":"PTPRS -> SLITRK3","headline":"Mouse cell-aggregation evidence that PTP-sigma and SLITRK3 adhere; single paper.","interaction_type":"functional only","direction_and_effect":"Slitrk3-expressing cells aggregated with PTP-sigma-expressing cells; the paper concludes PTP-sigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Slitrks require distinct LAR-RPTP family members for synapse formation, in an isoform-dependent manner [PMID:23345436]. Subunit needs beyond that are not reported.","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells; the abstract also uses rat brain [PMID:23345436]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Cell-cell aggregation implies contact-dependent action; PTPRS is flagged secreted [flag] [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check.","key_references":[{"PMID":"23345436","why":"Slitrk-PTP-sigma cell aggregation and synapse-formation requirement"}],"covers":["LR003172","LR006393"]},"LR004683":{"pair":"PYY -> NPY5R","headline":"PYY activates human NPY5R in a beta-arrestin assay, with a database agonist record; no direct binding evidence in our dossier.","interaction_type":"functional only","direction_and_effect":"PYY stimulated beta-arrestin 2 association with the Y5 receptor (t1/2 4.6 min; maximal response about 60% of Y1) [PMID:12665544]. GtoPdb lists PYY as a full agonist of NPY5R [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; beta-arrestin 2 recruitment was the readout [PMID:12665544].","affinity_potency":[],"species_and_systems":"BRET2 assay with GFP2-beta-arrestin 2 in the paper, human receptors [PMID:12665544]. Human and mouse pairs are projected from evidence (ortholog inferred).","localisation_and_range":"PYY is flagged secreted [flag].","caveats":"Readout is receptor-arrestin association, not ligand binding, and the paper was read as abstract. GtoPdb gives pKi as unit without a value in our evidence [DB:GtoPdb]. Another paper was review only and one pending.","key_references":[{"PMID":"12665544","why":"PYY-induced beta-arrestin 2 association with Y5"}],"covers":["LR001283","LR004683"]},"LR001956":{"pair":"RAET1L -> KLRK1","headline":"ULBP6/RAET1L binds recombinant human NKG2D and stimulates NK killing; one abstract-only paper plus IntAct and PDB records.","interaction_type":"direct binding","direction_and_effect":"ULBP6 bound recombinant NKG2D, and its expression on target cells significantly increased NK-cell killing; curators label it an agonist [PMID:19658097].","molecular_requirements":"Not reported in our evidence beyond NKG2D; the PDB entry 4S0U contains a chain of Q5VY80 and a chain of P26718 [DB:PDB 4S0U].","affinity_potency":[],"species_and_systems":"Human proteins; target cells and recombinant NKG2D binding; expression was seen in HPV-positive cervical carcinoma lines and inducible by human CMV [PMID:19658097]. IntAct lists FACS and X-ray crystallography records [DB:IntAct].","localisation_and_range":"Flagged transmembrane, not secreted, so likely contact-dependent [flag].","caveats":"Single paper read as abstract only; no affinity reported. Binding to recombinant NKG2D differed from ULBP4 and ULBP5 and correlated with NK activation [PMID:19658097]. UL16 retains ULBP6 intracellularly, reducing surface expression [PMID:19658097].","key_references":[{"PMID":"19658097","why":"ULBP6/RAET1L binds NKG2D and increases NK killing"}],"covers":["LR001956"]},"LR004692":{"pair":"RELN -> VLDLR","headline":"Reelin binds VLDLR directly with a reported sub-nM to low-nM affinity and signals via Dab1; multiple primary papers.","interaction_type":"direct binding","direction_and_effect":"Reelin binds VLDLR and ApoER2 directly, calcium-dependently, and is internalised after VLDLR binding [PMID:10571240]. In a full-text paper, Reelin bound the VLDLR ectodomain, RAP and EDTA blocked binding, and blocking reduced Dab1 phosphorylation (agonist) [PMID:10571241]. Reactome has a VLDLR-RELN binding reaction [DB:Reactome R-HSA-8854466].","molecular_requirements":"Binding was to the receptor ectodomain; neither receptor bound the isolated N-terminal Reelin domain, so other parts of Reelin are needed [PMID:10571241]. ApoER2 is also a Reelin receptor [PMID:10571241].","affinity_potency":[{"value":"Kd ~500 pM","assay":"co-IP/pull-down with VLDLR ectodomain-Fc","system":"human VLDLR ectodomain","cite":"PMID:10571241"},{"value":"KD 1.2 nM","assay":"surface plasmon resonance","system":"human proteins","cite":"PMID:12899622"}],"species_and_systems":"Human VLDLR ectodomain with Reelin from culture supernatant [PMID:10571241]; mouse/human ligand with human receptor [PMID:10571240]; SPR, human [PMID:12899622].","localisation_and_range":"RELN is flagged secreted [flag]. VLDLR is flagged transmembrane [flag].","caveats":"Two of the three papers were read as abstracts. ApoER2 has about 6-fold higher affinity than VLDLR (0.2 vs 1.2 nM) [PMID:12899622]. Two further papers were abstract_insufficient and one is pending (outcome counts).","key_references":[{"PMID":"10571241","why":"Full-text direct binding to VLDLR ectodomain, Kd ~500 pM"},{"PMID":"12899622","why":"SPR KD 1.2 nM for VLDLR"},{"PMID":"10571240","why":"Direct binding to lipoprotein receptors"}],"covers":["LR001293","LR004692"]},"LR001299":{"pair":"RLN2 -> RXFP2","headline":"Relaxin-2 activates RXFP2, but more weakly than INSL3 and in a species-dependent way; binding and activation both reported.","interaction_type":"direct binding","direction_and_effect":"H2 relaxin activates RXFP2 as an agonist [PMID:28607406]; GtoPdb lists a full agonist [DB:GtoPdb]. Relaxin activation of RXFP2 uses an RXFP1-like mechanism: linker binding, LDLa reorientation, and transmembrane activation by LDLa alone [PMID:28607406].","molecular_requirements":"The RXFP2 LDLa module and the linker's conserved N-terminal region are needed for activation by relaxin; the linker is needed for relaxin binding but not INSL3 binding [PMID:28607406]. Wild-type RXFP2 bound relaxin with lower affinity than INSL3 [PMID:28607406].","affinity_potency":[{"value":"pKi 8.300000190734863 to 8.479999542236328","assay":"GtoPdb affinity range (pKi)","system":"not reported in our evidence","cite":"DB:GtoPdb"},{"value":"Kd of around 330 \u00b5M","assay":"NMR chemical shift titration of RXFP2(1-65) LDLa-linker with truncated relaxin","system":"isolated domain construct, not full receptor","cite":"PMID:28607406"}],"species_and_systems":"Human ligand and receptor. Mutant receptors were tested in HEK293T cells [PMID:28607406]. Other papers were read as abstracts only.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"Binding of relaxin to RXFP2 is explicitly described as species-specific, and not all relaxin peptides bind RXFP2 [PMID:15649866]. INSL3 is described as the cognate ligand [PMID:28607406]. PMID:12506116 states the pairing only as background; its own data concern H3 relaxin.","key_references":[{"PMID":"28607406","why":"Full-text study of RXFP2 activation by relaxin versus INSL3"},{"PMID":"15649866","why":"Species-specific relaxin-RXFP2 binding in a two-site model"},{"PMID":"11809971","why":"LGR8 (RXFP2) mediates relaxin action via cAMP"}],"covers":["LR001299"]},"LR003189":{"pair":"RLN3 -> GPR135","headline":"Relaxin-3 binds and activates the receptor named GPCR135 with sub-nanomolar affinity in one abstract-level study.","interaction_type":"direct binding","direction_and_effect":"Recombinant human relaxin-3 stimulates GTPgammaS binding and inhibits cAMP accumulation in GPCR135-overexpressing cells, i.e. agonism [PMID:14522968]. Relaxin-3 is reported as the only insulin/relaxin superfamily member that activates it [PMID:14522968].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[{"value":"Kd 0.31 nM","assay":"125I-relaxin-3 radioligand binding","system":"GPCR135-expressing cells","cite":"PMID:14522968"},{"value":"EC50 0.25 nM","assay":"GTPgammaS binding","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"EC50 0.35 nM","assay":"cAMP accumulation inhibition","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"}],"species_and_systems":"Recombinant human relaxin-3 in cell lines; ligand first isolated from porcine brain extracts, with rat brain extracts also active [PMID:14522968]. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand flagged as secreted [flag]; receptor annotated only as a receptor, with no membrane flag given. Brain expression of both is described in situ [PMID:14522968].","caveats":"Single paper, read as abstract only. The mouse pair is inferred, not tested.","key_references":[{"PMID":"14522968","why":"Deorphanisation of GPCR135 by relaxin-3 with binding and functional data"}],"covers":["LR003189","LR006409"]},"LR012387":{"pair":"RNF43 -> FZD7:LRP6","headline":"RNF43 -> FZD7:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 2, different_entity 1). Some judged rows were a different entity.","key_references":[],"covers":["LR012387"]},"LR007392":{"pair":"RSPO1 -> KREMEN1:LRP6","headline":"RSPO1 with the KREMEN1:LRP6 complex rests on one abstract-only functional paper and UniProt.","interaction_type":"functional only","direction_and_effect":"RSpo1 interferes with DKK1/Kremen-mediated LRP6 internalization via an interaction with Kremen, increasing LRP6 on the cell surface [PMID:17804805]. UniProt says it antagonizes DKK1/KREM1-mediated LRP6 internalization [DB:UniProt].","molecular_requirements":"The paper names an interaction with Kremen; RSpo1 does not directly activate LRP6 [PMID:17804805]. Whether it binds the KREMEN1:LRP6 complex as a unit is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not stated in this row [PMID:17804805].","localisation_and_range":"RSPO1 secreted per flag; complex flagged transmembrane [flag].","caveats":"Abstract only. The binding partner shown is Kremen, not the LRP6-containing complex; LRP6 is a regulated target, not shown as a binder.","key_references":[{"PMID":"17804805","why":"RSpo1-Kremen mechanism on LRP6 internalization"}],"covers":["LR007392"]},"LR003198":{"pair":"RTN3 -> RTN4R","headline":"RTN3 binds NgR1 (RTN4R) with nanomolar affinity in a single biophysical mapping paper, read as abstract only.","interaction_type":"direct binding","direction_and_effect":"The paper reports novel nanomolar interactions of RTN2 and RTN3 with NgR1; effect on signalling is not reported in our evidence [PMID:17189258].","molecular_requirements":"Not reported for this pair; the abstract describes NgR1 mapping to the concave face of its leucine-rich-repeat domain [PMID:17189258].","affinity_potency":[],"species_and_systems":"Recombinant biophysical mapping across reticulon and NgR families; curators record human ligand and receptor. The human pair is ortholog-inferred [PMID:17189258].","localisation_and_range":"RTN4R is flagged transmembrane [flag]; RTN3 is a reticulon, typically intracellular, and its extracellular availability is not reported in our evidence.","caveats":"The exact affinity value is not in the abstract. The curator assay_class is direct_binding but the paper is abstract-only. Effect direction \"agonist\" is not stated in the abstract. No database records.","key_references":[{"PMID":"17189258","why":"Systematic mapping of reticulon-NgR interactions; RTN2/RTN3 bind NgR1"}],"covers":["LR003198","LR006418"]},"LR006438":{"pair":"S100A4 -> ERBB4","headline":"S100A4 binds ErbB4 (Kd 66.0 nM) and its neuroprotection depends on ErbB4; best-supported of the S100A4-ErbB pairs.","interaction_type":"direct binding","direction_and_effect":"S100A4-induced neuroprotection depends on ErbB4 expression and ErbB2/Akt, and is reduced by anti-ErbB4 antibody or functional NRG/ErbB4 blockade [PMID:30083275].","molecular_requirements":"ErbB2 is needed as a signalling partner though it does not bind S100A4; neuregulin involvement was seen for long-term but not 2 h exposure [PMID:30083275].","affinity_potency":[{"value":"Kd 66.0 \u00b1 26.9 nM","assay":"surface plasmon resonance, S100A4 on immobilized ErbB4","system":"recombinant proteins","cite":"PMID:30083275"}],"species_and_systems":"Cultured hippocampal neurons and dopaminergic neuron models [PMID:30083275]. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"S100A4 is flagged secreted and ERBB4 transmembrane [flag].","caveats":"Species of cells not stated in excerpts. Abstract-level curation. Role of neuregulin is time-dependent.","key_references":[{"PMID":"30083275","why":"ErbB4-dependent S100A4 neuroprotection"}],"covers":["LR003220","LR006438"]},"LR006447":{"pair":"S100A8 -> NPTN","headline":"Neuroplastin-beta identified as an S100A8 receptor in keratinocytes (abstract-only).","interaction_type":"functional only","direction_and_effect":"Neuroplastin-beta is identified as an unreported S100A8 receptor; on S100A8 stimulation it recruited GRB2 and activated ERK, driving keratinocyte proliferation [PMID:27388991]. Agonist.","molecular_requirements":"Neuroplastin-beta forms homodimers and a heterodimer with EMMPRIN; the authors propose the heterodimer as a functional receptor for the S100A8/A9 heterodimer [PMID:27388991]. Knockdown of both receptors suppressed proliferation and cytokine induction [PMID:27388991].","affinity_potency":[],"species_and_systems":"Cultured normal human keratinocytes; S100A8-transgenic mice and atopic dermatitis skin were also examined [PMID:27388991]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. Neuroplastin-beta and EMMPRIN are co-localized on the keratinocyte surface [PMID:27388991].","caveats":"Abstract only; curator row says direct_binding but the abstract does not describe a binding measurement. No affinity reported. Not clear that NPTN acts alone without EMMPRIN.","key_references":[{"PMID":"27388991","why":"Identifies neuroplastin-beta as S100A8 receptor, with EMMPRIN heterodimer"}],"covers":["LR003230","LR006447"]},"LR006456":{"pair":"S100A9 -> MCAM","headline":"MCAM reported as an S100A8/A9 receptor in melanoma cells; abstract-only functional evidence.","interaction_type":"functional only","direction_and_effect":"MCAM and ALCAM function as S100A8/A9 receptors as RAGE does, inducing NF-kappaB activation and ROS formation in melanoma; MCAM activated NF-kappaB more prominently than ALCAM and RAGE [PMID:27151304].","molecular_requirements":"The ligand is the S100A8/A9 complex; S100A9 alone is not separated [PMID:27151304].","affinity_potency":[],"species_and_systems":"Human melanoma cells per the abstract; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted [flag]; MCAM flagged as receptor but not transmembrane [flag].","caveats":"Abstract only; no binding data; no database support.","key_references":[{"PMID":"27151304","why":"MCAM as S100A8/A9 receptor in melanoma"}],"covers":["LR003240","LR006456"]},"LR004728":{"pair":"SAA1 -> SCARB1","headline":"SAA binds SCARB1 (SR-BI/CLA-1) with high affinity, but also inhibits SR-BI function; supported by two binding studies.","interaction_type":"direct binding","direction_and_effect":"125I-SAA, lipid-free or in reconstituted HDL, acted as a high-affinity ligand for SR-BI in CHO cells and bound HepG2 cells; SAA was internalized in an SR-BI-dependent manner [PMID:15561721]. Lipid-free SAA inhibited SR-BI-dependent HDL binding and selective cholesteryl ester uptake, and SAA on HDL decreased selective uptake by 30-50% [PMID:15561721]. In HeLa cells with CLA-1, SAA uptake rose more than 5-fold and SAA bound CLA-1 by cross-linking [PMID:15576377].","molecular_requirements":"Not reported in our evidence; both lipid-free and HDL-bound SAA bind [PMID:15561721].","affinity_potency":[],"species_and_systems":"Human SAA and receptor in CHO, HepG2 and HeLa cells; HDL from SAA-overexpressing mice was also used [PMID:15561721][PMID:15576377]. The mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, membrane receptor; paracrine/endocrine uptake [flag].","caveats":"Both papers were read as abstracts only. High affinity is stated without a number in the dossier. The effect is mixed: uptake ligand plus inhibitor of HDL uptake. A third confirmed paper is not shown.","key_references":[{"PMID":"15561721","why":"125I-SAA binding to SR-BI and inhibition of HDL uptake"},{"PMID":"15576377","why":"CLA-1 mediates SAA uptake; cross-linking shows direct binding"}],"covers":["LR001332","LR004728"]},"LR006465":{"pair":"SCRG1 -> CD36","headline":"SCRG1 binds CD36 on the cell surface in a CRISPRa screen with flow-cytometry validation; one paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"SCRG1 was a top-scoring CD36 hit in the CRISPRa screen, and tetramerised SCRG1 (400 nM) stained CD36-transfected cells by flow cytometry [PMID:36178190]. Functional effect on CD36 is not reported in our evidence.","molecular_requirements":"Full-length CD36 was expressed; no co-receptor requirement is reported in our evidence [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human proteins; CD36-transfected 293F cells versus control cells, with SPRC tetramers as a negative control [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"SCRG1 is flagged secreted and CD36 transmembrane [flag]; the assay used soluble multimerised ligand on cell-surface receptor [PMID:36178190].","caveats":"Single paper, tetramer cell staining only (no SPR or affinity). The paper notes SCRG1 is only to some extent related in sequence to the other CD36 ligands, and the CD36-enriched ligands cluster in brain where CD36 mRNA is low [PMID:36178190]. CD36 is described as multifunctional and binding several secreted ligands, so specificity is a question.","key_references":[{"PMID":"36178190","why":"CRISPRa screen and flow-cytometry binding of SCRG1 to CD36"}],"covers":["LR003249","LR006465"]},"LR005295":{"pair":"SDC2 -> PTPRJ","headline":"The syndecan-2 ectodomain is reported as a ligand of CD148 (PTPRJ), driving beta1-integrin adhesion; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"The syndecan-2 extracellular domain (S2ED) is described as a novel ligand for CD148; CD148 siRNA reduced fibroblast adhesion to S2ED and CD148 transduces the signal to beta1-integrin adhesion via Src kinase [PMID:21813734].","molecular_requirements":"The region proximal to the transmembrane domain of syndecan-2 is the interaction site with CD148 [PMID:21813734]; the extracellular domain acts as the ligand.","affinity_potency":[],"species_and_systems":"Human WI38 lung fibroblasts, Jurkat and U937 cells; rat embryo fibroblasts in inhibitor experiments; siRNA and adhesion assays [PMID:21813734]. Pair is ortholog-inferred for human and mouse.","localisation_and_range":"SDC2 is flagged transmembrane and not secreted [flag]; the paper uses a soluble ectodomain, which implies shed or matrix-coated presentation, but this is not stated.","caveats":"Read as abstract plus excerpts; excerpts show adhesion and knockdown, and the direct binding evidence is not detailed in our excerpts. No affinity.","key_references":[{"PMID":"21813734","why":"S2ED as a CD148 ligand with siRNA and mapping of the interaction site"}],"covers":["LR001963","LR005295"]},"LR001965":{"pair":"SELE -> CD44","headline":"E-selectin binds native CD44 glycoforms in vitro, with slow kinetics for dimeric E-selectin; one abstract-only paper plus databases.","interaction_type":"direct binding","direction_and_effect":"CD44 captured from hematopoietic cell extracts binds recombinant monomeric E-selectin transiently with fast on- and off-rates, and dimeric E-selectin with remarkably slow on- and off-rates [PMID:26124272]. Reactome lists E-selectin binding an E-selectin ligand [DB:Reactome].","molecular_requirements":"Binding requires sialyl Lewis x on both O- and N-glycans; association is salt sensitive [PMID:26124272]. Oligomeric state of E-selectin changes kinetics.","affinity_potency":[],"species_and_systems":"Native human CD44 from hematopoietic cell extracts on an SPR chip with recombinant E-selectin [PMID:26124272]. IntAct lists co-IP and solid-phase assays [DB:IntAct].","localisation_and_range":"SELE is flagged transmembrane and not secreted [flag], consistent with contact-dependent leukocyte tethering [PMID:26124272].","caveats":"Read as abstract only; no numeric affinity in our evidence. CD44 acts here as a glycoprotein carrying sialyl Lewis x, so binding is glycan dependent; role as a signalling receptor is not reported.","key_references":[{"PMID":"26124272","why":"SPR kinetics of E-selectin binding to native CD44"}],"covers":["LR001965","LR005297"]},"LR006474":{"pair":"SELENOP -> LRP6","headline":"SELENOP co-immunoprecipitates with LRP6 and amplifies WNT signalling; single full-text paper, best evidence of the LRP5/6 pair.","interaction_type":"direct binding","direction_and_effect":"SELENOP co-immunoprecipitated with FLAG-LRP6 in 293T cells and decreased cell-surface LRP6, interpreted as promoting LRP6 internalization and amplifying WNT signalling [PMID:37166989].","molecular_requirements":"Truncation before the fourth selenocysteine and deletion of U258-U299 uncoupled the interaction [PMID:37166989]. Heparin prevented the SELENOP-LRP6 co-IP while sodium chlorate (HSPG synthesis inhibition) enhanced it, so HSPGs may sequester SELENOP [PMID:37166989].","affinity_potency":[],"species_and_systems":"Endogenous FLAG-tagged LRP6 in human 293T cells, plus mouse constructs for proximity ligation and mapping; mouse Apc-deletion model for phenotype [PMID:37166989].","localisation_and_range":"SELENOP is annotated secreted [flag]; the authors speculate LRP6 may mediate SELENOP uptake in gut [PMID:37166989].","caveats":"Co-IP and proximity ligation only, no affinity. The paper's own discussion says the gut SELENOP receptor remains unidentified [PMID:37166989]. No database records.","key_references":[{"PMID":"37166989","why":"co-IP and mapping of SELENOP-LRP6 interaction"}],"covers":["LR003258","LR006474"]},"LR004737":{"pair":"SEMA3A -> NRP2","headline":"One mouse genetic paper (abstract only) reports SEMA3A signalling redundantly through NRP1 and, unconventionally, NRP2.","interaction_type":"functional only","direction_and_effect":"SEMA3A signals redundantly through NRP1 and unconventionally NRP2 in GnRH neuron system development; mice lacking signalling through both NRP1 and NRP2 recapitulate the anatomical features of a Kallmann-syndrome case. Effect is agonist [PMID:21059704].","molecular_requirements":"NRP2 is described as an unconventional receptor for SEMA3A; its usual ligand SEMA3F is dispensable here [PMID:21059704]. Co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse genetics and in vitro models [PMID:21059704]. The human pair is projected from the mouse interaction (ortholog-inferred flag) [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"Single paper, abstract only; genetic redundancy with NRP1 means NRP2 contribution is inferred, and no direct binding or affinity is reported in our evidence.","key_references":[{"PMID":"21059704","why":"SEMA3A signals through NRP1 and NRP2 in GnRH neuron migration"}],"covers":["LR001341","LR004737"]},"LR006483":{"pair":"SEMA3C -> PLXNB1","headline":"SEMA3C:Fc binds Plexin B1 in a proximity ligation assay in DU145 cells, with full-text support.","interaction_type":"direct binding","direction_and_effect":"SEMA3C drives activation of EGFR, ErbB2 and MET via Plexin B1 and promotes prostate cancer cell growth [PMID:29348142]. Plexin B1 sema-domain Fc fusion proteins suppressed RTK signaling and cell growth, acting as a decoy [PMID:29348142].","molecular_requirements":"Binding was seen with Plexin B1 and tested alongside NRP1 in the same assay; whether NRP1 is needed is not reported in our evidence [PMID:29348142].","affinity_potency":[],"species_and_systems":"Human recombinant SEMA3C:Fc in human DU145 cells; xenografts of LNCaP in vivo for the decoy [PMID:29348142]. Mouse pair is ortholog-inferred.","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. PLXNB1 is annotated transmembrane [flag].","caveats":"Binding evidence is proximity ligation (close proximity in cells), not purified-protein binding; no affinity reported [PMID:29348142].","key_references":[{"PMID":"29348142","why":"PLA binding of SEMA3C:Fc to Plexin B1 and RTK transactivation"}],"covers":["LR003267","LR006483"]},"LR004746":{"pair":"SEMA3C -> PLXND1","headline":"SEMA3C signals through PlexinD1 (with NRP1) to inhibit pathological retinal angiogenesis; one paper read from abstract.","interaction_type":"functional only","direction_and_effect":"Sema3C signaled through the receptors Neuropilin-1 and PlexinD1, inhibited angiogenesis and abrogated VEGF-induced AKT, FAK and p38MAPK activation [PMID:26194913].","molecular_requirements":"PlexinD1 is reported together with Neuropilin-1; whether PlexinD1 alone suffices is not reported in our evidence. Full-text excerpts show the furin-cleaved Sema3Cp60 isoform lacked effect [PMID:26194913].","affinity_potency":[],"species_and_systems":"Mouse neonatal retina and oxygen-induced retinopathy model, HUVEC assays and xenografts in mice [PMID:26194913]. Human and mouse pairs are both listed; the mouse record is not ortholog-inferred.","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. PLXND1 is annotated transmembrane [flag].","caveats":"Receptor naming is from the abstract; no binding data in our evidence. Other judged rows (abstract_insufficient, review_only) are not shown.","key_references":[{"PMID":"26194913","why":"Sema3C signals via NRP1 and PlexinD1 in retinal angiogenesis"}],"covers":["LR001350","LR004746"]},"LR006492":{"pair":"SEMA4A -> NRP1","headline":"Sema4a-Nrp1 interaction reported in Treg cells in one abstract-level paper; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Sema4a on immune cells and Nrp1 on Treg cells interact in vitro, potentiating Treg function and survival, and in vivo at inflammatory sites [PMID:23913274]. Ligation restrains Akt phosphorylation via PTEN [PMID:23913274].","molecular_requirements":"Nrp1 on Tregs; Sema4a-Ig beads were sufficient to potentiate suppression [PMID:23913274]. Plexin involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"The experiments are in mouse Treg cells (Treg-restricted Nrp1 deletion), though the curator tagged human [PMID:23913274]. Human pair is ortholog-inferred.","localisation_and_range":"Sema4a is expressed on Tconv cells and DCs and contacts Tregs, apparently contact-dependent or as Ig fusion [PMID:23913274].","caveats":"Read as abstract with partial excerpts; direct binding assay is not itself shown in the text we have.","key_references":[{"PMID":"23913274","why":"Sema4a-Nrp1 interaction potentiates Treg function"}],"covers":["LR003276","LR006492"]},"LR004755":{"pair":"SEMA4B -> DCBLD2","headline":"SEMA4B-DCBLD2 (CLCP1) rests on one abstract-only paper using phage display and co-immunoprecipitation in a lung cancer line.","interaction_type":"direct binding","direction_and_effect":"A phage clone resembling the SEMA4B Sema domain interacted with LNM35 lung cancer cells, and immunoprecipitation confirmed CLCP1 interaction with SEMA4B; SEMA4B enhanced CLCP1 ubiquitination and proteasomal degradation, so the effect is labelled antagonist [PMID:17213806].","molecular_requirements":"DCBLD2 (CLCP1) alone is reported; no co-receptor in our evidence.","affinity_potency":[],"species_and_systems":"Human lung cancer cell line LNM35; mouse pair is ortholog-inferred [PMID:17213806].","localisation_and_range":"SEMA4B is not flagged secreted [flag]; range not stated in the paper abstract.","caveats":"One paper, abstract only, no affinity. Physiological role was described by the authors as remaining to be investigated [PMID:17213806]. No database support.","key_references":[{"PMID":"17213806","why":"CLCP1-SEMA4B interaction and CLCP1 degradation"}],"covers":["LR001359","LR004755"]},"LR003279":{"pair":"SEMA4D -> PTPRC","headline":"SEMA4D (CD100) is physically associated with CD45 on human T cells; this is an association, not clearly a ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"CD100 is associated with CD45 at the surface of human T lymphocytes, and the association has functional significance in T cell homotypic adhesion [PMID:8955171]. Direction and effect as ligand to receptor are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human T lymphocytes [PMID:8955171]. BioGRID Affinity Capture-Western [DB:BioGRID]; Reactome complex SEMA4D:PTPRC [DB:Reactome]; IntAct co-immunoprecipitation [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTPRC flagged transmembrane, not secreted [flag]; SEMA4D is flagged secreted and transmembrane [flag].","caveats":"One paper, abstract only; co-association evidence does not show that CD45 acts as a signalling receptor for SEMA4D.","key_references":[{"PMID":"8955171","why":"CD100 associates with CD45 on T cells"}],"covers":["LR003279","LR006495"]},"LR004764":{"pair":"SEMA6D -> PLXNA1","headline":"Well supported by three confirmed papers across chick and mouse: Plexin-A1 is a major Sema6D receptor, with co-receptor-dependent effects.","interaction_type":"direct binding","direction_and_effect":"Plexin-A1 is the major Sema6D-binding receptor in chick heart, where VEGFR2 or Off-track as co-receptor gives opposite migration outcomes [PMID:14977921]. PlexinA1 mediates sema6D signalling for proprioceptive axon segregation in mouse [PMID:17145500]. Sema6D with Nr-CAM and Plexin-A1 promotes contralateral RGC projection (agonist) [PMID:22632726].","molecular_requirements":"Co-receptors VEGFR2, Off-track [PMID:14977921], Nr-CAM [PMID:22632726]; Reactome lists a SEMA6D:PLXNA1:TREM2:DAP12 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Chick [PMID:14977921], mouse [PMID:17145500] and optic chiasm cultures [PMID:22632726].","localisation_and_range":"Sema6D is flagged membrane-bound; the optic chiasm paper separates ligand-expressing radial glia from receptor-expressing neurons [flag][PMID:22632726].","caveats":"All three papers abstract only (the last has excerpts); no affinity reported. The sign of effect depends on co-receptor.","key_references":[{"PMID":"14977921","why":"Plexin-A1 major Sema6D receptor; co-receptor-dependent outcome"},{"PMID":"17145500","why":"PlexinA1 receptor for sema6D in mouse axon segregation"},{"PMID":"22632726","why":"Trans Sema6D, Plexin-A1, Nr-CAM at chiasm"}],"covers":["LR001368","LR004764"]},"LR003288":{"pair":"SERPIND1 -> LRP1","headline":"Heparin cofactor II-thrombin complex binds purified LRP1 and is internalised; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Heparin cofactor II-thrombin bound purified LRP, with binding inhibited by RAP; LRP-expressing fibroblasts internalised and degraded the complexes and LRP-deficient fibroblasts did not [PMID:8626456].","molecular_requirements":"The complex, not the free inhibitor, is the ligand: native or modified inhibitor forms were unable to bind [PMID:8626456].","affinity_potency":[],"species_and_systems":"Human proteins as labelled; purified LRP, mouse fibroblasts, HepG2 cells [PMID:8626456]. Mouse pair is ortholog-projected.","localisation_and_range":"SERPIND1 is flagged secreted [flag]; clearance by endocytosis.","caveats":"One paper, abstract only; the rat in vivo clearance data in the abstract concern ATIII-thrombin, not this complex.","key_references":[{"PMID":"8626456","why":"HCII-thrombin binding to LRP and cellular clearance"}],"covers":["LR003288","LR006504"]},"LR008418":{"pair":"SFRP1 -> WNT2","headline":"Support is a computational docking paper plus database records; no experimental binding in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"A docking study found Wnt2 and SFRP1 interact in the same mode as xWnt8-mFz8 and hWnt3-mFz8, used to design antagonist peptides [PMID:33155881]. BioGRID and IntAct list co-IP-type records [DB:BioGRID, DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In silico homology modelling and docking [PMID:33155881]; database records cite PMID:10347172.","localisation_and_range":"SFRP1 is flagged secreted [flag]; ligand-ligand interaction.","caveats":"Computational evidence only; the paper's experiments are on designed peptides; abstract only. One other row was a different entity.","key_references":[{"PMID":"33155881","why":"Docking of SFRP1 and Wnt2 (computational)"}],"covers":["LR008418"]},"LR003297":{"pair":"SFTPA2 -> TLR2","headline":"SP-A binds the recombinant TLR2 extracellular domain; one abstract-level paper plus Reactome, not specific to SFTPA2.","interaction_type":"direct binding","direction_and_effect":"SP-A directly bound recombinant soluble TLR2 and reduced sTLR2 binding to peptidoglycan, attenuating PGN-induced NF-kappaB activity [PMID:11724772]; effect is inhibitory.","molecular_requirements":"Reactome lists a TLR2:TLR1 binding reaction [DB:Reactome]; subunits not tested in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant soluble TLR2, HEK293 transfectants, U937 cells and rat alveolar macrophages [PMID:11724772].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One abstract-only paper that concerns SP-A without distinguishing SFTPA2 from SFTPA1.","key_references":[{"PMID":"11724772","why":"SP-A binds sTLR2 and inhibits PGN signalling"}],"covers":["LR003297"]},"LR001974":{"pair":"SFTPD -> LAIR1","headline":"SP-D binds LAIR-1 through its collagenous domain and inhibits FcalphaR-driven reactive oxygen; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Inhibitory: SP-D induces LAIR-1 cross-linking in a reporter assay and inhibits FcalphaR-mediated reactive oxygen production via LAIR-1 [PMID:24585933].","molecular_requirements":"The collagenous domain mediates binding; this does not affect SP-D mannan-binding [PMID:24585933]. The related LAIR-2 also binds.","affinity_potency":[],"species_and_systems":"Binding assays and cellular reporter assay; human ligand and receptor listed; mouse pair is ortholog-inferred [PMID:24585933].","localisation_and_range":"SP-D is flagged secreted and LAIR1 transmembrane [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"24585933","why":"SP-D collagenous domain binds LAIR-1 and inhibits ROS"}],"covers":["LR001974","LR005304"]},"LR004782":{"pair":"SHH -> GPC5","headline":"SHH binds GPC5 through glycosaminoglycan chains and GPC5 promotes Hh signalling; two curator-verified papers.","interaction_type":"direct binding","direction_and_effect":"GPC5 increases Sonic Hh binding to Ptc1 and stimulates Hh signaling and rhabdomyosarcoma cell proliferation [PMID:21339334]. GPC5-containing HSPG co-receptors promote Shh binding and signaling in cerebellar granule cell precursors [PMID:23867465]. Reactome lists Hh-Np binds GPC5 [DB:Reactome].","molecular_requirements":"GPC5 binds Hh and Ptc1 through its glycosaminoglycan chains [PMID:21339334]. Needs a glypican 5 core protein with 2-O-sulfo-iduronic acid residues [PMID:23867465].","affinity_potency":[],"species_and_systems":"Human rhabdomyosarcoma cells (RH30, CW9019) with GPC5 siRNA or overexpression [PMID:21339334]; cerebellar granule cell precursors [PMID:23867465].","localisation_and_range":"GPC5 is flagged secreted [flag]; the papers describe it near the primary cilium [PMID:23867465] and localised to primary cilia [PMID:21339334]; SHH is secreted [flag].","caveats":"Binding depends on the glycan chains, so it is cell-type and glycosylation dependent. Three more papers were judged abstract-insufficient. No affinity reported.","key_references":[{"PMID":"21339334","why":"GPC5 GAG chains bind Hh and Ptc1"},{"PMID":"23867465","why":"GPC5/2-O-sulfo-iduronic acid HSPG co-receptor for Shh"}],"covers":["LR001387","LR004782"]},"LR001389":{"pair":"SHH -> LRP2","headline":"SHH is bound by LRP2 as an apical binding protein in forebrain; one confirmed abstract, human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"LRP2 acts as an apical SHH-binding protein that sequesters SHH in its target field and controls internalization and trafficking of SHH/patched 1 complexes; overexpression of LRP2 variants increases SHH signaling [PMID:22340494].","molecular_requirements":"LRP2 acts alongside patched 1; Lrp2-deficient mice and cephalic explants fail to respond to SHH despite functional patched 1 and smoothened [PMID:22340494].","affinity_potency":[],"species_and_systems":"Mouse embryos and cephalic explants, plus cells [PMID:22340494]. The curated primary pair is mouse; human is ortholog-inferred.","localisation_and_range":"Apical, membrane-associated at the target field [PMID:22340494]; SHH is flagged secreted [flag].","caveats":"Abstract-only read. Two more papers were review-only. No affinity or direct assay reported in the dossier.","key_references":[{"PMID":"22340494","why":"LRP2 binds and sequesters SHH in forebrain"}],"covers":["LR001389","LR004784"]},"LR006519":{"pair":"Siglecg -> Aoc3","headline":"Mouse pair projected from a human Siglec-10 to VAP-1 study; one abstract-only paper, no mouse data.","interaction_type":"direct binding","direction_and_effect":"Siglec-10 was identified as a leukocyte ligand for VAP-1 by phage display and verified in adhesion assays and molecular modelling; the interaction increased hydrogen peroxide production, so Siglec-10 acts as a VAP-1 substrate [PMID:19861682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Siglec-10 and VAP-1 in adhesion assays; no mouse experiment in our evidence [PMID:19861682].","localisation_and_range":"Ligand is flagged secreted [flag]; the paper describes lymphocyte adhesion to endothelium, a contact interaction [PMID:19861682].","caveats":"Abstract only. The mouse pair is ortholog-inferred, and the paper names Siglec-10, not Siglecg. Signalling direction is unclear because VAP-1 is both adhesin and enzyme.","key_references":[{"PMID":"19861682","why":"Siglec-10 identified as VAP-1 ligand, adhesion assays"}],"covers":["LR006519"]},"LR001983":{"pair":"SLAMF7 -> SLAMF7","headline":"Homophilic SLAMF7 interaction reported in myeloma cells (soluble to surface), plus IntAct and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Soluble SLAMF7 enhanced multiple-myeloma cell growth through homophilic interaction with surface SLAMF7, activating SHP-2 and ERK; elotuzumab suppressed this in vitro and in vivo [PMID:31358854].","molecular_requirements":"Cleaved soluble SLAMF7 acts on surface SLAMF7 [PMID:31358854]. Further subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human myeloma cells and a murine xenograft model [PMID:31358854].","localisation_and_range":"Soluble form shed from the membrane, detected in myeloma-patient serum, so potentially paracrine or endocrine; membrane form acts by contact [PMID:31358854].","caveats":"Abstract only; no affinity. IntAct (FACS, protein array, solid phase) and Reactome dimer records support self-interaction [DB:IntAct] [DB:Reactome]. A second confirmed row is not shown.","key_references":[{"PMID":"31358854","why":"Soluble SLAMF7 homophilic action on myeloma cells"}],"covers":["LR001983","LR005312"]},"LR004791":{"pair":"SLIT2 -> ROBO2","headline":"SLIT2 signals through ROBO2, supported by binding, in vitro and mouse knockout evidence.","interaction_type":"direct binding","direction_and_effect":"Slit2 binds Robo2 [PMID:10102268]. Mouse Slit2 or Robo2 mutants develop supernumerary ureteric buds, with signal transduced in nephrogenic mesenchyme [PMID:15130495]. SLIT2 binding to Gremlin inhibited SLIT2-ROBO2 signalling in neurons [PMID:29317497].","molecular_requirements":"Not reported in our evidence beyond the mixed Slit2 fragments used [PMID:10102268].","affinity_potency":[],"species_and_systems":"Human Slit2 on COS cells expressing rat Robo2 [PMID:10102268]; Slit2 and Robo2 mutant mice [PMID:15130495]; neurons and myoblasts/fibroblasts [PMID:29317497].","localisation_and_range":"SLIT2 secreted, ROBO2 flagged transmembrane [flag]; Reactome lists a ROBO2:SLIT2 plasma-membrane complex [DB:Reactome].","caveats":"Two of three papers are abstract-only. PMID:29317497 states SLIT2-ROBO2 binding as background and tests the Gremlin cross-talk, so it is not direct evidence for the pair. PMID:15130495 shows genetics, not binding.","key_references":[{"PMID":"10102268","why":"direct binding of Slit2 to Robo2"},{"PMID":"15130495","why":"Slit2/Robo2 mutant mice, kidney induction"},{"PMID":"29317497","why":"SLIT2-Gremlin cross-talk inhibits SLIT2-ROBO2"}],"covers":["LR001396","LR004791"]},"LR006528":{"pair":"SLIT3 -> PLXNA1","headline":"Slit3-C fragment is reported as a PlexinA1 receptor ligand in brown fat; one bioRxiv abstract.","interaction_type":"functional only","direction_and_effect":"Plxna1 is reported as a previously unrecognised receptor for Slit3-C and is essential for sympathetic innervation and cold-induced neurite expansion in BAT [PMID:39386533].","molecular_requirements":"Cleavage of Slit3 yields Slit3-N and Slit3-C; Slit3-C acts on Plxna1 while Slit3-N binds a distinct receptor [PMID:39386533]. Bmp1 is the cleaving protease [PMID:39386533].","affinity_potency":[],"species_and_systems":"Mouse brown adipose tissue is implied; species of the experiments is not stated in the abstract [PMID:39386533]. Mouse pair is non-inferred, human ortholog-inferred.","localisation_and_range":"Secreted by adipocyte progenitors [PMID:39386533].","caveats":"Preprint, abstract only; the assay is annotated direct_binding but the abstract shows functional requirement, binding data not reported in our evidence. Two other abstracts insufficient.","key_references":[{"PMID":"39386533","why":"Plxna1 as Slit3-C receptor in BAT"}],"covers":["LR003314","LR006528"]},"LR001398":{"pair":"SLIT3 -> ROBO2","headline":"SLIT3 associates directly with ROBO2 in a binding ELISA with osteoblast lysate; one paper.","interaction_type":"direct binding","direction_and_effect":"Binding ELISA showed SLIT3-associated ROBO1 and ROBO2 increased with osteoblast lysate, indicating direct association [PMID:29504949]. Functional effect via ROBO2 specifically is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Osteoblast lysate ELISA; mouse pair non-inferred, human ortholog-inferred [PMID:29504949].","localisation_and_range":"SLIT3 is flagged secreted, ROBO2 transmembrane [flag]. Reactome lists a ROBO2:SLIT3 plasma-membrane complex [DB:Reactome].","caveats":"Quote browser-read, spot-check pending; ROBO1 and ROBO2 are reported together so ROBO2-specific binding is not separated. Eight abstracts insufficient and three different-entity rows not shown. No affinity.","key_references":[{"PMID":"29504949","why":"Binding ELISA of SLIT3 with ROBO1 and ROBO2"}],"covers":["LR001398","LR004793"]},"LR001992":{"pair":"SLITRK3 -> PTPRD","headline":"SLITRK3 acts via PTPdelta to drive inhibitory synapses; two papers, one with Slitrk3-deficient mice.","interaction_type":"direct binding","direction_and_effect":"Slitrk3 is a postsynaptic adhesion molecule that selectively regulates inhibitory synapse development via trans-interaction with axonal PTPdelta; Slitrk3-deficient mice have fewer inhibitory synapses [PMID:22286174]. Slitrk3-expressing L cells aggregated with PTPdelta cells [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Fibroblasts with co-cultured rat hippocampal neurons, and mice [PMID:22286174]; mouse L cells [PMID:23345436]. Both pairs ortholog-inferred.","localisation_and_range":"Trans-synaptic contact: postsynaptic Slitrk3 on inhibitory sites, axonal PTPdelta [PMID:22286174].","caveats":"Direct binding is inferred from a coculture trans-interaction assay in the abstract. Four review-only rows not shown.","key_references":[{"PMID":"22286174","why":"Slitrk3 inhibitory synapses via PTPdelta"},{"PMID":"23345436","why":"Slitrk3 L-cell aggregation with PTPdelta"}],"covers":["LR001992","LR005321"]},"LR010686":{"pair":"SLURP1 -> CHRNA3","headline":"Synthetic SLURP-1 inhibits alpha3beta4 and alpha3beta2 nAChRs in functional assays; no direct binding shown for this subunit.","interaction_type":"functional only","direction_and_effect":"Synthetic SLURP-1 inhibits human alpha3beta4 and alpha3beta2 nAChRs (antagonist); alpha3beta4 was the most sensitive. [PMID:29192197]","molecular_requirements":"Tested as heteromers with beta subunits; alpha3 alone is not reported in our evidence [PMID:29192197].","affinity_potency":[],"species_and_systems":"Human receptors expressed heterologously (two-electrode voltage clamp), synthetic human SLURP-1 tested at 10 uM [PMID:29192197].","localisation_and_range":"SLURP1 is flagged secreted [flag]; the paper describes it as a secreted protein that co-localizes with nAChRs [PMID:29192197]. ","caveats":"Curator read abstract level only. The evidence is inhibition of ACh-evoked currents, not binding. Synthetic SLURP-1 did not compete with alpha-bungarotoxin at human alpha7 or muscle-type nAChRs and did not inhibit alpha7 currents without PNU120596; earlier recombinant SLURP-1 with extensions gave conflicting results [PMID:29192197].","key_references":[{"PMID":"29192197","why":"Chemically synthesized human SLURP-1 tested on nAChR subtypes"}],"covers":["LR010686"]},"LR006537":{"pair":"SPARC -> VCAM1","headline":"SPARC is reported as a VCAM-1 counter-ligand needed for leukocyte transmigration; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"SPARC-VCAM-1 interaction induces actin rearrangement and intercellular gaps; leukocyte-derived SPARC binding to VCAM-1 was necessary for transmigration in vitro, and SPARC-null mice have abnormal leukocyte recruitment to inflamed peritoneum [PMID:17178915]. Agonist-like.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro endothelial monolayers (human, per curator) and SPARC-null mice [PMID:17178915]. Mouse pair ortholog-inferred.","localisation_and_range":"SPARC secreted; VCAM1 is flagged both transmembrane and secreted [flag].","caveats":"Abstract only; the quoted evidence is a functional readout rather than a binding assay, and the abstract says 'binding' without detail here. No affinity. No database records.","key_references":[{"PMID":"17178915","why":"SPARC as VCAM-1 counter-ligand in transmigration"}],"covers":["LR003330","LR006537"]},"LR008616":{"pair":"SPN -> ICAM1","headline":"CD43 is reported as a ligand for ICAM-1 by one 1991 abstract; thin evidence.","interaction_type":"direct binding","direction_and_effect":"The paper reports evidence that ICAM-1 is a ligand for CD43, in a setting where CD43 expressed in a murine T-cell hybridoma enhanced antigen-specific response to Daudi cells [PMID:1683685]. Direction and activating/inhibitory effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD43 expressed in heterologous cells (curator note) and Daudi cells [PMID:1683685]. IntAct solid phase assay also lists SPN-ICAM1 [DB:IntAct].","localisation_and_range":"Both partners are flagged membrane proteins; interaction class is Receptor-Receptor, so contact-dependent [flag].","caveats":"Abstract only; the abstract does not show the binding data. No affinity.","key_references":[{"PMID":"1683685","why":"ICAM-1 reported as a ligand for CD43"}],"covers":["LR008616"]},"LR007059":{"pair":"SPP1 -> ITGA4:ITGB1","headline":"Osteopontin is a ligand for the alpha4beta1 integrin in leukocyte adhesion assays; abstract-only paper plus a BioGRID complex record.","interaction_type":"direct binding","direction_and_effect":"Osteopontin promoted adhesion of HL-60 and Ramos leukocyte lines through alpha4beta1; alpha4beta1 specifically bound osteopontin in affinity chromatography [PMID:9547293].","molecular_requirements":"Adhesion was inhibited by antibodies to either alpha4 or beta1 and by an LDV-containing alpha4beta1-binding peptide; leukocyte activation was required; Mg2+ and Ca2+ were present [PMID:9547293]. Both chains are therefore needed in this evidence.","affinity_potency":[],"species_and_systems":"Human leukocyte cell lines HL-60 and Ramos with osteopontin purified from bovine milk [PMID:9547293].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; matrix-adhesion assays suggest substrate-bound use [PMID:9547293].","caveats":"One paper, abstract only and truncated. The evidence sentence in the dossier is background rather than the result. BioGRID lists only SPP1-ITGB1 reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"9547293","why":"Osteopontin binds alpha4beta1, antibody and LDV peptide inhibition"}],"covers":["LR007059"]},"LR004809":{"pair":"SST -> SSTR5","headline":"Somatostatin peptides bind human SSTR5 with high affinity in recombinant membranes; supported by binding assays and a PDB structure, no in vivo data.","interaction_type":"direct binding","direction_and_effect":"Agonist: SST-14 and SST-28 dose-dependently inhibited forskolin-stimulated cAMP, consistent with adenylyl cyclase inhibitory coupling [PMID:7908405]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Binding was reduced by GTP, GTPgammaS, Na+ and pertussis toxin, indicating pertussis-toxin-sensitive G-protein coupling [PMID:7908405]. A PDB structure with both chains is recorded [DB:PDB 8ZBJ], and IntAct lists a FRET interaction [DB:IntAct].","affinity_potency":[{"value":"Ki = 2.24 nM","assay":"radioligand competition, SST-14","system":"COS-7 membranes expressing hSSTR5","cite":"PMID:7908405"},{"value":"Ki = 0.19 nM","assay":"radioligand competition, SST-28","system":"COS-7 membranes expressing hSSTR5","cite":"PMID:7908405"},{"value":"pKi 8.4-9.9","assay":"GtoPdb range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in transfected COS-7 and CCL39 cells [PMID:7908405][PMID:9652348][PMID:9650799]. Mouse entry is projected from human evidence.","localisation_and_range":"SST flagged secreted, SSTR5 transmembrane, implying paracrine or endocrine action [flag].","caveats":"All three shown papers were read as abstracts only. hSSTR5 is SST-28 selective over SST-14 [PMID:7908405]. Sst5 affinity values varied 2-123-fold depending on the radioligand used [PMID:9652348]. Two of the papers used octreotide or an SST-28 analogue as the radioligand rather than SST-14 itself [PMID:9652348][PMID:9650799].","key_references":[{"PMID":"7908405","why":"cloning of hSSTR5 with SST-14/SST-28 Ki values and cAMP inhibition"},{"PMID":"9652348","why":"sst2 and sst5 radioligand pharmacology in CCL39 cells"},{"PMID":"9650799","why":"five-subtype binding profile with SST-28 analogue control"}],"covers":["LR001414","LR004809"]},"LR008922":{"pair":"SSTR2 -> SHANK1","headline":"Only a UniProt note of a PDZ-domain interaction; not a ligand-receptor pair with any paper evidence in our dossier.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. UniProt states SHANK1 interacts with the C-terminus of SSTR2 via its PDZ domain [DB:UniProt].","molecular_requirements":"PDZ domain of SHANK1 with the SSTR2 C-terminus, per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence; a PDZ-mediated scaffold link suggests an intracellular interaction, but no flag or paper states this.","caveats":"No papers were judged (both candidate rows were rejected as a different entity). Support rests on one UniProt annotation. SHANK1 has no receptor or secretion flags here, so this looks like an intracellular scaffold interaction rather than a signalling ligand-receptor pair.","key_references":[],"covers":["LR008922"]},"LR004818":{"pair":"TAC4 -> TACR3","headline":"Hemokinin-1 (TAC4) is reported as a full agonist at NK3 (TACR3) in isolated tissue assays; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"In isolated bioassays HEK-1 was a full agonist at tachykinin NK(1), NK(2) and NK(3) receptors [PMID:11786503]; responses in guinea-pig ileum were blocked by SR 142801 [PMID:11786503]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 8.6-9.1","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Guinea-pig ileum bioassay [PMID:11786503]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"TAC4 flagged secreted [flag].","caveats":"Abstract only; no binding data at NK3 in the abstract. The GtoPdb row cites a different paper [PMID:11226387].","key_references":[{"PMID":"11786503","why":"HEK-1 agonism at NK3 in guinea-pig ileum"}],"covers":["LR001423","LR004818"]},"LR006555":{"pair":"TAFA4 -> NRXN1","headline":"TAFA4 (FAM19A4) binds neurexins, including NRXN1; one paper, recombinant and mouse brain work.","interaction_type":"direct binding","direction_and_effect":"FAM19A1-A4 bind neurexins other than neurexin-1\u03b3 [PMID:32706374]. Recombinant FAM19A4 was detected on the surface of HEK293T cells with neurexins [PMID:32706374]. The authors argue neurexins are the predominant binding partners of FAM19A1-A4 and ask how this fits with FAM19A4 as an FPR1 ligand [PMID:32706374].","molecular_requirements":"FAM19A1-A4 bind the cysteine-loop domain of neurexins by forming intermolecular disulfide bonds; both the cysteines and an adjacent neurexin sequence were required [PMID:32706374]. FAM19A5 does not bind [PMID:32706374].","affinity_potency":[],"species_and_systems":"Recombinant proteins in HEK293T cells; neurexin complexes from mouse brain were analysed for FAM19A1 and FAM19A2 [PMID:32706374]. Human pair projected from mouse evidence.","localisation_and_range":"TAFA4 annotated secreted; NRXN1 annotated transmembrane [flag].","caveats":"Supported by one paper read as an abstract plus full-text excerpts; the abstract states that neurexin-1\u03b3 is the exception [PMID:32706374]. Binding is covalent and forms during transit through the secretory pathway, which is unusual for a ligand-receptor pair. A separate report proposes FPR1 as the FAM19A4 receptor [PMID:32706374].","key_references":[{"PMID":"32706374","why":"FAM19A1-A4 bind neurexins via disulfide linkage"}],"covers":["LR003352","LR006555"]},"LR006564":{"pair":"TENM4 -> ADGRL1","headline":"Direct binding shown by pulldown of teneurin-4 with latrophilin-1 in one full-text paper; no affinity for this pair.","interaction_type":"direct binding","direction_and_effect":"Teneurin-4 (Ten4) binds latrophilin-1 (Lphn1) in pulldowns; Ten1 did not bind. The paper reports that teneurin binding mediates cell adhesion, consistent with trans-synaptic adhesion rather than classic agonist signalling [PMID:24273166].","molecular_requirements":"Binding is to the lectin-like domain of latrophilins; Ten4 bound all Lphn1 constructs tested. Alternative splicing of latrophilin-1 modulates teneurin binding [PMID:24273166].","affinity_potency":[],"species_and_systems":"Pulldown with purified Lphn1-Ig fusion proteins and immobilized teneurin ectodomains, HEK293T-derived; species of ligand and receptor unspecified. The mouse pair is projected from human evidence (ortholog-inferred) [PMID:24273166].","localisation_and_range":"Both partners have transmembrane flags [flag], so interaction is likely cell-contact (juxtacrine). The abstract says nanomolar affinity for teneurin-latrophilin binding in general; no value is given for Ten4/Lphn1 in our evidence [PMID:24273166].","caveats":"Curator quote came from a browser read and is marked unverifiable (spot-check pending); only the abstract is stored. Ten4 is also flagged as a receptor.","key_references":[{"PMID":"24273166","why":"Pulldown of Ten4 with Lphn1; teneurin-latrophilin cell adhesion"}],"covers":["LR003361","LR006564"]},"LR004827":{"pair":"TFPI -> VLDLR","headline":"Binding and blocking experiments indicate VLDL receptor recognizes full-length TFPI and mediates its antiproliferative effect on endothelial cells.","interaction_type":"direct binding","direction_and_effect":"TFPI inhibited proliferation of bFGF-stimulated endothelial cells; this effect was inhibited by receptor-associated protein and anti-VLDL receptor antibodies [PMID:11278667].","molecular_requirements":"Full-length TFPI, but not a truncated form with two Kunitz domains, is recognized; the carboxyl-terminal region is required [PMID:11278667].","affinity_potency":[],"species_and_systems":"Endothelial cells; species not stated in the abstract. Mouse pair is ortholog-inferred [PMID:11278667].","localisation_and_range":"TFPI is annotated secreted [flag]; VLDLR is annotated transmembrane [flag].","caveats":"Abstract only. The paper calls binding 'high affinity' but no value is in our evidence.","key_references":[{"PMID":"11278667","why":"VLDL receptor binds full-length TFPI"}],"covers":["LR001432","LR004827"]},"LR010758":{"pair":"TGFA -> EGFR:ERBB2","headline":"Evidence concerns only the EGFR chain; ERBB2 involvement is not shown.","interaction_type":"direct binding","direction_and_effect":"TGFalpha binds EGFR in a 2:2 crystal complex [PMID:12297049]; the TGFalpha precursor binds EGF/TGF-alpha receptors and activates tyrosine kinase activity in rat cells [PMID:3018723].","molecular_requirements":"ERBB2 is not in the structure and not named in the precursor paper; whether EGFR alone suffices is not tested [PMID:12297049]. Complex scoring by least-expressed subunit may therefore be over-restrictive.","affinity_potency":[],"species_and_systems":"Truncated human EGFR ectodomain [PMID:12297049]; rat transformed cells [PMID:3018723].","localisation_and_range":"Ligand is annotated secreted and transmembrane [flag].","caveats":"Chain-only evidence; abstracts only.","key_references":[{"PMID":"12297049","why":"TGFalpha-EGFR co-crystal structure"},{"PMID":"3018723","why":"Precursor binds EGF/TGF-alpha receptor"}],"covers":["LR010758"]},"LR003369":{"pair":"TGFB1 -> ITGA8","headline":"Integrin alpha8beta1 adheres to LAP-TGFbeta1 in cell assays; adhesion evidence only.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cell lines spread on and adhere to recombinant LAP-TGFbeta1 better than mock cells [PMID:12415008].","molecular_requirements":"The binder assayed is the alpha8 subunit with beta1 (alpha8beta1); the ligand is LAP-TGFbeta1, the latent form [PMID:12415008]. Adhesion was RGD-dependent and enhanced by Mn2+ or activating antibody 8A2 per curator notes [PMID:12415008].","affinity_potency":[],"species_and_systems":"Recombinant LAP-TGFbeta1 and transfected cell lines; species not reported in our evidence [PMID:12415008].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Matrix-like adhesion of latent complex to a cell integrin; no further range data.","caveats":"Adhesion assay is not direct binding; read as abstract only. Ligand is the latent form, not mature TGF-beta1. No database records.","key_references":[{"PMID":"12415008","why":"alpha8beta1-mediated adhesion to LAP-TGFbeta1"}],"covers":["LR003369","LR006570"]},"LR007428":{"pair":"TGFB1 -> ITGAV:ITGB6","headline":"Weak functional support only for alphaVbeta6 acting on TGF-beta1; database support from UniProt for the complex.","interaction_type":"functional only","direction_and_effect":"ITGB6 activates the TGF-beta1/ALP signalling cascade, and integrin inhibitor CWHM-12 abrogates ODAPH-mediated induction; labelled agonist [PMID:40680053]. UniProt states ITGAV:ITGB6 interacts with TGFB1 [DB:UniProt].","molecular_requirements":"Only ITGB6 is named in the paper; ITGAV is not named [PMID:40680053].","affinity_potency":[],"species_and_systems":"Human ameloblast-lineage cells [PMID:40680053].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Complex flagged transmembrane [flag].","caveats":"The paper is about ODAPH/LAMC2 signalling and does not test TGF-beta1 binding to the integrin; read as abstract only. Direct structural evidence for alphaVbeta6 sits in the sibling ITGB6 record, not here. Complex flagged is_receptor 0 in annotation [flag].","key_references":[{"PMID":"40680053","why":"ITGB6-dependent TGF-beta1/ALP signalling in ameloblast cells"}],"covers":["LR007428"]},"LR004836":{"pair":"TGFB1 -> ITGB8","headline":"Strong evidence: alphaVbeta8 binds latent TGF-beta1 with high specificity (cryo-EM, binding assays).","interaction_type":"direct binding","direction_and_effect":"alphaVbeta8 binds latent TGF-beta with exquisite specificity and this is essential for activating it [PMID:31955848]. SLC binds alphaVbeta8, followed by MT1-MMP-dependent release of active TGF-beta [PMID:11970960].","molecular_requirements":"Needs the alphaV partner. Leu-218 after the RGD motif in the latency-associated peptide defines high-affinity binding via the beta8 I-like domain [PMID:27033701].","affinity_potency":[],"species_and_systems":"Cryo-EM of ectodomain with intact ligand [PMID:31955848]; human proteins [PMID:27033701]; PDB structures [DB:PDB 6OM2].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Latent complex presented at the cell surface; mature TGF-beta signals within the latent complex without release [PMID:31955848].","caveats":"Ligand is the latent complex. Affinity values are not given in the dossier. One further paper abstract-insufficient; PMID:27033701 read as abstract only.","key_references":[{"PMID":"31955848","why":"Cryo-EM of alphaVbeta8 bound to latent TGF-beta"},{"PMID":"27033701","why":"Leu-218 defines alphaVbeta8 specificity"},{"PMID":"11970960","why":"SLC binds alphaVbeta8, MT1-MMP-dependent activation"}],"covers":["LR001441","LR004836"]},"LR004845":{"pair":"TGFB3 -> ENG","headline":"TGF-beta3 and endoglin: one paper says endoglin binds TGF-beta3 only with signalling receptors; UniProt says it does not bind TGFB3.","interaction_type":"conflicting","direction_and_effect":"Endoglin binds TGF-beta1 and -beta3 by associating with the TGF-beta type II receptor and cannot bind ligand on its own [PMID:9872992]. UniProt states high affinity for TGFB1 and TGFB2 but not TGFB3 [DB:UniProt]; BioGRID lists ENG-TGFB3 affinity capture-western [DB:BioGRID].","molecular_requirements":"Requires TGF-beta type II receptor coexpression [PMID:9872992].","affinity_potency":[],"species_and_systems":"Human endothelial and leukaemic cells, affinity labelling [PMID:9872992].","localisation_and_range":"Ligand secreted [flag].","caveats":"Abstract-only; conflicts with UniProt text. Endoglin is an accessory protein, not a standalone receptor.","key_references":[{"PMID":"9872992","why":"Endoglin binds TGF-beta1/-beta3 via type II receptor"}],"covers":["LR001450","LR004845"]},"LR006573":{"pair":"TGFB3 -> ITGA8","headline":"Integrin alpha8 chain: cells expressing alpha8 adhere to LAP-TGF-beta3 in an RGD-dependent manner; chain-only evidence.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cells adhered to LAP-TGFbeta3 better than mock cells; adhesion was RGD-dependent [PMID:12415008].","molecular_requirements":"The binder is the alpha8beta1 heterodimer; the alpha8 chain alone is not shown to suffice [PMID:12415008].","affinity_potency":[],"species_and_systems":"Transfected cell lines, adhesion and spreading assays; species not reported in our evidence [PMID:12415008]. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; adhesion is matrix/contact-type.","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Abstract-only; RGD site role is from curator notes.","key_references":[{"PMID":"12415008","why":"alpha8beta1 adhesion to LAP-TGFbeta3"}],"covers":["LR003372","LR006573"]},"LR003378":{"pair":"TGM2 -> ITGA5","headline":"G-361 melanoma cell adhesion to tTG uses alpha5beta1; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"G-361 cells use alpha(9)beta(1) and alpha(5)beta(1) to adhere to tTG [PMID:10816592]. The assay used blocking antibodies [PMID:10816592].","molecular_requirements":"Functional receptor is alpha5beta1, so ITGB1 is also needed [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human G-361 melanoma cells [PMID:10816592]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; adhesion to tTG as substrate [PMID:10816592].","caveats":"Cell adhesion only, abstract-level read, no direct binding. BioGRID records are for ITGB1-TGM2, not ITGA5 [DB:BioGRID].","key_references":[{"PMID":"10816592","why":"G-361 adhesion to tTG via alpha5beta1 and alpha9beta1"}],"covers":["LR003378","LR006579"]},"LR004854":{"pair":"TGM2 -> SDC4","headline":"Cell-surface TG2 associates with heparan sulfate chains of syndecan-4, shown by SPR and cell assays.","interaction_type":"direct binding","direction_and_effect":"Cell-surface TG2 directly associates with the HS chains of syndecan-4 without fibronectin mediation [PMID:19398782]. Syndecan-4-null fibroblasts fail to externalize TG2, which accumulates in the cytosol [PMID:19398782].","molecular_requirements":"Binding is via heparan sulfate chains; syndecan-4 plays a major but not exclusive role among HSPGs [PMID:19398782].","affinity_potency":[{"value":"high affinity for heparin/HS, comparable to fibronectin (no numeric value in abstract)","assay":"heparin/HS solid-binding assays and SPR","system":"purified TG2","cite":"PMID:19398782"}],"species_and_systems":"Human TG2 per curation; fibroblasts including syndecan-4-null cells [PMID:19398782]. Human and mouse pairs are both listed.","localisation_and_range":"Cell-surface syndecan-4 acts as a trafficking receptor for TG2 externalization [PMID:19398782].","caveats":"Abstract-only read. Binding is to glycosaminoglycan chains, so other HSPGs may also bind TG2.","key_references":[{"PMID":"19398782","why":"TG2 binds syndecan-4 heparan sulfate; trafficking"}],"covers":["LR001459","LR004854"]},"LR006582":{"pair":"THBS1 -> ITGA1","headline":"Single recent paper supports a THBS1-ITGA1 interaction by co-IP in osteosarcoma cells; thin evidence.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation confirmed THBS1 interacts with ITGA1 (and ITGA6) in human 143B and MG-63 osteosarcoma cells; THBS1 promoted ITGA1 accumulation on the cell membrane, FAK/MLC2 phosphorylation and cytoskeleton remodeling, i.e. a stimulatory outcome [PMID:40083708].","molecular_requirements":"Not reported in our evidence which beta chain pairs with ITGA1. ITGA6 was also implicated, and colocalisation with THBS1 occurred only in the early sphere-formation phase [PMID:40083708].","affinity_potency":[],"species_and_systems":"Human osteosarcoma lines; metastasis models in nude mice used tumour cells with THBS1 manipulations [PMID:40083708]. The mouse pair is ortholog-inferred, not tested.","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"One paper only. The paper's own text describes direct interactions between THBS1 and ITGA1 as already shown in a network analysis, with co-IP as its confirmation; co-IP does not prove direct binding. No affinity reported. No database record.","key_references":[{"PMID":"40083708","why":"Co-IP of THBS1 with ITGA1/ITGA6 in osteosarcoma cells (full text)"}],"covers":["LR003381","LR006582"]},"LR004863":{"pair":"THBS1 -> ITGB1","headline":"THBS1 engages beta1 integrins (alpha6beta1, alpha4beta1, alpha3beta1) in adhesion and chemotaxis assays; abstract-level evidence only.","interaction_type":"functional only","direction_and_effect":"Beta1 integrins mediate cell adhesion and chemotaxis to THBS1; alpha6beta1 mediates adhesion and chemotaxis of microvascular endothelial and HT-1080 cells [PMID:12909644], alpha3beta1 does so in breast carcinoma cells [PMID:10196234]. Effect is receptor-mediated cell response; agonist/antagonist not reported in our evidence.","molecular_requirements":"ITGB1 acts as a partner of specific alpha chains: alpha6beta1 binds the N-terminal pentraxin module [PMID:12909644], alpha4beta1 is used by venous but not microvascular endothelial cells [PMID:14699013]. Beta1 integrins also recognise the type 1 and type 2 repeats in a pan-beta1 manner [PMID:15292271]. Reactome lists alpha3beta1/alpha4beta1:THBS1 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human microvascular endothelial and HT-1080 cells [PMID:12909644], mouse endothelial cells and muscle explants [PMID:14699013], human and breast carcinoma cell lines (species unspecified) [PMID:10196234, PMID:15292271]. The mouse pair is ortholog-inferred.","localisation_and_range":"THBS1 is flagged secreted; used in these assays as immobilised matrix substrate, so contact/matrix signalling [flag] [PMID:12909644].","caveats":"All four papers were read as abstracts only. Evidence is adhesion/functional, with direct-binding labels resting on cell-adhesion readouts; integrin activation state matters (HUVEC respond only to certain agonists) [PMID:12909644]. Use the specific alpha:beta heterodimer when scoring. BioGRID lists an affinity-capture-western record [DB:BioGRID].","key_references":[{"PMID":"12909644","why":"alpha6beta1 adhesion/chemotaxis to THBS1 N-terminal module"},{"PMID":"14699013","why":"alpha4beta1 in endothelial responses and angiogenesis"},{"PMID":"15292271","why":"beta1 integrin sites in type 1/2 repeats"}],"covers":["LR001468","LR004863"]},"LR003387":{"pair":"THBS4 -> ITGA5","headline":"THBS4 binds ITGA5 by immunoprecipitation in a hepatocellular carcinoma study; browser-read quote pending spot-check.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation confirmed that THBS4 can bind ITGB1, ITGB5 and ITGA5 [PMID:32567740].","molecular_requirements":"Pairs with beta integrins ITGB1 and ITGB5 in the same study [PMID:32567740].","affinity_potency":[],"species_and_systems":"Human HCC cells; mouse pair ortholog-inferred [PMID:32567740].","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"The quote is browser-read and unverified; IntAct anti-bait co-IP records exist [DB:IntAct].","key_references":[{"PMID":"32567740","why":"THBS4 co-IP with ITGB1, ITGB5, ITGA5 in HCC"}],"covers":["LR003387","LR006588"]},"LR006591":{"pair":"THBS4 -> NOTCH1","headline":"Thbs4 binds Notch1 directly in pull-downs and IP and drives Notch activation in mouse brain; one paper, full text read.","interaction_type":"direct binding","direction_and_effect":"Agonist: Thbs4 binding and endocytosis of Notch1 raises NICD and downstream Nfia, supporting injury-induced astrogenesis; Thbs4-knockout mice show defective SVZ astrogenesis [PMID:23615612].","molecular_requirements":"Recombinant Notch1-Fc containing the first 13 extracellular EGF-like repeats pulled down purified Thbs4; Thbs2 did not [PMID:23615612]. Thbs4 effects needed Notch activity (not rescued with DAPT or DBZ) [PMID:23615612].","affinity_potency":[],"species_and_systems":"Mouse experiments: primary SVZ neural stem cell cultures, mouse Notch1-Fc, injured mouse brain. Human pair is ortholog-inferred; the mouse interaction is the one tested [PMID:23615612].","localisation_and_range":"Thbs4 is a secreted homopentameric glycoprotein [PMID:23615612] and is flagged secreted [flag]; Notch1 is flagged transmembrane [flag]. Paracrine action on Notch1-bearing cells.","caveats":"IP from freshly isolated SVZ tissue did not detect Thbs4 pull-down; the interaction appeared 3 days post-injury [PMID:23615612]. No affinity reported.","key_references":[{"PMID":"23615612","why":"Direct Thbs4-Notch1 binding and Notch activation in SVZ astrogenesis"}],"covers":["LR003390","LR006591"]},"LR003396":{"pair":"THY1 -> ITGB1","headline":"Thy-1 binds alpha5beta1 integrin at single-molecule level; ITGB1 row rests on one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Thy-1 independently binds alpha5beta1 and syndecan-4, which together form a cooperative trimolecular complex [PMID:25216363].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer, not beta1 alone; syndecan-4 cooperates [PMID:25216363].","affinity_potency":[],"species_and_systems":"Single-molecule force spectroscopy in melanoma cell context [PMID:25216363].","localisation_and_range":"Membrane-bound; contact-dependent.","caveats":"Abstract only; one further paper was judged abstract_insufficient. ITGB1 is a chain-level assignment of an alpha5beta1 result.","key_references":[{"PMID":"25216363","why":"Thy-1 binds alpha5beta1 and syndecan-4"}],"covers":["LR003396"]},"LR008508":{"pair":"TIE1 -> TEK","headline":"TIE1 and TIE2 interact in co-IP and docking in cervical cancer cells, and databases record a heterodimer.","interaction_type":"direct binding","direction_and_effect":"Tie1 regulates Tie2 phosphorylation and downstream PI3K/Akt in cervical cancer cells [PMID:41407748]. Interaction class is recorded as inhibitory modulatory effect; the paper's direction beyond this is not reported in our evidence.","molecular_requirements":"Tie1 and Tie2 form a heterodimer [DB:UniProt]; Tie2 interacted with PI3K p85\u03b1 [PMID:41407748].","affinity_potency":[],"species_and_systems":"Human HeLa cells, co-IP and molecular docking (binding energy docking values reported) [PMID:41407748]. BioGRID: Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"Both membrane receptors; cis/co-receptor assembly, not a secreted ligand.","caveats":"Receptor-receptor pair, not a classical ligand-receptor. Co-IP in cells does not prove direct binding. Two other rows were judged a different entity and one abstract_insufficient.","key_references":[{"PMID":"41407748","why":"Co-IP of Tie1 with Tie2 in HeLa cells"}],"covers":["LR008508"]},"LR005349":{"pair":"TIMD4 -> HAVCR1","headline":"TIM-4 reported as the ligand of TIM-1 (HAVCR1); costimulatory in T cells; evidence is functional, read from abstracts only.","interaction_type":"functional only","direction_and_effect":"TIM-4-Ig costimulated CD3/CD28-driven T-cell proliferation in vitro, and soluble TIM-1-Ig or TIM-4-Ig caused T-cell hyperproliferation in vivo, so TIM-4 on antigen-presenting cells is proposed as the endogenous TIM-1 ligand [PMID:15793576]. In allergic rhinitis, the TIM4/TIM1 interaction promoted CD4+ T-cell SIRT1 expression via PI3K/Akt phosphorylation and Th2 proliferation; silencing TIM4 in DCs or TIM1 in T cells reduced proliferation [PMID:28949386].","molecular_requirements":"not reported in our evidence. No complex partners reported.","affinity_potency":[],"species_and_systems":"The curated records list human experiments, but the allergic-rhinitis work (PMID 28949386) describes mice (OVA-pulsed splenic DCs, CD4+ T cells). The human pair is ortholog-inferred; the mouse pair is not [PMID:28949386].","localisation_and_range":"TIMD4 is flagged secreted and HAVCR1 as a receptor [flag]; the papers describe an APC-to-T-cell contact setting [PMID:15793576].","caveats":"Both papers were read as abstracts (the second with excerpts). No direct binding measurement (affinity, pull-down) is in the dossier; the first paper uses Ig fusion proteins in functional assays. Species labels in the curated rows conflict with the mouse model of PMID 28949386.","key_references":[{"PMID":"15793576","why":"Original report of TIM-4 as TIM-1 ligand, with costimulation assays"},{"PMID":"28949386","why":"TIM4/TIM1 signalling to SIRT1 in allergic mice"}],"covers":["LR002021","LR005349"]},"LR004872":{"pair":"TIMP1 -> CD63","headline":"TIMP-1 binds CD63 (yeast two-hybrid, co-IP) and CD63 is needed for TIMP-1 cell-surface binding; supported by databases too.","interaction_type":"direct binding","direction_and_effect":"Yeast two-hybrid identified CD63 as a TIMP-1 interactor, confirmed by co-immunoprecipitation and confocal colocalisation; CD63 shRNA knockdown reduced TIMP-1 cell-surface binding and reversed TIMP-1-driven integrin beta1 activation and survival signalling [PMID:16917503]. BioGRID, IntAct and UniProt records support TIMP1-CD63 physical interaction [DB:BioGRID][DB:IntAct][DB:UniProt].","molecular_requirements":"CD63 also co-immunoprecipitates with integrin beta1 and TIMP-1 on the cell surface [PMID:16917503]; UniProt states CD63 recruits TIMP1 to ITGB1 [DB:UniProt]. Whether CD63 alone suffices for signalling is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human breast epithelial MCF10A cells, including 3D Matrigel culture [PMID:16917503]. Mouse pair is ortholog-inferred.","localisation_and_range":"TIMP1 is flagged secreted and CD63 as a receptor [flag]; TIMP-1 binds the cell surface [PMID:16917503].","caveats":"Primary paper read as abstract only; no affinity reported. Signalling may depend on integrin beta1 as a partner.","key_references":[{"PMID":"16917503","why":"Identification of CD63 as TIMP-1 binding partner"}],"covers":["LR001477","LR004872"]},"LR001479":{"pair":"TIMP2 -> ITGB1","headline":"TIMP-2 acts through beta1 integrin on endothelial cells (mouse system); one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"TIMP-2 abrogated angiogenic-factor-induced endothelial proliferation in vitro and angiogenesis in vivo independently of MMP inhibition, requiring alpha3beta1 binding; it reduced beta1-associated PTP activity and dissociated SHP-1 from beta1 [PMID:12887919]. BioGRID has a reconstituted-complex record for TIMP2-ITGB1 [DB:BioGRID].","molecular_requirements":"Requires alpha3beta1; beta1 alone is not shown sufficient in our evidence [PMID:12887919].","affinity_potency":[],"species_and_systems":"Curated as mouse/mouse experiments; human pair is not ortholog-inferred in the interactions list, while the mouse pair is [PMID:12887919].","localisation_and_range":"TIMP2 flagged secreted; ITGB1 flagged receptor [flag].","caveats":"Abstract-only evidence; two other papers were abstract_insufficient. Species labels differ between this and the ITGA3:ITGB1 record from the same paper.","key_references":[{"PMID":"12887919","why":"TIMP-2 angiogenesis inhibition via alpha3beta1"}],"covers":["LR001479","LR004874"]},"LR006609":{"pair":"TMPRSS6 -> HJV","headline":"Matriptase-2 (TMPRSS6) binds and cleaves hemojuvelin, inhibiting hepcidin activation; one abstract-read paper plus database co-IP records.","interaction_type":"direct binding","direction_and_effect":"Matriptase-2 cleaved membrane HJV, inhibiting the hepcidin response; it interacted with HJV through its ectodomain, and this was preserved in the protease-dead matriptase-2 MASK mutant, so binding is separable from cleavage [PMID:18976966]. The effect is inhibitory. IntAct and UniProt record the interaction [DB:IntAct][DB:UniProt].","molecular_requirements":"The ectodomain mediates binding; cleavage needs the serine protease domain, and the R774C mutant gave partial cleavage and partial inhibition [PMID:18976966].","affinity_potency":[],"species_and_systems":"Human Hep3B cells with human constructs and zebrafish expression of mutants [PMID:18976966]; mouse pair is ortholog-inferred.","localisation_and_range":"TMPRSS6 is flagged non-secreted and HJV as secreted [flag]; cleavage occurs on the plasma membrane [PMID:18976966].","caveats":"Flags label HJV as the receptor, but the paper shows HJV is the substrate of the protease. Binding was assessed in an abstract-read paper; no affinity reported.","key_references":[{"PMID":"18976966","why":"Matriptase-2 ectodomain interacts with and cleaves HJV"}],"covers":["LR003408","LR006609"]},"LR007068":{"pair":"TNC -> ITGA4:ITGB1","headline":"No verified paper; database records concern other integrins (alpha8, alpha9) rather than alpha4beta1.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; four papers were abstract_insufficient [outcome_counts]. Database records describe alpha8beta1 and alpha9beta1 binding tenascin-C [DB:Reactome] and ITGA9:ITGB1 binding TNC via its third fibronectin type III domain [DB:UniProt].","molecular_requirements":"Complex of ITGA4 and ITGB1 [flag]; none of the cited records name alpha4.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Cited database records do not mention alpha4beta1, so the pair itself is unsupported in our evidence.","key_references":[],"covers":["LR007068"]},"LR004881":{"pair":"TNC -> ITGA8","headline":"Human alpha8beta1 mediates adhesion to tenascin; binding domain localised to the third FNIII repeat; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Of RGD-containing proteins tested, only tenascin mediated adhesion of alpha8-transfected 293 cells; the alpha8beta1 binding domain was localised to the RGD-containing third fibronectin type III repeat [PMID:7559467]. Reactome also records alpha8beta1:tenascin-C [DB:Reactome].","molecular_requirements":"Alpha8 pairs with beta1 (alpha8beta1) [PMID:7559467]; stored per subunit though the heterodimer binds.","affinity_potency":[],"species_and_systems":"Human embryonic kidney 293 cells transfected with alpha8 cDNA [PMID:7559467].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only; cell-adhesion assay. Alpha8beta1 also binds fibronectin and vitronectin [PMID:7559467]. Curator notes the entry should be folded into the alpha8:beta1 complex.","key_references":[{"PMID":"7559467","why":"alpha8beta1 as receptor for tenascin, fibronectin, vitronectin"}],"covers":["LR001486","LR004881"]},"LR001488":{"pair":"TNC -> ITGAV","headline":"AlphaV integrins bind tenascin-C in human cells (alphavbeta3, alphavbeta6); several papers, mostly abstract-only.","interaction_type":"direct binding","direction_and_effect":"Affinity purification identified alpha2beta1 and alphavbeta3 as tenascin-binding receptors on endothelial cells; alphaVbeta3 antibody gave 35% attachment inhibition [PMID:7693733]. TN-C interaction with alphavbeta3 modifies smooth muscle cell shape and EGF-dependent growth [PMID:9314546]. Oral SCC adhesion involves alpha(v) integrins [PMID:9219848].","molecular_requirements":"AlphaV pairs with beta3 or beta6 in these papers; alphavbeta3 binding is mediated by the SRRGDMS site [PMID:7693733].","affinity_potency":[],"species_and_systems":"Human cells: HUVEC [PMID:7693733], smooth muscle cells [PMID:9314546], oral SCC lines [PMID:9219848].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"All read as abstracts. Single-chain entry; beta partner varies. Two further rows abstract_insufficient.","key_references":[{"PMID":"7693733","why":"Affinity purification of alphavbeta3 as tenascin receptor"},{"PMID":"9314546","why":"TN-C/alphavbeta3 in SMC EGF growth"},{"PMID":"9219848","why":"alpha(v) integrins in oral SCC adhesion to TN-C"}],"covers":["LR001488","LR004883"]},"LR010965":{"pair":"TNF -> RIPK1","headline":"RIPK1 is an intracellular adaptor in the TNF receptor complex; support is from co-purification databases only, not a direct ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. Reactome describes RIPK1 binding in a TNF:TNFR1 complex with TRADD and TRAF2 [DB:Reactome][PMID:7758105].","molecular_requirements":"RIPK1 appears recruited with the receptor complex, not bound by TNF itself [DB:Reactome]. Other subunits are not reported in our evidence beyond TRADD and TRAF2.","affinity_potency":[],"species_and_systems":"BioGRID affinity capture-Western records (29 records) [DB:BioGRID][PMID:25911380], IntAct co-immunoprecipitation and pull-down records [DB:IntAct][PMID:12887920], and a UniProt note on RIPK1 interacting with SQSTM1 upon TNF stimulation [DB:UniProt][PMID:10356400].","localisation_and_range":"RIPK1 is an intracellular protein with no receptor flag; TNF is flagged secreted and transmembrane [flag].","caveats":"No paper was confirmed: 11 papers were judged to concern a different entity and one was review-only. The records most likely reflect pull-down of the TNFR1 complex after TNF stimulation, not TNF binding RIPK1; this inference is ours from the Reactome text. This is likely not a true ligand-receptor pair.","key_references":[],"covers":["LR010965"]},"LR009624":{"pair":"TNF -> TRADD","headline":"TRADD is an intracellular adaptor recruited to the TNF receptor complex; support is from co-precipitation databases and no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The pair carries an inhibitory annotation, but no paper in our evidence shows this. Reactome describes TNF:TNFR1 binding TRADD, TRAF2 and RIPK1 [DB:Reactome][PMID:7758105].","molecular_requirements":"TRADD appears with the receptor complex after stimulation of TNFRSF1A [DB:UniProt][PMID:14585990]. Not reported in our evidence beyond that.","affinity_potency":[],"species_and_systems":"BioGRID affinity capture-Western and capture-MS records [DB:BioGRID][PMID:12753742] and IntAct co-immunoprecipitation records [DB:IntAct][PMID:12887920].","localisation_and_range":"TRADD has no secreted or receptor flag; TNF is flagged secreted and transmembrane [flag].","caveats":"Only one paper was judged and it was review-only; none confirmed. The records reflect receptor-complex pull-down, not TNF binding TRADD (our inference from the Reactome text). This is probably not a true ligand-receptor pair.","key_references":[],"covers":["LR009624"]},"LR007437":{"pair":"TNFSF10 -> TNFRSF11B","headline":"No curator-verified paper; OPG is described only in database annotations as a possible decoy for TRAIL.","interaction_type":"database-asserted only","direction_and_effect":"UniProt annotates OPG as a protein that may act as a decoy receptor for TRAIL and protect against apoptosis [DB:UniProt]. TRAIL activity may be modulated by decoy receptors TNFRSF10C, TNFRSF10D and OPG [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system not reported in our evidence; the only records are UniProt entries [DB:UniProt].","localisation_and_range":"OPG carries no receptor or transmembrane flag [flag], consistent with a soluble decoy, but this is not tested in our evidence.","caveats":"Curated papers: one review only, two different-entity and one unresolvable; none confirmed. UniProt wording is 'may' and 'possibly'.","key_references":[],"covers":["LR007437"]},"LR001497":{"pair":"TNFSF12 -> TNFRSF12A","headline":"TWEAK binds Fn14 (TNFRSF12A) with nanomolar affinity, shown by five assays; well supported.","interaction_type":"direct binding","direction_and_effect":"Five different assays demonstrate TWEAK-TweakR binding [PMID:11728344]. Cross-linking TweakR induces HUVEC growth, and soluble TweakR inhibits endothelial migration and corneal angiogenesis [PMID:11728344]. TWEAK activates NF-kappaB in mouse NIH 3T3 cells [PMID:12529173]. Effect: agonist.","molecular_requirements":"The TweakR cytoplasmic domain binds TRAFs 1, 2 and 3; TRAF 1, 2, 3 and 5 bind the murine Fn14 tail and an intact TRAF site is needed for NF-kappaB activation [PMID:11728344][PMID:12529173].","affinity_potency":[{"value":"Kd 2.3 +/- 0.1 nM","assay":"binding affinity from five assays (types not stated in abstract)","system":"human TWEAK and TweakR","cite":"PMID:11728344"}],"species_and_systems":"Human receptor cloned from HUVEC [PMID:11728344]; human TWEAK extracellular domain also binds murine Fn14, tested in NIH 3T3 cells [PMID:12529173]. Databases: IntAct ELISA [DB:IntAct], Reactome [DB:Reactome], GtoPdb without type or affinity [DB:GtoPdb].","localisation_and_range":"TWEAK is flagged secreted and transmembrane; Fn14 is a type I transmembrane protein [PMID:12529173].","caveats":"Both papers were read as abstracts.","key_references":[{"PMID":"11728344","why":"Cloning of TweakR and Kd of TWEAK binding"},{"PMID":"12529173","why":"Human TWEAK binds mouse Fn14; TRAF and NF-kappaB signalling"}],"covers":["LR001497","LR004888"]},"LR004890":{"pair":"TNFSF13B -> TNFRSF13C","headline":"BAFF binds BAFF-R, shown by co-crystal structure and binding studies; strongly supported.","interaction_type":"direct binding","direction_and_effect":"BAFF-R was identified as a third BAFF receptor with highly specific binding [PMID:11509692]; crystal structure of soluble TALL-1 with the BAFF-R extracellular domain at 2.5 A [PMID:12721620]. Annotated stimulatory [flag].","molecular_requirements":"One disulphide bridge in BAFF-R sets specificity for TALL-1 over APRIL, confirmed by in vitro binding [PMID:12721620]. Reactome shows a 3xBAFFR:BAFF trimer complex [DB:Reactome]. Soluble TALL-1 acts as a virus-like assembly [PMID:12721620].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:12721620][PMID:11509692]; BAFF-R locus disrupted in A/WySnJ mice, which resemble BAFF-deficient mice [PMID:11509692].","localisation_and_range":"BAFF flagged secreted and transmembrane; BAFF-R transmembrane [flag].","caveats":"Both papers abstract only. Structures also in PDB [DB:PDB 1OQE][DB:PDB 3V56]. No affinity value in our evidence.","key_references":[{"PMID":"12721620","why":"Co-crystal structure of BAFF with BAFF-R"},{"PMID":"11509692","why":"Identification of BAFF-R as specific BAFF receptor"}],"covers":["LR001499","LR004890"]},"LR006618":{"pair":"TNR -> CNTN1","headline":"Tenascin-R binds contactin 1 in a sandwich-binding assay; one abstract-read paper, projected to mouse by orthology.","interaction_type":"direct binding","direction_and_effect":"Tenascin-R interacts with contactin 1 as its neuronal receptor; aggrecan, brevican and neurocan compete for this binding and block TN-R effects on microprocess formation and growth cone size [PMID:16899820].","molecular_requirements":"Aggrecan interaction with TN-R fibronectin type III domains 4-A is needed for its inhibition of TN-R binding to contactin 1; chondroitin sulfate chains are not involved [PMID:16899820].","affinity_potency":[],"species_and_systems":"Tectal cells and a sandwich-binding assay; the species is not stated in the abstract. Both listed interactions (human, mouse) are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor flagged transmembrane and not secreted [flag]. The paper describes extracellular matrix TN-R acting on neurites.","caveats":"Abstract read only; the curator notes the interaction was first described in an earlier paper [PMID:16899820]. The primary assay is competition, so affinity not reported in our evidence.","key_references":[{"PMID":"16899820","why":"Sandwich-binding assay for TN-R/contactin 1 and lectican competition"}],"covers":["LR003417","LR006618"]},"LR006627":{"pair":"TULP1 -> MERTK","headline":"Tulp1 binds MerTK, the best-characterised TAM target, and induces its activation and phagocytosis; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Tulp1 interacts with Tyro3, Axl and MerTK of the TAM subfamily [PMID:20978472]. Both ligands induced MerTK activation with receptor phosphorylation and signalling, and excess soluble MerTK extracellular domain blocked Tulp1-mediated phagocytosis. [PMID:20978472]","molecular_requirements":"Five minimal phagocytic determinants (K/R(X)1-2KKK) in the Tulp1 N-terminus are essential for MerTK binding, receptor phosphorylation and phagocytosis; the C-terminal region binds phagocytic prey [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. One of the human/mouse pairs is ortholog-inferred.","localisation_and_range":"Unconventionally secreted, no classical signal peptide [PMID:20978472]; ligand flagged secreted and not transmembrane [flag].","caveats":"Abstract read only; no affinity value. Evidence for each TAM receptor shares the same sentence, so receptor-specific binding strength not reported in our evidence. Detailed motif mapping is for MerTK.","key_references":[{"PMID":"20978472","why":"Tulp1 interacts with Tyro3, Axl and MerTK"}],"covers":["LR003426","LR006627"]},"LR004908":{"pair":"UCN2 -> CRHR1","headline":"Database-asserted only: GtoPdb lists urocortin 2 as a weak agonist at CRF1; no paper in our evidence confirms the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a full agonist [DB:GtoPdb]; no paper in our dossier tests direction or effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 5.3 to 5.4","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:15450949"}],"species_and_systems":"Species and system not reported in our evidence. The dossier covers human and mouse pairs.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"No papers were confirmed: 11 were judged abstract_insufficient and 2 concerned a different entity. The only record is one GtoPdb entry, and the pKd of 5.3 to 5.4 is low, so interaction is weak at best.","key_references":[],"covers":["LR001518","LR004908"]},"LR007338":{"pair":"ULBP3 -> HCST:KLRK1","headline":"ULBP3 engages the NKG2D receptor on NK cells; supported by one functional paper and a crystal structure with KLRK1.","interaction_type":"direct binding","direction_and_effect":"Agonist, activating: ULBPs stimulate cytokine and chemokine production from NK cells and make NK-resistant target cells susceptible to NK cytotoxicity [PMID:11239445]. The structural record is a database assertion of physical contact [DB:PDB 1KCG].","molecular_requirements":"NKG2D is required: anti-NKG2D antiserum blocked ULBP1-Fc binding to NKL cells, and the ULBPs are described as ligands for the activating receptor NKG2D/DAP10 [PMID:11239445]. HCST (DAP10) is named only through the statement that the receptor is 'probably NKG2D/DAP10'; HCST was not tested separately in our evidence [PMID:11239445].","affinity_potency":[],"species_and_systems":"Human proteins and human NKL cells, using Fc fusion proteins [PMID:11239445]. A crystal structure with chains of ULBP3 and KLRK1 exists [DB:PDB 1KCG]; IntAct lists X-ray crystallography, FACS and SPR records [DB:IntAct] [PMID:11754823] [PMID:18544572]; UniProt notes interaction with KLRK1/NKG2D [DB:UniProt] [PMID:11491531].","localisation_and_range":"Ligand is membrane-bound [flag]; the paper describes ULBPs as GPI-linked glycoproteins [PMID:11239445].","caveats":"Blocking evidence was shown with ULBP1-Fc, with the paper's text extending it to all ULBP/MIC-Fc fusions per the curator. Binding affinity is not reported in our evidence. Only one paper supports this pair [PMID:11239445]; it is functional in vitro (human NKL cells), read in full text. Database records add physical-interaction support only.","key_references":[{"PMID":"11239445","why":"ULBPs bind NKG2D on NK cells and stimulate cytotoxicity"}],"covers":["LR007338"]},"LR006636":{"pair":"UNC5B -> ROBO4","headline":"Robo4 extracellular domain binds UNC5B and activates it to counter VEGF signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"A protein-protein interaction screen with the Robo4 extracellular domain found specific binding to UNC5B [PMID:21238923]. Robo4 activates UNC5B, which inhibits signalling downstream of VEGF; so Robo4 acts on UNC5B, the reverse of the listed direction [PMID:21238923]. Function-blocking antibodies against either protein increase angiogenesis and disrupt vessel integrity [PMID:21238923].","molecular_requirements":"Soluble Robo4 rescues barrier defects in Robo4-/- mice but not in mice treated with anti-UNC5B, so functional UNC5B is required [PMID:21238923]. Other subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curators tag both partners as human; the abstract itself describes endothelial cells and Robo4-/- mice, so in vivo work is murine [PMID:21238923].","localisation_and_range":"Both are endothelial membrane guidance receptors; ROBO4 has only a receptor annotation [flag]. Soluble Robo4 protein was active in vivo [PMID:21238923].","caveats":"Read from the abstract only; no affinity, and the binding assay format is not specified. This is a receptor-receptor pairing, and the ligand/receptor labels are conventional.","key_references":[{"PMID":"21238923","why":"Robo4 binds and activates UNC5B to maintain vessel integrity"}],"covers":["LR003435","LR006636"]},"LR007077":{"pair":"VCAM1 -> ITGA4:ITGB7","headline":"No judged papers; support is a UniProt note and generic database records.","interaction_type":"database-asserted only","direction_and_effect":"UniProt notes ITGB7-containing integrin 'also interacts with VCAM1' (Probable) [DB:UniProt].","molecular_requirements":"Complex of ITGA4 and ITGB7 [flag].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Entity flags: VCAM1 secreted and transmembrane, complex transmembrane [flag].","caveats":"The only judged row was 'abstract_insufficient'. The Reactome and IntAct records shown concern alpha4beta1, not alpha4beta7 [DB:Reactome][DB:IntAct]; the UniProt text is hedged ('Probable').","key_references":[],"covers":["LR007077"]},"LR004917":{"pair":"VCAM1 -> ITGA9","headline":"VCAM-1 supports alpha9beta1-mediated adhesion in human cells; one confirmed paper, ITGA9 recorded alone.","interaction_type":"functional only","direction_and_effect":"alpha9beta1 mediates stable adhesion to recombinant VCAM-1 and to TNF-alpha-induced VCAM-1 on HUVEC; neutrophil migration on VCAM-1 was partially blocked by anti-alpha9beta1 or anti-alpha4 antibodies and fully blocked by both [PMID:10209034].","molecular_requirements":"The partner is alpha9beta1 heterodimer; ITGA9 alone was not tested [PMID:10209034].","affinity_potency":[],"species_and_systems":"Human: transfected SW480 and CHO cells, HUVEC and neutrophils [PMID:10209034]. Mouse pair is ortholog-inferred.","localisation_and_range":"Adhesion to cell-surface and recombinant VCAM-1; VCAM1 flagged secreted and transmembrane [flag].","caveats":"Functional adhesion, not binding affinity. Single paper. Reactome records the reaction [DB:Reactome].","key_references":[{"PMID":"10209034","why":"alpha9beta1 adhesion to VCAM-1 and neutrophil migration"}],"covers":["LR001528","LR004917"]},"LR004926":{"pair":"VEGFA -> FLT1","headline":"VEGFA binds FLT1 directly, supported by structure and mutagenesis; signalling role is complex and the soluble form acts as a trap.","interaction_type":"direct binding","direction_and_effect":"VEGF residues Asp63, Glu64 and Glu67 are associated with FLT-1 binding, separable from the KDR determinant, and FLT-1-deficient mutants still induced normal endothelial proliferation, implicating KDR rather than FLT-1 in mitogenesis [PMID:8621427]. Soluble FLT1 sequesters VEGF-A in mouse cornea, maintaining avascularity (decoy role) [PMID:17051153]. In bovine endothelial cells PGI2 synthesis required a VEGFR-1/VEGFR-2 heterodimer [PMID:15637071].","molecular_requirements":"Flt-1 domains 2 and 3 are necessary and sufficient for near-native VEGF binding; domain 2 alone binds 60-fold less tightly [PMID:9393862]. Prostacyclin response needs FLT1 plus KDR together [PMID:15637071].","affinity_potency":[],"species_and_systems":"Human VEGF with human FLT-1 in the structure and mutagenesis papers [PMID:9393862, PMID:8621427]; bovine aortic endothelial cells [PMID:15637071]; mouse cornea in vivo [PMID:17051153]. Crystal structures 1FLT, 1QTY, 5T89 [DB:PDB 1FLT].","localisation_and_range":"VEGFA is flagged secreted and FLT1 transmembrane [flag]; the soluble FLT1 isoform is secreted per the cornea paper [PMID:17051153].","caveats":"Three of four papers were read as abstracts only. The cornea paper is about the soluble isoform, not the full-length receptor. No affinity values in our evidence. Database support: Reactome, IntAct, BioGRID, GtoPdb [DB:Reactome].","key_references":[{"PMID":"9393862","why":"Crystal structure of VEGF with Flt-1 domain 2"},{"PMID":"8621427","why":"Mutagenesis mapping of FLT-1 and KDR binding determinants"},{"PMID":"17051153","why":"Soluble FLT1 traps VEGF-A in cornea"}],"covers":["LR001537","LR004926"]},"LR006645":{"pair":"VEGFA -> PDGFRB","headline":"Cross-family VEGF-A binding to PDGFR-beta measured by SPR with high affinity; single abstract-level paper, no independent replication in our evidence.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-A bound PDGFR-beta in surface plasmon resonance; curators label the effect agonist, but the paper reports binding kinetics, not signalling [PMID:29180757].","molecular_requirements":"Not reported in our evidence (no subunit or co-receptor requirements); receptor is a single chain.","affinity_potency":[{"value":"KD = 340 pM","assay":"surface plasmon resonance (BIAcore)","system":"recombinant human proteins","cite":"PMID:29180757"}],"species_and_systems":"Human ligand and receptor, purified recombinant proteins in vitro [PMID:29180757]. The mouse pair is inferred from human evidence (ortholog projection).","localisation_and_range":"VEGFA is flagged secreted and PDGFRB transmembrane [flag]; this implies paracrine action on receptor-bearing cells.","caveats":"Only one paper; curator read depth is abstract only, although full-text excerpts describe the SPR method and chi2-to-Rmax cut-off. The paper calls the interaction recent/previously reported but quantified here for the first time. IntAct lists a cross-linking record (PMID 17470632) [DB:IntAct]. No cell-based functional test in our evidence.","key_references":[{"PMID":"29180757","why":"SPR kinetics of VEGF-A:PDGFR-beta, KD = 340 pM"}],"covers":["LR003444","LR006645"]},"LR004935":{"pair":"VEGFC -> FLT4","headline":"VEGF-C is a well-supported agonist ligand of FLT4 (VEGFR-3), with two concurrent discovery papers, functional and in vivo studies, and structures.","interaction_type":"direct binding","direction_and_effect":"VEGF-C binds Flt4 and induces tyrosine autophosphorylation of VEGFR-3 and VEGFR-2 [PMID:8617204]. VRP, described in the notes as later recognised as VEGF-C, binds the Flt4 extracellular domain and stimulates its phosphorylation, without appreciable binding to Flt1 or Flk1 [PMID:8700872]. Effect is stimulatory.","molecular_requirements":"VEGF-C is proteolytically processed [PMID:8617204], and ADAMTS3 with CCBE1 is needed to convert VEGFC into an active ligand in the in vivo study [PMID:27159393]. In lymphatic endothelial cells VEGF-C also induced VEGFR-3/VEGFR-2 heterodimers in which VEGFR-3 was phosphorylated at three of five sites [PMID:12881528].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in all shown papers, including primary lymphatic endothelial cells and isolated lymphatic endothelial cells [PMID:12881528] [PMID:11532940]; mouse genetics are described in the in vivo paper [PMID:27159393]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted and FLT4 transmembrane [flag].","caveats":"All papers were read as abstracts. The cancer-invasion paper treats the pairing as background [PMID:16530705]. Eleven rows were confirmed but only six are shown here; two more were review-only. No affinity in our evidence. Structures exist [DB:PDB 4BSK].","key_references":[{"PMID":"8617204","why":"VEGF-C identified as Flt4 ligand"},{"PMID":"8700872","why":"independent discovery, specific Flt4 binding"},{"PMID":"27159393","why":"proteolytic activation of VEGFC in vivo"}],"covers":["LR001546","LR004935"]},"LR004944":{"pair":"VIP -> VIPR1","headline":"Well-established direct VIP agonist binding to VPAC1, with many human recombinant studies, sub-nanomolar to low-nanomolar affinity, and structures.","interaction_type":"direct binding","direction_and_effect":"VIP binds human VPAC1 and stimulates cAMP; in transfectants it also raised intracellular calcium [PMID:8074647]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"VIP residues His1, Val5, Arg14, Lys15, Lys21, Leu23 and Ile26 interact with VPAC1 by alanine scan [PMID:10801840]. Receptor N-terminal ectodomain is essential: E36A abolished 125I-VIP binding [PMID:9454823], W67A abolished binding [PMID:11027527], and VIP Phe6-Tyr22 contacts fragment 104-108 of that domain [PMID:15247290]. A PDB structure exists [DB:PDB 8E3Z].","affinity_potency":[{"value":"Kd 0.2-0.8 nM","assay":"[125I]VIP binding","system":"HEK293/CHO stable transfectants, human VIP1 receptor","cite":"PMID:8074647"},{"value":"Kd 0.8 nM","assay":"saturable VIP binding","system":"COS-7 and 293 cells, human receptor","cite":"PMID:8390245"},{"value":"Ki 0.9 nM","assay":"competition of [125I]VIP binding","system":"CHO clone, human VIP1 receptor","cite":"PMID:8791009"},{"value":"Ki 3.4 nM","assay":"competitive binding","system":"CHO transfectants, human VIPR1","cite":"PMID:9152366"}],"species_and_systems":"Mostly human recombinant receptor in CHO, HEK293 and COS cells; native HT29 cells also respond [PMID:8074647]. Mouse pair is not ortholog-inferred in the record, but no mouse experiment is shown in the papers displayed.","localisation_and_range":"VIP is flagged secreted and VIPR1 transmembrane [flag].","caveats":"Many papers are analogue or mutagenesis studies using VIP as reference, not studies of the endogenous pair itself. VIP also binds VPAC2 with similar affinity, so it is not VPAC1-selective [PMID:10801840]. Only abstracts were read for the papers shown.","key_references":[{"PMID":"8074647","why":"Human VPAC1 binds VIP, couples to cAMP and calcium"},{"PMID":"8791009","why":"Pharmacology of recombinant human VIP1 receptor; VIP highest affinity"},{"PMID":"10801840","why":"Alanine scan of VIP on VPAC1 and VPAC2"}],"covers":["LR001555","LR004944"]},"LR004953":{"pair":"VTN -> ITGB6","headline":"A vitronectin fragment, VTN(381-397), binds alphaVbeta6 and antagonises TGF-beta1 activation; full-length vitronectin is not shown.","interaction_type":"direct binding","direction_and_effect":"In a competition assay the VTN(381-397) peptide bound only alphaVbeta6 and prevented TGF-beta1 activation in human fibroblast-like synoviocytes, acting as an antagonist [PMID:33526813].","molecular_requirements":"Beta6 acts as alphaVbeta6; the evidence is for a fragment, not the whole protein [PMID:33526813].","affinity_potency":[{"value":"IC50 = 3.2 \u00b5M","assay":"competition with radiolabelled echistatin","system":"recombinant human alphaVbeta6, VTN(381-397) peptide","cite":"PMID:33526813"},{"value":"IC50 = 0.79 \u00b5M","assay":"same competition assay","system":"VTN(365-381) fragment at alphaVbeta6","cite":"PMID:33526813"}],"species_and_systems":"Human integrin and primary human synoviocytes [PMID:33526813]; mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"The fragment, not intact vitronectin, was tested at alphaVbeta6. The paper also noted that 10 ng/mL fragment increased alpha-SMA. Chain-only entry. 3 other abstracts were insufficient. One of the confirmed papers (full text) is the only support.","key_references":[{"PMID":"33526813","why":"VTN fragment competition at alphaVbeta6 with IC50 values"}],"covers":["LR001564","LR004953"]},"LR001569":{"pair":"VWF -> ITGA2B","headline":"VWF binds platelet GPIIb/IIIa (alphaIIb) via RGDS and C4 domain; evidence from two abstract-only papers, chain-level.","interaction_type":"functional only","direction_and_effect":"RGDS point mutants of recombinant vWF could not displace 125I-vWF from thrombin- or ADP-activated platelets, so the RGDS site is needed for GPIIb/IIIa binding [PMID:1737795]. A cell-based assay with HEK293 cells expressing constitutively active GPIIb/IIIa measured binding of 14 VWF C domain mutants; four showed significantly reduced binding [PMID:31035301]. Curated effect is stimulatory.","molecular_requirements":"The receptor is the alphaIIb-beta3 complex (GPIIb/IIIa), activated by inside-out signalling [PMID:31035301]; VWF binds through RGDS and its C4 domain.","affinity_potency":[],"species_and_systems":"Human proteins; CHO-produced recombinant vWF with platelets and HUVEC, and HEK293 cells [PMID:1737795] [PMID:31035301]. Reactome and IntAct list the alphaIIbbeta3:VWF interaction [DB:Reactome] [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Both papers are abstract-only. Evidence is for the GPIIb/IIIa complex, not alphaIIb alone, and the first paper infers the receptor from platelet binding. No affinity reported.","key_references":[{"PMID":"1737795","why":"RGDS mutations impair vWF binding to activated platelets"},{"PMID":"31035301","why":"cell-based GPIIb/IIIa binding assay for VWF C domain variants"}],"covers":["LR001569","LR004958"]},"LR006654":{"pair":"VWF -> ITGAV","headline":"VWF strings on endothelial cells bind integrin alphavbeta3; functional evidence in one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"RGDS peptide or a function-blocking anti-alphavbeta3 antibody reduced the number of VWF strings formed, integrin alphav decorated the strings, and alphav shRNA knockdown impaired string retention [PMID:18927433]. The curated effect is agonist.","molecular_requirements":"The integrin is alphavbeta3, so ITGB3 is also required; P-selectin is also implicated in anchoring [PMID:18927433].","affinity_potency":[],"species_and_systems":"Live human umbilical vein endothelial cells after histamine stimulation, with shear flow [PMID:18927433]. Mouse pair is ortholog-inferred.","localisation_and_range":"VWF strings several hundred micrometers long are tethered to the endothelial cell surface [PMID:18927433].","caveats":"Abstract-only read. Functional anchoring evidence, not purified binding; no affinity. Database support is for alphaVbeta3:VWF [DB:Reactome].","key_references":[{"PMID":"18927433","why":"alphavbeta3 anchors VWF strings on endothelial cells"}],"covers":["LR003454","LR006654"]},"LR003459":{"pair":"VWF -> STAB2","headline":"Stabilin-2 binds and internalises VWF and mediates VWF-FVIII clearance; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Stabilin-2-expressing cells bind and internalise human VWF and FVIII in a VWF-dependent manner, and stabilin-2-deficient mice had prolonged human VWF-FVIII half-life [PMID:30124466]. Variant p.E2377K decreased stabilin-2 expression and impaired VWF endocytosis. Acts as a clearance receptor.","molecular_requirements":"Binding was VWF-dependent for FVIII uptake [PMID:30124466]; further requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human VWF with mouse in vivo and heterologous cell expression [PMID:30124466]. Both pairs are listed, mouse not ortholog-inferred.","localisation_and_range":"Endothelial scavenger receptor [PMID:30124466].","caveats":"Abstract-only read. The curated binding label comes from cell uptake, not purified binding. No affinity reported.","key_references":[{"PMID":"30124466","why":"stabilin-2 clears VWF-FVIII"}],"covers":["LR003459","LR006659"]},"LR008409":{"pair":"VWF -> TNFRSF11B","headline":"Osteoprotegerin (OPG) is physically complexed with VWF by co-IP; OPG is a secreted decoy, not a classic receptor.","interaction_type":"direct binding","direction_and_effect":"Reciprocal co-immunoprecipitation showed OPG is physically complexed with vWF in Weibel-Palade bodies, after secretion from endothelial cells, and in plasma [PMID:15799029]. Signalling direction is not reported in our evidence.","molecular_requirements":"OPG was not associated with P-selectin; no domain requirements are reported in our evidence [PMID:15799029].","affinity_potency":[],"species_and_systems":"Human HUVEC and plasma [PMID:15799029].","localisation_and_range":"TNFRSF11B has receptor and transmembrane flags of 0 [flag]; OPG colocalises with VWF in Weibel-Palade bodies [PMID:15799029].","caveats":"Co-IP shows association, not necessarily direct binding. Abstract-only. OPG is flagged non-receptor, so ligand-receptor framing is questionable.","key_references":[{"PMID":"15799029","why":"OPG complexed with VWF by reciprocal co-IP"}],"covers":["LR008409"]},"LR008049":{"pair":"WNT1 -> FZD2:LRP6","headline":"WNT1 to FZD2:LRP6 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]; BioGRID lists a reconstituted LRP6-WNT1 complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"No verified paper. Reactome records here are Wnt1:Frizzled1 complexes, not FZD2 [DB:Reactome].","key_references":[],"covers":["LR008049"]},"LR008058":{"pair":"WNT1 -> FZD4:LRP6","headline":"WNT1 to FZD4:LRP6 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]; BioGRID lists a reconstituted LRP6-WNT1 complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"No verified paper. Reactome records are Wnt1:Frizzled1 complexes, not FZD4 [DB:Reactome].","key_references":[],"covers":["LR008058"]},"LR008067":{"pair":"WNT1 -> FZD5:LRP6","headline":"WNT1 to FZD5:LRP6 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]; BioGRID lists a reconstituted LRP6-WNT1 complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"No verified paper. Reactome records are Wnt1:Frizzled1 complexes, not FZD5 [DB:Reactome].","key_references":[],"covers":["LR008067"]},"LR006663":{"pair":"WNT1 -> FZD6","headline":"Recombinant WNT-1 changes FZD6 membrane mobility in a FRAP assay in HEK293T/17 cells; functional evidence.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-1 increased the FZD6-GFP mobile fraction, indicating action on this receptor, classed as agonist [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility appear linked to putative precoupling of Gi/o proteins, since pertussis toxin and N-ethylmaleimide altered the effect [PMID:24873871].","affinity_potency":[],"species_and_systems":"Human FZD6-GFP in HEK293T/17 cells; the recombinant WNT proteins' species is not confirmed in the text [PMID:24873871]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Lateral-mobility readout is indirect and not a binding or affinity measurement; no affinity reported in our evidence.","key_references":[{"PMID":"24873871","why":"FRAP shows WNT-1 acts on FZD6"}],"covers":["LR003463","LR006663"]},"LR001578":{"pair":"WNT1 -> LRP6","headline":"WNT1 binds the LRP6 ectodomain; two abstract-level papers plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"The LRP6 extracellular domain bound Wnt-1 and associated with Fz in a Wnt-dependent manner; LRP6 acted as a Wnt co-receptor [PMID:11029007]. Anti-LRP6 antibodies defined Wnt1-class proteins as engaging the first propeller domain [PMID:20713706].","molecular_requirements":"Wnt1-class proteins use LRP6's first propeller, distinct from Wnt3a-class proteins (third propeller) [PMID:20713706]. Fz association was Wnt-dependent [PMID:11029007].","affinity_potency":[],"species_and_systems":"Xenopus embryos and ectodomain binding [PMID:11029007]; phage-display antibodies and MMTV-Wnt1 xenografts [PMID:20713706]. Both abstract only. Curators record human species; the abstracts do not state it.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Propeller assignment is inferred from antibody epitope mapping, not direct Wnt1 mapping. BioGRID lists a reconstituted complex [DB:BioGRID]. Four papers were abstract_insufficient.","key_references":[{"PMID":"11029007","why":"LRP6 ectodomain binds Wnt-1"},{"PMID":"20713706","why":"Wnt1 uses LRP6 first propeller"}],"covers":["LR001578","LR004967"]},"LR007473":{"pair":"WNT1 -> WIF1","headline":"Database-asserted only: BioGRID lists a WNT1-WIF1 affinity capture; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID records WIF1-WNT1 by affinity capture-western [DB:BioGRID]. The interaction is annotated inhibitory; the mechanism is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the record are not reported in our evidence.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"One paper was review_only and another a different entity; no verified primary paper.","key_references":[],"covers":["LR007473"]},"LR008148":{"pair":"WNT10A -> FZD5:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD5:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: abstract_insufficient 1.","key_references":[],"covers":["LR008148"]},"LR003468":{"pair":"WNT10B -> FZD6","headline":"Several human-cell studies support WNT10B acting on FZD6, mostly functional; one co-IP shows association in HEK293T.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-10B (among other WNTs) increased FZD6-GFP mobile fraction in FRAP, an agonist-type effect [PMID:24873871]. In co-culture IP, FZD6 co-precipitated Wnt10b, and SMOC-2 enhanced the Wnt10b-Fzd6 binding [PMID:30594556]. A third paper, titled 'FZD6 triggers Wnt-signalling driven by WNT10B', is abstract-only and truncated [PMID:33497493].","molecular_requirements":"FZD6 alone was sufficient in the FRAP and co-IP assays. The co-IP also tested LRP6 separately [PMID:30594556]. SMOC-2 enhances the interaction in that system.","affinity_potency":[],"species_and_systems":"HEK293T/17 cells with human FZD6-GFP and recombinant WNT proteins, whose species is not confirmed in the text [PMID:24873871]; HEK293T co-culture IP with tagged proteins [PMID:30594556]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; the IP used co-cultured ligand-expressing and receptor-expressing cells [PMID:30594556].","caveats":"FRAP shows an effect on the receptor, not binding, and the paper's own selectivity claim is about which WNTs act on FZD6. The co-IP is of tagged overexpressed proteins. The 33497493 evidence is the title only.","key_references":[{"PMID":"24873871","why":"WNT-10B changes FZD6 mobility in FRAP (full text)"},{"PMID":"30594556","why":"Fzd6 co-precipitates Wnt10b; SMOC-2 enhances binding"},{"PMID":"33497493","why":"Title reports FZD6 triggering WNT10B-driven signalling; abstract truncated"}],"covers":["LR003468","LR006668"]},"LR007509":{"pair":"WNT11 -> WIF1","headline":"WNT11 to WIF1 is annotated as an inhibitory ligand-ligand pair with an IntAct SPR record only.","interaction_type":"database-asserted only","direction_and_effect":"The pair is classed Ligand-Ligand with an inhibitory effect [flag]; WIF1 is not annotated as a receptor [flag]. IntAct holds a surface plasmon resonance record for Q9Y5W5 and O96014 [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"No paper was judged as confirming the pair (one review-only, two abstract_insufficient). The IntAct record's affinity and species are not reported in our evidence. WIF1 acts as an extracellular binder, not a signalling receptor, so CCC tools should treat it as an inhibitor.","key_references":[],"covers":["LR007509"]},"LR005367":{"pair":"WNT2 -> FZD4","headline":"Fzd4 is reported as a Wnt2 receptor in hepatic sinusoidal endothelial cells by pull-down and co-IP; abstract only.","interaction_type":"direct binding","direction_and_effect":"GST pull-down and co-IP showed Fzd4 to be a novel Wnt2 receptor in HSECs; Wnt2 stimulated HSEC proliferation and canonical beta-catenin signalling (agonist annotated) [PMID:18302287].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Isolated hepatic sinusoidal endothelial cells; dossier lists receptor species as rat and ligand as human; human and mouse pairs are ortholog-inferred [PMID:18302287].","localisation_and_range":"Wnt2 flagged secreted [flag]; autocrine in HSECs [PMID:18302287].","caveats":"Abstract only; the pull-down details are not shown. Cell-type-specific finding. No affinity.","key_references":[{"PMID":"18302287","why":"Fzd4 as Wnt2 receptor in HSECs: pull-down and co-IP"}],"covers":["LR002041","LR005367"]},"LR003477":{"pair":"WNT2 -> FZD6","headline":"WNT2 changes FZD6 surface mobility in live cells (FRAP); a functional readout, not binding.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-2 among WNT-1, -3A, -4, -5A, -7A, -9B and -10B affected FZD6-GFP lateral mobility, taken to mean they act on FZD6 [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility relate to Gi/o precoupling (blocked by pertussis toxin and NEM) [PMID:24873871].","affinity_potency":[],"species_and_systems":"HEK293 cells expressing FZD6-GFP, commercial recombinant WNTs; WNT species not reported in our evidence. Mouse pair ortholog-inferred.","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"FRAP shows an effect on the receptor but not direct binding; no affinity reported.","key_references":[{"PMID":"24873871","why":"FRAP of FZD6-GFP shows WNT-2 effect"}],"covers":["LR003477","LR006677"]},"LR004971":{"pair":"WNT2 -> FZD8","headline":"Functional evidence only: WNT2 with FZD8 activates TCF reporter in human cell lines; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Canonical Wnt/TCF signalling was activated when Wnt-2 and Frizzled-8 were co-expressed; a dominant-negative Wnt-2 construct blocked it [PMID:23815780].","molecular_requirements":"Not reported in our evidence (no co-receptor or subunit test).","affinity_potency":[],"species_and_systems":"Human cell lines (293T, 293, A549, A427) and a xenograft mouse model; mouse pair is projected from human evidence [PMID:23815780].","localisation_and_range":"WNT2 is annotated as secreted [flag]; FZD8 is a receptor, not secreted [flag].","caveats":"No direct binding shown; co-expression readout only. Read from abstract only, so details are limited [PMID:23815780]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"23815780","why":"Co-expression activates TCF reporter; dominant-negative Wnt-2 blocks it"}],"covers":["LR001582","LR004971"]},"LR008184":{"pair":"WNT2 -> FZD9:LRP5","headline":"Co-immunoprecipitation shows WNT2-FZD9 interaction in human cumulus cells; LRP5 contribution not shown.","interaction_type":"direct binding","direction_and_effect":"WNT2 antibody co-precipitated FZD3 and FZD9, but only FZD9 antibody precipitated WNT2; authors suggest WNT2 acts through FZD9 on the beta-catenin pathway [PMID:19038973].","molecular_requirements":"Evidence concerns FZD9 only; LRP5 is not reported in this paper's abstract, so the complex is not tested as such [PMID:19038973].","affinity_potency":[],"species_and_systems":"Human cumulus cells from IVF oocytes, endogenous proteins [PMID:19038973].","localisation_and_range":"WNT2 is annotated as secreted [flag].","caveats":"Complex pair rests on a FZD9-only result. Co-IP is asymmetric (WNT2 pulled down by FZD9 antibody only). Abstract read only [PMID:19038973].","key_references":[{"PMID":"19038973","why":"Co-IP of WNT2 with FZD9 in human cumulus cells"}],"covers":["LR008184"]},"LR006681":{"pair":"WNT2B -> FZD6","headline":"Direct binding evidence: WNT2B transfers to purified FZD6-CRD (preprint, human proteins).","interaction_type":"direct binding","direction_and_effect":"WNT2B was rapidly transferred from SFRP2 and GPC4 to FZD6-CRD; the paper treats WNT2B as non-canonical and FZD6 rescued FZD-knockout cells [PMID:39229119].","molecular_requirements":"FZD6 cysteine-rich domain sufficient for transfer; carriers SFRP2 or GPC4 used [PMID:39229119].","affinity_potency":[],"species_and_systems":"Purified human proteins and HEK293 cells [PMID:39229119]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"bioRxiv preprint, not peer reviewed. No affinity value reported [PMID:39229119].","key_references":[{"PMID":"39229119","why":"WNT2B transferred to FZD6-CRD"}],"covers":["LR003481","LR006681"]},"LR003486":{"pair":"WNT3 -> FZD4","headline":"Wnt3 induced signalling through FZD4 in a human cell reporter screen, a generic functional result; mouse pair is projected.","interaction_type":"functional only","direction_and_effect":"Agonist-type signalling: the paper states \"Wnt3/Wnt3a induced signaling via all FZDs, in contrast to other Wnts that were more selective\" [PMID:28733458].","molecular_requirements":"Co-receptor and subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T FZD1,2,7 (and FZD1,2,4,5,7,8) CRISPR-mutant cells, TCF4/Wnt luciferase [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"The sentence is generic across FZDs; specifics sit in a figure matrix not in the dossier. Functional rescue only, no binding. Many other papers were abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD rescue map in CRISPR FZD-mutant HEK293T cells"}],"covers":["LR003486","LR006686"]},"LR001596":{"pair":"WNT3 -> FZD8","headline":"The only curated paper concerns Wnt3A, not WNT3, and shows IGFBP-4 blocking Wnt3A binding to Frizzled 8; WNT3-FZD8 is not shown directly.","interaction_type":"database-asserted only","direction_and_effect":"IGFBP-4 physically interacted with Frizzled 8 and LRP6 and inhibited the binding of Wnt3A to them; this is inhibition by a competitor, not Wnt3 agonism [PMID:18528331].","molecular_requirements":"Not reported in our evidence for WNT3.","affinity_potency":[],"species_and_systems":"Experimental species not specified in the dossier; abstract only [PMID:18528331].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"The paper names Wnt3A, a different ligand from WNT3, and its main finding is IGFBP-4 antagonism; it does not show a WNT3-FZD8 interaction. Abstract only.","key_references":[{"PMID":"18528331","why":"Wnt3A binding to Frz8 inhibited by IGFBP-4 (Wnt3A, not WNT3)"}],"covers":["LR001596","LR004985"]},"LR008094":{"pair":"WNT3 -> FZD8:LRP6","headline":"No curated paper supports WNT3 -> FZD8:LRP6; the only record is a database interaction entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the complex name.","affinity_potency":[],"species_and_systems":"Species of the database experiment not reported in our evidence; the pair is annotated human.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"No paper was confirmed for this pair (outcomes: review_only, abstract_insufficient, different_entity). The one IntAct record is a surface plasmon resonance entry for accession pair O75581-P56703 [DB:IntAct] and does not identify the Frizzled member [PMID:31036956].","key_references":[],"covers":["LR008094"]},"LR007617":{"pair":"WNT3 -> SFRP5","headline":"Only a computational docking study links WNT3 and SFRP5; it ranks SFRP5 among the lowest-affinity SFRP partners.","interaction_type":"functional only","direction_and_effect":"SFRP5 is an annotated Wnt antagonist class (SFRP family); docking found SFRP3 has the highest binding affinity to Wnt3 while SFRP1 and SFRP5 have the lowest [PMID:40372458].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In silico homology models and molecular dynamics of human SFRPs; no wet experiment [PMID:40372458]. Abstract only.","localisation_and_range":"SFRPs are secreted antagonists that act near secreting cells when positively charged [PMID:40372458].","caveats":"Computational only; no measured binding. Interaction class is Ligand-Ligand (inhibitor), not a receptor interaction. Docking affinity is a model output without a reported value.","key_references":[{"PMID":"40372458","why":"Docking of SFRPs with Wnt3"}],"covers":["LR007617"]},"LR006690":{"pair":"WNT3A -> FZD3","headline":"Functional evidence only: FZD3 mediates Wnt-3a-driven neurite outgrowth via a noncanonical route.","interaction_type":"functional only","direction_and_effect":"Recombinant Wnt-3a stimulated neurite formation in Ewing sarcoma family tumor cells, and Fzd3 antiserum or siRNA markedly reduced it [PMID:18212053]. Disrupting the Wnt/Fzd/LRP complex or LRP5/LRP6 knockdown enhanced neuritogenesis, indicating a beta-catenin-independent response [PMID:18212053].","molecular_requirements":"Dishevelled-2 and Dvl-3 knockdown suppressed outgrowth [PMID:18212053]. LRP5/6 were not required.","affinity_potency":[],"species_and_systems":"Human Ewing sarcoma family tumor cells, recombinant Wnt-3a [PMID:18212053]. Mouse interaction is ortholog-inferred.","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Abstract-only; no direct binding assay shown in our evidence and no affinity. A second confirmed paper exists but is not shown. No database record.","key_references":[{"PMID":"18212053","why":"Fzd3 needed for Wnt-3a-induced neurite outgrowth"}],"covers":["LR003490","LR006690"]},"LR008139":{"pair":"WNT3A -> FZD4:LRP5","headline":"No curated paper for this complex; support is only a UniProt note.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"Complex needs both FZD4 and LRP5 as modeled; no evidence shows which subunit is required.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Only UniProt subunit notes, which say an interaction is enhanced in the presence of GSK3B and WNT1 or WNT3A [DB:UniProt]; they do not show direct WNT3A binding to this FZD4:LRP5 complex. Papers were judged review_only or abstract_insufficient.","key_references":[],"covers":["LR008139"]},"LR001587":{"pair":"WNT3A -> FZD5","headline":"WNT3A activates FZD5 in cells, with strong CRD binding reported; both papers are indirect for FZD5 specifically.","interaction_type":"direct binding","direction_and_effect":"WNT-3A activated the WNT-beta-catenin pathway through FZD5 in 32D cells, agonist effect [PMID:25605717]. Wnt3a induced signaling through a broad range of FZDs in a CRISPR FZD-mutant system [PMID:28733458].","molecular_requirements":"LRP6 phosphorylation accompanied activation [PMID:25605717]. Excerpts describe FZD5 and FZD8 as the most promiscuous receptors and FZD5 as effective for canonical signaling, citing prior work [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human ligand and receptor [PMID:25605717]; 32D cells and HEK293T CRISPR mutants [PMID:28733458]. Human and mouse versions are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"PMID:25605717 was read as abstract only; FZD5-specific affinity is not reported in our evidence. PMID:28733458 gives a generic statement across FZDs. A UniProt/IntAct record concerns other partners of this complex [DB:UniProt] [DB:IntAct].","key_references":[{"PMID":"25605717","why":"Binding map and FZD5-dependent canonical activation by WNT-3A"},{"PMID":"28733458","why":"Wnt3a signals via FZDs in a functional rescue map"}],"covers":["LR001587","LR004976"]},"LR008076":{"pair":"WNT3A -> FZD5:LRP6","headline":"No curated paper for this complex; support is database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"UniProt says LRP6 interacts via beta-propeller regions 3 and 4 with WNT3A [DB:UniProt]; FZD5 contribution is only from separate interaction notes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records include BioGRID [DB:BioGRID], IntAct including bio-layer interferometry [DB:IntAct], and Reactome WNT3A:FZD:LRP5/6 complexes [DB:Reactome]. Papers were review_only.","key_references":[],"covers":["LR008076"]},"LR003495":{"pair":"WNT3A -> LRP5","headline":"Wnt3a-conditioned medium acts through LRP5 to recruit Axin and activate signalling; direct binding is only supported computationally.","interaction_type":"functional only","direction_and_effect":"LRP-5 enhances Wnt-3a effects: Wnt-3a medium translocates Axin to the membrane in an LRP-5 dependent manner and raises Axin-LRP-5 FRET within minutes [PMID:11336703]. LRP5 is a stimulatory co-receptor.","molecular_requirements":"LRP-5 works with Wnt; its intracellular domain binds Axin (the last 40 C-terminal amino acids) [PMID:11336703]. A modelling study suggests Wnt3a has a protruding loop favouring LRP5/6 binding [PMID:25425204].","affinity_potency":[],"species_and_systems":"Human LRP-5 in 3T3 and other cells with Wnt-3a conditioned medium [PMID:11336703]; docking and homology modelling [PMID:25425204]. Human pair, mouse version projected.","localisation_and_range":"LRP5 is flagged transmembrane [flag].","caveats":"No direct binding assay in our evidence. The computational paper was read as abstract only and concerns LRP6 mainly [PMID:25425204]. UniProt notes the Axin interaction is enhanced by WNT3A [DB:UniProt].","key_references":[{"PMID":"11336703","why":"Wnt-3a drives LRP-5 dependent Axin translocation"},{"PMID":"25425204","why":"modelling of Wnt3a binding to LRP5/6"}],"covers":["LR003495","LR006695"]},"LR004980":{"pair":"WNT3A -> LRP6","headline":"WNT3A binds the LRP6 E3E4 propeller region directly and activates canonical signalling; well supported.","interaction_type":"direct binding","direction_and_effect":"Wnt3a activates canonical signalling through LRP6 [PMID:12897152]. Wnt3a-class antibodies binding the third propeller block Wnt3a signalling [PMID:20713706].","molecular_requirements":"Wnt3a binds LRP6 at the third and fourth beta-propeller domains (E3E4); it binds with Fz8 CRD in a reconstituted complex, and Wnt3a and Wnt9b can bind LRP6 simultaneously [PMID:20093360]. Wnt3a binding also involves the third propeller [PMID:20713706]. Wnt triggers an intracellular conformational switch [PMID:12897152].","affinity_potency":[],"species_and_systems":"Purified insect-cell mouse Fz8 CRD and human LRP6 ectodomain [PMID:20093360]; MMTV-Wnt3 xenografts [PMID:20713706]; HEK293T co-IP [PMID:30594556]. Mouse version listed separately, not projected.","localisation_and_range":"Ligand flagged secreted, LRP6 transmembrane [flag]; membrane-level Wnt-co-receptor complex with FZD [DB:Reactome].","caveats":"Most papers read as abstracts. A binding-affinity determination is mentioned but the values are not in our evidence. Database support: BioGRID, IntAct, Reactome and UniProt [DB:BioGRID] [DB:IntAct]. PMID 30594556 is mainly about SMOC-2 enhancing the interaction.","key_references":[{"PMID":"20093360","why":"purified-protein binding of Wnt3a to LRP6 E3E4"},{"PMID":"20713706","why":"antibody epitope mapping of Wnt3a-class LRP6 site"},{"PMID":"12897152","why":"Wnt activation of LRP6 signalling"}],"covers":["LR001591","LR004980"]},"LR008157":{"pair":"WNT5A -> FZD5:LRP5","headline":"No paper evidence for WNT5A with the FZD5:LRP5 complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. Reactome lists WNT5A:FZD plasma membrane complexes [DB:Reactome]; UniProt (Q13467) notes in vitro activation of WNT5A signaling [DB:UniProt].","molecular_requirements":"Not reported in our evidence; records concern individual chains.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone; the judged papers were review-only.","key_references":[],"covers":["LR008157"]},"LR006708":{"pair":"WNT5A -> TLR2","headline":"WNT5A binds TLR2 directly (SPR, pulldown) and signals through it in human myeloid cells; one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Wnt5a binds TLR2 and TLR4 and drives MyD88-dependent signalling; in human myeloid cells it induces IL-10 and tolerance, while in mouse cells the profile is pro-inflammatory [PMID:31098409].","molecular_requirements":"Dominant-negative TLR2/TLR4 in THP-1 cells reduced Wnt5a-induced IL-10 and IL-8; the IL-10 response depended on TLR2/4-MyD88 [PMID:31098409]. Other subunits or co-receptors for TLR2: not reported in our evidence.","affinity_potency":[{"value":"KD 26.5 \u00b1 4.5 nM","assay":"SPR, TLR2 on surface, Wnt5a injected (Table 1)","system":"recombinant proteins","cite":"PMID:31098409"}],"species_and_systems":"Human THP-1 cells and primary monocytes plus mouse cells; recombinant proteins for binding [PMID:31098409].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Single paper, curated from the abstract although full-text excerpts were available. Antibodies against the LPS-binding site of TLR2/4 did not block Wnt5a-induced IL-10 [PMID:31098409]. The text gives ~27, 45 and 36 nM in the order TLR4, TLR4/MD2, TLR2, which does not match Table 1 [PMID:31098409].","key_references":[{"PMID":"31098409","why":"SPR binding, pulldown/MS and TLR-dependence in myeloid cells"}],"covers":["LR003508","LR006708"]},"LR008562":{"pair":"WNT5B -> FZD6","headline":"Only a docking study of homology models suggests WNT5B-FZD6 binding.","interaction_type":"computational prediction only","direction_and_effect":"Direction not reported; in silico docking only [PMID:31285641].","molecular_requirements":"Cysteine-rich domain of FZDs docked into a palm-shaped opening or near the largest binding pocket, as in hWnt5b-hFzd6 [PMID:31285641].","affinity_potency":[],"species_and_systems":"Human protein homology models, docking; no wet-lab experiment [PMID:31285641].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Computational only, abstract only, no measured affinity in our evidence. Models were generated by homology modeling [PMID:31285641]. Another paper was review-only.","key_references":[{"PMID":"31285641","why":"docking of hWnt5b against hFzd isoforms"}],"covers":["LR008562"]},"LR006717":{"pair":"WNT6 -> FZD4","headline":"Wnt6 and FZD4 knockdown or antibody blockade reduce centrosome amplification; binding is suggested, not shown.","interaction_type":"functional only","direction_and_effect":"Agonist: secreted Wnt6-FZD4-beta-catenin signalling is upstream of ROCK1 and 14-3-3 sigma; Wnt6 or FZD4 siRNA or antibodies attenuated centrosome amplification [PMID:31618077].","molecular_requirements":"Beta-catenin dependent; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured cells (species not stated in the abstract) and diabetic mouse colon tissue [PMID:31618077].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding is only suggested ('It is suggested that secreted Wnt6 binds to FZD4') [PMID:31618077]. Abstract only.","key_references":[{"PMID":"31618077","why":"Wnt6-FZD4-beta-catenin in diabetes-linked centrosome amplification"}],"covers":["LR003517","LR006717"]},"LR008085":{"pair":"WNT7A -> FZD7:LRP6","headline":"Complex support is the WNT7A linker-FZD7 binding only; LRP6 is untested.","interaction_type":"direct binding","direction_and_effect":"The WNT7A C-terminal linker binds FZD7 without activating non-canonical signalling [PMID:36420144].","molecular_requirements":"LRP6 is not addressed in the evidence shown.","affinity_potency":[],"species_and_systems":"Myogenic cells [PMID:36420144].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP6 is flagged transmembrane [flag].","caveats":"Chain-only evidence for FZD7; abstract only; fragment binding.","key_references":[{"PMID":"36420144","why":"WNT7A linker binds FZD7"}],"covers":["LR008085"]},"LR006726":{"pair":"WNT7B -> ADGRA2","headline":"WNT7B-ADGRA2 (GPR124) has abstract-level support: binding to the GPR124:RECK complex and a requirement for GPR124 in Wnt synergy.","interaction_type":"functional only","direction_and_effect":"WNT7A/B bind the GPR124:RECK complex, not WNT3A; GPR124 ectodomain mediates RECK/WNT7 canonical signalling [PMID:30304675]. WNT1/WNT7B synergistic signalling requires GPR124 (ADGRA2) and RECK [PMID:28289266]. UniProt: Gpr124 works with RECK to let brain endothelial cells respond to Wnt7A or B [DB:UniProt].","molecular_requirements":"RECK, FZD5/FZD8 and LRP6 are required for the WNT1/WNT7B synergy [PMID:28289266].","affinity_potency":[],"species_and_systems":"Human proteins per curator fields; HEK293-type cell data not detailed in abstracts [PMID:30304675, PMID:28289266]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. ADGRA2 is flagged transmembrane [flag].","caveats":"Both papers abstract-only. Binding is shown for the GPR124:RECK complex, not demonstrated for GPR124 alone in these abstracts; the second paper is functional.","key_references":[{"PMID":"30304675","why":"WNT7 binds GPR124:RECK complex"},{"PMID":"28289266","why":"GPR124 and RECK needed for WNT1/WNT7B synergy"}],"covers":["LR003526","LR006726"]},"LR005376":{"pair":"WNT7B -> FZD4","headline":"WNT7B-FZD4 rests on a UniProt note; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records the interaction with FZD4 as in vitro [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro per UniProt; details not reported in our evidence [DB:UniProt].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Two papers judged abstract-insufficient, none confirmed. Support is database-only.","key_references":[],"covers":["LR002050","LR005376"]},"LR008166":{"pair":"WNT7B -> FZD7:LRP5","headline":"WNT7B-FZD7:LRP5 rests on abstracts for WNT7B/FZD7 only; LRP5 is not named.","interaction_type":"functional only","direction_and_effect":"Fzd7 binds Wnt7b and modulates beta-catenin in pancreatic cancer cells [PMID:33934523]; Fz7 is the receptor for Wnt7b dendrite growth via non-canonical signalling [PMID:29898920].","molecular_requirements":"LRP5 is not named in either abstract; the second paper reports non-canonical signalling.","affinity_potency":[],"species_and_systems":"Capan-2 and Panc-1 cells [PMID:33934523]; hippocampal neurons [PMID:29898920].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Both abstract only; binding method not described. Evidence conflicts in kind (canonical versus non-canonical) and does not test LRP5.","key_references":[{"PMID":"33934523","why":"Fzd7 binds Wnt7b in pancreatic cancer cells"},{"PMID":"29898920","why":"Fz7 receptor for Wnt7b in neurons"}],"covers":["LR008166"]},"LR006735":{"pair":"WNT8B -> FZD5","headline":"WNT8B induces signalling via FZD5 in a FZD-knockout reporter map; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"Wnt8b induced signalling via FZD5 and FZD8 [PMID:28733458].","molecular_requirements":"FZD5 alone sufficed in the rescue setup; co-receptor need is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in HEK293 reporter cells with FZD knockouts [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map in HEK293 cells; promiscuous FZD5/FZD8 (about 70% homology) may be redundant [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR003535","LR006735"]},"LR006744":{"pair":"WNT9A -> MUSK","headline":"WNT9A binds MuSK extracellular domain and induces MuSK dimerization and phosphorylation; reported by one abstract-level study.","interaction_type":"direct binding","direction_and_effect":"Wnt9a and Wnt11 bind directly to the extracellular domain of MuSK, inducing MuSK dimerization and tyrosine phosphorylation; curators label it agonist [PMID:22309736].","molecular_requirements":"Wnt-induced acetylcholine receptor (AChR) clustering requires both MuSK and LRP4 [PMID:22309736]. AChR clustering by Wnt9a was dose-dependent and non-additive to agrin [PMID:22309736].","affinity_potency":[],"species_and_systems":"Cell/muscle-cell system; curators list human ligand and receptor, and the human pair is ortholog-inferred while the mouse pair is not, suggesting mouse experiments [PMID:22309736].","localisation_and_range":"WNT9A is flagged secreted [flag]; acts on the muscle MuSK receptor, so paracrine/synaptic.","caveats":"Read at abstract level only (read_depth abstract_only); binding affinity not reported. LRP4 requirement means MuSK alone may not suffice.","key_references":[{"PMID":"22309736","why":"Wnt9a binds MuSK ectodomain, induces dimerization, requires LRP4"}],"covers":["LR003544","LR006744"]},"LR005385":{"pair":"WNT9B -> FZD4","headline":"WNT9B activates canonical signalling through FZD4 in a human reporter-cell rescue map; one functional study.","interaction_type":"functional only","direction_and_effect":"Wnt9b induced canonical signalling with FZD4 and FZD10, as well as FZD5 and FZD8; effect is activating [PMID:28733458].","molecular_requirements":"FZD4 was tested as a single rescue receptor; FZD4 and FZD10 behaved similarly in clustering; the sgRNA design carried a 1-mismatch to FZD4 so knockout may have been partial [PMID:28733458].","affinity_potency":[],"species_and_systems":"HEK293 Wnt reporter cells (human; TCF4 luciferase) with FZD knockout and rescue [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Functional reporter only; no binding data. The pan-FZD sgRNA had one mismatch at FZD4 per the excerpts, which complicates the knockout background.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR002059","LR005385"]},"LR012369":{"pair":"ZNRF3 -> FZD2:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD2 partner is not named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012369"]},"LR000966":{"pair":"KNG1 -> ITGB2","headline":"Cleaved kininogen (HKa) binds the Mac-1 integrin (ITGAM:ITGB2) directly with nanomolar affinity; single abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"HKa binds Mac-1 and blocks adhesion of Mac-1-transfected cells to fibrinogen and ICAM-1, so it acts as a blocker of Mac-1 adhesion [PMID:10845911].","molecular_requirements":"The ligand is cleaved high molecular weight kininogen (HKa), a KNG1 product. The evidence is for the Mac-1 heterodimer (CD11b/CD18), not ITGB2 alone [PMID:10845911].","affinity_potency":[{"value":"Kd 3.2x10(-9) mol/L","assay":"IAsys resonant mirror optical biosensor, purified Mac-1","system":"cell-free","cite":"PMID:10845911"},{"value":"Kd 62 nmol/L","assay":"labeled HKa binding","system":"Mac-1-transfected HEK 293 cells","cite":"PMID:10845911"}],"species_and_systems":"Human HKa and human Mac-1, in HEK 293 transfectants and a cell-free system [PMID:10845911]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"One paper, read as abstract only. ITGB2 pairs with ITGAM here, so the alpha chain is needed.","key_references":[{"PMID":"10845911","why":"Direct HKa-Mac-1 binding by biosensor and cell assays"}],"covers":["LR000966","LR004388"]},"LR005952":{"pair":"GDF6 -> ACVR2A","headline":"Supported by SPR binding and shRNA knockdown; ACVR2A is a lower-affinity type II receptor for GDF6 acting as agonist.","interaction_type":"direct binding","direction_and_effect":"GDF6 (BMP13) is an agonist. Recombinant BMP13 bound ACVR2A by surface plasmon resonance, with BMP12 and BMP2 binding comparably [PMID:21702718]. In MC3T3 cells, ActRIIA shRNA suppressed GDF6 signalling, so ActRIIA is a required type II receptor [PMID:16049014].","molecular_requirements":"Type II receptor with a type I partner: ALK3 or ALK6 overexpression conferred GDF6 signalling, and ALK3 shRNA suppressed it [PMID:16049014]. BMPR2 and ACVR2B also bound BMP13 [PMID:21702718].","affinity_potency":[{"value":"KD (kin) 15.1 nM","assay":"surface plasmon resonance, 1:1 Langmuir fit, rhBMP13 (GDF6) on ACVR2A","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Human recombinant ligands and receptors for SPR [PMID:21702718]; MC3T3 cells (mouse line, species of experiment not stated in dossier) for knockdown [PMID:16049014]. The mouse pair is ortholog-inferred.","localisation_and_range":"GDF6 is annotated secreted [flag]; ACVR2A transmembrane [flag]; paracrine signalling.","caveats":"Both papers read as abstract only, though SPR excerpts come from full text. The binding paper refers to GDF6 as BMP13. ACVR2A affinity is more than 10-fold weaker than for type I receptors [PMID:21702718].","key_references":[{"PMID":"21702718","why":"SPR binding of BMP13 (GDF6) to ACVR2A with KD."},{"PMID":"16049014","why":"ActRIIA knockdown suppresses GDF6 signalling."}],"covers":["LR002687","LR005952"]},"LR004719":{"pair":"RSPO4 -> LGR5","headline":"RSPO4 is supported as an LGR5 agonist mainly by R-spondin family papers and databases, with no RSPO4-specific data in the papers.","interaction_type":"direct binding","direction_and_effect":"Stimulatory modulator of Wnt/beta-catenin signalling. LGR4 and LGR5 bind R-spondins with high affinity and potentiate Wnt signalling by enhancing Wnt-induced LRP6 phosphorylation [PMID:21693646]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"LGR5 is not coupled to G proteins or beta-arrestin on R-spondin stimulation [PMID:21693646]. Lgr4/5 associate with the Frizzled/Lrp Wnt receptor complex and enhance Wnt signals [PMID:21727895]. So it modulates Wnt rather than signalling alone.","affinity_potency":[],"species_and_systems":"Human proteins in reporter assays [PMID:21693646]; mouse gut and HEK293 cells [PMID:21727895]. Mouse pair is ortholog-inferred.","localisation_and_range":"RSPO4 is annotated secreted and LGR5 transmembrane [flag]; paracrine. Potency value held in a curated field is not reproduced here.","caveats":"Both papers abstract only and speak of R-spondins generally; RSPO4 itself is named only in UniProt as an LGR5 partner [DB:UniProt]. A pull-down is recorded in IntAct [DB:IntAct]. Reactome records RSPOs binding LGRs [DB:Reactome].","key_references":[{"PMID":"21693646","why":"R-spondins as ligands of LGR4 and LGR5."},{"PMID":"21727895","why":"Lgr4/5 mediate R-spondin signalling with the Wnt receptor complex."}],"covers":["LR001322","LR004719"]}};